"use strict";
const DATA = [{"id":"s01","section":1,"unit":1,"unitName":"单元01 · 第01–06节","short":"第01节 · L1–2","title":"一般疑问句","lessons":"Lesson 1 — Lesson 2","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>一般疑问句</strong></td>\n<td>一般疑问句的句式结构</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>一般疑问句</strong></td>\n<td>陈述句变为一般疑问句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般疑问句</div><div class=\"gb\"><p class=\"source-line\">以提出问题为目的的句子叫疑问句。以 be 动词、助动词或情态动词开头，用 yes 或 no 回答的疑问句叫一般疑问句。朗读一般疑问句时，一般用升调。</p>\n<p class=\"source-line\">（1）—— Is this your handbag? 这是你的手提包吗？<br/>\n—— Yes, it is. 是的，它是。<br/>\n—— No, it isn't. 不，它不是。</p>\n<p class=\"source-line\">（2）—— Do you play basketball? 你打篮球吗？<br/>\n—— Yes, I do. 是的，我打（篮球）。<br/>\n—— No, I don't. 不，我不打（篮球）。</p>\n<p class=\"source-line\">（3）—— Can you dance? 你会跳舞吗？<br/>\n—— Yes, I can. 是的，我会。<br/>\n—— No, I can't. 不，我不会。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般疑问句的句式结构</div><div class=\"gb\"><h5>1. 含 be 动词的一般疑问句</h5>\n<ul>\n<li>问句： be 动词（am / is / are） + 主语 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + be 动词 (am / is / are).</li>\n<li>否定回答： No, 主语 + be 动词 (am / is / are) + not.</li>\n</ul>\n<p class=\"source-line\"><strong>注意</strong>：对一般疑问句进行回答时，肯定回答不能用缩写形式。\n—— Are you Dr. Zhang? 你是张医生吗？<br/>\n—— Yes, I am. 是的，我是。<br/>\n—— No, I'm not. 不，我不是。</p>\n<h5>2. 含情态动词的一般疑问句</h5>\n<ul>\n<li>问句： 情态动词 + 主语 + 动词原形 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + 情态动词.</li>\n<li>否定回答： No, 主语 + 情态动词 + not.</li>\n</ul>\n<p class=\"source-line\">—— Can you speak English? 你会说英语吗？<br/>\n—— Yes, I can. 是的，我会。<br/>\n—— No, I can't. 不，我不会。</p>\n<h5>3. 含实义动词的一般疑问句</h5>\n<ul>\n<li>问句： 助动词 + 主语 + 动词原形 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + do / does / did.</li>\n<li>否定回答： No, 主语 + don't / doesn't / didn't.</li>\n</ul>\n<p class=\"source-line\">—— Does her father work in a factory? 她父亲在工厂工作吗？<br/>\n—— Yes, he does. 是的，他在工厂工作。<br/>\n—— No, he doesn't. 不，他不在工厂工作。</p></div></div>\n<div class=\"g\"><div class=\"gt\">陈述句变为一般疑问句</div><div class=\"gb\"><p class=\"source-line\"><strong>口诀：</strong></p>\n<p class=\"source-line\">（1） 一找: 有情找情 (can / could / must / should)；有 be 找 be (am / is / are / was / were)；无情无 be 添助动 (do / does / did)。</p>\n<p class=\"source-line\">（2） 二变: I 变 you, we 变 you; my 变 your, our 变 your。</p>\n<p class=\"source-line\">（3） 三问号: 结尾句号变问号。</p>\n<p class=\"source-line\"><strong>注意</strong>：第一人称为主语的肯定句变为一般疑问句时，主语要变为第二人称。</p>\n<h5>1. 含 be 动词的陈述句变一般疑问句</h5>\n<ul>\n<li>I am a teacher. → Are you a teacher? （我是一名老师。你是一名老师吗？）</li>\n<li>There is some water in the glass. → Is there any water in the glass? （玻璃杯里有些水。玻璃杯里有水吗？）\n<strong>注意</strong>：含有 some 的陈述句变为一般疑问句时，要把 some 变成 any。</li>\n</ul>\n<h5>2. 含情态动词的陈述句变一般疑问句</h5>\n<ul>\n<li>Tom can play football. → Can Tom play football? （汤姆会踢足球。汤姆会踢足球吗？）</li>\n</ul>\n<h5>3. 含实义动词的陈述句变一般疑问句</h5>\n<ul>\n<li>Tom likes books. → Does Tom like books? （汤姆喜欢书。汤姆喜欢书吗？）</li>\n</ul></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s01-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Are there ____ in the tree?</p>","options":["any birds","some birds","a bird"],"correct":0,"answer":"A"},{"id":"s01-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ you write to me soon?<br/><br>\n—— Yes, I can.</br></p>","options":["Do","Can","can"],"correct":1,"answer":"B"},{"id":"s01-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Does he go to school by bike?<br/><br>\n—— ____</br></p>","options":["Yes, he will.","No, he doesn't.","No, he isn't."],"correct":1,"answer":"B"},{"id":"s01-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I like balls. Do you like balls?<br/><br>\n—— ____ I like toy bears.</br></p>","options":["Yes, I do.","No, I don't.","Thanks."],"correct":1,"answer":"B"},{"id":"s01-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Does your mother often cook?<br/><br>\n—— ____ She can cook yummy food.</br></p>","options":["Yes, she does.","Yes, he does.","No, she doesn't."],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"句型转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s01-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Is this your handbag? （作肯定回答）</p>","options":[],"correct":null,"answer":"Yes, it is."},{"id":"s01-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">This is my handbag. （改为一般疑问句）</p>","options":[],"correct":null,"answer":"Is this your handbag?"},{"id":"s01-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Is that your handbag? （作否定回答）</p>","options":[],"correct":null,"answer":"No, it isn't."},{"id":"s01-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">They love their parents. （改为一般疑问句并作肯定回答）</p>","options":[],"correct":null,"answer":"Do they love their parents?\nYes, they do."},{"id":"s01-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">She can swim. （改为一般疑问句并作否定回答）</p>","options":[],"correct":null,"answer":"Can she swim?\nNo, she can't."}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【昆明·五华区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s01-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> he your father?</p>","options":["Does","Is","Are","Do"],"correct":1,"answer":"B\n解析：为一般疑问句，句中无实义动词，所以不能用 do / does 提问。主语 he （他） 为第三人称单数, be 动词应用 is, 故本题选择 B 选项。"},{"id":"s01-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> you like pears?</p>","options":["Do","Are","Does","Can"],"correct":0,"answer":"A\n解析：为一般疑问句, like （喜欢）为实义动词，所以此题是含有实义动词的一般疑问句，排除 B 选项。主语 you （你; 你们）为第二人称，助动词应用 do。D 选项不符合题意。"},{"id":"s01-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> David and Jane like watching TV?<br/><br>\n—— Yes, they <span class=\"blank-token\">_</span>.</br></p>","options":["Do; does","Do; do","Does; does","Do; don't"],"correct":1,"answer":"B"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【滁州·南谯区】判断题：判断下列句子是否为一般疑问句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s01-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">This is a sweater.</p>","options":["正确","错误"],"correct":1,"answer":"B\n解析：是以指示代词 this （这个） 开头的陈述句，句末为句号，与一般疑问句句型结构不符。"},{"id":"s01-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Is that an egg?</p>","options":["正确","错误"],"correct":0,"answer":"A\n解析：是以 be 动词开头的一般疑问句，符合一般疑问句句型结构。"},{"id":"s01-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">No, it isn't.</p>","options":["正确","错误"],"correct":1,"answer":"B\n解析：是以 be 动词开头的一般疑问句的否定回答，以 “No” 开头, it 指代问句中提到的事物，故此句不是一般疑问句。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【合肥·蜀山区】按要求改变句型。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s01-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">I am a student. （改为一般疑问句，并作否定回答）</p>","options":[],"correct":null,"answer":"Are you a student?\nNo, I'm not.\n解析：原句中的 am 是 be 动词，变为一般疑问句时要将 be 动词提到主语前。原句主语 I 变为问句中的 you，am 相应变为 are；作答者仍用 I 自称，因此否定回答为“No, I'm not.”。"},{"id":"s01-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">She reads English in the morning. （改为一般疑问句）</p>","options":[],"correct":null,"answer":"Does she read English in the morning?\n解析：句中的实义动词为 reads （阅读）, 所以要借助助动词 does 构成一般疑问句。动词 reads 要变为原形 read, 句号变为问号。"},{"id":"s01-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">He can play basketball very well. （改为一般疑问句，并作肯定和否定回答）</p>","options":[],"correct":null,"answer":"Can he play basketball very well?\nYes, he can.\nNo, he can't.\n解析：将 can 提至句首，句号变为问号。肯定回答以 “Yes” 开头。否定回答以 “No” 开头, can 后加 not, cannot 可缩写为 can't。"}],"questionCount":3,"hasAnswers":true}]},{"id":"s02","section":2,"unit":1,"unitName":"单元01 · 第01–06节","short":"第02节 · L3–4","title":"肯定句变否定句","lessons":"Lesson 3 — Lesson 4","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>否定句</strong></td>\n<td>含 be 动词的否定句</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>否定句</strong></td>\n<td>含实义动词的否定句</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">否定句</div><div class=\"gb\"><p class=\"source-line\">否定句就是表示否定的句子，必须有否定词。下面主要给大家讲两种否定句：含 be 动词的否定句和含实义动词的否定句。</p>\n<h5>1. 含 be 动词 的否定句</h5>\n<p class=\"source-line\">方法： 把含 be 动词的肯定句改为否定句，就在 be 动词后面加 not。</p>\n<p class=\"source-line\">（1）肯定句：This is my umbrella. 这是我的雨伞。<br/>\n否定句：This is not my umbrella. 这不是我的雨伞。</p>\n<p class=\"source-line\">（2）肯定句：I am a worker. 我是一名工人。<br/>\n否定句：I am not a worker. 我不是一名工人。</p>\n<p class=\"source-line\">（3）肯定句：We are good friends. 我们是好朋友。<br/>\n否定句：We are not good friends. 我们不是好朋友。</p>\n<p class=\"source-line\">（4）肯定句：I was ten years old last year. 我去年 10 岁。<br/>\n否定句：I was not ten years old last year. 我去年不是 10 岁。</p>\n<p class=\"source-line\">（5）肯定句：We were happy last Sunday. 我们上周日很开心。<br/>\n否定句：We were not happy last Sunday. 我们上周日不开心。</p>\n<div class=\"custom-block note\"><div class=\"custom-block-title\">注意</div><p class=\"source-line\">be 动词与 not 的缩写情况如下：is not = isn't, are not = aren't, was not = wasn't, were not = weren't\n注意: am not 不缩写</p></div>\n<h5>2. 含实义动词的否定句</h5>\n<p class=\"source-line\">方法： 把含实义动词的肯定句改为否定句，根据时态和人称的不同用 “do / does / did not + 动词原形” 构成否定。</p>\n<p class=\"source-line\">（1）肯定句：We go to the park every morning. 我们每天早晨去公园。<br/>\n否定句：We don't go to the park every morning. 我们每天早晨不去公园。</p>\n<p class=\"source-line\">（2）肯定句：My mother likes flowers. 我妈妈喜欢花儿。<br/>\n否定句：My mother doesn't like flowers. 我妈妈不喜欢花儿。</p>\n<p class=\"source-line\">（3）肯定句：I went shopping with my mother yesterday. 我和妈妈昨天去购物了。<br/>\n否定句：I didn't go shopping with my mother yesterday. 我和妈妈昨天没有去购物。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"判断题：判断下列句子是肯定句还是否定句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s02-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The taxi comes.</p>","options":["肯定句","否定句"],"correct":0,"answer":"A"},{"id":"s02-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">He isn't my brother.</p>","options":["肯定句","否定句"],"correct":1,"answer":"B"},{"id":"s02-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I didn't go to the supermarket yesterday.</p>","options":["肯定句","否定句"],"correct":1,"answer":"B"},{"id":"s02-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">They are my grandparents.</p>","options":["肯定句","否定句"],"correct":0,"answer":"A"},{"id":"s02-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">She is my aunt.</p>","options":["肯定句","否定句"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"把下列句子改成否定句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s02-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">She is a clever girl. （改为否定句）</p>","options":[],"correct":null,"answer":"She isn't a clever girl."},{"id":"s02-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">They are in the same class. （改为否定句）</p>","options":[],"correct":null,"answer":"They aren't in the same class."},{"id":"s02-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I was sad last night. （改为否定句）</p>","options":[],"correct":null,"answer":"I wasn't sad last night."},{"id":"s02-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Andy missed the bus two hours ago. （改为否定句）</p>","options":[],"correct":null,"answer":"Andy didn't miss the bus two hours ago."},{"id":"s02-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">My sister likes strawberries. （改为否定句）</p>","options":[],"correct":null,"answer":"My sister doesn't like strawberries."},{"id":"s02-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">I am from China. （改为否定句）</p>","options":[],"correct":null,"answer":"I am not from China."},{"id":"s02-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">This is my handbag. （改为否定句）</p>","options":[],"correct":null,"answer":"This is not my handbag."}],"questionCount":7,"hasAnswers":true},{"source":"practice","title":"【滁州·琅琊区】根据括号内的提示将下列句子变成否定句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s02-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">My aunt <span class=\"blank-token\">____</span> (be) a worker. She is a nurse.</p>","options":[],"correct":null,"answer":"isn't\n解析：句子时态为一般现在时，主语为第三人称单数，故 be 动词用 is, is 的否定形式为 isn't。"},{"id":"s02-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">My sister <span class=\"blank-token\">____</span> (do) go to school because she had a cold.</p>","options":[],"correct":null,"answer":"didn't\n解析：根据 “she had a cold” 可知此句时态为一般过去时，故助动词用 didn't。"},{"id":"s02-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> (be) from Shanghai.</p>","options":[],"correct":null,"answer":"aren't\n解析：主语是第三人称复数，故 be 动词用 are, are 的否定形式为 aren't。"},{"id":"s02-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Andy and Mary <span class=\"blank-token\">____</span> (be) classmates last year.</p>","options":[],"correct":null,"answer":"weren't\n解析：主语是复数，根据 last year （去年） 可知此句时态是一般过去时，故应填 be 动词 were 的否定形式 weren't。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【滁州·南谯区】把下列句子改为否定句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s02-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">I am from China.</p>","options":[],"correct":null,"answer":"I am not from China."},{"id":"s02-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">This is my handbag.</p>","options":[],"correct":null,"answer":"This isn't my handbag."},{"id":"s02-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My father likes tea.</p>","options":[],"correct":null,"answer":"My father doesn't like tea."},{"id":"s02-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">My mother went to Beijing last month.</p>","options":[],"correct":null,"answer":"My mother didn't go to Beijing last month."}],"questionCount":4,"hasAnswers":true}]},{"id":"s03","section":3,"unit":1,"unitName":"单元01 · 第01–06节","short":"第03节 · L5–6","title":"人称代词主格和不定冠词","lessons":"Lesson 5 — Lesson 6","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>人称代词主格和不定冠词</strong></td>\n<td>人称代词主格</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>人称代词主格和不定冠词</strong></td>\n<td>不定冠词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">人称代词</div><div class=\"gb\"><p class=\"source-line\">人称代词是表示“你、我、他”等人称的代词。为了避免重复，用来代替前面提到过的人、动物、事物等名称的词。人称代词根据用法不同而有人称、数与格的变化。</p>\n<ul>\n<li>She is a new student. 她是一名新学生。</li>\n<li>I like swimming. 我喜欢游泳。</li>\n<li>They are happy. 他们很开心。</li>\n</ul></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词主格</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>单数</th>\n<th>复数</th>\n<th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>I 我</td>\n<td>we 我们</td>\n<td>I am a boy. 我是一个男孩儿。<br/>We are boys. 我们是男孩儿。</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>you 你</td>\n<td>you 你们</td>\n<td>You are clever. 你很聪明。<br/>You are clever. 你们很聪明。</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>he 他<br/>she 她<br/>it 它</td>\n<td>they 他/她/它们</td>\n<td>He sings very well. 他唱歌很好。<br/>They sing very well. 他们唱歌很好。<br/>She is good at dancing. 她擅长跳舞。<br/>They are good at dancing. 她们擅长跳舞。<br/>It eats grapes. 它吃葡萄。<br/>They eat grapes. 它们吃葡萄。</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\"><strong>注意</strong>：人称的区分：“我/我们”叫作第一人称，“你/你们”叫作第二人称，“他/她/它（们）”叫作第三人称。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词的用法</div><div class=\"gb\"><h5>1. 人称代词的主格在句子中作主语</h5>\n<ul>\n<li>I am studying English now. 我现在正在学习英语。</li>\n<li>She gave Zhang Peng an English book. 她给了张鹏一本英语书。</li>\n</ul>\n<h5>2. 多个并列主语的语序</h5>\n<p class=\"source-line\">如果有几个人称代词并列作主语，它们的顺序是:\n* <strong>单数</strong>—you → he / she → I\n* <strong>复数</strong>—we → you → they</p>\n<ul>\n<li>You, she and I are good friends. 我、你和她都是好朋友。</li>\n<li>We, you and they all like music. 我们、你们和他们都喜欢音乐。</li>\n<li>I and she make mistakes. 我和她犯了错误。 （若把错误责任担，第一人称最当先）</li>\n</ul>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">人称代词排列顺序口诀：人称代词并列现，单数并列231，复数并列123；若把错误责任担，第一人称最当先。时时注意比身份，人总要在动物前。</p></div>\n<div class=\"custom-block note\"><div class=\"custom-block-title\">注意</div><p class=\"source-line\">人称代词主格与 be 动词的缩写：I am = I'm, we are = we're, you are = you're, she is = she's, he is = he's, it is = it's, they are = they're</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">不定冠词</div><div class=\"gb\"><p class=\"source-line\">冠词用在名词的前面，必须与名词一起出现。英语中的冠词有3个，它们是 a、an 和 the。这3个冠词又可分为不定冠词和定冠词。</p>\n<ul>\n<li>This is a car. 这是一辆小汽车。</li>\n<li>You should take an umbrella. 你应该带一把雨伞。</li>\n<li>The student goes to school on foot. 那个学生步行上学。</li>\n</ul></div></div>\n<div class=\"g\"><div class=\"gt\">不定冠词的用法</div><div class=\"gb\"><h5>1. 泛指任意一个</h5>\n<p class=\"source-line\">泛指一类事物或人中的任意一个。\n* His father is a policeman. 他父亲是一名警察。\n* Give me a book, please. 请给我一本书。</p>\n<h5>2. 代表一类</h5>\n<p class=\"source-line\">代表某一类人或事物。\n* A student should study hard. 学生应当努力学习。\n* A horse is a useful animal. 马是有用的动物。</p>\n<h5>3. 表示数量“一”</h5>\n<p class=\"source-line\">表示数量，有“一”的意思。但数的概念没有 one 强烈。\n* She has a mouth, a nose and two eyes. 她有一张嘴、一个鼻子和两只眼睛。</p>\n<h5>4. 表示单位“每”</h5>\n<p class=\"source-line\">表示单位，相当于“每”的意思。\n* We have three meals a day. 我们每日吃三餐。</p>\n<h5>5. 固定短语</h5>\n<p class=\"source-line\">用于某些固定短语中。\n* a few 一些，几个\n* a little 一点儿\n* a bit 一点儿\n* a lot of 许多，大量</p>\n<h5>6. a 和 an 的区别</h5>\n<p class=\"source-line\">发音以元音音素开头的单词前用 an。\n* an orange 一个橘子\n* an umbrella 一把雨伞\n* an old man 一位老人</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">a、an 的用法区别: 用 a 用 an 这样辨，不看字母看音素，不见元音别放 n。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"根据汉语提示用单词填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s03-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\"><strong><em>_ （她） is a student. </em></strong>_ （我） am a student, too.</p>","options":[],"correct":null,"answer":"She, I"},{"id":"s03-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\"><strong><em>_ （他） looks like him. </em></strong>_ （他们） are twins.</p>","options":[],"correct":null,"answer":"He, They"},{"id":"s03-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\"><strong><em>_（你们）are from the UK. </em></strong>_（我们）are from China.</p>","options":[],"correct":null,"answer":"You, We"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"在横线上写出适当的人称代词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s03-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Stella is a student. <strong><em>_ isn't German. </em></strong>_ is Spanish.</p>","options":[],"correct":null,"answer":"She, She"},{"id":"s03-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Alice is a student. <strong><em>_ isn't German. </em></strong>_ is French.</p>","options":[],"correct":null,"answer":"She, She"},{"id":"s03-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">This is her car. ____ is a French car.</p>","options":[],"correct":null,"answer":"It"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"选择题：从 a、an 中选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s03-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">它是一辆小汽车。 It's ____ car.</p>","options":["an","a"],"correct":1,"answer":"B"},{"id":"s03-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">它是一个苹果。 It's ____ apple.</p>","options":["a","an"],"correct":1,"answer":"B"},{"id":"s03-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">她是一名英语老师。 She is ____ English teacher.</p>","options":["an","a"],"correct":0,"answer":"A"},{"id":"s03-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">有一只宠物狗。 There is ____ pet dog.</p>","options":["a","an"],"correct":0,"answer":"A"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【佛山·南海区】用人称代词主格代替画线部分内容。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s03-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\"><u>My mother and I</u> are at home.</p>","options":[],"correct":null,"answer":"We\n解析：画线部分为 “My mother and I（我和我妈妈）”,应用人称代词 “We（我们）” 替换。"},{"id":"s03-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\"><u>Mr. Smith</u> is a kind man.</p>","options":[],"correct":null,"answer":"He\n解析：“Mr. Smith（史密斯先生）”是第三人称单数，应用人称代词“He（他）”替换。"},{"id":"s03-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\"><u>Her aunt</u> is a model（模特）。</p>","options":[],"correct":null,"answer":"She\n解析：“Her aunt（她姑姑）”是第三人称单数，应用人称代词 “She（她）” 替换。"},{"id":"s03-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\"><u>The car</u> is red.</p>","options":[],"correct":null,"answer":"It\n解析：“The car（这辆小汽车）”是第三人称单数，应用人称代词 “It（它）” 替换。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【昆明·官渡区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s03-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">William is <span class=\"blank-token\">____</span> kind boy.</p>","options":["/","an","a"],"correct":2,"answer":"C\n解析：kind是发音以辅音音素开头的单词，应用不定冠词a修饰。A选项不符合语法。"},{"id":"s03-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">English is <span class=\"blank-token\"><strong><em>_</em></strong></span> language （语言）. It is <span class=\"blank-token\">_</span> important tool.</p>","options":["a; an","a; /","a; a"],"correct":0,"answer":"A\n解析：language 是发音以辅音音素开头的单词，应用不定冠词 a 修饰。important 是发音以元音音素开头的单词，应用不定冠词 an 修饰。"},{"id":"s03-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">I usually have <span class=\"blank-token\">____</span> egg and bread for breakfast.</p>","options":["a","an","/"],"correct":1,"answer":"B\n解析：egg 是发音以元音音素开头的单词，应用不定冠词 an 修饰。"},{"id":"s03-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is this <span class=\"blank-token\">____</span> schoolbag?<br/><br>\n—— Yes, it is.</br></p>","options":["a","an","/"],"correct":0,"answer":"A\n解析：schoolbag 是发音以辅音音素开头的单词，应用不定冠词 a 修饰。"}],"questionCount":4,"hasAnswers":true}]},{"id":"s04","section":4,"unit":1,"unitName":"单元01 · 第01–06节","short":"第04节 · L7–8","title":"含 what 的特殊疑问句","lessons":"Lesson 7 — Lesson 8","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 what 的特殊疑问句</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>含 what 的特殊疑问句</strong></td>\n<td>what 的用法</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。\n常用的疑问词有 what、who、whose、which、when、where、how、why 等。</p>\n<p class=\"source-line\">what 用于对人名、时间、职业、日期、天气、颜色等事物提问，意为“什么”。\n—— What is your name? 你叫什么名字？<br/>\n—— My name's Mary. 我的名字是玛丽。</p>\n<p class=\"source-line\">—— What nationality are you? 你是哪国人？<br/>\n—— I'm British. 我是英国人。</p></div></div>\n<div class=\"g\"><div class=\"gt\">what 的用法</div><div class=\"gb\"><h5>1. 问“是什么”</h5>\n<p class=\"source-line\">—— What is this? 这是什么？<br/>\n—— It's a pencil sharpener. 它是一个转笔刀。</p>\n<p class=\"source-line\">—— What are those? 那些是什么？<br/>\n—— They are horses. 它们是马。</p>\n<h5>2. 问“姓名”</h5>\n<p class=\"source-line\">—— What is your name? 你叫什么名字？<br/>\n—— My name is Andy. 我的名字是安迪。</p>\n<p class=\"source-line\">—— What is her name? 她叫什么名字？<br/>\n—— Her name is Sue. 她的名字是休。</p>\n<h5>3. 问“天气”</h5>\n<p class=\"source-line\">—— What is the weather like today? 今天天气怎么样？<br/>\n—— It's sunny. 天气晴朗。</p>\n<h5>4. 问“颜色”</h5>\n<p class=\"source-line\">—— What colour is your bag? 你的包是什么颜色的？<br/>\n—— It's red. 它是红色的。</p>\n<p class=\"source-line\">—— What colour do you like? 你喜欢什么颜色？<br/>\n—— I like blue. 我喜欢蓝色。</p>\n<h5>5. 问“时间”</h5>\n<p class=\"source-line\">—— What time is it? 几点了？<br/>\n—— It's 8:00. 8:00 了。</p>\n<p class=\"source-line\">—— What time do you usually get up? 你通常几点钟起床？<br/>\n—— I usually get up at 6:30 a.m. 我通常早上 6:30 起床。</p>\n<h5>6. 问“星期几”</h5>\n<p class=\"source-line\">—— What day is it today? 今天星期几？<br/>\n—— It's Friday. 今天星期五。</p>\n<h5>7. 问“日期”</h5>\n<p class=\"source-line\">—— What date is it today? 今天几号？<br/>\n—— It's March 6th. 今天是3月6日。</p>\n<h5>8. 问“正在做什么”</h5>\n<p class=\"source-line\">—— What are you doing? 你正在做什么？<br/>\n—— I'm doing my homework. 我正在做作业。</p>\n<p class=\"source-line\">—— What is your mother doing? 你妈妈正在做什么？<br/>\n—— She's cooking. 她正在烹饪。</p>\n<h5>9. 问“意愿”</h5>\n<p class=\"source-line\">—— What would you like to drink? 你想喝什么？<br/>\n—— I'd like some juice. 我想要一些果汁。</p>\n<h5>10. 问“工作”</h5>\n<p class=\"source-line\">—— What does your mother do? 你妈妈是做什么的？<br/>\n—— She's a doctor. 她是一名医生。</p>\n<h5>11. 问“尺码”</h5>\n<p class=\"source-line\">—— What size do you want? 你想要几码？<br/>\n—— Size 37. 37 码。</p>\n<h5>12. 问“吃什么”</h5>\n<p class=\"source-line\">—— What would you like for breakfast? 你早餐想要什么？<br/>\n—— I'd like an egg, bread and milk. 我想要一个鸡蛋、面包和牛奶。</p>\n<h5>13. 问“季节”</h5>\n<p class=\"source-line\">—— What is your favourite season? 你最喜欢的季节是什么？<br/>\n—— Winter. 冬天。</p>\n<h5>14. 问“爱好”</h5>\n<p class=\"source-line\">—— What is your hobby? 你的爱好是什么？<br/>\n—— I like collecting stamps. 我喜欢集邮。</p>\n<h5>15. 问“计划”</h5>\n<p class=\"source-line\">—— What are you going to do tomorrow? 你明天打算做什么？<br/>\n—— I'm going to buy some books. 我打算去买些书。</p>\n<h5>16. 问“身体情况”</h5>\n<p class=\"source-line\">—— What is the matter? 怎么了？<br/>\n—— I have a sore throat. 我喉咙痛。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"选择题：选择正确的特殊疑问词组。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s04-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ is it today?<br/><br>\n—— It's May 1st.</br></p>","options":["What date","What time","What colour","What day","What size"],"correct":0,"answer":"A"},{"id":"s04-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ does your brother get up?<br/><br>\n—— My brother gets up at 6:00.</br></p>","options":["What colour","What time","What day","What size","What date"],"correct":1,"answer":"B"},{"id":"s04-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ is it?<br/><br>\n—— It's green.</br></p>","options":["What day","What size","What colour","What date","What time"],"correct":2,"answer":"C"},{"id":"s04-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ is it today?<br/><br>\n—— Today is Monday.</br></p>","options":["What time","What colour","What size","What day","What date"],"correct":3,"answer":"D"},{"id":"s04-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— ____ do you want?<br/><br>\n—— Size 36.</br></p>","options":["What time","What colour","What day","What date","What size"],"correct":4,"answer":"E"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"根据要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s04-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He is <u>a policeman</u>.（对画线部分提问）</p>","options":[],"correct":null,"answer":"What is he?"},{"id":"s04-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">I'm <u>French</u>.（对画线部分提问）</p>","options":[],"correct":null,"answer":"What nationality are you?"},{"id":"s04-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I like <u>red</u>.（对画线部分提问）</p>","options":[],"correct":null,"answer":"What colour do you like?"},{"id":"s04-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">My name is <u>Robert</u>.（对画线部分提问）</p>","options":[],"correct":null,"answer":"What is your name?"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【佛山·高明区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s04-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> are these?<br/><br>\n—— They're peaches.</br></p>","options":["Where","What","Who"],"correct":1,"answer":"B"},{"id":"s04-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is your dress?<br/><br>\n—— It's purple.</br></p>","options":["What time","What day","What colour"],"correct":2,"answer":"C"},{"id":"s04-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is it?<br/><br>\n—— It's 9:30.</br></p>","options":["What time","What date","What colour"],"correct":0,"answer":"A"},{"id":"s04-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is it today?<br/><br>\n—— It's July 2nd.</br></p>","options":["What time","What date","What day"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【沈阳·大东区】对画线部分提问。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s04-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">They are <u>red</u>.</p>","options":[],"correct":null,"answer":"What colour are they?\n解析：画线部分是颜色，故用 “What colour” 引导特殊疑问句。"},{"id":"s04-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I often go to bed <u>at half past eight</u>.</p>","options":[],"correct":null,"answer":"What time do you often go to bed?\n解析：画线部分是时间，故用 “What time” 引导特殊疑问句。"},{"id":"s04-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">His name is <u>Jason</u>.</p>","options":[],"correct":null,"answer":"What is his name?\n解析：画线部分是人名，故用 “What” 引导特殊疑问句。"},{"id":"s04-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I want <u>some milk</u>.</p>","options":[],"correct":null,"answer":"What do you want?\n解析：画线部分是物品，故用 “What” 引导特殊疑问句。"}],"questionCount":4,"hasAnswers":true}]},{"id":"s05","section":5,"unit":1,"unitName":"单元01 · 第01–06节","short":"第05节 · L9–10","title":"含 how 的特殊疑问句","lessons":"Lesson 9 — Lesson 10","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 how 的特殊疑问句</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>含 how 的特殊疑问句</strong></td>\n<td>how 的用法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">含 how 的特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。常用的疑问词有 what、who、whose、which、when、where、how、why 等。how 用来对感觉、方式、工具以及数量、距离、时间等进行提问。</p>\n<p class=\"source-line\">—— How are you, Binbin? 你好吗，彬彬？<br/>\n—— I'm well, thanks. 我很好，谢谢。</p>\n<p class=\"source-line\">—— How much is the suit? 这套西装多少钱？<br/>\n—— It's 130 yuan. 它 130 元。</p>\n<p class=\"source-line\">—— How often do you go shopping, Cindy? 你多久去购物一次，辛迪？<br/>\n—— I go shopping twice a month. 我一个月去购物两次。</p></div></div>\n<div class=\"g\"><div class=\"gt\">how 的用法</div><div class=\"gb\"><h5>1. 日常问候</h5>\n<p class=\"source-line\">—— How are you? 你好吗？<br/>\n—— I'm fine. 我很好。</p>\n<p class=\"source-line\">—— How is your mother? 你妈妈怎么样？<br/>\n—— She's very well. 她非常好。</p>\n<h5>2. 询问“感觉”</h5>\n<p class=\"source-line\">—— How do you feel? 你感觉怎么样？<br/>\n—— I feel terrible. 我感觉糟透了。</p>\n<h5>3. 询问“方式”</h5>\n<p class=\"source-line\">—— How do you go to school? 你怎样去上学？<br/>\n—— I go to school by bike. 我骑自行车去上学。</p>\n<h5>4. 询问“数（量）”</h5>\n<ul>\n<li><strong>how many</strong> 多少（询问可数事物的数量）\n—— How many people are there in your family? 你家里有几口人？<br/>\n—— Three. 3 口人。</li>\n<li><strong>how much</strong> 多少（询问不可数事物的量）\n—— How much water do you have? 你有多少水？<br/>\n—— Half a bottle. 半瓶。</li>\n</ul>\n<h5>5. 询问“价钱”</h5>\n<ul>\n<li><strong>how much</strong> 多少钱\n—— How much are these tomatoes? 这些西红柿多少钱？<br/>\n—— They're ten yuan. 它们 10 元。</li>\n</ul>\n<h5>6. 询问“年龄”</h5>\n<ul>\n<li><strong>how old</strong> 几岁\n—— How old are you? 你几岁了？<br/>\n—— I'm twenty years old. 我 20 岁了。</li>\n</ul>\n<h5>7. 询问“距离”</h5>\n<ul>\n<li><strong>how far</strong> 多远\n—— How far is it from here to your school? 从这儿到你学校有多远？<br/>\n—— It's five kilometres. 5 千米。</li>\n</ul>\n<h5>8. 询问“多长”或“多长时间”</h5>\n<ul>\n<li><strong>how long</strong> 多长\n—— How long is the river? 这条河多长？<br/>\n—— It's about 300 metres long. 它大约 300 米长。</li>\n<li><strong>how long</strong> 多长时间\n—— How long does it take you to go to school? 你去学校需要多长时间？<br/>\n—— It's about half an hour. 大约半个小时。</li>\n</ul>\n<h5>9. 询问“频率”</h5>\n<ul>\n<li><strong>how often</strong> 多久一次\n—— How often do you go to the cinema? 你多久去看一次电影？<br/>\n—— I go to the cinema once a week. 我一周去看一次电影。</li>\n</ul>\n<h5>10. 询问“多久”</h5>\n<ul>\n<li><strong>how soon</strong> 多久\n—— How soon will he be back? 他多久会回来？<br/>\n—— In an hour. 1 小时以后。</li>\n</ul></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s05-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">____ old is Mary?</p>","options":["How many","How"],"correct":1,"answer":"B"},{"id":"s05-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">____ books are there?</p>","options":["How many","How much"],"correct":0,"answer":"A"},{"id":"s05-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">____ children are in the park?</p>","options":["How many","How much"],"correct":0,"answer":"A"},{"id":"s05-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">____ is your arm?</p>","options":["How long","How far"],"correct":0,"answer":"A"},{"id":"s05-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">____ pens can you see?</p>","options":["How many","How soon"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s05-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">你爸爸现在好吗？（翻译句子）<br/>\n   ____ your father now?</p>","options":[],"correct":null,"answer":"How is your father now?"},{"id":"s05-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">你今天好吗？（翻译句子）<br/>\n   ____ today？</p>","options":[],"correct":null,"answer":"How are you today?"},{"id":"s05-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">He is English. （缩写句子）</p>","options":[],"correct":null,"answer":"He's English."},{"id":"s05-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">She is from Beijing. （缩写句子）</p>","options":[],"correct":null,"answer":"She's from Beijing."}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【佛山·禅城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s05-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> are you?<br/><br>\n—— I'm fine, thank you.</br></p>","options":["How old","What","How"],"correct":2,"answer":"C\n解析：答语意为 “我很好，谢谢你”, 应使用 “How are you?” 提问。"},{"id":"s05-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> does he visit his grandparents?<br/><br>\n—— Twice a month.</br></p>","options":["How much","How often","How long"],"correct":1,"answer":"B\n解析：答语意为 “一个月两次”, 应使用询问频率的 “How often...?”。"},{"id":"s05-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> water is there in the glass?<br/><br>\n—— There is a little water in the glass.</br></p>","options":["How much","How many","How soon"],"correct":0,"answer":"A\n解析：由答语可知问句询问水的量，应用 “How much...?” 提问。"},{"id":"s05-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is your younger brother?<br/><br>\n—— He is three years old.</br></p>","options":["How","How old","How tall"],"correct":1,"answer":"B\n解析：答语意为 “他 3 岁了”, 应用 “How old...?” 询问年龄。"},{"id":"s05-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> are those pants?<br/><br>\n—— They're 50 dollars.</br></p>","options":["How long","How far","How much"],"correct":2,"answer":"C\n解析：答语意为 “它们 50 美元”, 由此可知问句对价格进行提问，询问价格可以用 “How much... ?”。"},{"id":"s05-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> was your holiday?<br/><br>\n—— It was great!</br></p>","options":["How","How long","How soon"],"correct":0,"answer":"A\n解析：答语意为“它棒极了!”,问句应询问他人的感受，疑问词应用how。"}],"questionCount":6,"hasAnswers":true},{"source":"practice","title":"【天津·南开区】对画线部分提问。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s05-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My aunt goes to work <u>by subway</u>.</p>","options":[],"correct":null,"answer":"How does your aunt go to work?"},{"id":"s05-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I usually go to the library <u>four times a month</u>.</p>","options":[],"correct":null,"answer":"How often do you usually go to the library?"},{"id":"s05-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">The schoolbag is <u>seventy yuan</u>.</p>","options":[],"correct":null,"answer":"How much is the schoolbag?"},{"id":"s05-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">There are <u>fifty</u> apples in the basket.</p>","options":[],"correct":null,"answer":"How many apples are there in the basket?"}],"questionCount":4,"hasAnswers":true}]},{"id":"s06","section":6,"unit":1,"unitName":"单元01 · 第01–06节","short":"第06节 · L11–12","title":"含 whose 的特殊疑问句以及名词所有格","lessons":"Lesson 11 — Lesson 12","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>whose 的常见句型结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>名词所有格</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。</p>\n<p class=\"source-line\">常用的疑问词有 what、who、whose、which、when、where、how、why 等。</p>\n<p class=\"source-line\">whose 用于对物品的所属提问，意思是“谁的”。</p>\n<p class=\"source-line\">—— Whose coat is this? 这是谁的外套？<br/>\n—— It's my brother's. 它是我哥哥的。</p>\n<p class=\"source-line\">—— Whose glasses are those? 那副眼镜是谁的？<br/>\n—— They're my father's. 它们是我爸爸的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">whose 的常见句型结构</div><div class=\"gb\"><h5>1. Whose + 名词 + be 动词 + 主语？</h5>\n<p class=\"source-line\">在该句型中, whose 作定语, be 动词的变化主要取决于后面的主语。若主语为单数, be 动词用 is; 若主语为复数, be 动词用 are。另外, be 动词前面的名词的单复数形式要与主语保持一致。</p>\n<p class=\"source-line\">—— Whose schoolbag is this? 这是谁的书包？<br/>\n—— It's Mary's. 它是玛丽的。</p>\n<p class=\"source-line\">—— Whose sweaters are those? 那些是谁的毛衣？<br/>\n—— They're my mother's. 它们是我妈妈的。</p>\n<h5>2. Whose + be 动词 + 主语？</h5>\n<p class=\"source-line\">在该句型中，whose 作表语，be 动词的变化主要取决于后面的主语。若主语为单数，be 动词用 is；主语为复数，be 动词用 are。</p>\n<p class=\"source-line\">—— Whose is the pen? 这支钢笔是谁的？<br/>\n—— It's John's. 它是约翰的。</p>\n<p class=\"source-line\">—— Whose are those books? 那些书是谁的？<br/>\n—— They're Jack's. 它们是杰克的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词所有格</div><div class=\"gb\"><h5>1. 概念</h5>\n<p class=\"source-line\">名词所有格用来表示所属关系，常用“'s”或 of 构成。一般来说，“'s”多用于有生命的名词，of 所有格多用于无生命的名词，但实际使用中也有例外。</p>\n<p class=\"source-line\">Lucy's room is big. 露西的房间大。\nThe windows of the house are colourful. 这幢房子的窗户是彩色的。</p>\n<h5>2. 名词所有格的构成规则</h5>\n<p class=\"source-line\">（1） 单数名词，直接在词尾加 “'s”。</p>\n<p class=\"source-line\">the girl's bag 女孩儿的包</p>\n<p class=\"source-line\">his father's glasses 他爸爸的眼镜</p>\n<p class=\"source-line\">（2） 复数名词，不以 s 结尾时，在词尾加 “'s”。</p>\n<p class=\"source-line\">Women's Day 妇女节</p>\n<p class=\"source-line\">Children's Day 儿童节</p>\n<p class=\"source-line\">（3） 复数名词，以 s 结尾时，直接在词尾加 “'”。</p>\n<p class=\"source-line\">Teachers' Day 教师节\nthe students' books 学生们的书</p>\n<p class=\"source-line\">（4）表示共有时，在最后一个名词后面加“’s”;表示各自所有时，在每个名词后加“’s”。</p>\n<p class=\"source-line\">Kitty and Lily's room 姬蒂和莉莉的房间（共有一个房间）\nKitty's and Lily's rooms 姬蒂的房间和莉莉的房间（各有一个房间）</p>\n<p class=\"source-line\">（5）表示无生命的事物的所有格时，一般加 of 构成所有格，结构为 “名词+of+所有者”。</p>\n<p class=\"source-line\">the window of the room 这个房间的窗户\nthe map of China 中国地图</p>\n<p class=\"source-line\">（6）双重所有格表示整体中的一个部分，结构为“名词+of+名词所有格/名词性物主代词”。</p>\n<p class=\"source-line\">a friend of my father's 我爸爸的一个朋友</p>\n<p class=\"source-line\">an eraser of mine 我的一块橡皮</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s06-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is this?<br/><br>\n—— It's Mary's.</br></p>","options":["Who","Whose","Which"],"correct":1,"answer":"B"},{"id":"s06-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is Lucy now?<br/><br>\n—— She's in the car.</br></p>","options":["Whose","Which","Where"],"correct":2,"answer":"C"},{"id":"s06-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is it today?<br/><br>\n—— It's Monday.</br></p>","options":["What day","What time","What date"],"correct":0,"answer":"A"},{"id":"s06-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Whose books are these?<br/><br>\n—— <span class=\"blank-token\">____</span> Mr Smith's.</br></p>","options":["It's","They're","He's"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s06-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">它是玛丽的手提包。(Mary, handbag)</p>","options":[],"correct":null,"answer":"It's Mary's handbag."},{"id":"s06-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">它是保罗的车。(Paul, car)</p>","options":[],"correct":null,"answer":"It's Paul's car."},{"id":"s06-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">那是汤姆和约翰的房间。(Tom, John, room)</p>","options":[],"correct":null,"answer":"That is Tom and John's room."},{"id":"s06-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">我妈妈的妈妈是我的外婆。(mother, grandmother)</p>","options":[],"correct":null,"answer":"My mother's mother is my grandmother."}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【昆明·官渡区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s06-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">—— Whose pencil-case is it?<br/><br>\n—— It's <span class=\"blank-token\">____</span> (Lucy).</br></p>","options":[],"correct":null,"answer":"Lucy's\n解析：考查名词所有格。Lucy变名词所有格直接加“'s”即可。"},{"id":"s06-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">These are <span class=\"blank-token\">____</span> (teacher) books.</p>","options":[],"correct":null,"answer":"teachers'\n解析：根据句意应先把 teacher 变成复数形式 teachers, 以 s 结尾的复数名词变名词所有格在名词后加 “’” 即可。"},{"id":"s06-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">These are <span class=\"blank-token\">____</span> (Mike and Jim) rooms.</p>","options":[],"correct":null,"answer":"Mike's and Jim's\n解析：根据句中 rooms 可知 Mike 和 Jim 每人拥有一个房间，故在每个人名后加“'s”。"},{"id":"s06-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> (Who) cups are these?<br/><br>\n—— They're Andy's.</br></p>","options":[],"correct":null,"answer":"Whose\n解析：根据句意 “这些杯子是谁的？” 可知疑问词应填 “Whose”。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【惠州·惠阳区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s06-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">That isn't <span class=\"blank-token\">____</span> desk.</p>","options":["Sam","Sams","Sam's"],"correct":2,"answer":"C"},{"id":"s06-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">The third Sunday in June is <span class=\"blank-token\">____</span> Day, right?</p>","options":["Father","Father's","Fathers"],"correct":1,"answer":"B"},{"id":"s06-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> jacket is it?<br/><br>\n—— It's Tim's.</br></p>","options":["Whose","Which","What"],"correct":0,"answer":"A"},{"id":"s06-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> sister is an English teacher.</p>","options":["Jim's and Kate's","Jim and Kate's","Jim and Kate"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true}]},{"id":"s07","section":7,"unit":2,"unitName":"单元02 · 第07–12节","short":"第07节 · L13–14","title":"what colour 引导的特殊疑问句、祈使句","lessons":"Lesson 13 — Lesson 14","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>what colour 引导的特殊疑问句、祈使句</strong></td>\n<td>what colour 引导的特殊疑问句</td>\n<td>★</td>\n<td>★</td>\n</tr>\n<tr>\n<td><strong>what colour 引导的特殊疑问句、祈使句</strong></td>\n<td>祈使句</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">what colour 引导的特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。常用的疑问词有what、who、whose、which、when、where、how、why等。what colour引导的特殊疑问句通常询问某物的颜色。类似的还有how often问频率，how old问年龄，how much问价格等。</p>\n<p class=\"source-line\">—— What colour is the bag? 这个包是什么颜色的？<br/>\n—— It's black. 它是黑色的。</p>\n<p class=\"source-line\">—— What colour are these crayons? 这些蜡笔是什么颜色的？<br/>\n—— They're red, yellow and green. 它们是红色、黄色和绿色的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句</div><div class=\"gb\"><p class=\"source-line\">表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.)。为表示礼貌，可在句首或句末加上“please”。朗读时通常用降调。</p>\n<p class=\"source-line\">有时为了加强语气，可在动词原形前加do。如:Do be quiet, please! 请安静!</p>\n<p class=\"source-line\">Come in, please. 请进。</p>\n<p class=\"source-line\">Be careful next time! 下次小心点儿!</p>\n<p class=\"source-line\">Let me try. 让我试试。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句常见的三种类型</div><div class=\"gb\"><h5>1. Be 型：Be + 其他</h5>\n<p class=\"source-line\">Be quiet! 安静!</p>\n<h5>2. Do 型：实义动词原形（+ 其他）</h5>\n<p class=\"source-line\">Shut up. 闭嘴。</p>\n<p class=\"source-line\">Don't talk. 不要说话。</p>\n<h5>3. Let 型：Let + 宾语 + 动词原形（+ 其他）</h5>\n<p class=\"source-line\">Let's go. 让我们一起去。</p>\n<p class=\"source-line\">Let him not go. 别让他去。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"补全对话","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is your new tie?<br/><br>\n—— It's green.</br></p>","options":[],"correct":null,"answer":"What colour"},{"id":"s07-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> colour is your new car?<br/><br>\n—— It's black.</br></p>","options":[],"correct":null,"answer":"What"},{"id":"s07-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">—— What colour do you like?<br/><br>\n—— I <span class=\"blank-token\">____</span> blue.</br></p>","options":[],"correct":null,"answer":"like"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> get off the bus before it stops.</p>","options":["Don't","Doesn't","Didn't","Won't"],"correct":0,"answer":"A"},{"id":"s07-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">It's hot. <span class=\"blank-token\">____</span> the window, please.</p>","options":["Open","Close","Opening","Closing"],"correct":0,"answer":"A"},{"id":"s07-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> me your ticket, please.</p>","options":["Showing","Showed","Show","To show"],"correct":2,"answer":"C"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"英汉互译","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">不要迟到。</p>","options":[],"correct":null,"answer":"Don't be late."},{"id":"s07-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">安静！</p>","options":[],"correct":null,"answer":"Be quiet!"},{"id":"s07-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">看我！</p>","options":[],"correct":null,"answer":"Look at me!"},{"id":"s07-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Don't be sad.</p>","options":[],"correct":null,"answer":"不要伤心。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【惠州·惠城区】判断题：判断下列句子是否为祈使句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Take off your jacket.</p>","options":["正确","错误"],"correct":0,"answer":"A"},{"id":"s07-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Let's play games.</p>","options":["正确","错误"],"correct":0,"answer":"A"},{"id":"s07-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">How are you?</p>","options":["正确","错误"],"correct":1,"answer":"B"},{"id":"s07-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't play football in the classroom.</p>","options":["正确","错误"],"correct":0,"answer":"A"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【昆明·五华区】选择题：选择正确的单词完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">____ careful. The bus is coming.</p>","options":["Is","Be"],"correct":1,"answer":"B\n解析：此句是 Be 型祈使句。位于句首时，be 使用原形并大写首字母。"},{"id":"s07-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Let's <span class=\"blank-token\">____</span> to school together.</p>","options":["go","goes"],"correct":0,"answer":"A\n解析：此句是 Let 型祈使句，Let's 后接动词原形。"},{"id":"s07-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> on and join us!</p>","options":["Comes","Come"],"correct":1,"answer":"B\n解析：此句是 Do 型祈使句，实义动词使用原形。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【昆明·五华区】将下列句子改为祈使句","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s07-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">You can sit on this chair.</p>","options":[],"correct":null,"answer":"Sit on this chair."},{"id":"s07-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">You must sweep the floor carefully.</p>","options":[],"correct":null,"answer":"Sweep the floor carefully."},{"id":"s07-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">You should stay at home today.</p>","options":[],"correct":null,"answer":"Stay at home today."}],"questionCount":3,"hasAnswers":true}]},{"id":"s08","section":8,"unit":2,"unitName":"单元02 · 第07–12节","short":"第08节 · L15–16","title":"可数名词单复数变化规则（一）","lessons":"Lesson 15 — Lesson 16","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>可数名词单复数变化规则（一）</strong></td>\n<td>可数名词的概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>可数名词单复数变化规则（一）</strong></td>\n<td>名词单数变复数的规则变化</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">可数名词的概念</div><div class=\"gb\"><p class=\"source-line\">一般可以用数目来计算的名词叫可数名词，一般无法用数目来计算的名词叫不可数名词。在英语语法中，可数名词有单数和复数两种形式。表示一个人或事物时用单数，表示一个以上的人或事物时用复数。</p>\n<p class=\"source-line\">I want to drink some water. 我想喝些水。</p>\n<p class=\"source-line\">I have two good friends.</p>\n<p class=\"source-line\">我有2个好朋友。</p>\n<p class=\"source-line\">There are three suitcases. 有 3 个手提箱。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词单数变复数的规则变化</div><div class=\"gb\"><h5>1. 一般情况下，在词尾加 s</h5>\n<p class=\"source-line\">book → books 书 room → rooms 房间 pear → pears 梨</p>\n<p class=\"source-line\">house → houses 房子 day → days 天 song → songs 歌曲</p>\n<h5>2. 以 s、x、sh、ch 结尾的名词，在词尾加 es。如：</h5>\n<p class=\"source-line\">bus → buses 公共汽车 box → boxes 箱子</p>\n<p class=\"source-line\">watch → watches 手表 dish → dishes 盘子</p>\n<h5>3. 以“辅音字母 + y”结尾的名词，先变 y 为 i，再加 es</h5>\n<p class=\"source-line\">city → cities 城市 body → bodies 身体</p>\n<p class=\"source-line\">story → stories 故事</p>\n<p class=\"source-line\">factory → factories 工厂</p>\n<h5>4. 以 o 结尾的名词</h5>\n<p class=\"source-line\">多数以 o 结尾的名词直接加 s，部分常用词加 es。</p>\n<p class=\"source-line\">直接加 s：piano → pianos 钢琴</p>\n<p class=\"source-line\">radio → radios 收音机</p>\n<p class=\"source-line\">加 es：potato → potatoes 土豆</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">hero、potato、tomato、mango 等常用词的复数形式加 es。</p></div>\n<p class=\"source-line\">hero → heroes 英雄</p>\n<h5>5. 以 f 或 fe 结尾的名词</h5>\n<p class=\"source-line\">部分以 f 或 fe 结尾的名词，先将 f 或 fe 变为 v，再加 es。</p>\n<p class=\"source-line\">half → halves 一半</p>\n<p class=\"source-line\">leaf → leaves 树叶</p>\n<p class=\"source-line\">knife → knives 刀</p>\n<p class=\"source-line\">wife → wives 妻子</p>\n<div class=\"custom-block note\"><div class=\"custom-block-title\">注意</div><p class=\"source-line\">并非所有以 f 或 fe 结尾的名词都变为 ves，例如 roof → roofs、chief → chiefs。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"把下列可数名词由单数变为复数","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s08-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">book</p>","options":[],"correct":null,"answer":"books"},{"id":"s08-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">suit</p>","options":[],"correct":null,"answer":"suits"},{"id":"s08-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">factory</p>","options":[],"correct":null,"answer":"factories"},{"id":"s08-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">tie</p>","options":[],"correct":null,"answer":"ties"},{"id":"s08-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">passport</p>","options":[],"correct":null,"answer":"passports"},{"id":"s08-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">box</p>","options":[],"correct":null,"answer":"boxes"},{"id":"s08-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">umbrella</p>","options":[],"correct":null,"answer":"umbrellas"},{"id":"s08-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">dog <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"dogs"},{"id":"s08-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">baby</p>","options":[],"correct":null,"answer":"babies"},{"id":"s08-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">shelf</p>","options":[],"correct":null,"answer":"shelves"},{"id":"s08-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">city</p>","options":[],"correct":null,"answer":"cities"},{"id":"s08-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">boy</p>","options":[],"correct":null,"answer":"boys"},{"id":"s08-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">fox</p>","options":[],"correct":null,"answer":"foxes"},{"id":"s08-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">dish</p>","options":[],"correct":null,"answer":"dishes"},{"id":"s08-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">sandwich</p>","options":[],"correct":null,"answer":"sandwiches"}],"questionCount":15,"hasAnswers":true},{"source":"textbook","title":"用所给词的正确形式填空","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s08-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">There are nine <span class=\"blank-token\">____</span> (apple) on the desk.</p>","options":[],"correct":null,"answer":"apples"},{"id":"s08-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">The boy has two <span class=\"blank-token\">____</span> (watch).</p>","options":[],"correct":null,"answer":"watches"},{"id":"s08-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">A cat has four <span class=\"blank-token\">____</span> (foot).</p>","options":[],"correct":null,"answer":"feet"},{"id":"s08-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">There are 25 <span class=\"blank-token\"><strong><em>_</em></strong></span> (girl) and 15 <span class=\"blank-token\">_</span> (boy) in the group.</p>","options":[],"correct":null,"answer":"girls, boys"},{"id":"s08-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">I have a lot of <span class=\"blank-token\">____</span> (tomato) here.</p>","options":[],"correct":null,"answer":"tomatoes"},{"id":"s08-text-q021","number":21,"type":"input","questionHtml":"<p class=\"source-line\">Look, a <span class=\"blank-token\">____</span> (kite) is in the tree.</p>","options":[],"correct":null,"answer":"kite"},{"id":"s08-text-q022","number":22,"type":"input","questionHtml":"<p class=\"source-line\">There are many <span class=\"blank-token\">____</span> (bus) on the road.</p>","options":[],"correct":null,"answer":"buses"},{"id":"s08-text-q023","number":23,"type":"input","questionHtml":"<p class=\"source-line\">Three <span class=\"blank-token\">____</span> (photo) are on the table.</p>","options":[],"correct":null,"answer":"photos"},{"id":"s08-text-q024","number":24,"type":"input","questionHtml":"<p class=\"source-line\">The <span class=\"blank-token\">____</span> (plane) are in the sky.</p>","options":[],"correct":null,"answer":"planes"},{"id":"s08-text-q025","number":25,"type":"input","questionHtml":"<p class=\"source-line\">My father likes to eat <span class=\"blank-token\">____</span> (potato).</p>","options":[],"correct":null,"answer":"potatoes"}],"questionCount":10,"hasAnswers":true},{"source":"practice","title":"【昆明·西山区】单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s08-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I am 12 <span class=\"blank-token\">____</span> old.</p>","options":["years","year","yeares","/"],"correct":0,"answer":"A\n解析：当年龄大于 1 时, year （岁） 要变为复数形式，即在 year 后面加 “s”, 变为 years。"},{"id":"s08-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Look at these <span class=\"blank-token\">____</span>.</p>","options":["pear","pears","peares","a pear"],"correct":1,"answer":"B\n解析：these （这些） 是复数, pear （梨） 应变为复数形式，即在词尾加 “s”, 变为 pears。"},{"id":"s08-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I have two long <span class=\"blank-token\"><strong><em>_</em></strong></span> and two big <span class=\"blank-token\">_</span>.</p>","options":["feet; leg","legs; foot","legs; feet","leg; foot"],"correct":2,"answer":"C\n解析：two（两个）后接复数名词。leg（腿）变复数形式在词尾加“s”, 变为 legs。foot （脚）的复数形式为 feet。"},{"id":"s08-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! <span class=\"blank-token\">____</span> are eating our sandwiches.</p>","options":["The duck","This duck","These ducks","A duck"],"correct":2,"answer":"C\n解析：由 be 动词 are 可知主语为复数，只有 C 选项符合语法。"},{"id":"s08-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Here are some <span class=\"blank-token\"><strong><em>_</em></strong></span> in these <span class=\"blank-token\">_</span>.</p>","options":["knifes; pencil boxes","knife; pencils boxes","knives; pencils boxes","knives; pencil boxes"],"correct":3,"answer":"D\n解析：some （一些） 和 these （这些） 均表示复数。knife （刀） 的复数形式为 knives, pencil box （铅笔盒） 的复数形式为 pencil boxes, 故此题选择 D 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【深圳·福田区】填入所给名词的正确形式","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s08-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I have two <span class=\"blank-token\">____</span> (knife).</p>","options":[],"correct":null,"answer":"knives\n解析：two（二）后接复数名词。knife 的复数形式为 knives。"},{"id":"s08-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">A few <span class=\"blank-token\">____</span> (boy) are drawing on the wall.</p>","options":[],"correct":null,"answer":"boys\n解析：a few （一些; 几个） 常用来修饰可数名词复数。boy 的复数形式是 boys。"},{"id":"s08-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Please take those <span class=\"blank-token\">____</span> (photo) for me.</p>","options":[],"correct":null,"answer":"photos\n解析：those（那些）后接可数名词复数。photo 的复数形式是 photos。"},{"id":"s08-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Do you want some <span class=\"blank-token\">____</span> (milk)?</p>","options":[],"correct":null,"answer":"milk\n解析：some （一些）既可以修饰可数名词，又可以修饰不可数名词。milk （牛奶）为不可数名词，所以应填 milk。"},{"id":"s08-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">I like these red <span class=\"blank-token\">____</span> (tomato).</p>","options":[],"correct":null,"answer":"tomatoes\n解析：these（这些）后接可数名词复数。tomato 的复数形式是 tomatoes。"}],"questionCount":5,"hasAnswers":true}]},{"id":"s09","section":9,"unit":2,"unitName":"单元02 · 第07–12节","short":"第09节 · L17–18","title":"可数名词单复数变化规则（二）","lessons":"Lesson 17 — Lesson 18","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>可数名词单复数变化规则（二）</strong></td>\n<td>概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>可数名词单复数变化规则（二）</strong></td>\n<td>名词单数变复数的不规则变化</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">可数名词</div><div class=\"gb\"><p class=\"source-line\">一般可以用数目来计算的名词叫可数名词，一般无法用数目来计算的名词叫不可数名词。在英语语法中，可数名词有单数和复数两种形式。表示一个人或事物时用单数，表示一个以上的人或事物时用复数。</p>\n<p class=\"source-line\">The fish swim in the river.\n鱼在河里游泳。</p>\n<p class=\"source-line\">The children are playing on the playground. 孩子们正在操场上玩儿。</p>\n<p class=\"source-line\">There are 15 women teachers in our school.\n我们学校有 15 名女教师。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词单数变复数的不规则变化</div><div class=\"gb\"><h5>1. 元音字母发生变化。如：</h5>\n<p class=\"source-line\">man → men 男人</p>\n<p class=\"source-line\">woman → women 女人</p>\n<p class=\"source-line\">goose → geese 鹅</p>\n<p class=\"source-line\">foot → feet 脚</p>\n<p class=\"source-line\">tooth → teeth 牙齿</p>\n<p class=\"source-line\">以 man 或 woman 为核心词的复合名词变复数时，通常将 man 变为 men、woman 变为 women；German、human 等并不适用此规则。如：an Englishman → two Englishmen, a woman teacher → two women teachers。</p>\n<h5>2. 词尾发生变化。如：</h5>\n<p class=\"source-line\">child → children 孩子</p>\n<p class=\"source-line\">ox → oxen 公牛</p>\n<h5>3. 单复数同形。如：</h5>\n<p class=\"source-line\">Chinese → Chinese 中国人</p>\n<p class=\"source-line\">Japanese → Japanese 日本人</p>\n<p class=\"source-line\">deer → deer 鹿</p>\n<p class=\"source-line\">fish → fish 鱼</p>\n<p class=\"source-line\">sheep → sheep 绵羊</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">男人女人 a 变 e，鹅足牙 oo 变 ee；小孩儿加上 ren，老鼠变成 ice；中日小鹿鱼绵羊，单数复数一个样。</p></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">中（Chinese）日（Japanese）不变，英（Englishman → Englishmen）法（Frenchman → Frenchmen）变，其余通常在词尾加 s。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"把下列可数名词由单数变为复数","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s09-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">mechanic <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"mechanics"},{"id":"s09-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">teacher <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"teachers"},{"id":"s09-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">customs officer <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"customs officers"},{"id":"s09-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">taxi driver <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"taxi drivers"},{"id":"s09-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">housewife <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"housewives"},{"id":"s09-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">policeman <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"policemen"},{"id":"s09-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">girlfriend <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"girlfriends"},{"id":"s09-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">path <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"paths"},{"id":"s09-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">mouse <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"mice"},{"id":"s09-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">foot <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"feet"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s09-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">There are <span class=\"blank-token\"><strong><em>_</em></strong></span> and <span class=\"blank-token\">_</span>.</p>","options":["sheep; dogs","sheep; dog","sheeps; dog"],"correct":0,"answer":"A"},{"id":"s09-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">There are some <span class=\"blank-token\"><strong><em>_</em></strong></span> and <span class=\"blank-token\">_</span> in the basket.</p>","options":["tomatoes; potatos","tomatos; potatos","tomatoes; potatoes"],"correct":2,"answer":"C"},{"id":"s09-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Both my father and my brother are <span class=\"blank-token\">____</span>.</p>","options":["policemen","policewomen","police officer"],"correct":0,"answer":"A"},{"id":"s09-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">These boys want to be <span class=\"blank-token\">____</span> in the future.</p>","options":["man doctors","men doctors","man's doctors"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用所给词的适当形式填空","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s09-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">Six <span class=\"blank-token\">____</span> (sheep) are in the field.</p>","options":[],"correct":null,"answer":"sheep"},{"id":"s09-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">30 <span class=\"blank-token\">____</span> (day) is a long time for me.</p>","options":[],"correct":null,"answer":"days"},{"id":"s09-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">Some <span class=\"blank-token\">____</span> (mouse) are in the hole.</p>","options":[],"correct":null,"answer":"mice"},{"id":"s09-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">Chinese <span class=\"blank-token\">____</span> (people) like to eat noodles.</p>","options":[],"correct":null,"answer":"people"},{"id":"s09-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">I have two <span class=\"blank-token\">____</span> (pencil-box).</p>","options":[],"correct":null,"answer":"pencil-boxes"},{"id":"s09-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">There are some <span class=\"blank-token\">____</span> (child) in the garden.</p>","options":[],"correct":null,"answer":"children"}],"questionCount":6,"hasAnswers":true},{"source":"practice","title":"【惠州·惠城区】写出下列单词的复数形式","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s09-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">tooth <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"teeth"},{"id":"s09-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">man <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"men"},{"id":"s09-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">piano <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"pianos"},{"id":"s09-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">sheep <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"sheep"},{"id":"s09-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">child <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"children"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【蚌埠·禹会区】单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s09-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I have two <span class=\"blank-token\"><strong><em>_</em></strong></span> and three sharp <span class=\"blank-token\">_</span>.</p>","options":["watches; knives","watchs; knives","watches; knifes"],"correct":0,"answer":"A\n解析：two （二） 和 three （三） 后接可数名词的复数形式。watch 的复数形式为 watches, knife 的复数形式为 knives。"},{"id":"s09-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">There are ten <span class=\"blank-token\">____</span> in our class.</p>","options":["Germen","Germans","German"],"correct":1,"answer":"B\n解析：ten （十） 后面的名词要用可数名词的复数形式。German 的复数形式是 Germans。"},{"id":"s09-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Can you see nine <span class=\"blank-token\">____</span> in the picture?</p>","options":["fish","bookes","horse"],"correct":0,"answer":"A\n解析：nine（九）后接可数名词的复数形式。B 选项 bookes 写法错误。C 选项 horse （马）为单数名词。A 选项 fish（鱼）单复数同形。故本题选择 A 选项。"},{"id":"s09-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">The <span class=\"blank-token\"><strong><em>_</em></strong></span> begin to eat the green <span class=\"blank-token\">_</span> of young trees.</p>","options":["deer; leaves","deer; leafs","deers; leaf"],"correct":0,"answer":"A\n解析：句意为 “鹿开始吃小树的绿叶”, 由 begin （开始） 可知主语应为可数名词复数, deer （鹿） 的复数形式为 deer, leaf （叶子） 的复数形式为 leaves。故本题选择 A 选项。"},{"id":"s09-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">She must look after those <span class=\"blank-token\">____</span>.</p>","options":["dog","geese","animal"],"correct":1,"answer":"B\n解析：those （那些） 后接复数名词, A、C 选项均为单数名词。B 选项 geese 为 goose （鹅） 的复数形式。故此题选择 B 选项。"}],"questionCount":5,"hasAnswers":true}]},{"id":"s10","section":10,"unit":2,"unitName":"单元02 · 第07–12节","short":"第10节 · L19–20","title":"There be 句型","lessons":"Lesson 19 — Lesson 20","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的形式</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的就近原则</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">There be 句型的概念</div><div class=\"gb\"><p class=\"source-line\">在英语中, There be 句型表示 “某地存在某人或某物”。there 是无意义的引导词，在句中不充当任何成分。be 后面的名词是主语，两者在数上必须一致。句子最后面是地点或时间状语。</p>\n<p class=\"source-line\">There is a book on the desk.</p>\n<p class=\"source-line\">书桌上有一本书。</p>\n<p class=\"source-line\">There are some candies in the box.\n箱子里有一些糖果。</p></div></div>\n<div class=\"g\"><div class=\"gt\">There be 句型的形式</div><div class=\"gb\"><h5>1. 肯定句：There be + 主语 + 地点 / 时间状语</h5>\n<p class=\"source-line\">There is a new bike in front of the house.</p>\n<p class=\"source-line\">房子前面有一辆新自行车。</p>\n<p class=\"source-line\">There are twelve months in a year. 一年有 12 个月。</p>\n<h5>2. 否定句：There be + not any + 主语 + 地点 / 时间状语，或 There be + no + 主语 + 地点 / 时间状语</h5>\n<p class=\"source-line\">There are no mangoes on the desk. = There aren't any mangoes on the desk.\n书桌上没有芒果。</p>\n<p class=\"source-line\">There is no ink in the bottle. 瓶子里没有墨水。</p>\n<h5>3. 疑问句</h5>\n<p class=\"source-line\">（1）一般疑问句：只需将 be 提到 there 前。</p>\n<p class=\"source-line\">—— Is there a river in the forest? 森林里有条河吗？<br/>\n—— Yes, there is. 是的，有。</p>\n<p class=\"source-line\">—— Are there any candies in your bag? 你包里有糖果吗？<br/>\n—— No, there aren't. 不，没有。</p>\n<p class=\"source-line\">（2）特殊疑问句：常由 how many 或 how much 引导。</p>\n<p class=\"source-line\">—— How many students are there in your class? 你们班有多少名学生？<br/>\n—— There are forty students in our class. 我们班有 40 名学生。</p>\n<p class=\"source-line\">—— How much money is there in your bag? 你包里有多少钱？<br/>\n—— There's no money in my bag. 我包里没有钱。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">“有”字放前面，有“啥”放中间，地点（时间）放后面。单数用 is（was），复数用 are（were），注意 be 的变化。</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">There be 句型的就近原则</div><div class=\"gb\"><p class=\"source-line\">当 There be 句型中有两个或两个以上的主语时, be 的形式由离其最近的主语的单复数形式决定。</p>\n<p class=\"source-line\">There is a cock and five hens near the house.</p>\n<p class=\"source-line\">房子附近有1只公鸡和5只母鸡。</p>\n<p class=\"source-line\">There are five hens and a cock near the house.</p>\n<p class=\"source-line\">房子附近有 5 只母鸡和 1 只公鸡。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"选择题：选择恰当的 be 动词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s10-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> an eraser in the pencil case.</p>","options":["are","is"],"correct":1,"answer":"B"},{"id":"s10-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> bananas on the table.</p>","options":["is","are"],"correct":1,"answer":"B"},{"id":"s10-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> a book and three pencils on the desk.</p>","options":["are","is"],"correct":1,"answer":"B"},{"id":"s10-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some pears and a banana in the fridge.</p>","options":["is","are"],"correct":1,"answer":"B"},{"id":"s10-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some apples in the basket.</p>","options":["are","is"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s10-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">There are some pears on the tree. （变为一般疑问句，并作肯定和否定回答）</p>","options":[],"correct":null,"answer":"Are there any pears on the tree?\nYes, there are.\nNo, there aren't."},{"id":"s10-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">There is some orange juice in the glass. （变为否定句）</p>","options":[],"correct":null,"answer":"There isn't any orange juice in the glass."},{"id":"s10-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">There is a swing on the playground. （变为一般疑问句，并作肯定和否定回答）</p>","options":[],"correct":null,"answer":"Is there a swing on the playground?\nYes, there is.\nNo, there isn't."},{"id":"s10-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">There are <u>forty</u> pupils in Miss Wang's class.（对画线部分提问）</p>","options":[],"correct":null,"answer":"How many pupils are there in Miss Wang's class?"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s10-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> many trees here two years ago.</p>","options":["was","is","are","were"],"correct":3,"answer":"D"},{"id":"s10-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some interesting books in the school library now.</p>","options":["is","are","was","were"],"correct":1,"answer":"B"},{"id":"s10-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">How many days <span class=\"blank-token\">____</span> in a week?</p>","options":["are there","is there","have","were there"],"correct":0,"answer":"A"},{"id":"s10-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some juice in the bottle.</p>","options":["be","are","have","is"],"correct":3,"answer":"D"},{"id":"s10-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> any trees near the house.</p>","options":["are","aren't","is","isn't"],"correct":1,"answer":"B"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【合肥·包河区】选择题：选择括号内的正确单词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s10-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">There ____ twelve months in a year.</p>","options":["are","is"],"correct":0,"answer":"A"},{"id":"s10-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">There ____ some milk in the bottle.</p>","options":["is","isn't"],"correct":0,"answer":"A"},{"id":"s10-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There are some ____ in the garden.</p>","options":["flower","flowers"],"correct":1,"answer":"B"},{"id":"s10-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">There ____ any books on the shelf.</p>","options":["are","aren't"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【昆明·五华区】单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s10-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> an apple and two oranges on the table.</p>","options":["is","are","were"],"correct":0,"answer":"A\n解析：an apple （一个苹果） 为单数形式，故 be 用 is。"},{"id":"s10-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> seven days in a week.</p>","options":["is","are","was"],"correct":1,"answer":"B\n解析：seven days （7 天） 为复数形式，故 be 用 are。"},{"id":"s10-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">How many desks <span class=\"blank-token\">____</span> in your classroom?</p>","options":["there are","is there","are there"],"correct":2,"answer":"C\n解析：此题是由 how many 引导的特殊疑问句, desks 为可数名词复数，故选 are there。"},{"id":"s10-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> is there on the table?</p>","options":["How many apples","How much bread","How much breads"],"correct":1,"answer":"B\n解析：由 is there 可知此句主语应是不可数名词, how much （多少）询问不可数名词的量, bread（面包）为不可数名词，无复数形式，故此题选择 B 选项。"}],"questionCount":4,"hasAnswers":true}]},{"id":"s11","section":11,"unit":2,"unitName":"单元02 · 第07–12节","short":"第11节 · L21–22","title":"人称代词宾格","lessons":"Lesson 21 — Lesson 22","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>人称代词宾格</strong></td>\n<td>人称代词宾格</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">人称代词</div><div class=\"gb\"><p class=\"source-line\">人称代词是表示“你、我、他”等人称的代词，是为了避免重复，用来代替前面提到过的人、动物、事物等名称的词。人称代词根据用法不同而有人称、数与格的变化。</p>\n<p class=\"source-line\">He is a boy.\n他是一个男孩儿。</p>\n<p class=\"source-line\">Give me an envelope, please. 请给我一个信封。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词的主格、宾格</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>数</th>\n<th>主格</th>\n<th>宾格</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>单数</td>\n<td>I</td>\n<td>me</td>\n</tr>\n<tr>\n<td>第一人称</td>\n<td>复数</td>\n<td>we</td>\n<td>us</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>单数</td>\n<td>you</td>\n<td>you</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>复数</td>\n<td>you</td>\n<td>you</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>单数</td>\n<td>he / she / it</td>\n<td>him / her / it</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>复数</td>\n<td>they</td>\n<td>them</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">我用 me，你用 you；男他 him，女她 her；动植物它用 it。我们用 us，你们用 you，他们、她们、它们全用 them。</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词主格的用法</div><div class=\"gb\"><h5>1. 用于句子开头作主语。</h5>\n<p class=\"source-line\">He is a doctor. 他是一名医生。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词宾格的用法</div><div class=\"gb\"><h5>1. 在 be 动词后作表语。</h5>\n<p class=\"source-line\">—— Who is it? 是谁？<br/>\n—— It's me. 是我。</p>\n<h5>2. 在动词和介词后作宾语。</h5>\n<p class=\"source-line\">The ducklings follow him. 这些小鸭子跟着他。</p>\n<p class=\"source-line\">He runs after them. 他追赶它们。</p>\n<p class=\"source-line\">人称代词宾格巧用：代词宾格不动脑，跟着动词介词跑。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"选择题：选择正确的人称代词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s11-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> am wearing a white coat.</p>","options":["Me","I"],"correct":1,"answer":"B"},{"id":"s11-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">These green shoes are nice. I like <span class=\"blank-token\">____</span>.</p>","options":["they","them"],"correct":1,"answer":"B"},{"id":"s11-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! There are some rabbits. Oh! <span class=\"blank-token\">____</span> are so cute.</p>","options":["Them","They"],"correct":1,"answer":"B"},{"id":"s11-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Ann is a good student. <span class=\"blank-token\">____</span> is good at English. Her teacher likes her.</p>","options":["She","Her"],"correct":0,"answer":"A"},{"id":"s11-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Look! Some boys are playing football. Who is the boy in the green T-shirt?<br/><br>\n—— <span class=\"blank-token\">____</span> is Robert. He is my good friend.</br></p>","options":["Him","He"],"correct":1,"answer":"B"},{"id":"s11-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Give <span class=\"blank-token\">____</span> a toy, please.</p>","options":["he","him"],"correct":1,"answer":"B"},{"id":"s11-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Let <span class=\"blank-token\">____</span> help you.</p>","options":["me","I"],"correct":0,"answer":"A"},{"id":"s11-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">____ can go there by bus.</p>","options":["We","Us"],"correct":0,"answer":"A"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s11-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Look at <span class=\"blank-token\">____</span>.</p>","options":["he","him","his"],"correct":1,"answer":"B"},{"id":"s11-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> is short.</p>","options":["She","Her","me"],"correct":0,"answer":"A"},{"id":"s11-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">Let <span class=\"blank-token\">____</span> help you.</p>","options":["I","We","me"],"correct":2,"answer":"C"},{"id":"s11-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> are from China.</p>","options":["They","Them","Him"],"correct":0,"answer":"A"},{"id":"s11-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Give <span class=\"blank-token\">____</span> some bananas.</p>","options":["they","we","them"],"correct":2,"answer":"C"},{"id":"s11-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> are a good teacher.</p>","options":["Them","Us","You"],"correct":2,"answer":"C"},{"id":"s11-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't know <span class=\"blank-token\">____</span>.</p>","options":["she","he","her"],"correct":2,"answer":"C"},{"id":"s11-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">Come with <span class=\"blank-token\">____</span>.</p>","options":["I","me","they"],"correct":1,"answer":"B"}],"questionCount":8,"hasAnswers":true},{"source":"practice","title":"【佛山·南海区】单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s11-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Can you find <span class=\"blank-token\">____</span>?</p>","options":["they","them","he"],"correct":1,"answer":"B\n解析：find（找到）为实义动词，后接人称代词宾格。"},{"id":"s11-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> is a tall boy.</p>","options":["She","He","They"],"correct":1,"answer":"B"},{"id":"s11-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Let <span class=\"blank-token\">____</span> clean the floor.</p>","options":["me","I","we"],"correct":0,"answer":"A"},{"id":"s11-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I can't find my books. Where <span class=\"blank-token\">____</span>?</p>","options":["is it","are they","are you"],"correct":1,"answer":"B\n解析：第一句的句意为 “我找不到我的书了”, 其中 books （书） 为复数形式，故第二句中的 be 动词用 are, 人称代词用 they。故本题选择 B 选项。"},{"id":"s11-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">They are my good friends. I love <span class=\"blank-token\"><strong><em>_</em></strong></span> and they love <span class=\"blank-token\">_</span>.</p>","options":["they; me","them; I","them; me"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【滁州·琅琊区】用括号内人称代词的适当形式填空","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s11-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">John and I are in the same school. <span class=\"blank-token\">____</span> (we) go to school together.</p>","options":[],"correct":null,"answer":"We"},{"id":"s11-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Everyone likes <span class=\"blank-token\">____</span> (she).</p>","options":[],"correct":null,"answer":"her"},{"id":"s11-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> (I) have many friends. Some of <span class=\"blank-token\">_</span> (they) are good at English.</p>","options":[],"correct":null,"answer":"I; them"},{"id":"s11-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">They are waiting for <span class=\"blank-token\">____</span> (he).</p>","options":[],"correct":null,"answer":"him\n解析：for 为介词，后接人称代词宾格, he 的宾格为 him。"},{"id":"s11-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> (she) is going to the shop with <span class=\"blank-token\">_</span> (I).</p>","options":[],"correct":null,"answer":"She; me"}],"questionCount":5,"hasAnswers":true}]},{"id":"s12","section":12,"unit":2,"unitName":"单元02 · 第07–12节","short":"第12节 · L23–24","title":"介词 on 的用法","lessons":"Lesson 23 — Lesson 24","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>介词 on 的用法</strong></td>\n<td>介词的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>介词 on 的用法</strong></td>\n<td>介词 on 的用法</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">介词的概念</div><div class=\"gb\"><p class=\"source-line\">介词用来表示其后面的名词、代词或相当于名词的短语、从句与句中其他成分之间的关系。它是一种虚词。它不能独立充当句子成分，必须与名词、代词或相当于名词的其他词类、短语或从句构成介词短语，充当句子成分。</p>\n<p class=\"source-line\">常见的介词有 in、on、at、under、of、for 等。</p>\n<p class=\"source-line\">in January 在 1 月</p>\n<p class=\"source-line\">on June 1st 在 6 月 1 日</p>\n<p class=\"source-line\">at 12 o'clock 在 12:00</p>\n<p class=\"source-line\">under the desk 在书桌下面</p>\n<p class=\"source-line\">This is a photo of my family. 这是一张我家人的照片。</p>\n<p class=\"source-line\">What can I do for you? 我可以为你做什么？</p></div></div>\n<div class=\"g\"><div class=\"gt\">介词 on 的用法</div><div class=\"gb\"><h5>1. 表示位置，意为 “在……上面（物体的表面）”。</h5>\n<p class=\"source-line\">on the desk 在书桌上</p>\n<p class=\"source-line\">on the shelf 在架子上</p>\n<p class=\"source-line\">on the playground 在操场上</p>\n<h5>2. 表示时间，意为 “在（某一天）”。</h5>\n<p class=\"source-line\">（1） “on + 星期”</p>\n<p class=\"source-line\">on Monday 在星期一</p>\n<p class=\"source-line\">on Friday 在星期五</p>\n<p class=\"source-line\">on Sunday 在星期日</p>\n<p class=\"source-line\">（2） “on + 日期”</p>\n<p class=\"source-line\">on March 1st 在3月1日</p>\n<p class=\"source-line\">on July 10th 在7月10日</p>\n<p class=\"source-line\">on October 26th, 2024 在 2024 年 10 月 26 日</p>\n<p class=\"source-line\">（3） “on + 具体某天的上午、下午、晚上等”</p>\n<p class=\"source-line\">on Sunday morning 在星期日上午</p>\n<p class=\"source-line\">on Tuesday night 在星期二晚上</p>\n<p class=\"source-line\">on Monday afternoon 在星期一下午</p>\n<p class=\"source-line\">（4） “on + 节日”</p>\n<p class=\"source-line\">on Mid-Autumn Day 在中秋节当天</p>\n<p class=\"source-line\">on Teachers' Day 在教师节</p>\n<h5>3. 表示状态，意为“处于……状态”。</h5>\n<p class=\"source-line\">Who is on duty today? 今天谁值日？</p>\n<p class=\"source-line\">The house is on fire. 这个房子着火了。</p>\n<p class=\"source-line\">My mother was away on business. 我妈妈出差了。</p>\n<h5>4. 表示关系，意为 “关于，有关”。</h5>\n<p class=\"source-line\">I bought a book on health. 我买了一本关于健康的书。</p>\n<h5>5. 表示方位，意为“在……一边”</h5>\n<p class=\"source-line\">You will see the bus on your left. 你将在你的左边看到公共汽车。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"textbook","title":"选择题：选择正确的介词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s12-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">What do you wear <span class=\"blank-token\">____</span> sunny days?</p>","options":["on","in"],"correct":0,"answer":"A"},{"id":"s12-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">We have no classes <span class=\"blank-token\">____</span> Sundays.</p>","options":["at","on"],"correct":1,"answer":"B"},{"id":"s12-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There is a book <span class=\"blank-token\">____</span> the desk.</p>","options":["of","on"],"correct":1,"answer":"B"},{"id":"s12-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Children don't go to school <span class=\"blank-token\">____</span> New Year's Day.</p>","options":["in","on"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s12-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Look, there's a picture <span class=\"blank-token\">____</span> the wall.</p>","options":["in","on","at"],"correct":1,"answer":"B"},{"id":"s12-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">She was born <span class=\"blank-token\">____</span> 2000.</p>","options":["at","on","in"],"correct":2,"answer":"C"},{"id":"s12-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">My sister was born <span class=\"blank-token\">____</span> October 10th, 2012.</p>","options":["on","at","in"],"correct":0,"answer":"A"},{"id":"s12-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Teachers' Day is <span class=\"blank-token\">____</span> September 10th.</p>","options":["at","in","on"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【天津·和平区】用适当的介词填空","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s12-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I get up <span class=\"blank-token\">____</span> six o'clock every morning.</p>","options":[],"correct":null,"answer":"at\n解析：表示在具体几点介词用 at。"},{"id":"s12-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">He goes to bed early <span class=\"blank-token\">____</span> Mondays.</p>","options":[],"correct":null,"answer":"on\n解析：表示在星期几介词用 on。"},{"id":"s12-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> the afternoon of April 1st, we went to Beijing.</p>","options":[],"correct":null,"answer":"On\n解析：表示在具体某一天的上午 / 下午介词用 on, 句首单词首字母大写。"},{"id":"s12-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">He left home <span class=\"blank-token\">____</span> July.</p>","options":[],"correct":null,"answer":"in\n解析：表示在几月介词用 in。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【北京·房山区】单项选择","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s12-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Children's Day is <span class=\"blank-token\">____</span> June 1st.</p>","options":["in","on","at"],"correct":1,"answer":"B"},{"id":"s12-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">You can see the stars <span class=\"blank-token\">____</span> night.</p>","options":["at","on","in"],"correct":0,"answer":"A"},{"id":"s12-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">We have PE <span class=\"blank-token\">____</span> Mondays.</p>","options":["in","at","on"],"correct":2,"answer":"C"},{"id":"s12-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Mary is <span class=\"blank-token\">____</span> duty today.</p>","options":["in","on","at"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true}]},{"id":"s13","section":13,"unit":3,"unitName":"单元03 · 第13–18节","short":"第13节 · L25–26","title":"定冠词 the 的用法","lessons":"Lesson 25 — Lesson 26","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>冠词</td>\n<td>不定冠词 a、an</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★</td>\n</tr>\n<tr>\n<td>冠词</td>\n<td>定冠词 the</td>\n<td style=\"text-align: right;\">★★★</td>\n<td style=\"text-align: right;\">★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">冠词</div><div class=\"gb\"><p class=\"source-line\">冠词(Article)是虚词,它在名词的前面,必须与名词一起出现。英语冠词有3个,它们是a、an和the。这3个冠词又可分为不定冠词和定冠词两类。</p>\n<p class=\"source-line\">In the room, there is a table and a stereo.</p>\n<p class=\"source-line\">房间里有一张桌子和一台立体声音响。</p></div></div>\n<div class=\"g\"><div class=\"gt\">不定冠词 a、an 的用法</div><div class=\"gb\"><p class=\"source-line\">a、an 是不定冠词,有 “一; 每一” 的意思。a 用在发音以辅音音素开头的单词前面, an 用在发音以元音音素开头的单词前面。</p>\n<p class=\"source-line\">如: a hamburger 一个汉堡包、an ant 一只蚂蚁。</p>\n<p class=\"source-line\">a、an 的用法区别: 用 a 用 an 这样辨, 不看字母看音素, 不见元音别放 n。</p></div></div>\n<div class=\"g\"><div class=\"gt\">定冠词 the 的用法</div><div class=\"gb\"><h5>1. 特指某(些)人或某(些)事物。</h5>\n<p class=\"source-line\">Give me the book. 把那本书给我。</p>\n<p class=\"source-line\">How do you like the film? 你认为那部电影怎么样？</p>\n<h5>2. 用在谈话双方都知道的人或事物前。</h5>\n<p class=\"source-line\">Where is the dictionary? 字典在哪儿?</p>\n<p class=\"source-line\">Open the window, please. 请把窗户打开。</p>\n<h5>3. 用于上文提到过的人或事物前。</h5>\n<p class=\"source-line\">I buy a dress and a yellow sweater with my mum. The dress is in the wardrobe. The sweater is on the desk.</p>\n<p class=\"source-line\">我和我妈妈买了一条连衣裙和一件黄色的毛衣。连衣裙在衣柜里。毛衣在书桌上。</p>\n<h5>4. 用于世界上独一无二的事物前。</h5>\n<p class=\"source-line\">The earth is bigger than the moon, but smaller than the sun.\n地球比月球大,但比太阳小。</p>\n<h5>5. 用于序数词和形容词最高级前。</h5>\n<p class=\"source-line\">Miss Li teaches the first class. 李老师教第一节课。<br/>\nHe is the tallest boy in his class. 他是他班级里最高的男孩儿。</p>\n<h5>6. 用于可数名词单数前,表示某一类人或事物。</h5>\n<p class=\"source-line\">The dog is a friendly animal. 狗是一种友好的动物。</p>\n<h5>7. 与下列专有名词等连用。</h5>\n<p class=\"source-line\">（1）用在江、河、湖、海、群岛、山脉的名称前。如: the Yellow River 黄河</p>\n<p class=\"source-line\">（2）用在由普通名词构成的专有名词前。如: the United Nations 联合国、the Great Wall 长城。</p>\n<p class=\"source-line\">（3）用在姓氏的复数形式前,表示全家人。</p>\n<p class=\"source-line\">The Greens are sitting at the table. 格林一家人正围坐在桌旁。</p>\n<h5>8. 和某些形容词连用,表示某类人。</h5>\n<p class=\"source-line\">the old 老人</p>\n<p class=\"source-line\">the young 年轻人</p>\n<p class=\"source-line\">the sick 病人</p>\n<p class=\"source-line\">the rich 富人</p>\n<p class=\"source-line\">the poor 穷人</p>\n<h5>9. 用在乐器名称前。</h5>\n<p class=\"source-line\">play the piano 弹钢琴</p>\n<p class=\"source-line\">play the violin 拉小提琴</p>\n<h5>10. 用在表示方向的名词前。</h5>\n<p class=\"source-line\">The sun rises in the east. 太阳从东方升起。</p>\n<h5>11. 用在一些习惯用语中。</h5>\n<p class=\"source-line\">in the morning / afternoon / evening 在上午 / 下午 / 晚上</p>\n<p class=\"source-line\">on the left / right 在左边 / 右边</p>\n<p class=\"source-line\">in the end 最后</p>\n<p class=\"source-line\">go to the cinema 去看电影</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">定冠词用法：特指双熟悉，上文已提及；世上无独二，序数最高级；某些专有名，习语及乐器。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【合肥·庐阳区】判断题：判断下列表达是否正确。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s13-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">a story</p>","options":["正确","错误"],"correct":0,"answer":"A"},{"id":"s13-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">a apple</p>","options":["正确","错误"],"correct":1,"answer":"B"},{"id":"s13-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">an useful book</p>","options":["正确","错误"],"correct":1,"answer":"B"},{"id":"s13-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">a milk</p>","options":["正确","错误"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【佛山·三水区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s13-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I have a hat. <span class=\"blank-token\">____</span> hat is nicer than yours.</p>","options":["A","An","The","/"],"correct":2,"answer":"C\n解析：第一句意为 “我有一顶帽子”, 上文提到过的人或物在下文中提及时, 应用定冠词 the 修饰。"},{"id":"s13-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I went to <span class=\"blank-token\">____</span> Great Wall last week.</p>","options":["the","a","an","/"],"correct":0,"answer":"A\n解析：the Great Wall(长城)为专有名词, 故选 A。"},{"id":"s13-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">I am <span class=\"blank-token\">____</span> first one to get to school.</p>","options":["a","an","the","/"],"correct":2,"answer":"C\n解析：first(第一)为序数词, 序数词前应使用定冠词 the。"},{"id":"s13-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">I need about <span class=\"blank-token\">____</span> hour to finish the work.</p>","options":["/","an","some","a"],"correct":1,"answer":"B\n解析：hour（小时）是发音以元音音素开头的单词，应使用不定冠词 an 修饰。A、C 选项不符合语法。"},{"id":"s13-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> Greens are preparing for the coming Mid-Autumn Festival.</p>","options":["/","A","An","The"],"correct":3,"answer":"D\n解析：the 用在姓氏的复数名词前, 表示全家人。"},{"id":"s13-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Jack is <span class=\"blank-token\">____</span> honest boy and never tells lies.</p>","options":["a","some","an","/"],"correct":2,"answer":"C\n解析：honest (诚实的) 是发音以元音音素开头的单词, 应使用不定冠词 an 修饰。B、D 选项不符合语法。"}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"选择题：从 a、an、the 中选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s13-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Can you see <span class=\"blank-token\">____</span> teacher we talked about in the classroom?</p>","options":["an","the","a"],"correct":1,"answer":"B"},{"id":"s13-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Where is <span class=\"blank-token\"><strong><em>_</em></strong></span> teacher's desk?<br/><br>\n—— It's near <span class=\"blank-token\">_</span> window.</br></p>","options":["the, a","the, the","a, a","a, the"],"correct":1,"answer":"B"},{"id":"s13-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">We can find <span class=\"blank-token\">____</span> “f” in the word “family”.</p>","options":["a","an","the"],"correct":1,"answer":"B"},{"id":"s13-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is there <span class=\"blank-token\"><strong><em>_</em></strong></span> knife in that box?<br/><br>\n—— Yes, there is. Is <span class=\"blank-token\">_</span> knife sharp?</br></p>","options":["a, a","a, the","the, a","the, the"],"correct":1,"answer":"B"},{"id":"s13-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Can your sister play <span class=\"blank-token\">____</span> guitar?</p>","options":["the","a","an"],"correct":0,"answer":"A"},{"id":"s13-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I can see <span class=\"blank-token\">____</span> sun.</p>","options":["a","an","the"],"correct":2,"answer":"C"},{"id":"s13-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">She is <span class=\"blank-token\">____</span> English teacher.</p>","options":["an","the","a"],"correct":0,"answer":"A"},{"id":"s13-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Look at <span class=\"blank-token\">____</span> girl.</p>","options":["the","a","an"],"correct":0,"answer":"A"},{"id":"s13-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">I have <span class=\"blank-token\">____</span> red apple. The apple is so good.</p>","options":["a","an","the"],"correct":0,"answer":"A"},{"id":"s13-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> Browns are funny.</p>","options":["an","the","a"],"correct":1,"answer":"B"},{"id":"s13-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">I can see <span class=\"blank-token\">____</span> cars that belong to our neighbours and the moon.</p>","options":["the","a","an"],"correct":0,"answer":"A"},{"id":"s13-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">Please open <span class=\"blank-token\">____</span> door.</p>","options":["a","an","the"],"correct":2,"answer":"C"},{"id":"s13-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">I have <span class=\"blank-token\">____</span> idea.</p>","options":["an","the","a"],"correct":0,"answer":"A"},{"id":"s13-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">Can your brother play <span class=\"blank-token\">____</span> violin?</p>","options":["the","a","an"],"correct":0,"answer":"A"},{"id":"s13-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">There is <span class=\"blank-token\">____</span> old woman on the street (街道).</p>","options":["a","an","the"],"correct":1,"answer":"B"}],"questionCount":15,"hasAnswers":true}]},{"id":"s14","section":14,"unit":3,"unitName":"单元03 · 第13–18节","short":"第14节 · L27–28","title":"some、any 的用法","lessons":"Lesson 27 — Lesson 28","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>some、any 的用法</td>\n<td>some 的用法</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>some、any 的用法</td>\n<td>any 的用法</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">some 的用法</div><div class=\"gb\"><h5>1. some 作形容词,一般用于肯定句中。</h5>\n<p class=\"source-line\">（1）修饰可数名词复数或不可数名词,表示“一些,若干”。</p>\n<p class=\"source-line\">There are some books in the living room. 客厅里有一些书。<br/>\nThere is some water in the glass. 玻璃杯子里有一些水。</p>\n<p class=\"source-line\">（2）修饰可数名词单数,表示不明确的“某个”。</p>\n<p class=\"source-line\">She lives at some place in Beijing.</p>\n<p class=\"source-line\">她住在北京的某个地方。</p>\n<h5>2. some 作代词, 表示 “有些人, 有些事物”。</h5>\n<p class=\"source-line\">There are many people in the park. Some are walking. Some are talking.\n公园里有许多人。一些在散步，一些在谈话。</p>\n<p class=\"source-line\">Some of the apples are green.</p>\n<p class=\"source-line\">一些苹果是绿色的。</p>\n<h5>3. some 作副词, 表示 “大约”。</h5>\n<p class=\"source-line\">I have kept fish for some 20 years. 我养鱼大约有 20 年了。</p>\n<p class=\"source-line\">It's some 20 kilometres away. 它大约在20公里外。</p>\n<h5>4. some 用在疑问句中。</h5>\n<p class=\"source-line\">（1）表示请求、邀请或建议的一般疑问句。</p>\n<p class=\"source-line\">Can I have some peaches? 我可以吃一些桃子吗?\nWould you like some more cake? 你想再来点儿蛋糕吗?</p>\n<p class=\"source-line\">（2）期望得到对方肯定回答的一般疑问句。</p>\n<p class=\"source-line\">Would you like some eggs for breakfast? 你早餐想吃鸡蛋吗?\nHave you got some cash? 你有现金吗?</p>\n<p class=\"source-line\">（3）特殊疑问句及选择疑问句。</p>\n<p class=\"source-line\">Where can I get some travel information? 我在哪里可以得到一些旅游信息？</p></div></div>\n<div class=\"g\"><div class=\"gt\">any 的用法</div><div class=\"gb\"><h5>1. any 用在疑问句中。</h5>\n<p class=\"source-line\">Are there any trains to Shanghai at night? 晚上有去上海的火车吗?\nHave you got any questions to ask? 你有问题要问吗?</p>\n<h5>2. any 用在否定句中。</h5>\n<p class=\"source-line\">There isn't any money in my wallet. 我的钱包里没有钱。</p>\n<p class=\"source-line\">There aren't any students in the classroom. 教室里没有学生。</p>\n<h5>3. any 也可以用在肯定句中, 意为 “任何的”。</h5>\n<p class=\"source-line\">You can read any book in our library. 你可以读我们图书馆的任何一本书。</p>\n<p class=\"source-line\">Any student can answer this question. 任何学生都可以回答这个问题。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【广州·天河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s14-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you have <span class=\"blank-token\">____</span> money?</p>","options":["any","many","some"],"correct":0,"answer":"A\n解析：在一般疑问句中, 表示 “一些” 通常用 any, 故选 A。"},{"id":"s14-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I have <span class=\"blank-token\">____</span> oranges.</p>","options":["any","some","much"],"correct":1,"answer":"B\n解析：some 用在肯定句中, 表示 “一些”, 故选 B。C 选项不符合语法。"},{"id":"s14-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Would you like <span class=\"blank-token\">____</span> coffee?</p>","options":["lot","any","some"],"correct":2,"answer":"C\n解析：在表达请求或建议的句子中, 表示 “一些” 用 some, 故选 C。"},{"id":"s14-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">He wanted a job, <span class=\"blank-token\">____</span> sort of a job.</p>","options":["any","some","much"],"correct":0,"answer":"A\n解析：当表示 “任何一个” 时, 肯定句中用 any, 故选 A。"},{"id":"s14-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">There isn't <span class=\"blank-token\">____</span> water in the glass.</p>","options":["some","many","any"],"correct":2,"answer":"C\n解析：any 用在否定句中, 故选 C。B 选项不符合语法。"},{"id":"s14-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Lisa wants to do <span class=\"blank-token\">____</span> housework.</p>","options":["some","any","an"],"correct":0,"answer":"A\n解析：some 通常用在肯定句中, 表示 “一些”, 故选 A。C 选项不符合语法。"},{"id":"s14-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Bill doesn't have <span class=\"blank-token\">____</span> money.</p>","options":["some","any","many"],"correct":1,"answer":"B\n解析：any 通常用在否定句或疑问句中。C 选项不符合语法。"},{"id":"s14-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you have <span class=\"blank-token\">____</span> pens?</p>","options":["some","many","any"],"correct":2,"answer":"C\n解析：在一般疑问句中, 表示 “一些” 通常用 any, 故选 C。"},{"id":"s14-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you please give me <span class=\"blank-token\">____</span> milk?</p>","options":["few","little","some"],"correct":2,"answer":"C\n解析：在希望得到肯定回答的一般疑问句中, 表示 “一些” 用 some, 故选 C。"},{"id":"s14-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">There are <span class=\"blank-token\">____</span> pictures in the room.</p>","options":["some","any","much"],"correct":0,"answer":"A\n解析：此句为肯定句, pictures (图片) 是可数名词复数, 应用 some 修饰 pictures, 故选 A。"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"选择题：从 some、any 中选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s14-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">There isn't <span class=\"blank-token\">____</span> milk in the fridge.</p>","options":["any","some"],"correct":0,"answer":"A"},{"id":"s14-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I can see <span class=\"blank-token\"><strong><em>_</em></strong></span> cars, but I can't see <span class=\"blank-token\">_</span> buses.</p>","options":["any, some","any, any","some, some","some, any"],"correct":3,"answer":"D"},{"id":"s14-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">She has <span class=\"blank-token\">____</span> friends in Australia.</p>","options":["any","some"],"correct":1,"answer":"B"},{"id":"s14-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Are there <span class=\"blank-token\">____</span> trees on the farm?</p>","options":["some","any"],"correct":1,"answer":"B"},{"id":"s14-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">There are <span class=\"blank-token\">____</span> plates on the table.</p>","options":["any","some"],"correct":1,"answer":"B"},{"id":"s14-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Give me <span class=\"blank-token\">____</span> tickets, please.</p>","options":["some","any"],"correct":0,"answer":"A"},{"id":"s14-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">There aren't <span class=\"blank-token\">____</span> dogs in the room.</p>","options":["any","some"],"correct":0,"answer":"A"}],"questionCount":7,"hasAnswers":true},{"source":"textbook","title":"按要求改写句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s14-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I have some apples. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Do you have any apples?"},{"id":"s14-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">They have some pineapples. (改为否定句)</p>","options":[],"correct":null,"answer":"They don't have any pineapples."},{"id":"s14-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">I would like some apple juice. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Would you like some apple juice?"},{"id":"s14-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">She has some new books. (改为否定句)</p>","options":[],"correct":null,"answer":"She doesn't have any new books."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s14-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> milk in the bottle.</p>","options":["is any","are some","is some"],"correct":2,"answer":"C"},{"id":"s14-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm thirsty. I want to drink <span class=\"blank-token\">____</span> water.</p>","options":["some","any","many"],"correct":0,"answer":"A"},{"id":"s14-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">She has <span class=\"blank-token\">____</span> milk.</p>","options":["any","some","many"],"correct":1,"answer":"B"},{"id":"s14-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you have <span class=\"blank-token\"><strong><em>_</em></strong></span> toy cars?<br/><br>\n—— No, I don't. I have <span class=\"blank-token\">_</span> stickers.</br></p>","options":["some; some","any; any","any; some"],"correct":2,"answer":"C"},{"id":"s14-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't have <span class=\"blank-token\">____</span> new skirts.</p>","options":["any","some","much"],"correct":0,"answer":"A"},{"id":"s14-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is there <span class=\"blank-token\">____</span> coffee in the cup?<br/><br>\n—— Yes, there is.</br></p>","options":["some","any","many"],"correct":1,"answer":"B"}],"questionCount":6,"hasAnswers":true}]},{"id":"s15","section":15,"unit":3,"unitName":"单元03 · 第13–18节","short":"第15节 · L29–30","title":"祈使句","lessons":"Lesson 29 — Lesson 30","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>祈使句</td>\n<td>祈使句的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n<tr>\n<td>祈使句</td>\n<td>祈使句的句型结构</td>\n<td style=\"text-align: right;\">★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">祈使句</div><div class=\"gb\"><p class=\"source-line\">表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.)，为表示礼貌，可在句首或句末加上“please”。句子朗读用降调。</p>\n<p class=\"source-line\">有时为了加强语气,可在动词原形前加do。例如:Do be quiet! 一定要保持安静!</p>\n<p class=\"source-line\">Be quick!</p>\n<p class=\"source-line\">快点儿!</p>\n<p class=\"source-line\">Let's play basketball.</p>\n<p class=\"source-line\">我们打篮球吧。</p>\n<p class=\"source-line\">Sweep the floor.\n打扫地板。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句的句型结构</div><div class=\"gb\"><h5>1. 肯定祈使句</h5>\n<p class=\"source-line\">（1）Do 型肯定祈使句: 实义动词原形(+其他).</p>\n<p class=\"source-line\">Listen! 听!</p>\n<p class=\"source-line\">Stand up. 起立。</p>\n<p class=\"source-line\">Shut up! 闭嘴!</p>\n<p class=\"source-line\">（2）Be 型肯定祈使句: Be + 其他.</p>\n<p class=\"source-line\">Be careful! 小心!</p>\n<p class=\"source-line\">Be quiet! 保持安静!</p>\n<p class=\"source-line\">Be a good child. 做个好孩子。</p>\n<p class=\"source-line\">（3）Let 型肯定祈使句: Let + 宾语 + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Let her sit here! 让她坐这儿吧！<br/>\nLet's go. 我们走吧。</p>\n<p class=\"source-line\">let's 表建议,包括所有对象; let us 表请求,不包括请求对象。</p>\n<h5>2. 否定祈使句</h5>\n<p class=\"source-line\">（1）Do 型否定祈使句: Don't + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Don't eat in class! 不要在课堂上吃东西!\nDon't go there! 不要去那儿!</p>\n<p class=\"source-line\">（2）Be 型否定祈使句: Don't be + 其他.</p>\n<p class=\"source-line\">Don't be nervous! 不要紧张!</p>\n<p class=\"source-line\">Don't be sad. 不要难过。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【沈阳·和平区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s15-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> (not be) late for class.</p>","options":[],"correct":null,"answer":"Don't be"},{"id":"s15-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> (clean) the table, please.</p>","options":[],"correct":null,"answer":"Clean"},{"id":"s15-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> (not play) with fire.</p>","options":[],"correct":null,"answer":"Don't play"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【北京·西城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s15-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The doctor says “<span class=\"blank-token\">____</span> eat too much”.</p>","options":["Stop","Don’t","Aren’t"],"correct":1,"answer":"B\n解析：题意为“医生说‘不要吃太多’”, eat(吃)为实义动词原形, 应用 don't, 故选 B。"},{"id":"s15-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> read in the sun.</p>","options":["Not to","Don't","Is"],"correct":1,"answer":"B\n解析：题意为 “不要在阳光下阅读”, read(阅读)为实义动词, 故在句首加 Don't。"},{"id":"s15-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Let's <span class=\"blank-token\">____</span> look at the picture.</p>","options":["not","don't","can't"],"correct":0,"answer":"A\n解析：句子是 Let 型否定祈使句。Let 型否定祈使句有两种形式, 分别是 “Don’t let + 宾语 + 动词原形 (+ 其他).” 和 “Let + 宾语 + not + 动词原形 (+ 其他).”。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【佛山·三水区】句型转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s15-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Let her make salad. (改为否定句)</p>","options":[],"correct":null,"answer":"Let her not make salad. 或 Don't let her make salad."},{"id":"s15-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Come here. (改为否定句)</p>","options":[],"correct":null,"answer":"Don't come here."},{"id":"s15-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Peter stands up. (改为祈使句)</p>","options":[],"correct":null,"answer":"Peter, stand up."}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s15-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> in the street. It's dangerous (危险的).</p>","options":["Not play","Not to play","Don't to play","Don't play"],"correct":3,"answer":"D"},{"id":"s15-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> tell a lie.</p>","options":["Be","Not","No","Don't"],"correct":3,"answer":"D"},{"id":"s15-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Let's <span class=\"blank-token\">____</span> the classroom.</p>","options":["clean","cleaning","to clean","cleaned"],"correct":0,"answer":"A"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"英汉互译。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s15-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">打开窗户, 给房间通风。</p>","options":[],"correct":null,"answer":"Open the window and air the room."},{"id":"s15-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">把这些衣服放到衣橱里去。</p>","options":[],"correct":null,"answer":"Put these clothes in the wardrobe."},{"id":"s15-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">请关上门。</p>","options":[],"correct":null,"answer":"Close the door, please."},{"id":"s15-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Don't worry!</p>","options":[],"correct":null,"answer":"别担心！"},{"id":"s15-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Stop and wait.</p>","options":[],"correct":null,"answer":"停下来等一等。"}],"questionCount":5,"hasAnswers":true}]},{"id":"s16","section":16,"unit":3,"unitName":"单元03 · 第13–18节","short":"第16节 · L31–32","title":"现在进行时","lessons":"Lesson 31 — Lesson 32","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在进行时</td>\n<td>现在进行时的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>现在进行时</td>\n<td>现在进行时的构成</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">现在进行时的概念</div><div class=\"gb\"><p class=\"source-line\">现在进行时表示现在正在进行的动作或行为。</p>\n<p class=\"source-line\">My mother is cooking now. 我妈妈现在正在煮饭。</p>\n<p class=\"source-line\">We are playing football now. 我们现在正在踢足球。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在进行时的构成</div><div class=\"gb\"><h5>1. 肯定句: 主语 + be (am / is / are) + 现在分词 (+ 其他).</h5>\n<p class=\"source-line\">My little sister is reading a book and my brother is playing games. 我妹妹正在看书,我哥哥正在玩儿游戏。<br/>\nHe is cleaning the bedroom. 他正在打扫卧室。</p>\n<h5>2. 否定句: 主语 + be (am / is / are) + not + 现在分词 (+ 其他).</h5>\n<p class=\"source-line\">My father isn't reading now. 我父亲现在没在看书。</p>\n<p class=\"source-line\">They aren't having a maths lesson. 他们没在上数学课。</p>\n<h5>3. 一般疑问句: Be (Am / Is / Are) + 主语 + 现在分词 (+ 其他)?</h5>\n<p class=\"source-line\">Are you having a music lesson? 你们正在上音乐课吗？</p>\n<p class=\"source-line\">Is she playing computer games? 她正在玩儿电脑游戏吗？</p>\n<h5>4. 特殊疑问句:疑问词 + be (am / is / are) + 主语 + 现在分词(+其他)?</h5>\n<p class=\"source-line\">What are you doing now? 你们现在正在做什么？</p>\n<p class=\"source-line\">What is he looking at? 他正在看什么？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·红桥区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s16-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Who <span class=\"blank-token\">____</span> over there now?</p>","options":["singing","are sing","is singing","sing"],"correct":2,"answer":"C\n解析：句子是现在进行时的特殊疑问句, 句型结构是 “疑问词 + be (am / is / are) + 动词 -ing 形式 (+ 其他)?”, 此句中缺少 be 和动词 -ing 形式, 故选 C。"},{"id":"s16-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">It's nine o'clock. The students <span class=\"blank-token\">____</span> an English class.</p>","options":["have","having","is having","are having"],"correct":3,"answer":"D\n解析：根据句意可知第二个句子是现在进行时的肯定句, 句中缺少 be 和动词 -ing 形式, 句中主语是复数, be 用 are, 故选 D。"},{"id":"s16-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Listen! The baby <span class=\"blank-token\">____</span> in the living room.</p>","options":["are crying","cried","is crying","cries"],"correct":2,"answer":"C\n解析：由 “Listen!” 可知第二个句子是现在进行时的肯定句,主语是第三人称单数, be 用 is, 故选 C。"},{"id":"s16-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Lily <span class=\"blank-token\">____</span> the piano now.</p>","options":["is playing","plays","playing","are playing"],"correct":0,"answer":"A\n解析：根据句意可知此句是现在进行时的肯定句, 主语 Lily 是第三人称单数, be 用 is, 故选 A。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【天津·南开区】根据要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s16-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Tom is reading a book. (改为否定句)</p>","options":[],"correct":null,"answer":"Tom isn't reading a book.\n解析：句子时态是现在进行时, 变为否定句时, 在 is 后加 not, is not 可缩写为 isn't。"},{"id":"s16-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">the dog, chase, the cat, now ( . ) (用现在进行时写句子)</p>","options":[],"correct":null,"answer":"The dog is chasing the cat now.\n解析：此句主语为第三人称单数, 故 be 用 is, chase 改为 chasing。"},{"id":"s16-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Kate is looking for her watch. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Is Kate looking for her watch?\n解析：句子时态是现在进行时,变一般疑问句时,将 is 提到句首,首字母要大写,句尾句号变问号。"},{"id":"s16-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Miss White <u>is doing some washing</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What is Miss White doing?\n解析：对做某事进行提问疑问词用 what, 将 is 提到主语前, 画线部分用 doing 代替。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用现在进行时完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s16-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> (sing) an English song.</p>","options":[],"correct":null,"answer":"is singing"},{"id":"s16-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> (do) now?</p>","options":[],"correct":null,"answer":"are, doing"},{"id":"s16-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> she <span class=\"blank-token\">_</span> (sit) on the bench?</p>","options":[],"correct":null,"answer":"Is, sitting"},{"id":"s16-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">The baby <span class=\"blank-token\">____</span> (sleep). Don't make a noise!</p>","options":[],"correct":null,"answer":"is sleeping"},{"id":"s16-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The boy <span class=\"blank-token\">____</span> (draw) a picture now.</p>","options":[],"correct":null,"answer":"is drawing"},{"id":"s16-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Listen! The girls <span class=\"blank-token\">____</span> (sing).</p>","options":[],"correct":null,"answer":"are singing"},{"id":"s16-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My mother <span class=\"blank-token\">____</span> (cook) now.</p>","options":[],"correct":null,"answer":"is cooking"},{"id":"s16-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Look! They <span class=\"blank-token\">____</span> (have) an English lesson.</p>","options":[],"correct":null,"answer":"are having"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s16-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\"><u>Lucy</u> is looking at me. (对画线部分提问)</p>","options":[],"correct":null,"answer":"Who is looking at you?"},{"id":"s16-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">My mother <u>is emptying a basket</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What is your mother doing?"},{"id":"s16-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">Mary is drinking milk. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Is Mary drinking milk?"},{"id":"s16-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">Is Mr Black cleaning the room? (作肯定回答)</p>","options":[],"correct":null,"answer":"Yes, he is."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s16-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> about weather at the moment.</p>","options":["talk","talking","are talking"],"correct":2,"answer":"C"},{"id":"s16-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">Mum <span class=\"blank-token\">____</span> on the sofa now.</p>","options":["is lying","lying","lie"],"correct":0,"answer":"A"},{"id":"s16-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> he <span class=\"blank-token\">_</span> now?<br/><br>\n—— He <span class=\"blank-token\">____</span> basketball.</br></p>","options":["is; playing; plays","is; playing; is playing","does; play; is playing"],"correct":1,"answer":"B"},{"id":"s16-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">Listen! Who <span class=\"blank-token\">____</span> the piano?</p>","options":["was play","played","is playing"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true}]},{"id":"s17","section":17,"unit":3,"unitName":"单元03 · 第13–18节","short":"第17节 · L33–34","title":"现在分词","lessons":"Lesson 33 — Lesson 34","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在分词</td>\n<td>现在分词的概念</td>\n<td style=\"text-align: right;\">★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>现在分词</td>\n<td>现在分词的变化规则</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">现在分词的概念</div><div class=\"gb\"><p class=\"source-line\">动词的 -ing 形式除了可以作动名词外，还可以作现在分词。</p>\n<p class=\"source-line\">Look! They are jumping. 看！他们正在跳。</p>\n<p class=\"source-line\">The family are walking over the bridge.\n这家人正在过桥。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在分词变化规则</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>变化规则</th>\n<th>动词原形</th>\n<th>现在分词</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般情况下，直接在词尾加 -ing</td>\n<td>do</td>\n<td>doing</td>\n</tr>\n<tr>\n<td>一般情况下，直接在词尾加 -ing</td>\n<td>see</td>\n<td>seeing</td>\n</tr>\n<tr>\n<td>以不发音的字母 e 结尾，去 e 再加 -ing</td>\n<td>make</td>\n<td>making</td>\n</tr>\n<tr>\n<td>以不发音的字母 e 结尾，去 e 再加 -ing</td>\n<td>write</td>\n<td>writing</td>\n</tr>\n<tr>\n<td>末尾只有一个辅音字母的重读闭音节，双写末尾辅音字母再加 -ing</td>\n<td>run</td>\n<td>running</td>\n</tr>\n<tr>\n<td>末尾只有一个辅音字母的重读闭音节，双写末尾辅音字母再加 -ing</td>\n<td>swim</td>\n<td>swimming</td>\n</tr>\n<tr>\n<td>以 ie 结尾，先将 ie 变为 y，再加 -ing</td>\n<td>die</td>\n<td>dying</td>\n</tr>\n<tr>\n<td>以 ie 结尾，先将 ie 变为 y，再加 -ing</td>\n<td>lie</td>\n<td>lying</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">现在分词变化规则：动词加上 ing，这种形式真有趣。哑 e 结尾去掉 e，然后加上 ing。结尾重读闭音节，双写再加 ing。结尾 ie 别慌张，变 y 加上 ing。</p></div>\n<p class=\"source-line\">重读闭音节三要素：</p>\n<p class=\"source-line\">（1）结构为“辅元辅”；</p>\n<p class=\"source-line\">（2）元音字母发短音；</p>\n<p class=\"source-line\">（3）最后一个音节是重读音节。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·五华区】用所给词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s17-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Look at my baby brother. He <span class=\"blank-token\">____</span> (sleep).</p>","options":[],"correct":null,"answer":"is sleeping\n解析：第二个句子时态为现在进行时,主语 he (他)为第三人称单数, be 用 is, sleep (睡觉)的现在分词为 sleeping。"},{"id":"s17-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Lots of students are <span class=\"blank-token\">____</span> (learn) Chinese in England now.</p>","options":[],"correct":null,"answer":"learning\n解析：now (现在) 为现在进行时的标志性词语。learn (学习) 的现在分词为 learning。"},{"id":"s17-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Sue is <span class=\"blank-token\">____</span> (talk) with her friends.</p>","options":[],"correct":null,"answer":"talking"},{"id":"s17-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Listen! Who <span class=\"blank-token\">____</span> (sing) in the room?</p>","options":[],"correct":null,"answer":"is singing"},{"id":"s17-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Look! My sister <span class=\"blank-token\">____</span> (fly) a kite.</p>","options":[],"correct":null,"answer":"is flying"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【佛山·顺德区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s17-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">What are you <span class=\"blank-token\">____</span> now?</p>","options":["doing","do","does"],"correct":0,"answer":"A\n解析：now(现在)为现在进行时的标志性词语。do(做)的现在分词为 doing。"},{"id":"s17-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">I am <span class=\"blank-token\">____</span> English.</p>","options":["speak","speaks","speaking"],"correct":2,"answer":"C"},{"id":"s17-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! The rabbit is <span class=\"blank-token\">____</span>.</p>","options":["jump","jumping","jumps"],"correct":1,"answer":"B"},{"id":"s17-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Tina, what's your dad doing?<br/><br>\n—— He <span class=\"blank-token\">____</span> my computer.</br></p>","options":["repairs","is repairing","has repaired"],"correct":1,"answer":"B"},{"id":"s17-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">The workers <span class=\"blank-token\">____</span> the community centre now.</p>","options":["cleaned","is cleaning","are cleaning"],"correct":2,"answer":"C\n解析：now (现在)为现在进行时的标志性词语, 主语为第三人称复数, be 用 are, clean (打扫)的现在分词为 cleaning。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"把下列动词改为现在分词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s17-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">shake <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"shaking"},{"id":"s17-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">cook <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"cooking"},{"id":"s17-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">cry <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"crying"},{"id":"s17-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">type <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"typing"},{"id":"s17-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">do <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"doing"},{"id":"s17-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">run <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"running"},{"id":"s17-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">shine <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"shining"},{"id":"s17-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">walk <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"walking"},{"id":"s17-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">have <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"having"},{"id":"s17-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">buy <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"buying"},{"id":"s17-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">plant <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"planting"},{"id":"s17-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">make <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"making"},{"id":"s17-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">drink <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"drinking"},{"id":"s17-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">play <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"playing"},{"id":"s17-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">go <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"going"},{"id":"s17-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">give <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"giving"},{"id":"s17-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">dance <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"dancing"},{"id":"s17-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">worry <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"worrying"},{"id":"s17-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">ask <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"asking"},{"id":"s17-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">eat <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"eating"},{"id":"s17-text-q021","number":21,"type":"input","questionHtml":"<p class=\"source-line\">read <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"reading"},{"id":"s17-text-q022","number":22,"type":"input","questionHtml":"<p class=\"source-line\">put <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"putting"},{"id":"s17-text-q023","number":23,"type":"input","questionHtml":"<p class=\"source-line\">let <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"letting"},{"id":"s17-text-q024","number":24,"type":"input","questionHtml":"<p class=\"source-line\">keep <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"keeping"}],"questionCount":24,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s17-text-q025","number":25,"type":"input","questionHtml":"<p class=\"source-line\">She opens the window. (用 now 改写句子)</p>","options":[],"correct":null,"answer":"She is opening the window now."},{"id":"s17-text-q026","number":26,"type":"input","questionHtml":"<p class=\"source-line\">who, is, cleaning, the window (?) (连词成句)</p>","options":[],"correct":null,"answer":"Who is cleaning the window?"},{"id":"s17-text-q027","number":27,"type":"input","questionHtml":"<p class=\"source-line\">She is closing the door now. (改成否定句)</p>","options":[],"correct":null,"answer":"She is not closing the door now."},{"id":"s17-text-q028","number":28,"type":"input","questionHtml":"<p class=\"source-line\">You are doing your homework. (“I”作主语改写句子）</p>","options":[],"correct":null,"answer":"I am doing my homework."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s17-text-q029","number":29,"type":"input","questionHtml":"<p class=\"source-line\">I am <span class=\"blank-token\">____</span> (read) at home.</p>","options":[],"correct":null,"answer":"reading"},{"id":"s17-text-q030","number":30,"type":"input","questionHtml":"<p class=\"source-line\">He is <span class=\"blank-token\">____</span> (do) his homework.</p>","options":[],"correct":null,"answer":"doing"},{"id":"s17-text-q031","number":31,"type":"input","questionHtml":"<p class=\"source-line\">They are <span class=\"blank-token\">____</span> (fly) kites.</p>","options":[],"correct":null,"answer":"flying"},{"id":"s17-text-q032","number":32,"type":"input","questionHtml":"<p class=\"source-line\">We are <span class=\"blank-token\">____</span> (play) basketball.</p>","options":[],"correct":null,"answer":"playing"},{"id":"s17-text-q033","number":33,"type":"input","questionHtml":"<p class=\"source-line\">Are you <span class=\"blank-token\">____</span> (sing) an English song?</p>","options":[],"correct":null,"answer":"singing"},{"id":"s17-text-q034","number":34,"type":"input","questionHtml":"<p class=\"source-line\">He doesn't like <span class=\"blank-token\">____</span> (read).</p>","options":[],"correct":null,"answer":"reading / to read"}],"questionCount":6,"hasAnswers":true}]},{"id":"s18","section":18,"unit":3,"unitName":"单元03 · 第13–18节","short":"第18节 · L35–36","title":"方位介词","lessons":"Lesson 35 — Lesson 36","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>方位介词</td>\n<td>方位介词的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>方位介词</td>\n<td>between、on、beside 等的用法</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">方位介词的概念</div><div class=\"gb\"><p class=\"source-line\">表示事物存在的方向和位置的介词,我们称之为方位介词。</p>\n<p class=\"source-line\">常见的方位介词有 in、on、at、under、beside、between、near、behind、up、over、down 等。</p>\n<p class=\"source-line\">The Greens are on the beach. 格林一家在沙滩上。</p>\n<p class=\"source-line\">The man is in the car. 那个男人在车里。</p>\n<p class=\"source-line\">Lucy is near her two sisters. 露西在她两个姐姐的附近。</p></div></div>\n<div class=\"g\"><div class=\"gt\">方位介词 between、on、beside</div><div class=\"gb\"><h5>1. between 和 among 的区别</h5>\n<p class=\"source-line\">（1）between : (空间上) 在……中间</p>\n<p class=\"source-line\">My mother planted a lot of flowers between the two gardens.</p>\n<p class=\"source-line\">我妈妈在两个花园中间种了许多花儿。</p>\n<p class=\"source-line\">（2）between : (时间上) 在……之间</p>\n<p class=\"source-line\">That lady is between fifty and sixty.</p>\n<p class=\"source-line\">那位女士年龄在50岁到60岁之间。</p>\n<p class=\"source-line\">（3）between 作为介词时常与 and 连用；不与 and 连用时，后面通常接表示两个或多个个体的复数名词或代词。</p>\n<p class=\"source-line\">The house is between the mountain and the sea. 房子在山与海之间。<br/>\nThe apple is between the two boxes. 苹果在两个盒子之间。</p>\n<p class=\"source-line\">（4）among: 在……中；……之一；在三者或以上之中</p>\n<p class=\"source-line\">The house is among the trees. 房子在树木中。<br/>\nI saw Peter among the crowd. 我看见彼得在人群中。</p>\n<h5>2. on、over 和 above 的区别</h5>\n<p class=\"source-line\">（1）on: (指与另一物体表面相接触) 在……上</p>\n<p class=\"source-line\">The book is on the desk. 那本书在书桌上。<br/>\nThe apples are on the trees. 苹果在树上。</p>\n<p class=\"source-line\">（2）over: (指在物体的垂直上方) 悬在……上面</p>\n<p class=\"source-line\">There is a clock over the blackboard.\n黑板上方有一个钟。</p>\n<p class=\"source-line\">There is a bridge over the river. 河上有一座桥。</p>\n<p class=\"source-line\">（3）above: (一般指位置高于某物, 但不一定在正上方, 也不接触另一物) 在上面</p>\n<p class=\"source-line\">Raise your hands above your head. 把你的手举过头。<br/>\nCan you see the birds flying above the trees?<br/>\n你能看见鸟儿在树的上空飞吗？</p>\n<h5>3. beside 和 near 的区别</h5>\n<p class=\"source-line\">（1）beside: 在……旁边</p>\n<p class=\"source-line\">The chair is beside the table. 椅子在桌子旁边。</p>\n<p class=\"source-line\">Come and sit beside me. 过来坐我旁边。</p>\n<p class=\"source-line\">（2）near: 在……附近</p>\n<p class=\"source-line\">There is a supermarket near his home. 他家附近有一家超市。</p>\n<p class=\"source-line\">Don't play near the road. 不要在马路附近玩儿。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·顺德区】选择题：选择合适的介词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s18-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">She puts her watch <span class=\"blank-token\">____</span> the table.</p>","options":["between","at","near","on","above","among","beside","to"],"correct":3,"answer":"D\n解析：此句意为 “她把手表放在桌子上”, 手表与桌子相接触, 故选介词 on。"},{"id":"s18-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">He often goes <span class=\"blank-token\">____</span> school by bus.</p>","options":["at","near","on","above","among","beside","to","between"],"correct":6,"answer":"G\n解析：go to school(去上学)是固定短语, 故选介词 to。"},{"id":"s18-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't need a car because I live <span class=\"blank-token\">____</span> the city centre.</p>","options":["near","on","above","among","beside","to","between","at"],"correct":0,"answer":"A\n解析：表达在城市中心附近介词用 near。"},{"id":"s18-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The letter B is <span class=\"blank-token\">____</span> A and C.</p>","options":["on","above","among","beside","to","between","at","near"],"correct":5,"answer":"F\n解析：“between...and...”意为“在……和……之间”，是固定短语，故选介词 between。"},{"id":"s18-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Sue sits <span class=\"blank-token\">____</span> Mary.</p>","options":["above","among","beside","to","between","at","near","on"],"correct":2,"answer":"C\n解析：表达坐在某人旁边介词用 beside。"},{"id":"s18-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">There is a mountain <span class=\"blank-token\">____</span> the trees.</p>","options":["among","beside","to","between","at","near","on","above"],"correct":0,"answer":"A"},{"id":"s18-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">You can see stars <span class=\"blank-token\">____</span> night.</p>","options":["beside","to","between","at","near","on","above","among"],"correct":3,"answer":"D"},{"id":"s18-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">The bird is flying <span class=\"blank-token\">____</span> the trees.</p>","options":["to","between","at","near","on","above","among","beside"],"correct":5,"answer":"F"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"根据汉语提示完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s18-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">There is a desk <span class=\"blank-token\">____</span> (在……中间) the two chairs.</p>","options":[],"correct":null,"answer":"between"},{"id":"s18-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Our school is <span class=\"blank-token\">____</span> (在旁边) the library.</p>","options":[],"correct":null,"answer":"beside"},{"id":"s18-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">There are ships <span class=\"blank-token\">____</span> (在……上) the river.</p>","options":[],"correct":null,"answer":"on"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s18-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The plane flew <span class=\"blank-token\">____</span> the clouds.</p>","options":["in","above","on"],"correct":1,"answer":"B"},{"id":"s18-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Mary is sitting <span class=\"blank-token\">____</span> Tom and Mike.</p>","options":["between","among","over"],"correct":0,"answer":"A"},{"id":"s18-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">She is very popular <span class=\"blank-token\">____</span> the students.</p>","options":["on","beside","among"],"correct":2,"answer":"C"},{"id":"s18-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Is your birthday <span class=\"blank-token\">____</span> May?</p>","options":["on","at","in"],"correct":2,"answer":"C"},{"id":"s18-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">The pears are <span class=\"blank-token\">____</span> the trees.</p>","options":["over","on","in"],"correct":1,"answer":"B"},{"id":"s18-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Lucy sits <span class=\"blank-token\">____</span> the two trees.</p>","options":["on","above","between"],"correct":2,"answer":"C"},{"id":"s18-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">There is a bank <span class=\"blank-token\">____</span> my house.</p>","options":["near","between","among"],"correct":0,"answer":"A"},{"id":"s18-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">She lives <span class=\"blank-token\">____</span> the sea.</p>","options":["on","beside","in"],"correct":1,"answer":"B"}],"questionCount":8,"hasAnswers":true}]},{"id":"s19","section":19,"unit":4,"unitName":"单元04 · 第19–24节","short":"第19节 · L37–38","title":"be going to 的用法","lessons":"Lesson 37 — Lesson 38","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 的含义</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 与 be doing 的区别</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">be going to 的含义</div><div class=\"gb\"><p class=\"source-line\">be going to 表示在将来某个时间里将要发生的动作或存在的状态,表示“打算,将要”。常和表示将来的时间状语 next year（明年）、tomorrow（在明天）、in the future（在将来）等连用。</p>\n<p class=\"source-line\">—— What are you going to do, Dad? 你打算做什么,爸爸?<br/>\n—— I'm going to make a bookcase. 我打算做一个书架。</p>\n<p class=\"source-line\">—— What is he going to do? 他打算做什么？<br/>\n—— He is going to paint the bookcase. 他打算给书架漆上颜色。</p></div></div>\n<div class=\"g\"><div class=\"gt\">be going to 结构</div><div class=\"gb\"><h5>1. 含 be going to 结构的一般将来时的肯定句</h5>\n<p class=\"source-line\">结构: 主语 + be (am / is / are) going to + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">I am going to paint it pink. 我打算把它漆成粉色。</p>\n<h5>2. 含 be going to 结构的一般将来时的否定句</h5>\n<p class=\"source-line\">结构: 主语 + be (am / is / are) not going to + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">I am not going to paint it pink. 我不打算把它漆成粉色。</p>\n<h5>3. 含 be going to 结构的一般将来时的一般疑问句</h5>\n<p class=\"source-line\">结构: Be (Am / Is / Are) + 主语 + going to + 动词原形 (+ 其他)?</p>\n<p class=\"source-line\">Are you going to paint it pink? 你打算把它漆成粉色吗？</p>\n<h5>4. 含 be going to 结构的一般将来时的特殊疑问句</h5>\n<p class=\"source-line\">结构:疑问词+be(am/is/are)+主语+going to+动词原形(+其他)?</p>\n<p class=\"source-line\">When are you going to paint it? 你打算什么时候给它漆颜色？</p></div></div>\n<div class=\"g\"><div class=\"gt\">be going to 与 be doing 的区别</div><div class=\"gb\"><h5>1. be going to 结构常用在一般将来时中,表示在将来某个时间里将要发生的动作或存在的状态,表示“打算,将要”。</h5>\n<h5>2. be doing 结构常用在现在进行时中,表示现在正在进行或发生的动作。</h5>\n<p class=\"source-line\">I am going to make a bookcase. 我打算做一个书架。(打算要做)</p>\n<p class=\"source-line\">I am making a bookcase. 我正在做书架。(正在做)</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·盘龙区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s19-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> are they going to <span class=\"blank-token\">_</span> tomorrow?<br/><br>\n—— They are going to have a party.</br></p>","options":["When; do","What; go","What; do"],"correct":2,"answer":"C\n解析：答语意为 “他们打算举办一场派对”, 对做某事进行回答, 所以疑问词用 what。做某事用动词 do 代替。"},{"id":"s19-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm <span class=\"blank-token\">____</span> my grandmother tomorrow.</p>","options":["visited","going to visit","visit"],"correct":1,"answer":"B\n解析：tomorrow (在明天) 表示将来, 可用 be going to 结构表将来, 句中缺失的部分为 going to visit, 故此题选择 B 选项。"},{"id":"s19-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm going <span class=\"blank-token\">____</span> a tree tomorrow.</p>","options":["plant","to plant","plants"],"correct":1,"answer":"B"},{"id":"s19-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Are you going to take a piano lesson?<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["No, we don't.","No, I can't.","Yes, I am."],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【北京·丰台区】阅读短文，根据短文内容选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"<p class=\"source-line\">Ma Lili's parents are going to give a birthday party for her. She's going to be fourteen years old. Ma Lili has a lot of friends. They are going to come to the party. They are girls from Ma Lili's school. There are twenty-five of them.<br/>\nMa Lili's mother is making birthday cakes for the party. They are very nice cakes. Ma Lili says to her mother, \"Mum, you're very nice. Thank you for your nice cakes.\" Her father is going to go shopping. He will buy a lot of apples, bananas, oranges and pears. It will be a nice birthday party.</p>","items":[{"id":"s19-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Who is going to give Ma Lili a birthday party?</p>","options":["Ma Lili herself.","Her friends.","Her parents."],"correct":2,"answer":"C\n解析：句子意为 “谁打算给马丽丽举办一个生日派对?”, 第一段第一句话提到 “Ma Lili’s parents are going to give a birthday party for her. (马丽丽的父母打算为她举办一个生日派对。)”, 故正确答案为 C 选项。"},{"id":"s19-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">How many people are coming to Ma Lili's party?</p>","options":["Twenty.","Twenty-one.","Twenty-five."],"correct":2,"answer":"C\n解析：句子意为 “多少个人将要来马丽丽的派对?”, 在第一段提到 “Ma Lili has a lot of friends. They are going to the party. (马丽丽有很多朋友。他们打算来派对。)” “There are twenty-five of them. (他们有 25 个人。)”, 故正确答案为 C 选项。"},{"id":"s19-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Her mother <span class=\"blank-token\">____</span> for her party.</p>","options":["is making cakes","is shopping","makes a cake"],"correct":0,"answer":"A\n解析：句子意为 “她妈妈为她的聚会……”, 第二段第一句 “Ma Lili’s mother is making birthday cakes for the party. (马丽丽的妈妈正在为派对做蛋糕。)”, 句子时态为现在进行时, 故正确答案为 A 选项。"},{"id":"s19-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">How old is Ma Lili going to be?</p>","options":["12.","13.","14."],"correct":2,"answer":"C\n解析：句子意为 “马丽丽将要多少岁?”, 第一段提到 “She’s going to be fourteen years old. (她将要 14 岁了。)”, 故正确答案为 C 选项。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s19-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">—— What are you <span class=\"blank-token\"><strong><em>_</em></strong></span> (go) to do tomorrow?<br/><br>\n—— I'm <span class=\"blank-token\">_</span> (go) to <span class=\"blank-token\">____</span> (have) a picnic.</br></p>","options":[],"correct":null,"answer":"going; going; have"},{"id":"s19-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) you going to see a play this weekend?<br/><br>\n—— Yes, we <span class=\"blank-token\">_</span> (be).</br></p>","options":[],"correct":null,"answer":"Are; are"},{"id":"s19-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">—— What are you doing?<br/><br>\n—— I'm <span class=\"blank-token\">____</span> (have) an English lesson.</br></p>","options":[],"correct":null,"answer":"having"},{"id":"s19-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) you doing?<br/><br>\n—— I <span class=\"blank-token\">_</span> (be) washing the dishes.</br></p>","options":[],"correct":null,"answer":"are; am"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s19-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Mike is going to <u>Shanghai</u> next week. (对画线部分提问)</p>","options":[],"correct":null,"answer":"Where is Mike going next week?"},{"id":"s19-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I'm going to buy some delicious food. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Are you going to buy any delicious food?"},{"id":"s19-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">They are going to <u>watch a film</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What are they going to do?"},{"id":"s19-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I'm going to catch fish next week. (改为否定句)</p>","options":[],"correct":null,"answer":"I'm not going to catch fish next week."}],"questionCount":4,"hasAnswers":true}]},{"id":"s20","section":20,"unit":4,"unitName":"单元04 · 第19–24节","short":"第20节 · L39–40","title":"动词 + 间接宾语 + 直接宾语","lessons":"Lesson 39 — Lesson 40","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>宾语</td>\n<td>宾语</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>宾语</td>\n<td>直接宾语和间接宾语</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>祈使句</td>\n<td>否定祈使句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">宾语</div><div class=\"gb\"><p class=\"source-line\">宾语表示动作的对象,是动作的承受者。英语的及物动词须接宾语,宾语一般放在及物动词之后。可以用作宾语的有名词、代词、数词、动词不定式、动名词、名词化的形容词或分词、短语和从句。</p>\n<p class=\"source-line\">Pass me the fork, please. 请把叉子递给我。\nCan you see her? 你能看到她吗？</p></div></div>\n<div class=\"g\"><div class=\"gt\">直接宾语和间接宾语</div><div class=\"gb\"><h5>1. 有些及物动词,如 give(给)、tell(告诉)、show(给……看)、pass(递)、send(发送)、lend(借给)、bring(带来)等,可以有两个宾语。这种动词所要接的两个宾语,往往一个指物,一个指人。指物的叫直接宾语,指人的叫间接宾语。间接宾语一般放在直接宾语之前。</h5>\n<p class=\"source-line\">Give me a book, please. 请给我一本书。</p>\n<p class=\"source-line\">(me 是间接宾语, book 是直接宾语)</p>\n<p class=\"source-line\">Show me that picture. 给我看看那张照片。</p>\n<p class=\"source-line\">(me 是间接宾语, picture 是直接宾语)</p>\n<h5>2. 双宾语结构可改为“动词 + 直接宾语 + to / for + 间接宾语”。</h5>\n<p class=\"source-line\">如果直接宾语是人称代词，通常必须把直接宾语放在前面，再用 to 或 for 引出间接宾语。</p>\n<p class=\"source-line\">Can you see the green bag? Hand it to me, please.</p>\n<p class=\"source-line\">你能看见那个绿色的包吗？请把它递给我。</p>\n<p class=\"source-line\">Take those flowers to her.</p>\n<p class=\"source-line\">把那些花儿带给她。</p>\n<h5>3. 强调间接宾语时,把作为直接宾语的名词放在前面,把带 to 的间接宾语放在后面。</h5>\n<p class=\"source-line\">I sent an email to my grandmother yesterday.</p>\n<p class=\"source-line\">我昨天给我奶奶发送了一封电子邮件。</p></div></div>\n<div class=\"g\"><div class=\"gt\">否定祈使句</div><div class=\"gb\"><h5>1. 表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.),为表示礼貌,可在句首或句末加上“please”。句子用降调朗读。</h5>\n<p class=\"source-line\">Be careful next time. 下次小心点儿。</p>\n<p class=\"source-line\">Don't be late! 不要迟到!</p>\n<h5>2. 祈使句的否定结构</h5>\n<p class=\"source-line\">（1）Let 型否定祈使句：</p>\n<p class=\"source-line\">① Don't let + 宾语 + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Don't let him go out. 不要让他出去。</p>\n<p class=\"source-line\">② Let + 宾语 + not + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Let him not go out. 不要让他出去。</p>\n<p class=\"source-line\">（2）No 型否定祈使句: No + 动词 -ing 形式. / No + 名词.</p>\n<p class=\"source-line\">No parking!\n禁止停车!</p>\n<p class=\"source-line\">No photos!\n禁止拍照!</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·盘龙区】用括号内所给动词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s20-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Don't <span class=\"blank-token\">____</span> (open) the door.</p>","options":[],"correct":null,"answer":"open"},{"id":"s20-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">No <span class=\"blank-token\">____</span> (talk)!</p>","options":[],"correct":null,"answer":"talking"},{"id":"s20-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Mary shows <span class=\"blank-token\">____</span> (I) her new bag.</p>","options":[],"correct":null,"answer":"me"},{"id":"s20-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">My mother bought a bike for <span class=\"blank-token\">____</span> (I).</p>","options":[],"correct":null,"answer":"me"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【合肥·蜀山区】把下列肯定祈使句改为否定祈使句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s20-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Put on your hat.（改为否定祈使句）</p>","options":[],"correct":null,"answer":"Don't put on your hat.\n解析：根据 Do 型祈使句的否定结构: Don't + 动词原形 + 其他. 在 put 前加 Don't。"},{"id":"s20-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Turn on the lights.（改为否定祈使句）</p>","options":[],"correct":null,"answer":"Don't turn on the lights.\n解析：Do 型祈使句的否定结构为 “Don’t + 动词原形 (+ 其他)”, 故在 turn 前加 “Don’t”。"},{"id":"s20-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Take off your coats.（改为否定祈使句）</p>","options":[],"correct":null,"answer":"Don't take off your coats.\n解析：Do 型祈使句的否定结构为 “Don’t + 动词原形 (+ 其他)”, 故在 take 前加 “Don’t”。"},{"id":"s20-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Let's go and play together.（改为否定祈使句）</p>","options":[],"correct":null,"answer":"Let's not go and play together.\n解析：Let 型祈使句的否定结构为 “Let + 宾语 + not + 动词原形 (+ 其他)”, 故在 Let's 后加 not。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s20-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Please give these books <span class=\"blank-token\">____</span> me.</p>","options":["to","for"],"correct":0,"answer":"A"},{"id":"s20-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I buy some flowers <span class=\"blank-token\">____</span> my mum on Mother's Day.</p>","options":["for","to"],"correct":0,"answer":"A"},{"id":"s20-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">They want to sing a birthday song <span class=\"blank-token\">____</span> Kitty.</p>","options":["to","for"],"correct":1,"answer":"B"},{"id":"s20-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">She lent some money <span class=\"blank-token\">____</span> me yesterday.</p>","options":["for","to"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"写出下列句子的同义句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s20-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Give me the book.</p>","options":[],"correct":null,"answer":"Give the book to me."},{"id":"s20-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Send him the letter.</p>","options":[],"correct":null,"answer":"Send the letter to him."},{"id":"s20-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Show me that book.</p>","options":[],"correct":null,"answer":"Show that book to me."},{"id":"s20-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Pass the pen to me.</p>","options":[],"correct":null,"answer":"Pass me the pen."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s20-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> with fire. It's dangerous.</p>","options":["Playing","Doesn't","Don't play"],"correct":2,"answer":"C"},{"id":"s20-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't <span class=\"blank-token\">____</span> the radio. The baby is sleeping.</p>","options":["turn off","turn on","turn over"],"correct":1,"answer":"B"},{"id":"s20-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> cross the road until the traffic light turns green.</p>","options":["Don't","Doesn't","Not"],"correct":0,"answer":"A"},{"id":"s20-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> smoking!</p>","options":["Not","Don't","No"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true}]},{"id":"s21","section":21,"unit":4,"unitName":"单元04 · 第19–24节","short":"第21节 · L41–42","title":"不可数名词","lessons":"Lesson 41 — Lesson 42","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>不可数名词</td>\n<td>概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>不可数名词</td>\n<td>不可数名词的量的表示方法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是不可数名词？</div><div class=\"gb\"><p class=\"source-line\">不可数名词是不能直接用数词计数的名词。常见的不可数名词包括液体、食品、材料以及抽象概念等。不可数名词通常没有复数形式，表示具体数量时需要借助量词。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>类型</th>\n<th>说明</th>\n<th>示例</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>不可数名词</td>\n<td>物质名词</td>\n<td>无法分为个体的实物的词</td>\n<td>cheese 乳酪 soap 肥皂 milk 牛奶 bread 面包</td>\n</tr>\n<tr>\n<td>不可数名词</td>\n<td>抽象名词</td>\n<td>表示动作、状态、品质、感情等抽象概念的词</td>\n<td>work 工作 study 学习 love 爱 friendship 友谊</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">不可数名词的量的表示方法</div><div class=\"gb\"><h5>1. 用 some、much、a little、a lot of、a bit of、plenty of 等数量形容词表示。</h5>\n<div class=\"custom-block note\"><div class=\"custom-block-title\">不可数名词的修饰语</div><p class=\"source-line\">some meat 一些肉<br/>a lot of money 很多钱<br/>a little water 一点水</p>\n<p class=\"source-line\">plenty of、some、a lot of、lots of、most of 等既可修饰可数名词复数，也可修饰不可数名词。</p></div>\n<h5>2. 用 “a ... of” 表示。</h5>\n<p class=\"source-line\">（1）表 “条、块、片、张、份、则” 的 piece。</p>\n<p class=\"source-line\">a piece of meat 一块肉</p>\n<p class=\"source-line\">a piece of paper 一张纸</p>\n<p class=\"source-line\">two pieces of information 两条信息</p>\n<p class=\"source-line\">a piece of advice 一条建议</p>\n<p class=\"source-line\">a piece of news 一则新闻</p>\n<p class=\"source-line\">（2）表“容积、容量”的 glass（一杯的量）、cup（一杯的量）、bottle（一瓶的量）、</p>\n<p class=\"source-line\">basket(一篮)。</p>\n<p class=\"source-line\">a glass of milk 一杯牛奶</p>\n<p class=\"source-line\">a bottle of juice 一瓶果汁</p>\n<p class=\"source-line\">a cup of tea 一杯茶</p>\n<p class=\"source-line\">a basket of food 一篮食物</p>\n<p class=\"source-line\">（3）表 “形状” 的 loaf(条)、bar(块)、tin(罐)。</p>\n<p class=\"source-line\">a loaf of bread 一条面包</p>\n<p class=\"source-line\">a tin of beans 一罐青豆</p>\n<p class=\"source-line\">a bar of soap 一块肥皂</p>\n<p class=\"source-line\">（4）表 “重量” 的 kilo (千克)、pound (磅)。</p>\n<p class=\"source-line\">a pound of sugar 一磅糖</p>\n<p class=\"source-line\">half a pound of coffee 半磅咖啡</p>\n<p class=\"source-line\">two kilos of meat 两千克肉</p>\n<p class=\"source-line\">（5）表“行为状态”的单位词。</p>\n<p class=\"source-line\">a ray of hope 一线希望</p>\n<p class=\"source-line\">a flash of lightning 一道闪电</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·南开区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s21-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">They don't have <span class=\"blank-token\">____</span>.</p>","options":["much homework","many homeworks","many homework","much homeworks"],"correct":0,"answer":"A\n解析：homework(家庭作业)为不可数名词, 可以用 much(许多)修饰。many(许多)常用来修饰可数名词复数。"},{"id":"s21-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Can you give me <span class=\"blank-token\">____</span>?</p>","options":["a sheet paper","some pieces of paper","some pieces of papers","some piece of paper"],"correct":1,"answer":"B\n解析：paper(纸)为不可数名词, 其前不可以加不定冠词, 也不可以把 paper 变为复数形式。piece(块; 张)为可数名词, 复数形式为 pieces。故此题选择 B 选项。"},{"id":"s21-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Would you like to have a drink?<br/><br>\n—— Yes. Two <span class=\"blank-token\">____</span>, please.</br></p>","options":["cup of tea","cups of tea","cup of teas","cups of teas"],"correct":1,"answer":"B\n解析：two(二)后接可数名词复数, cup(杯)的复数形式为 cups。tea(茶)为不可数名词,无复数形式。故此题选择 B 选项。"},{"id":"s21-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">We have some <span class=\"blank-token\"><strong><em>_</em></strong></span> and <span class=\"blank-token\">_</span> every morning.</p>","options":["milks; egg","milks; eggs","milk; eggs","milk; egg"],"correct":2,"answer":"C\n解析：some (一些) 可以修饰可数名词复数或不可数名词, milk (牛奶) 为不可数名词, egg (鸡蛋) 的复数形式为 eggs。故此题选择 C 选项。"},{"id":"s21-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Dad has <span class=\"blank-token\">____</span> for breakfast.</p>","options":["two piece of bread","two pieces of bread","two piece of breads","two pieces of breads"],"correct":1,"answer":"B\n解析：two (二) 后接可数名词复数, piece (块; 张) 为可数名词, 复数形式为 pieces。bread (面包) 为不可数名词。故此题选择 B 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【沈阳·铁西区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s21-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">There is some <span class=\"blank-token\">____</span> (water) in the bottle.</p>","options":[],"correct":null,"answer":"water"},{"id":"s21-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Do you want to have two <span class=\"blank-token\"><strong><em>_</em></strong></span> (pound) of <span class=\"blank-token\">_</span> (sugar)?</p>","options":[],"correct":null,"answer":"pounds, sugar"},{"id":"s21-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I'd like a <span class=\"blank-token\">____</span> (loaf) of bread for breakfast.</p>","options":[],"correct":null,"answer":"loaf"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"根据汉语提示完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s21-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">There are <span class=\"blank-token\">____</span> (三杯茶) on the desk.</p>","options":[],"correct":null,"answer":"three cups of tea"},{"id":"s21-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Give me <span class=\"blank-token\">____</span> (一块巧克力).</p>","options":[],"correct":null,"answer":"a bar of chocolate"},{"id":"s21-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">There is <span class=\"blank-token\">____</span> (一磅茶叶).</p>","options":[],"correct":null,"answer":"a pound of tea"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"连词成句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s21-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">chocolate, bars, are, some, there, the, in, bag, of ( . )</p>","options":[],"correct":null,"answer":"There are some bars of chocolate in the bag."},{"id":"s21-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">any, there, in, is, not, milk, the, glass (.)</p>","options":[],"correct":null,"answer":"There is not any milk in the glass."},{"id":"s21-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">please, me, pound, a, of, sugar, for, buy ( . )</p>","options":[],"correct":null,"answer":"Please buy a pound of sugar for me."}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s21-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Dad has <span class=\"blank-token\">____</span> for breakfast.</p>","options":["two piece of bread","two pieces of bread","two piece of breads","two pieces of breads"],"correct":1,"answer":"B"},{"id":"s21-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">He doesn't have <span class=\"blank-token\">____</span>.</p>","options":["much homework","many homeworks","many homework","much homeworks"],"correct":0,"answer":"A"},{"id":"s21-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">We're busy because we have so <span class=\"blank-token\">____</span> housework to do today.</p>","options":["few","little","many","much"],"correct":3,"answer":"D"},{"id":"s21-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm <span class=\"blank-token\">____</span> hungry. I only ate some bread in the morning.</p>","options":["a little","plenty of","a few","few"],"correct":0,"answer":"A"},{"id":"s21-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">There is <span class=\"blank-token\">____</span> meat in the fridge.</p>","options":["any","many","some","few"],"correct":2,"answer":"C"},{"id":"s21-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you give me <span class=\"blank-token\">____</span>, Mary?</p>","options":["two bag of ice","two bags of ices","two bag of ices","two bags of ice"],"correct":3,"answer":"D"},{"id":"s21-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Can you give us some <span class=\"blank-token\">____</span> about the writer?</p>","options":["informations","an information","piece of informations","pieces of information"],"correct":3,"answer":"D"},{"id":"s21-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">I had a cup of <span class=\"blank-token\"><strong><em>_</em></strong></span> and two pieces of <span class=\"blank-token\">_</span> this morning.</p>","options":["teas; breads","teas; bread","tea; breads","tea; bread"],"correct":3,"answer":"D"}],"questionCount":8,"hasAnswers":true}]},{"id":"s22","section":22,"unit":4,"unitName":"单元04 · 第19–24节","short":"第22节 · L43–44","title":"情态动词 can","lessons":"Lesson 43 — Lesson 44","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>情态动词 can</td>\n<td>情态动词的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>情态动词 can</td>\n<td>can 的用法</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>情态动词 can</td>\n<td>can 的句式结构</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是情态动词？</div><div class=\"gb\"><p class=\"source-line\">情态动词本身有一定的词义,表示说话人对有关行为或事物的态度和看法,认为其可能、应该或必要等。</p>\n<p class=\"source-line\">情态动词不能独立作谓语, 只能和动词原形一起构成谓语。情态动词没有人称和数的变化。</p>\n<p class=\"source-line\">常见的情态动词有 : can / could (能, 可以)、may / might (可能)、must (必须)、will / would (将要)、need (需要) 等。</p>\n<p class=\"source-line\">I can swim. 我会游泳。</p>\n<p class=\"source-line\">Her mother may be at home. 她妈妈可能在家。</p>\n<p class=\"source-line\">You must clean your bedroom on Sunday.</p>\n<p class=\"source-line\">你必须在星期日打扫你的卧室。</p>\n<p class=\"source-line\">Need I go home at once? 我需要立刻回家吗?</p></div></div>\n<div class=\"g\"><div class=\"gt\">can 的用法</div><div class=\"gb\"><h5>1. 表示能力,意为“能,会”。</h5>\n<p class=\"source-line\">I can speak English, but he can't. 我会讲英语,但是他不会。</p>\n<p class=\"source-line\">She can swim. 她会游泳。</p>\n<h5>2. 表示允许、许可或请求。</h5>\n<p class=\"source-line\">Can / May I come in? 我可以进来吗?\nCan / Could you help me? 你能帮我吗?</p>\n<h5>3. 用于否定句或疑问句中,表示推测。</h5>\n<p class=\"source-line\">The girl can't be Li Mei. She's at school.\n那个女孩儿不可能是李梅，她在学校呢。\nJack can't be at home. 杰克不可能在家。</p>\n<p class=\"source-line\">cannot = can't</p></div></div>\n<div class=\"g\"><div class=\"gt\">can 的句式结构</div><div class=\"gb\"><h5>1. 肯定句: 主语 + can + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">I can see three boats on the river. 我能看到河面上有 3 条船。</p>\n<p class=\"source-line\">He can play the guitar. 他会弹吉他。</p>\n<h5>2. 否定句: 主语 + can't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">She can't play volleyball. 她不会打排球。</p>\n<p class=\"source-line\">I can't dance. 我不会跳舞。</p>\n<h5>3. 一般疑问句: Can + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + can.</p>\n<p class=\"source-line\">否定回答: No, 主语 + can't.</p>\n<p class=\"source-line\">—— Can you sing English songs? 你会唱英文歌曲吗?<br/>\n—— Yes, I can. 是的,我会。</p>\n<p class=\"source-line\">—— Can you play the piano? 你会弹钢琴吗?<br/>\n—— No, I can't. 不,我不会。</p>\n<h5>4. 特殊疑问句: 疑问词 + can + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">What can you do? 你会做什么？</p>\n<p class=\"source-line\">Who can play the violin? 谁会拉小提琴?</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·南海区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s22-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> you play football?<br/><br>\n—— Yes, I can.</br></p>","options":["Do","Can","Are"],"correct":1,"answer":"B"},{"id":"s22-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can I listen to music here?<br/><br>\n—— <span class=\"blank-token\">____</span>, but you can listen in the music room.</br></p>","options":["Yes, you can","No, you can't","Yes, I do"],"correct":1,"answer":"B"},{"id":"s22-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I can <span class=\"blank-token\">____</span>.</p>","options":["do kung fu","does kung fu","did kung fu"],"correct":0,"answer":"A"},{"id":"s22-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can you sing?<br/><br>\n—— No, I <span class=\"blank-token\">____</span>.</br></p>","options":["can","don't","can't"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【天津·南开区】按照要求完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s22-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Can you <span class=\"blank-token\">____</span> (find) any ice cream? (用所给词的正确形式填空)</p>","options":[],"correct":null,"answer":"find\n解析：由 can 引导的一般疑问句句型结构为 “Can + 主语 + 动词原形(+其他)?”, 故填 find。"},{"id":"s22-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">She can see <u>two birds</u> in the picture. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What can she see in the picture?\n解析：画线部分是物体,疑问词用 what,句子其他部分变成一般疑问句,can 提前,末尾句号变问号。"},{"id":"s22-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">你能做什么？（翻译句子）</p>","options":[],"correct":null,"answer":"What can you do?"},{"id":"s22-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I can make cakes, but I <span class=\"blank-token\">____</span> (can) make biscuits. (用所给词的正确形式填空)</p>","options":[],"correct":null,"answer":"can't\n解析：句中 but 表转折, 前半句是肯定, 后半句应是否定, 故填 can't。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用所给单词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s22-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I can <span class=\"blank-token\">____</span> (play) basketball.</p>","options":[],"correct":null,"answer":"play"},{"id":"s22-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Can you <span class=\"blank-token\">____</span> (swim) in the swimming pool?</p>","options":[],"correct":null,"answer":"swim"},{"id":"s22-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\">____</span> (can) he do?</p>","options":[],"correct":null,"answer":"can"},{"id":"s22-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">She can <span class=\"blank-token\">____</span> (dance).</p>","options":[],"correct":null,"answer":"dance"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"根据汉语意思完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s22-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">你哥哥会游泳吗？</p>\n<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> your brother <span class=\"blank-token\">_</span> ?</p>","options":[],"correct":null,"answer":"Can, swim"},{"id":"s22-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">玛丽不会打篮球。</p>\n<p class=\"source-line\">Mary <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> basketball.</p>","options":[],"correct":null,"answer":"can't play"},{"id":"s22-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">你会说英语吗？</p>\n<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> English ?</p>","options":[],"correct":null,"answer":"Can, speak"},{"id":"s22-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">你爸爸会打乒乓球吗？是的，他会。</p>\n<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> your father <span class=\"blank-token\">_</span> ping-pong ?</p>\n<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span>, he <span class=\"blank-token\">_</span>.</p>","options":[],"correct":null,"answer":"Can, play, Yes, can"}],"questionCount":4,"hasAnswers":true}]},{"id":"s23","section":23,"unit":4,"unitName":"单元04 · 第19–24节","short":"第23节 · L45–46","title":"一般现在时（一）","lessons":"Lesson 45 — Lesson 46","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般现在时(一)</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>一般现在时(一)</td>\n<td>一般现在时的构成</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(一)</td>\n<td>动词第三人称单数形式的变化规则</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是一般现在时？</div><div class=\"gb\"><p class=\"source-line\">一般现在时表示经常性、习惯性或规律性的动作，也可表示现在的状态、客观事实或普遍真理。</p>\n<p class=\"source-line\">I get up at six o'clock every morning. 我每天早上6:00起床。</p>\n<p class=\"source-line\">I often go to school by bus. 我经常乘公共汽车去上学。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的构成</div><div class=\"gb\"><h5>1. 含有 be 动词的一般现在时。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + 表语(+其他).</p>\n<p class=\"source-line\">I am a boy. 我是一个男孩儿。</p>\n<p class=\"source-line\">It is cloudy today. 今天多云。</p>\n<h5>2. 含有实义动词的一般现在时。</h5>\n<p class=\"source-line\">结构: 主语+实义动词(+其他).</p>\n<p class=\"source-line\">It works well. 它运转正常。</p>\n<p class=\"source-line\">She goes to work by bike every day. 她每天骑自行车去上班。</p></div></div>\n<div class=\"g\"><div class=\"gt\">动词第三人称单数形式的变化规则</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>变化规则</th>\n<th>例词</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般情况下,在词尾直接加s</td>\n<td>run — runs<br/>like — likes</td>\n</tr>\n<tr>\n<td>以s、x、sh、ch、o结尾的动词,在词尾加es</td>\n<td>pass — passes<br/>teach — teaches</td>\n</tr>\n<tr>\n<td>以辅音字母加y结尾的动词,把y变i,再加es</td>\n<td>try — tries<br/>study — studies</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（1）以元音字母加 y 结尾的动词，在词尾加 s，如：pay — pays、play — plays 等。</p>\n<p class=\"source-line\">（2）have 的第三人称单数形式是 has。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·丰台区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s23-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\"><strong><em>_</em></strong></span> (want) to be a teacher. But he <span class=\"blank-token\">_</span> (want) to be a doctor.</p>","options":[],"correct":null,"answer":"want, wants\n解析：前一句主语 I (我) 为第一人称, 故后面实义动词用原形 want; 后一句主语 he (他) 是第三人称单数, 故后面的实义动词用单三形式 wants。"},{"id":"s23-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Andy and I <span class=\"blank-token\">____</span> (watch) TV every Sunday.</p>","options":[],"correct":null,"answer":"watch\n解析：主语 Andy and I(安迪和我)是复数, 故后面的实义动词用原形 watch。"},{"id":"s23-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Mary usually <span class=\"blank-token\">____</span> (get) up at 6:30 in the morning.</p>","options":[],"correct":null,"answer":"gets"},{"id":"s23-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">My parents often <span class=\"blank-token\">____</span> (go) to the supermarket on Sundays.</p>","options":[],"correct":null,"answer":"go"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【佛山·三水区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s23-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Alice <span class=\"blank-token\"><strong><em>_</em></strong></span> a student. I <span class=\"blank-token\">_</span> a worker. They <span class=\"blank-token\">____</span> drivers.</p>","options":["are ; is ; am","is ; am ; are","am ; is ; are"],"correct":1,"answer":"B\n解析：第一句主语 Alice (艾丽斯) 是第三人称单数, 故 be 动词用 is; 第二句主语 I (我) 是第一人称, 故 be 动词用 am; 第三句主语 They (他们) 是第三人称复数, 故 be 动词用 are。"},{"id":"s23-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Jack and his mother <span class=\"blank-token\">____</span> at the supermarket.</p>","options":["are","is","am"],"correct":0,"answer":"A\n解析：主语 Jack and his mother (杰克和他妈妈) 是复数, 故 be 动词用 are。"},{"id":"s23-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> to bed at nine every night.</p>","options":["is","go","goes"],"correct":2,"answer":"C"},{"id":"s23-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">My brother <span class=\"blank-token\">____</span> his homework every day.</p>","options":["does","do","is"],"correct":0,"answer":"A"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"写出下列动词的第三人称单数形式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s23-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">drink</p>","options":[],"correct":null,"answer":"drinks"},{"id":"s23-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">go</p>","options":[],"correct":null,"answer":"goes"},{"id":"s23-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">stay</p>","options":[],"correct":null,"answer":"stays"},{"id":"s23-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">make</p>","options":[],"correct":null,"answer":"makes"},{"id":"s23-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">look</p>","options":[],"correct":null,"answer":"looks"},{"id":"s23-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">have</p>","options":[],"correct":null,"answer":"has"},{"id":"s23-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">pass</p>","options":[],"correct":null,"answer":"passes"},{"id":"s23-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">carry</p>","options":[],"correct":null,"answer":"carries"},{"id":"s23-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">watch</p>","options":[],"correct":null,"answer":"watches"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"用括号内所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s23-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">He often <span class=\"blank-token\">____</span> (have) dinner at home.</p>","options":[],"correct":null,"answer":"has"},{"id":"s23-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">Daniel and Tommy <span class=\"blank-token\">____</span> (be) in Class One.</p>","options":[],"correct":null,"answer":"are"},{"id":"s23-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (not watch) TV on Monday.</p>","options":[],"correct":null,"answer":"don't watch"},{"id":"s23-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">Nick <span class=\"blank-token\">____</span> (not go) to the zoo on Sunday.</p>","options":[],"correct":null,"answer":"doesn't go"},{"id":"s23-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> they <span class=\"blank-token\">_</span> (like) the World Cup?</p>","options":[],"correct":null,"answer":"Do, like"},{"id":"s23-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">Bob <span class=\"blank-token\">____</span> (go) to the garden every day.</p>","options":[],"correct":null,"answer":"goes"},{"id":"s23-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">We usually <span class=\"blank-token\">____</span> (play) football after school.</p>","options":[],"correct":null,"answer":"play"},{"id":"s23-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">Linda <span class=\"blank-token\">____</span> (study) English every day.</p>","options":[],"correct":null,"answer":"studies"},{"id":"s23-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">My parents <span class=\"blank-token\">____</span> (do) exercise every day.</p>","options":[],"correct":null,"answer":"do"},{"id":"s23-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">Sally <span class=\"blank-token\">____</span> (ride) a bike to school every day.</p>","options":[],"correct":null,"answer":"rides"},{"id":"s23-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> (take) a bus to school every day.</p>","options":[],"correct":null,"answer":"take"}],"questionCount":11,"hasAnswers":true},{"source":"textbook","title":"用 be 动词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s23-text-q021","number":21,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> from Australia.</p>","options":[],"correct":null,"answer":"am"},{"id":"s23-text-q022","number":22,"type":"input","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> a student.</p>","options":[],"correct":null,"answer":"is"},{"id":"s23-text-q023","number":23,"type":"input","questionHtml":"<p class=\"source-line\">My parents <span class=\"blank-token\">____</span> very busy.</p>","options":[],"correct":null,"answer":"are"},{"id":"s23-text-q024","number":24,"type":"input","questionHtml":"<p class=\"source-line\">The dog <span class=\"blank-token\">____</span> tall and fat.</p>","options":[],"correct":null,"answer":"is"},{"id":"s23-text-q025","number":25,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> friends.</p>","options":[],"correct":null,"answer":"are"}],"questionCount":5,"hasAnswers":true}]},{"id":"s24","section":24,"unit":4,"unitName":"单元04 · 第19–24节","short":"第24节 · L47–48","title":"一般现在时（二）","lessons":"Lesson 47 — Lesson 48","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的肯定句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的否定句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的一般疑问句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的特殊疑问句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般现在时的肯定句</div><div class=\"gb\"><h5>1. 含有 be 动词的肯定句。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + 表语(+其他).</p>\n<p class=\"source-line\">They are good friends.\n他们是好朋友。</p>\n<p class=\"source-line\">She is my English teacher. 她是我的英语老师。</p>\n<h5>2. 含有实义动词的肯定句。</h5>\n<p class=\"source-line\">结构: 主语+实义动词(+其他).</p>\n<p class=\"source-line\">I have a beautiful cup.</p>\n<p class=\"source-line\">我有一个漂亮的杯子。</p>\n<p class=\"source-line\">My mother goes to work by bus every day.</p>\n<p class=\"source-line\">我妈妈每天乘公共汽车去上班。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的否定句</div><div class=\"gb\"><h5>1. 含有 be 动词的否定句。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + not + 表语(+其他).</p>\n<p class=\"source-line\">She is not my sister. 她不是我姐姐。</p>\n<p class=\"source-line\">Those are not donkeys. 那些不是驴。</p>\n<h5>2. 含有实义动词的否定句。</h5>\n<p class=\"source-line\">结构: 主语+助动词(do / does) + not + 其他.</p>\n<p class=\"source-line\">I do not like tigers. 我不喜欢老虎。</p>\n<p class=\"source-line\">She does not like pears. 她不喜欢梨。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的一般疑问句</div><div class=\"gb\"><h5>1. 含有 be 动词的一般疑问句。</h5>\n<p class=\"source-line\">结构: Be 动词(Am / Is / Are) + 主语 + 表语(+其他)?</p>\n<p class=\"source-line\">Is Mr White a writer? 怀特先生是一位作家吗?</p>\n<p class=\"source-line\">Is this your pen? 这是你的钢笔吗？</p>\n<h5>2. 含有实义动词的一般疑问句。</h5>\n<p class=\"source-line\">结构: Do / Does + 主语 + 动词原形 (+ 其他)?</p>\n<p class=\"source-line\">Do you like watermelons? 你喜欢西瓜吗？</p>\n<p class=\"source-line\">Does he read English every morning? 他每天早上读英语吗?</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的特殊疑问句</div><div class=\"gb\"><h5>1. 对地点提问。</h5>\n<p class=\"source-line\">Where is the supermarket? 超市在哪里?</p>\n<p class=\"source-line\">Where do you want to go? 你想去哪里？</p>\n<h5>2. 对时间提问。</h5>\n<p class=\"source-line\">When is your birthday? 你的生日在什么时候？</p>\n<p class=\"source-line\">What time do you usually get up? 你通常几点起床？</p>\n<h5>3. 对方式提问。</h5>\n<p class=\"source-line\">How does your mother go to work? 你妈妈怎么去上班?\nHow do you go to school? 你怎么上学?</p>\n<h5>4. 对人物提问。</h5>\n<p class=\"source-line\">Who is your Chinese teacher? 你的语文老师是谁?\nWho are they? 他们是谁?</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·红桥区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s24-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I often <span class=\"blank-token\">____</span> school by bus.</p>","options":["going to","goes to","go to"],"correct":2,"answer":"C\n解析：主语 I(我) 是第一人称, 故后面的动词用原形 go。"},{"id":"s24-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> you like playing the guitar?</p>","options":["Do","Are","Does"],"correct":0,"answer":"A\n解析：主语 you (你 / 你们) 是第二人称, 谓语动词是实义动词, 故用助动词 Do。"},{"id":"s24-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\"><strong><em>_</em></strong></span> they usually <span class=\"blank-token\">_</span> on Sundays?</p>","options":["do; does","do; do","does; do"],"correct":1,"answer":"B\n解析：这是 what 引导的特殊疑问句, 主语 they (他们) 是第三人称复数, 故助动词用 do, 第二个空根据句意选择实义动词 do (做; 干)。"},{"id":"s24-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">How <span class=\"blank-token\">____</span> Andy go to school every day?</p>","options":["do","is","does"],"correct":2,"answer":"C\n解析：这是 how 引导的特殊疑问句, 主语 Andy (安迪) 是第三人称单数, 谓语动词是实义动词, 故助动词用 does。"},{"id":"s24-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">My mother usually <span class=\"blank-token\">____</span> clothes on Sundays.</p>","options":["wash","washes","washing"],"correct":1,"answer":"B\n解析：主语是第三人称单数, 故后面的动词用单三形式。"},{"id":"s24-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> those tomatoes?</p>","options":["Do","Is","Are"],"correct":2,"answer":"C\n解析：句中没有实义动词, 主语 those (那些) 表示复数, 故用 be 动词 are。"},{"id":"s24-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Does he <span class=\"blank-token\">____</span> dinner at home?</p>","options":["having","had","have"],"correct":2,"answer":"C\n解析：由 does 引导的一般疑问句,后面的动词用原形,故用 have。"},{"id":"s24-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Alice <span class=\"blank-token\">____</span> to learn cooking.</p>","options":["wants","want","want to"],"correct":0,"answer":"A\n解析：主语是第三人称单数, 故后面的动词用单三形式。"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"用括号中所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s24-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Susan <span class=\"blank-token\"><strong><em>_</em></strong></span> (have) a stomachache.<br/><br>\nShe must <span class=\"blank-token\">_</span> (take) some medicine.</br></p>","options":[],"correct":null,"answer":"has, take"},{"id":"s24-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Sam <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) ill, so he can't <span class=\"blank-token\">_</span> (go) to school today.</p>","options":[],"correct":null,"answer":"is, go"},{"id":"s24-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">That <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) good news for Tom because he doesn't <span class=\"blank-token\">_</span> (like) sports.</p>","options":[],"correct":null,"answer":"is, like"},{"id":"s24-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> he <span class=\"blank-token\">_</span> (do) his homework every day?</p>","options":[],"correct":null,"answer":"Does, do"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s24-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">She wants some books. (改为否定句)</p>","options":[],"correct":null,"answer":"She doesn't want any books."},{"id":"s24-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I like some honey. (主语改为 he)</p>","options":[],"correct":null,"answer":"He likes some honey."},{"id":"s24-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\"><u>They</u> can see an apple in the picture. (对画线部分提问)</p>","options":[],"correct":null,"answer":"Who can see an apple in the picture?"},{"id":"s24-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Lucy watches TV at home on Sundays. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Does Lucy watch TV at home on Sundays?"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s24-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Lily's sister <span class=\"blank-token\">____</span> like dancing.</p>","options":["don't","not","doesn't","can't"],"correct":2,"answer":"C"},{"id":"s24-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">It often <span class=\"blank-token\">____</span> in Suzhou in summer.</p>","options":["rain","rains","rainy","raining"],"correct":1,"answer":"B"},{"id":"s24-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Look at the monkeys.<br/><br>\n—— Wow! They <span class=\"blank-token\">____</span> so funny.</br></p>","options":["is","are","am","be"],"correct":1,"answer":"B"},{"id":"s24-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">The book <span class=\"blank-token\">____</span> on the desk.</p>","options":["am","is","are","be"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true}]},{"id":"s25","section":25,"unit":5,"unitName":"单元05 · 第25–30节","short":"第25节 · L49–50","title":"选择疑问句","lessons":"Lesson 49 — Lesson 50","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>选择疑问句</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>一般疑问句式的选择疑问句</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>特殊疑问句式的选择疑问句</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>选择疑问句的回答</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>but的用法</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是选择疑问句？</div><div class=\"gb\"><p class=\"source-line\">选择疑问句是指提出两个或两个以上可能的答案供对方选择的句式。</p>\n<p class=\"source-line\">—— Do you want beef or mutton? 你想要牛肉还是羊肉？<br/>\n—— Beef, please. 牛肉。</p>\n<p class=\"source-line\">—— Would you like an apple or a banana? 你想要一个苹果还是一根香蕉？<br/>\n—— An apple, please. 一个苹果。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般疑问句式的选择疑问句</div><div class=\"gb\"><p class=\"source-line\">句型结构:一般疑问句+or+可选择内容?</p>\n<p class=\"source-line\">Are you in Class Three or Class Four?</p>\n<p class=\"source-line\">你在3班还是4班？</p>\n<p class=\"source-line\">Is he thirteen or fourteen? 他13岁还是14岁?</p></div></div>\n<div class=\"g\"><div class=\"gt\">特殊疑问句式的选择疑问句</div><div class=\"gb\"><p class=\"source-line\">句型结构: 特殊疑问句, 可选择内容 A + or + 可选择内容 B?</p>\n<p class=\"source-line\">Which do you prefer, tea or coffee?</p>\n<p class=\"source-line\">你更喜欢哪个,茶还是咖啡?</p>\n<p class=\"source-line\">How can we go to the park, by bus or by taxi?</p>\n<p class=\"source-line\">我们可以怎样去公园,乘坐公共汽车还是乘坐出租车?</p></div></div>\n<div class=\"g\"><div class=\"gt\">选择疑问句的回答</div><div class=\"gb\"><p class=\"source-line\">选择疑问句的回答不用 yes 或 no, 而是根据实际情况进行回答。</p>\n<p class=\"source-line\">—— Are your shoes red or blue? 你的鞋是红色的还是蓝色的？<br/>\n—— They are red. 它们是红色的。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">选择问句真奇妙，一般问句加上 or；or 的前后要对称，朗读时前升后降。</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">but 的用法</div><div class=\"gb\"><p class=\"source-line\">but 用于“肯定句+否定句”或“否定句+肯定句”中, 连接相反意思的词、短语或句子, 表示转折关系, 意为 “但是”。</p>\n<p class=\"source-line\">He likes steak, but he doesn't like chicken.</p>\n<p class=\"source-line\">他喜欢牛排,但是他不喜欢鸡肉。</p>\n<p class=\"source-line\">He likes steak, but I don't.</p>\n<p class=\"source-line\">他喜欢牛排，但是我不喜欢。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s25-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I like water <span class=\"blank-token\">____</span> I don't like cola.</p>","options":["and","but"],"correct":1,"answer":"B\n解析：“I like water” 为肯定句, 意为 “我喜欢水”; “I don’t like cola” 为否定句, 意为 “我不喜欢可乐”。前后句是转折关系, 表转折用 but。"},{"id":"s25-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">It will be warm <span class=\"blank-token\">____</span> sunny on Friday.</p>","options":["but","and"],"correct":1,"answer":"B\n解析：warm 和 sunny 都是描述天气的形容词，二者为并列关系，应用 and 连接。"},{"id":"s25-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I like cold <span class=\"blank-token\">____</span> snowy days.</p>","options":["and","but"],"correct":0,"answer":"A"},{"id":"s25-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I like ice cream <span class=\"blank-token\">____</span> I like cake.</p>","options":["but","and"],"correct":1,"answer":"B\n解析：“I like ice cream” 为肯定句, “I like cake” 为肯定句, 前后句是并列关系, 用 and。"},{"id":"s25-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I like cake <span class=\"blank-token\">____</span> I don't like ice cream.</p>","options":["and","but"],"correct":1,"answer":"B\n解析：“I like cake”为肯定句，“I don’t like ice cream”为否定句，前后句是转折关系，用 but。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【佛山·禅城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s25-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I have a brother <span class=\"blank-token\"><strong><em>_</em></strong></span> two sisters, <span class=\"blank-token\">_</span> I don't have cousins.</p>","options":["but; and","and; and","and; but"],"correct":2,"answer":"C\n解析：前半句中 a brother (一个兄弟) 和 two sisters (两个姐妹) 表示并列关系, 用 and 连接; 前后句是转折关系, 用 but。故此题选择 C 选项。"},{"id":"s25-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">David likes <span class=\"blank-token\"><strong><em>_</em></strong></span> model planes, <span class=\"blank-token\">_</span> Mike doesn't.</p>","options":["make; but","making; but","make; and"],"correct":1,"answer":"B\n解析：like (喜欢) 后接动词 -ing 形式或动词不定式, make (制作) 的 -ing 形式为 making。前后句是转折关系, 用 but。故此题选择 B 选项。"},{"id":"s25-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you like orange juice <span class=\"blank-token\">____</span> grape juice?<br/><br>\n—— I like orange juice.</br></p>","options":["or","so","but"],"correct":0,"answer":"A\n解析：问句是选择疑问句。orange juice (橙汁) 和 grape juice (葡萄汁) 用 or 连接。故此题选择 A 选项。"},{"id":"s25-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Would you like tea <span class=\"blank-token\"><strong><em>_</em></strong></span> milk?<br/><br>\n—— I don't like tea <span class=\"blank-token\">_</span> milk. I'd like some coffee.</br></p>","options":["and; and","and; or","or; or"],"correct":2,"answer":"C\n解析：问句是选择疑问句。tea(茶)和 milk(牛奶)用 or 连接。答语为否定句,否定句中连接两种事物用 or,而不用 and。故此题选择 C 选项。"},{"id":"s25-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you want these <span class=\"blank-token\">_</span> those?<br/><br>\n—— I want these.</br></p>","options":["Do; and","Are; or","Do; or"],"correct":2,"answer":"C\n解析：you (你)为第二人称, want (想要)为实义动词, 所以用助动词 do 提问。问句为选择疑问句, these (这些)和 those (那些)用 or 连接。故此题选择 C 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s25-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is this a Chinese book or an English book?</p>","options":["Yes, it is.","No, it isn't.","It's an English book.","It's a music book."],"correct":2,"answer":"C"},{"id":"s25-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is Jack French or American?</p>","options":["He is American.","No, he isn't.","Yes, it is.","No, it isn't."],"correct":0,"answer":"A"},{"id":"s25-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Which do you like better, <span class=\"blank-token\"><strong><em>_</em></strong></span> or <span class=\"blank-token\">_</span>?</p>","options":["biscuits; breads","biscuit; bread","biscuits; bread","biscuit; breads"],"correct":2,"answer":"C"},{"id":"s25-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> you want these <span class=\"blank-token\">_</span> those?</p>","options":["Are; and","Are; or","Do; or","Do; and"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s25-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">He likes coffee, but I <span class=\"blank-token\">____</span>.</p>","options":["can't","don't","doesn't","isn't"],"correct":1,"answer":"B"},{"id":"s25-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">She likes tea, but he <span class=\"blank-token\">____</span>.</p>","options":["don't","doesn't","isn't","can't"],"correct":1,"answer":"B"},{"id":"s25-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">He is eating some bread, but she <span class=\"blank-token\">____</span>.</p>","options":["doesn't","isn't","can't","don't"],"correct":1,"answer":"B"},{"id":"s25-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">I can dance and draw, but my friend <span class=\"blank-token\">____</span>.</p>","options":["isn't","can't","don't","doesn't"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true}]},{"id":"s26","section":26,"unit":5,"unitName":"单元05 · 第25–30节","short":"第26节 · L51–52","title":"关于 what 的句型","lessons":"Lesson 51 — Lesson 52","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>关于what的句型</td>\n<td>句型“What's ... like?”</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>关于what的句型</td>\n<td>句型“What do / does ... like?”</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">句型 What&#x27;s ... like?</div><div class=\"gb\"><p class=\"source-line\">句型结构1：</p>\n<p class=\"source-line\">（1）What's + 主语 + like?（询问某人的性格特征或外貌特点）</p>\n<p class=\"source-line\">（2）主语 + is + 描述性格特征或外貌特点的形容词。</p>\n<p class=\"source-line\">—— What's your mother like? 你妈妈什么样？<br/>\n—— She is very kind. 她很和蔼。<br/>\n—— What's his English teacher like? 他的英语老师什么样？<br/>\n—— She is very strict. 她很严厉。</p>\n<p class=\"source-line\">句型结构2：</p>\n<p class=\"source-line\">（1）What's the weather like (in) ...?</p>\n<p class=\"source-line\">（2）It's + 描述天气状况的形容词。</p>\n<p class=\"source-line\">—— What's the weather like in Beijing? 北京的天气怎么样？<br/>\n—— It's sunny. 天气阳光明媚。<br/>\n—— What's the weather like there? 那里的天气怎么样？<br/>\n—— It's cloudy. 天气多云。</p></div></div>\n<div class=\"g\"><div class=\"gt\">句型 “What do / does ... like?”</div><div class=\"gb\"><p class=\"source-line\">句型结构：</p>\n<p class=\"source-line\">（1）What do / does + 主语 + like?</p>\n<p class=\"source-line\">（2）主语 + like / likes + 其他。</p>\n<p class=\"source-line\">—— What do you like? 你喜欢什么？<br/>\n—— I like peaches. 我喜欢桃子。<br/>\n—— What does your mother like? 你妈妈喜欢什么？<br/>\n—— She likes singing. 她喜欢唱歌。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【合肥·包河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s26-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> is he like?<br/><br>\n—— He is strict.</br></p>","options":["Who","What","Which"],"correct":1,"answer":"B\n解析：根据句型 “What be + 主语 + like?” 可知选 What。"},{"id":"s26-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">My aunt <span class=\"blank-token\">____</span> strawberries.</p>","options":["like","liked","likes"],"correct":2,"answer":"C\n解析：主语 my aunt 是第三人称单数, 实义动词用单三形式 likes。"},{"id":"s26-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\"><strong><em>_</em></strong></span> and <span class=\"blank-token\">_</span> in London.</p>","options":["snowy; hot","warm; snowy","snowy; cold"],"correct":2,"answer":"C\n解析：根据生活常识可知 “下雪时天气寒冷”,故选 snowy 和 cold。"},{"id":"s26-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't like <span class=\"blank-token\">____</span> days.</p>","options":["snowy","snowing","snows"],"correct":0,"answer":"A\n解析：day(天)是名词, 故用形容词 snowy 修饰。"},{"id":"s26-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\">____</span> the weather like today?</p>","options":["is","are","am"],"correct":0,"answer":"A\n解析：根据句型 “What is the weather like(+其他)?” 可知选 is。"},{"id":"s26-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I like <span class=\"blank-token\">____</span> days.</p>","options":["cloudy","clouds","clouding"],"correct":0,"answer":"A\n解析：day(天)是名词, 故用形容词 cloudy 修饰。"},{"id":"s26-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\">____</span> your uncle like?</p>","options":["do","does","did"],"correct":1,"answer":"B\n解析：主语 your uncle 是第三人称单数, 助动词用 does。"},{"id":"s26-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span> today.</p>","options":["suns","sun","sunny"],"correct":2,"answer":"C\n解析：根据句型“It's + 描述天气的形容词.”可知选sunny。"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s26-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">My grandfather is <u>kind</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What is your grandfather like?"},{"id":"s26-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">He likes <u>bread</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What does he like?"},{"id":"s26-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">I like <u>oranges</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What do you like?"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s26-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> is the weather like today?</p>","options":["Which","What","Who","When"],"correct":1,"answer":"B"},{"id":"s26-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">My grandmother <span class=\"blank-token\">____</span> tomatoes.</p>","options":["likes","like","to like","liking"],"correct":0,"answer":"A"},{"id":"s26-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">What's the weather like <span class=\"blank-token\">____</span> Shanghai?</p>","options":["at","on","in","under"],"correct":2,"answer":"C"},{"id":"s26-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What's her brother like?<br/><br>\n—— <span class=\"blank-token\">____</span> is very outgoing.</br></p>","options":["He","She","They","It"],"correct":0,"answer":"A"},{"id":"s26-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What's your sister like?<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["She likes bananas.","She is very clever.","She likes dancing.","He is very cute."],"correct":1,"answer":"B"},{"id":"s26-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> does your mother like?<br/><br>\n—— She likes playing the piano.</br></p>","options":["Who","Where","What","When"],"correct":2,"answer":"C"}],"questionCount":6,"hasAnswers":true}]},{"id":"s27","section":27,"unit":5,"unitName":"单元05 · 第25–30节","short":"第27节 · L53–54","title":"频度副词","lessons":"Lesson 53 — Lesson 54","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>频度副词</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>频度副词</td>\n<td>常见频度副词所表示的频率</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>频度副词</td>\n<td>频度副词的位置</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是频度副词？</div><div class=\"gb\"><p class=\"source-line\">频度副词又称频率副词,用来表示动作、事情发生的频率,即某事多长时间发生一次,通常用于一般现在时的句子中。</p>\n<p class=\"source-line\">Ben often goes to the cinema with his friend.</p>\n<p class=\"source-line\">本经常和他的朋友去看电影。</p>\n<p class=\"source-line\">He never eats hamburgers. 他从不吃汉堡包。</p></div></div>\n<div class=\"g\"><div class=\"gt\">常见频度副词所表示的频率</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>频率</th>\n<th>频度副词</th>\n<th>含义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>100%</td>\n<td>always</td>\n<td>(总是)</td>\n</tr>\n<tr>\n<td>90%</td>\n<td>usually</td>\n<td>(通常)</td>\n</tr>\n<tr>\n<td>70%</td>\n<td>often</td>\n<td>(经常)</td>\n</tr>\n<tr>\n<td>50%</td>\n<td>sometimes</td>\n<td>(有时)</td>\n</tr>\n<tr>\n<td>10%</td>\n<td>seldom</td>\n<td>(很少)</td>\n</tr>\n<tr>\n<td>5%</td>\n<td>hardly</td>\n<td>(几乎不)</td>\n</tr>\n<tr>\n<td>0%</td>\n<td>never</td>\n<td>(从不)</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block note\"><div class=\"custom-block-title\">注意</div><p class=\"source-line\">表中的百分比只用于帮助理解各频度副词的大致频率，并不是固定不变的精确数值。</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">频度副词的位置</div><div class=\"gb\"><h5>1. 在句中放在实义动词前面。</h5>\n<p class=\"source-line\">I always go to school by bike.</p>\n<p class=\"source-line\">我总是骑自行车去上学。</p>\n<p class=\"source-line\">My sister often does exercise.</p>\n<p class=\"source-line\">我妹妹经常锻炼。</p>\n<h5>2. 一般放在 be(动词)、助动词和情态动词后面。</h5>\n<p class=\"source-line\">I am never late for school.</p>\n<p class=\"source-line\">我上学从不迟到。</p>\n<p class=\"source-line\">I can hardly say a word.</p>\n<p class=\"source-line\">我几乎说不出一个字。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">频度副词很重要，句中位置要记牢：实义动词前，be 动词、助动词和情态动词后；sometimes 较灵活，也可用于句首或句末。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【惠州·惠城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s27-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How often do you go to the cinema?<br/><br>\n—— <span class=\"blank-token\">____</span>. I only watch movies at home.</br></p>","options":["Always","Usually","Sometimes","Never"],"correct":3,"answer":"D\n解析：根据句意可知回答者从不去电影院,故选择 D 选项。"},{"id":"s27-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How often do you go to work by subway?<br/><br>\n—— <span class=\"blank-token\">____</span>. I always take a bus, because there is no subway in this city.</br></p>","options":["Sometimes","Often","Never","Seldom"],"correct":2,"answer":"C\n解析：根据句意可知回答者从未乘坐过地铁，故选择C选项。"},{"id":"s27-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Tina <span class=\"blank-token\">____</span> drives to work. But today she is driving because of the rain.</p>","options":["always","often","sometimes","hardly ever"],"correct":3,"answer":"D\n解析：后一句中, but 表转折, 故前一句 Tina 不常开车, D 选项 hardly ever 符合题意。"},{"id":"s27-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I am <span class=\"blank-token\">____</span> late for school because I get up early every day.</p>","options":["sometimes","often","never","usually"],"correct":2,"answer":"C\n解析：“because I get up early every day”意为“因为我每天起得早”，说明回答者从未迟到，故本题选择 C 选项。"},{"id":"s27-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you play computer games?<br/><br>\n—— No, <span class=\"blank-token\">____</span>. I think they're boring.</br></p>","options":["always","never","usually","often"],"correct":1,"answer":"B\n解析：根据 “I think they’re boring. (我认为它们很无聊。)” 可知回答者从不玩儿电脑游戏,故本题选择 B 选项。"},{"id":"s27-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">The boy is very lazy. He <span class=\"blank-token\">____</span> washes his shoes.</p>","options":["always","usually","hardly ever","often"],"correct":2,"answer":"C\n解析：由前一句 “这个男孩儿非常懒” 可知后一句大意为 “他几乎不刷鞋”, 故本题选择 C 选项。"}],"questionCount":6,"hasAnswers":true},{"source":"practice","title":"【合肥·包河区】排序题：将下列句子重新排序，组成完整对话。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s27-practice-q007","number":7,"type":"mcq","questionHtml":"","options":["I usually watch TV. Sometimes I go shopping. What about you?","Hi, Lily! What do you do on the weekend?","Great!","I often clean my room. Sometimes I go shopping too.","Let's go shopping together next Saturday."],"correct":1,"answer":"B—A—D—E—C"}],"questionCount":1,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s27-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Bill <u>never</u> goes to the cinema. (对画线部分提问)</p>","options":[],"correct":null,"answer":"How often does Bill go to the cinema?"},{"id":"s27-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">My father <span class=\"blank-token\">____</span> (有时) works at the weekend. (根据汉语提示补全句子)</p>","options":[],"correct":null,"answer":"sometimes"},{"id":"s27-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">David <span class=\"blank-token\">____</span> (通常) gets home at 5:00. (根据汉语提示补全句子)</p>","options":[],"correct":null,"answer":"usually"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"连词成句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s27-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">home, go, at, I, forty, four, always (.)</p>","options":[],"correct":null,"answer":"I always go home at four forty."},{"id":"s27-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">what, do, do, usually, you, Sundays, on (?)</p>","options":[],"correct":null,"answer":"What do you usually do on Sundays?"},{"id":"s27-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">often, she, on, plays, piano, the, Sundays (.)</p>","options":[],"correct":null,"answer":"She often plays the piano on Sundays."}],"questionCount":3,"hasAnswers":true}]},{"id":"s28","section":28,"unit":5,"unitName":"单元05 · 第25–30节","short":"第28节 · L55–56","title":"动词的第三人称单数","lessons":"Lesson 55 — Lesson 56","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>动词的第三人称单数</td>\n<td>概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>动词的第三人称单数</td>\n<td>动词第三人称单数的变化规则</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">第三人称单数的判断</div><div class=\"gb\"><h5>1. 什么是第三人称单数？</h5>\n<p class=\"source-line\">第一人称:I / we</p>\n<p class=\"source-line\">第二人称:you</p>\n<p class=\"source-line\">第三人称: he / she / it / they</p>\n<p class=\"source-line\">“单” → 单数</p>\n<h5>2. 怎样判断主语是不是“单三”？</h5>\n<p class=\"source-line\">满足“三非”即可！</p>\n<p class=\"source-line\">非你非我非复数即是“单三”！</p>\n<p class=\"source-line\">单三: Mary、my mother、the cat</p>\n<p class=\"source-line\">非单三: they (第三人称复数)、my teachers (第三人称复数)、I (第一人称单数)、we (第一人称复数)、you (第二人称单数 / 复数)</p>\n<h5>3. 在一般现在时的句子中,当主语是第三人称单数时,谓语动词要用第三人称单数形式。</h5></div></div>\n<div class=\"g\"><div class=\"gt\">动词第三人称单数的变化规则</div><div class=\"gb\"><h5>1. 一般情况下,在词尾直接加 s。</h5>\n<p class=\"source-line\">run → runs 跑</p>\n<p class=\"source-line\">speak → speaks 说,讲话</p>\n<p class=\"source-line\">like → likes 喜欢<br/>\nsing → sings 唱歌</p>\n<p class=\"source-line\">My sister likes ice cream. 我姐姐喜欢冰激凌。</p>\n<p class=\"source-line\">My mother always cooks delicious food for us.</p>\n<p class=\"source-line\">我妈妈总是为我们做美味的食物。</p>\n<h5>2. 以 ch、sh、s、x、o 结尾的动词，在词尾加 es。</h5>\n<p class=\"source-line\">teach → teaches 讲授,教授</p>\n<p class=\"source-line\">do → does 做, 干</p>\n<p class=\"source-line\">pass → passes 给;递</p>\n<p class=\"source-line\">My brother usually does housework at home. 我哥哥在家通常做家务。</p>\n<p class=\"source-line\">wash → washes 洗;洗涤</p>\n<p class=\"source-line\">Miss Wang teaches us Chinese.</p>\n<p class=\"source-line\">王老师教我们语文。</p>\n<h5>3. 以辅音字母加 y 结尾的动词, 把 y 变 i, 再加 es。</h5>\n<p class=\"source-line\">try → tries 试图;想要</p>\n<p class=\"source-line\">fly → flies 飞</p>\n<p class=\"source-line\">study → studies 学习,研究</p>\n<p class=\"source-line\">marry → marries 结婚</p>\n<p class=\"source-line\">My little sister studies very hard.</p>\n<p class=\"source-line\">我妹妹学习很努力。</p>\n<p class=\"source-line\">The bird flies very high.</p>\n<p class=\"source-line\">那只鸟飞得很高。</p>\n<p class=\"source-line\">（1）以“元音字母+y”结尾的动词，在词尾加s，如pay—pays、play—plays等。</p>\n<p class=\"source-line\">（2）have 的第三人称单数形式是 has。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·红桥区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s28-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> (like) strawberries.</p>","options":[],"correct":null,"answer":"likes\n解析：主语 She 是第三人称单数，故 like 应使用第三人称单数形式 likes。"},{"id":"s28-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">My cousin <span class=\"blank-token\">____</span> (speak) English very well.</p>","options":[],"correct":null,"answer":"speaks\n解析：主语 My cousin 是第三人称单数，故 speak 应变为 speaks。"},{"id":"s28-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Mr Green often <span class=\"blank-token\">____</span> (wash) his car on Sundays.</p>","options":[],"correct":null,"answer":"washes\n解析：主语 Mr Green 是第三人称单数；wash 以 sh 结尾，应加 es。"},{"id":"s28-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Andy can <span class=\"blank-token\">____</span> (swim).</p>","options":[],"correct":null,"answer":"swim\n解析：情态动词 can 后用动词原形, 故填 swim。"},{"id":"s28-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Alice always <span class=\"blank-token\">____</span> (do) housework on Saturdays.</p>","options":[],"correct":null,"answer":"does\n解析：主语 Alice 是第三人称单数，do 应使用第三人称单数形式 does。"},{"id":"s28-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He often <span class=\"blank-token\">____</span> (go) to school by bike.</p>","options":[],"correct":null,"answer":"goes\n解析：主语 He 是第三人称单数，go 应使用第三人称单数形式 goes。"},{"id":"s28-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My aunt <span class=\"blank-token\">____</span> (look) after her baby carefully.</p>","options":[],"correct":null,"answer":"looks\n解析：主语 My aunt 是第三人称单数，look 应使用第三人称单数形式 looks。"},{"id":"s28-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">They always <span class=\"blank-token\">____</span> (do) their homework quickly.</p>","options":[],"correct":null,"answer":"do\n解析：主语 They(他们)是第三人称复数, 故后面的实义动词用原形 do。"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"写出下列动词的第三人称单数形式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s28-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">drink</p>","options":[],"correct":null,"answer":"drinks"},{"id":"s28-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">go</p>","options":[],"correct":null,"answer":"goes"},{"id":"s28-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">stay</p>","options":[],"correct":null,"answer":"stays"},{"id":"s28-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">make</p>","options":[],"correct":null,"answer":"makes"},{"id":"s28-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">look <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"looks"},{"id":"s28-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">have</p>","options":[],"correct":null,"answer":"has"},{"id":"s28-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">pass <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"passes"},{"id":"s28-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">carry</p>","options":[],"correct":null,"answer":"carries"},{"id":"s28-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">watch</p>","options":[],"correct":null,"answer":"watches"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"用所给单词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s28-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">She often <span class=\"blank-token\">____</span> (have) dinner at home.</p>","options":[],"correct":null,"answer":"has"},{"id":"s28-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">Mr. Li <span class=\"blank-token\">____</span> (teach) us English every Friday.</p>","options":[],"correct":null,"answer":"teaches"},{"id":"s28-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">My grandfather <span class=\"blank-token\">____</span> (like) cooking.</p>","options":[],"correct":null,"answer":"likes"},{"id":"s28-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> (go) to school on foot every day.</p>","options":[],"correct":null,"answer":"goes"},{"id":"s28-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">My father often <span class=\"blank-token\">____</span> (watch) TV in the evening.</p>","options":[],"correct":null,"answer":"watches"}],"questionCount":5,"hasAnswers":true}]},{"id":"s29","section":29,"unit":5,"unitName":"单元05 · 第25–30节","short":"第29节 · L57–58","title":"现在进行时和一般现在时","lessons":"Lesson 57 — Lesson 58","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>现在进行时</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>一般现在时</td>\n<td>★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>现在进行时和一般现在时的区别</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">现在进行时</div><div class=\"gb\"><h5>1. 含义: 表示现在正在进行或发生的动作。</h5>\n<h5>2. 肯定句结构: 主语 + be (am / is / are) + 动词 -ing 形式 (+ 其他).</h5>\n<h5>3. 动词 -ing 形式的构成</h5>\n<p class=\"source-line\">（1）一般情况下,直接加 ing。如:read — reading</p>\n<p class=\"source-line\">（2）以不发音的 e 结尾的动词,去 e 加 ing。如:make — making</p>\n<p class=\"source-line\">（3）以重读闭音节结尾,且词尾只有一个辅音字母的动词,双写词尾辅音字母再加ing。如:run—running、plan—planning。</p>\n<p class=\"source-line\">（4）有些以 ie 结尾的动词,变 ie 为 y,再加 ing。如:lie — lying</p>\n<h5>4. 用法</h5>\n<p class=\"source-line\">（1）表示说话时正在发生的事情, 常与 now、at present 等时间状语连用。</p>\n<p class=\"source-line\">Sarah is singing now. 萨拉现在正在唱歌。</p>\n<p class=\"source-line\">Look! Mike is doing his homework.</p>\n<p class=\"source-line\">看！迈克正在做作业。</p>\n<p class=\"source-line\">（2）表示当前一段时间内正在进行的动作, 说话时不一定进行。</p>\n<p class=\"source-line\">Three bees are flying from flowers to flowers this afternoon.</p>\n<p class=\"source-line\">三只蜜蜂今天下午在花丛中飞来飞去。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时</div><div class=\"gb\"><h5>1. 含义: 表示经常发生的动作或存在的状态。</h5>\n<h5>2. 肯定句结构</h5>\n<p class=\"source-line\">主语 + 情态动词 + 动词原形（+ 其他）；或：主语 + 动词原形／动词第三人称单数形式（+ 其他）。</p>\n<h5>3. 动词第三人称单数形式的构成</h5>\n<p class=\"source-line\">（1）一般情况下,在动词词尾直接加 s。如:like — likes</p>\n<p class=\"source-line\">（2）以 s、x、sh、ch、o 结尾的动词,加 es。如: watch — watches、do — does。</p>\n<p class=\"source-line\">（3）以“辅音字母+y”结尾的动词,先变y为i,再加es。如:study—studies</p>\n<p class=\"source-line\">（4）不规则变化。如:have—has</p>\n<h5>4. 用法</h5>\n<p class=\"source-line\">（1）表示经常性或习惯性的动作; 常与 always、often、usually、every day 等词语连用。</p>\n<p class=\"source-line\">She studies English every day. 她每天学习英语。</p>\n<p class=\"source-line\">Jack often takes a bath at night. 杰克经常在晚上洗澡。</p>\n<p class=\"source-line\">（2）表示永恒不变的真理或描述一般性的事实。</p>\n<p class=\"source-line\">The sun rises in the east. 太阳从东边升起。</p>\n<p class=\"source-line\">Three and five is eight. 3 加 5 等于 8。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在进行时和一般现在时的区别</div><div class=\"gb\"><p class=\"source-line\">肯定句: He is reading an interesting book. 他正在读一本有趣的书。</p>\n<p class=\"source-line\">He often reads interesting books. 他经常读有趣的书。</p>\n<p class=\"source-line\">否定句: He isn't reading an interesting book. 他没在读一本有趣的书。\nHe doesn't often read interesting books. 他不常读有趣的书。</p>\n<p class=\"source-line\">一般疑问句: Is he reading an interesting book? 他正在读一本有趣的书吗?\nDoes he read an interesting book? 他读一本有趣的书吗?</p>\n<p class=\"source-line\">特殊疑问句: What is he doing?</p>\n<p class=\"source-line\">他正在做什么？</p>\n<p class=\"source-line\">What does he do?</p>\n<p class=\"source-line\">他是做什么工作的？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·顺德区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s29-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> they often <span class=\"blank-token\">_</span> on Sundays?<br/><br>\n—— They often play football on Sundays.</br></p>","options":["does; do","do; does","do; do"],"correct":2,"answer":"C\n解析：主语 they (他们) 为第三人称复数, 助动词用 do, 第二个 do 为实义动词, 用原形。"},{"id":"s29-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> they doing?<br/><br>\n—— They are <span class=\"blank-token\">_</span> their hair.</br></p>","options":["are; cutting","do; cut","is; cutting"],"correct":0,"answer":"A"},{"id":"s29-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! The mice <span class=\"blank-token\">____</span> through the grass.</p>","options":["is running","run","are running"],"correct":2,"answer":"C\n解析：look (看) 是现在进行时的标志词。mice (老鼠) 是 mouse 的复数形式, 所以 be 用 are, be 后接动词 -ing 形式。"},{"id":"s29-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Jill and her friend often <span class=\"blank-token\">____</span> hiking on the weekend.</p>","options":["went","go","goes"],"correct":1,"answer":"B"},{"id":"s29-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> she <span class=\"blank-token\">_</span> her homework?<br/><br>\n—— No, she isn't.</br></p>","options":["Is; doing","Does; do","Is; do"],"correct":0,"answer":"A\n解析：根据答语可知问句是 is 引导的一般疑问句, 后接动词 -ing 形式。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【昆明·官渡区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s29-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Sam often <span class=\"blank-token\">____</span> (clean) his bedroom on the weekend.</p>","options":[],"correct":null,"answer":"cleans"},{"id":"s29-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Look! Lily and Bob <span class=\"blank-token\">____</span> (skate).</p>","options":[],"correct":null,"answer":"are skating\n解析：主语 Lily and Bob (莉莉和鲍勃) 为第三人称复数, be 用 are, 后接动词 -ing 形式。skate (滑冰) 的 -ing 形式为 skating。"},{"id":"s29-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Each girl <span class=\"blank-token\">____</span> (have) a dream.</p>","options":[],"correct":null,"answer":"has"},{"id":"s29-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Jim always <span class=\"blank-token\">____</span> (do) his homework in the evening.</p>","options":[],"correct":null,"answer":"does"},{"id":"s29-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Don't talk! My baby Bill <span class=\"blank-token\">____</span> (sleep) in the bedroom.</p>","options":[],"correct":null,"answer":"is sleeping\n解析：第二个句子为现在进行时, my baby (我的宝贝)为第三人称单数, be 用 is, 后接动词 -ing 形式。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"用括号内所给词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s29-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Binbin <span class=\"blank-token\">____</span> (like) elephants.</p>","options":[],"correct":null,"answer":"likes"},{"id":"s29-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (not like) apples.</p>","options":[],"correct":null,"answer":"don't like"},{"id":"s29-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">My brother <span class=\"blank-token\">____</span> (not like) the teddy bear.</p>","options":[],"correct":null,"answer":"doesn't like"},{"id":"s29-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Look! The children <span class=\"blank-token\">____</span> (play) in the park.</p>","options":[],"correct":null,"answer":"are playing"},{"id":"s29-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">It's 7 o'clock now. My mother <span class=\"blank-token\">____</span> (cook) dinner.</p>","options":[],"correct":null,"answer":"is cooking"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s29-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">My mother goes shopping every Friday. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Does your mother go shopping every Friday?"},{"id":"s29-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Peter has a new sweater. (改为否定句)</p>","options":[],"correct":null,"answer":"Peter doesn't have a new sweater."},{"id":"s29-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Sally makes a cake. (用 now 改写句子)</p>","options":[],"correct":null,"answer":"Sally is making a cake now."},{"id":"s29-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">They are <u>doing morning exercises</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What are they doing?"},{"id":"s29-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Is he talking about his summer plan with Tom? (作否定回答)</p>","options":[],"correct":null,"answer":"No, he isn't."}],"questionCount":5,"hasAnswers":true}]},{"id":"s30","section":30,"unit":5,"unitName":"单元05 · 第25–30节","short":"第30节 · L59–60","title":"have 的用法","lessons":"Lesson 59 — Lesson 60","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>have 的用法</td>\n<td>have 的用法</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>have 的用法</td>\n<td>have 和 there be 的用法对比</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">have 的用法</div><div class=\"gb\"><h5>1. have 作实义动词, 表示 “有”。</h5>\n<p class=\"source-line\">I have a new pen. 我有一支新钢笔。</p>\n<p class=\"source-line\">She has an apple. 她有一个苹果。</p>\n<h5>2. have 作实义动词, 表示 “吃, 喝”。</h5>\n<p class=\"source-line\">I have breakfast at 6:30 every morning.</p>\n<p class=\"source-line\">我每天早上6:30吃早餐。</p>\n<p class=\"source-line\">She often has rice and fish for dinner.</p>\n<p class=\"source-line\">她晚餐经常吃米饭和鱼肉。</p>\n<h5>3. have 与 to 构成 have to 结构，表示“不得不；必须”。</h5>\n<p class=\"source-line\">I have to finish my homework.</p>\n<p class=\"source-line\">我不得不完成我的家庭作业。</p>\n<p class=\"source-line\">She has to look after her younger sister at home today.</p>\n<p class=\"source-line\">她今天必须在家照顾她妹妹。</p></div></div>\n<div class=\"g\"><div class=\"gt\">have 和 there be 的用法对比</div><div class=\"gb\"><h5>1. have 表示 “某人 / 某物拥有……”, 强调 “拥有”。</h5>\n<p class=\"source-line\">I have some pears. 我有一些梨。</p>\n<p class=\"source-line\">The table has three legs. 这张桌子有 3 条腿。</p>\n<h5>2. there be 表示某处有某人 / 某物, 强调 “存在”。</h5>\n<p class=\"source-line\">There are some pears on the table.</p>\n<p class=\"source-line\">桌子上有一些梨。</p>\n<p class=\"source-line\">There are some people in the park.</p>\n<p class=\"source-line\">公园里有一些人。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·五华区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s30-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Does Alice <span class=\"blank-token\">____</span> many friends?</p>","options":["have","has","there are"],"correct":0,"answer":"A\n解析：由助动词 does 引导的一般疑问句,后面的实义动词用原形,故选 have。"},{"id":"s30-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> a lot of food, milk and fruit in the fridge.</p>","options":["are","am","is"],"correct":2,"answer":"C\n解析：a lot of food (许多食物) 不可数, 故选 is。"},{"id":"s30-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">It <span class=\"blank-token\">____</span> a short tail.</p>","options":["have","has","there is"],"correct":1,"answer":"B\n解析：主语 It(它) 是第三人称单数, 故后面的动词用单三形式 has。"},{"id":"s30-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">How many watches <span class=\"blank-token\">____</span> in the box?</p>","options":["there are","there is","are there"],"correct":2,"answer":"C\n解析：此句是特殊疑问句, watches(手表) 是可数名词复数, 故后面选择 are there。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【北京·东城区】翻译下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s30-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">书桌上有一本书。</p>","options":[],"correct":null,"answer":"There is a book on the desk."},{"id":"s30-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">我姐姐有一个新杯子。</p>","options":[],"correct":null,"answer":"My sister has a new cup."},{"id":"s30-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">床下面有一个篮球。</p>","options":[],"correct":null,"answer":"There is a basketball under the bed."},{"id":"s30-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">那个小婴儿没有牙齿。</p>","options":[],"correct":null,"answer":"The little baby has no teeth."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用括号内所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s30-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">My uncle <span class=\"blank-token\">____</span> (have) a nice car.</p>","options":[],"correct":null,"answer":"has"},{"id":"s30-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">He often <span class=\"blank-token\">____</span> (have) dinner at home.</p>","options":[],"correct":null,"answer":"has"},{"id":"s30-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> (be) some apples in the basket.</p>","options":[],"correct":null,"answer":"are"},{"id":"s30-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> (be not) any books in the backpack.</p>","options":[],"correct":null,"answer":"aren't"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s30-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> some maps on the wall.</p>","options":["has","There is","There are","have"],"correct":2,"answer":"C"},{"id":"s30-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> a new computer.</p>","options":["There is","There are","have","has"],"correct":2,"answer":"C"},{"id":"s30-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> a TV in our classroom.</p>","options":["There are","have","has","There is"],"correct":3,"answer":"D"},{"id":"s30-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">The cat <span class=\"blank-token\">____</span> two big eyes.</p>","options":["have","has","There is","There are"],"correct":1,"answer":"B"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s30-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some paper and a pen on the desk.</p>","options":["is","are","have"],"correct":0,"answer":"A"},{"id":"s30-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">The man <span class=\"blank-token\">____</span> a plate in his hand.</p>","options":["there is","there are","has"],"correct":2,"answer":"C"},{"id":"s30-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">How many bowls <span class=\"blank-token\">____</span> in your kitchen?</p>","options":["have","are there","is there"],"correct":1,"answer":"B"},{"id":"s30-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> there a library in your school?</p>","options":["Have","Are","Is"],"correct":2,"answer":"C"},{"id":"s30-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't <span class=\"blank-token\">____</span> enough money.</p>","options":["have","has","there is"],"correct":0,"answer":"A"},{"id":"s30-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> many apples on the table.</p>","options":["Have","There is","There are"],"correct":2,"answer":"C"}],"questionCount":6,"hasAnswers":true}]},{"id":"s31","section":31,"unit":6,"unitName":"单元06 · 第31–36节","short":"第31节 · L61–62","title":"系动词","lessons":"Lesson 61 — Lesson 62","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>系动词</td>\n<td>be 动词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>系动词</td>\n<td>感官连系动词</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">系动词</div><div class=\"gb\"><p class=\"source-line\">系动词也叫连系动词,不能单独作谓语,必须后接名词、形容词等表语一起作句子的谓语。be 动词是最基本的系动词。</p>\n<p class=\"source-line\">She is pretty. 她很漂亮。</p>\n<p class=\"source-line\">I am a football player. 我是一名足球运动员。</p></div></div>\n<div class=\"g\"><div class=\"gt\">be 动词</div><div class=\"gb\"><p class=\"source-line\">be 动词通常用来表示事物的性质或状态。根据主语的人称和单复数形式，be 动词可变化为 am、is、are。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>单数·主语</th>\n<th>单数·be 动词</th>\n<th>单数·缩写</th>\n<th>复数·主语</th>\n<th>复数·be 动词</th>\n<th>复数·缩写</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>I</td>\n<td>am</td>\n<td>I'm</td>\n<td>we</td>\n<td>are</td>\n<td>we're</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>you</td>\n<td>are</td>\n<td>you're</td>\n<td>you</td>\n<td>are</td>\n<td>you're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>he</td>\n<td>is</td>\n<td>he's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>she</td>\n<td>is</td>\n<td>she's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>it</td>\n<td>is</td>\n<td>it's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">我（I）用 am，你（you）用 are，is 连着他（he）、她（she）、它（it）；单数名词用 is，复数名词用 are。</p></div></div></div>\n<div class=\"g\"><div class=\"gt\">感官连系动词</div><div class=\"gb\"><p class=\"source-line\">除了 be 动词, 常用的系动词还有感官连系动词。</p>\n<p class=\"source-line\">look 看起来</p>\n<p class=\"source-line\">smell 闻起来</p>\n<p class=\"source-line\">taste 尝起来</p>\n<p class=\"source-line\">sound 听起来</p>\n<p class=\"source-line\">feel 摸起来</p>\n<p class=\"source-line\">His mother looks very young.</p>\n<p class=\"source-line\">他妈妈看起来很年轻。</p>\n<p class=\"source-line\">The flowers smell sweet.</p>\n<p class=\"source-line\">这些花儿闻起来很香。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【广州·天河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s31-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The strawberries <span class=\"blank-token\">____</span> delicious. You can have a try.</p>","options":["drink","taste","sound"],"correct":1,"answer":"B\n解析：第一句意为 “草莓尝起来很美味”, 故本题选择 B 选项。"},{"id":"s31-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I like this silk dress, and it <span class=\"blank-token\">____</span> so soft and comfortable.</p>","options":["is feeling","feels","has felt"],"correct":1,"answer":"B\n解析：此句意为 “我喜欢这条丝绸裙子, 它摸起来柔软舒服”, 故选择 B 选项。"},{"id":"s31-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> some children singing and dancing in the yard.</p>","options":["is","are","has"],"correct":1,"answer":"B\n解析：some children (一些孩子) 为第三人称复数形式, be 用 are。"},{"id":"s31-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">How old <span class=\"blank-token\">____</span> she?</p>","options":["am","is","are"],"correct":1,"answer":"B"},{"id":"s31-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> these your parents?<br/><br>\n—— No, they are <span class=\"blank-token\">_</span> uncle and aunt.</br></p>","options":["Is; me","Are; me","Are; my"],"correct":2,"answer":"C"},{"id":"s31-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! There <span class=\"blank-token\">____</span> some milk, two eggs and a few cakes on the table.</p>","options":["is","are","has"],"correct":0,"answer":"A\n解析：此句为 there be 句型, 句中有多个主语, 要遵循 “就近原则”。离 be 最近的主语 some milk (一些牛奶) 为不可数名词, 故 be 用 is。"},{"id":"s31-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">The milk <span class=\"blank-token\">____</span> sour. You'd better not drink it.</p>","options":["sounds","tastes","looks"],"correct":1,"answer":"B"},{"id":"s31-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">The number of the students in our class <span class=\"blank-token\">____</span> thirty-nine.</p>","options":["is","are","have"],"correct":0,"answer":"A\n解析：“the number of...”意为“……的数量”，number 为主语，be 动词用 is。"},{"id":"s31-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">The trip <span class=\"blank-token\">____</span> really exciting to me. How I wish to go!</p>","options":["tastes","smells","sounds"],"correct":2,"answer":"C"},{"id":"s31-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">This apple looks nice but <span class=\"blank-token\">____</span> sour.</p>","options":["touches","feels","tastes"],"correct":2,"answer":"C"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s31-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">My grandma <span class=\"blank-token\">____</span> a doctor.</p>","options":["is","are","am"],"correct":0,"answer":"A"},{"id":"s31-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Xiaoming <span class=\"blank-token\"><strong><em>_</em></strong></span> twelve years old. He <span class=\"blank-token\">_</span> tall and thin.<br/>\nA. am, are<br/>\nB. is, am<br/>\nC. is, is<br/>\nD. is, are<br/>\nE. are, am<br/>\nF. are, is<br/>\nG. are, are<br/>\nH. am, am<br/>\nI. am, is</p>","options":[],"correct":null,"answer":"C"},{"id":"s31-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Lucy and Lily <span class=\"blank-token\">____</span> twins.</p>","options":["am","is","are"],"correct":2,"answer":"C"},{"id":"s31-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The weather <span class=\"blank-token\">____</span> nice today.</p>","options":["is","are","am"],"correct":0,"answer":"A"},{"id":"s31-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">These bags <span class=\"blank-token\">____</span> heavy.</p>","options":["are","am","is"],"correct":0,"answer":"A"},{"id":"s31-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I have a dog. Its name <span class=\"blank-token\">____</span> Coco.</p>","options":["am","is","are"],"correct":1,"answer":"B"},{"id":"s31-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> a student in the middle school.</p>","options":["is","are","am"],"correct":2,"answer":"C"},{"id":"s31-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">His parents <span class=\"blank-token\">____</span> Chinese. They live in Beijing.</p>","options":["are","am","is"],"correct":0,"answer":"A"},{"id":"s31-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Where <span class=\"blank-token\">____</span> their teachers from?</p>","options":["am","is","are"],"correct":2,"answer":"C"},{"id":"s31-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Many children <span class=\"blank-token\"><strong><em>_</em></strong></span> in the park. And they <span class=\"blank-token\">_</span> playing games now.<br/>\nA. am, is<br/>\nB. am, are<br/>\nC. is, am<br/>\nD. is, is<br/>\nE. is, are<br/>\nF. are, am<br/>\nG. are, is<br/>\nH. are, are<br/>\nI. am, am</p>","options":[],"correct":null,"answer":"H"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"用括号中所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s31-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">Susan <span class=\"blank-token\"><strong><em>_</em></strong></span> (have) a stomachache. She must <span class=\"blank-token\">_</span> (take) some medicine.</p>","options":[],"correct":null,"answer":"has, take"},{"id":"s31-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">Sam <span class=\"blank-token\"><strong><em>_</em></strong></span> (have) a flu, so he can't <span class=\"blank-token\">_</span> (go) to school today.</p>","options":[],"correct":null,"answer":"has, go"},{"id":"s31-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">That <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) good news for Tom because he doesn't <span class=\"blank-token\">_</span> (like) meat.</p>","options":[],"correct":null,"answer":"is, like"},{"id":"s31-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\"><strong><em>_</em></strong></span> (be) from China. Lily <span class=\"blank-token\">_</span> (be) from Canada.</p>","options":[],"correct":null,"answer":"am, is"},{"id":"s31-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">The food <span class=\"blank-token\">____</span> (smell) good. I can't wait to eat it.</p>","options":[],"correct":null,"answer":"smells"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"根据汉语提示完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s31-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">老师们对我们都很友好。我们很开心。</p>\n<p class=\"source-line\">Teachers <span class=\"blank-token\"><strong><em>_</em></strong></span> all friendly to us. We <span class=\"blank-token\">_</span> very glad.</p>","options":[],"correct":null,"answer":"are, are"},{"id":"s31-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">她和她妈妈正在谈论那部电视剧。</p>\n<p class=\"source-line\">She and her mother <span class=\"blank-token\">____</span> talking about the TV play.</p>","options":[],"correct":null,"answer":"are"},{"id":"s31-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">他是个加拿大人。他有一个妹妹，叫玛丽。</p>\n<p class=\"source-line\">He <span class=\"blank-token\"><strong><em>_</em></strong></span> a Canadian. He has a sister. And her name <span class=\"blank-token\">_</span> Mary.</p>","options":[],"correct":null,"answer":"is, is"},{"id":"s31-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">—— 房间里有什么？——有两把椅子和一张书桌。<br/><br>\n—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> in the room?<br/><br>\n—— There <span class=\"blank-token\">_</span> two chairs and a desk.</br></br></p>","options":[],"correct":null,"answer":"is, are"},{"id":"s31-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">—— 那是一棵苹果树吗？——不，不是。那是一棵梨树。<br/><br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong></span> that an apple tree?<br/><br>\n—— No, it isn't. It <span class=\"blank-token\">_</span> a pear tree.</br></br></p>","options":[],"correct":null,"answer":"Is, is"}],"questionCount":5,"hasAnswers":true}]},{"id":"s32","section":32,"unit":6,"unitName":"单元06 · 第31–36节","short":"第32节 · L63–64","title":"情态动词 must","lessons":"Lesson 63 — Lesson 64","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>情态动词 must</td>\n<td>情态动词的概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>情态动词 must</td>\n<td>情态动词 must 的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">情态动词的概念</div><div class=\"gb\"><p class=\"source-line\">情态动词本身有一定的词义,表示说话人对有关行为或事物的态度和看法,认为其可能、应该或必要等。</p>\n<p class=\"source-line\">常见的情态动词有 can（能）、may（可以）、need（需要）、must（必须）、should（应该）等。</p>\n<p class=\"source-line\">I can do Chinese kung fu.</p>\n<p class=\"source-line\">我会练中国功夫。</p>\n<p class=\"source-line\">May I borrow your pen?</p>\n<p class=\"source-line\">我可以借用你的钢笔吗？</p>\n<p class=\"source-line\">You needn't finish that work today.</p>\n<p class=\"source-line\">你不必今天做完那项工作。</p>\n<p class=\"source-line\">You must clean your bedroom on Sunday.</p>\n<p class=\"source-line\">你必须在星期日打扫你的卧室。</p>\n<p class=\"source-line\">You should study hard from now on.</p>\n<p class=\"source-line\">你应该从现在开始努力学习。</p></div></div>\n<div class=\"g\"><div class=\"gt\">情态动词 must 的用法</div><div class=\"gb\"><h5>1. must 表示说话人的主观意志, 意为 “必须, 一定”, 后接动词原形。</h5>\n<p class=\"source-line\">You must study English hard.</p>\n<p class=\"source-line\">你必须努力学习英语。</p>\n<p class=\"source-line\">I must go now.</p>\n<p class=\"source-line\">我现在必须走。</p>\n<h5>2. 含有 must 的肯定句结构: 主语 + must + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">You must listen to your teacher. 你必须听你老师(的话)。</p>\n<p class=\"source-line\">I must earn money. 我必须赚钱。</p>\n<h5>3. 含有 must 的否定句结构: 主语 + mustn't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">You mustn't take photos here.</p>\n<p class=\"source-line\">你不得在这里拍照。</p>\n<p class=\"source-line\">You mustn't tell him about it.</p>\n<p class=\"source-line\">你一定不要告诉他这件事。</p>\n<h5>4. must 开头的一般疑问句结构: Must + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + must.</p>\n<p class=\"source-line\">否定回答: No, 主语 + needn't.</p>\n<p class=\"source-line\">—— Must you go now? 你现在必须走吗？<br/>\n—— Yes, I must. 是的, 我必须走。<br/>\n—— No, I needn't. 不, 我不必走。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【广州·天河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s32-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Even the top students can't work out this problem, so it <span class=\"blank-token\">____</span> be very difficult.</p>","options":["can","may","must"],"correct":2,"answer":"C\n解析：此题想表达 “它一定很难”, 故选 must。"},{"id":"s32-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Must I stay at the cinema?<br/><br>\n—— No, you <span class=\"blank-token\">____</span>.</br></p>","options":["needn't","mustn't","don't"],"correct":0,"answer":"A\n解析：must 引导的一般疑问句, 否定回答为 “No, 主语 + needn't.”, 故选 needn't。"},{"id":"s32-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Miss Zhang <span class=\"blank-token\">____</span> be in Shanghai now, because she went to Beijing yesterday.</p>","options":["may","can't","needn't"],"correct":1,"answer":"B\n解析：此题想表达 “张小姐现在不可能在上海”, 故选 can't。"},{"id":"s32-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Cars <span class=\"blank-token\">____</span> stop when the traffic lights turn red.</p>","options":["need","can","must"],"correct":2,"answer":"C\n解析：根据常识 “红灯车停”, 故选 must。"},{"id":"s32-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Look out! The knife is very sharp, you <span class=\"blank-token\">____</span> cut your finger.</p>","options":["need","may","must"],"correct":1,"answer":"B"},{"id":"s32-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I can’t find my pen. <span class=\"blank-token\">____</span> I use yours?<br/><br>\n—— Sure, here you are.</br></p>","options":["May","Must","Need"],"correct":0,"answer":"A"},{"id":"s32-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you like poems?<br/><br>\n—— Yes, I <span class=\"blank-token\">____</span> read some poems.</br></p>","options":["must","can","need"],"correct":1,"answer":"B"},{"id":"s32-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\">____</span> he do?<br/><br>\n—— He can do kung fu.</br></p>","options":["can","must","may"],"correct":0,"answer":"A"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s32-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Jack <span class=\"blank-token\">____</span> come to my birthday party. He's not sure.</p>","options":["can","can't","may","must"],"correct":2,"answer":"C"},{"id":"s32-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> swim. So let's go swimming.</p>","options":["can't","may","must","can"],"correct":3,"answer":"D"},{"id":"s32-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> I go now?<br/><br>\n—— No, you needn't.</br></p>","options":["may","must","can","can't"],"correct":1,"answer":"B"},{"id":"s32-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">It <span class=\"blank-token\">____</span> be Mr Green. He has gone to America.</p>","options":["must","can","can't","may"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s32-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Mike must stay in bed. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Must Mike stay in bed?"},{"id":"s32-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He must take the medicine. (改为否定句)</p>","options":[],"correct":null,"answer":"He must not / mustn't take the medicine."},{"id":"s32-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Must I do my homework now? (作否定回答)</p>","options":[],"correct":null,"answer":"No, you needn't."},{"id":"s32-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">The boy mustn't go to school. (改为肯定句)</p>","options":[],"correct":null,"answer":"The boy must go to school."}],"questionCount":4,"hasAnswers":true}]},{"id":"s33","section":33,"unit":6,"unitName":"单元06 · 第31–36节","short":"第33节 · L65–66","title":"反身代词","lessons":"Lesson 65 — Lesson 66","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>反身代词</td>\n<td>反身代词的形式</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>反身代词</td>\n<td>反身代词的用法</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">反身代词</div><div class=\"gb\"><p class=\"source-line\">反身代词是一种表示反身或强调的代词。即表示“我(们)自己、你(们)自己、他/她/它(们)自己”的代词称为反身代词。</p>\n<p class=\"source-line\">I made the hamburger by myself. 我自己做的汉堡包。</p>\n<p class=\"source-line\">Help yourselves, children.</p>\n<p class=\"source-line\">孩子们，随便吃点儿吧。</p></div></div>\n<div class=\"g\"><div class=\"gt\">反身代词的形式</div><div class=\"gb\"><p class=\"source-line\">反身代词第一、二人称是由“形容词性物主代词+self/selves”构成。第三人称是由“人称代词宾格+self/selves”构成。反身代词可作宾语、同位语等，但不可作主语。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>数</th>\n<th>第一人称</th>\n<th>第二人称</th>\n<th>第三人称</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>单数</td>\n<td>myself 我自己</td>\n<td>yourself 你自己</td>\n<td>himself / herself / itself 他 / 她 / 它自己</td>\n</tr>\n<tr>\n<td>复数</td>\n<td>ourselves 我们自己</td>\n<td>yourselves 你们自己</td>\n<td>themselves 他 / 她 / 它们自己</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">反身代词的用法</div><div class=\"gb\"><h5>1. 主语与宾语同为一(群)人时,宾语用反身代词。</h5>\n<p class=\"source-line\">Sarah hurt herself while riding the bike.</p>\n<p class=\"source-line\">萨拉在骑自行车时弄伤了自己。</p>\n<h5>2. 用反身代词加强语气。</h5>\n<p class=\"source-line\">She cooked breakfast by herself.</p>\n<p class=\"source-line\">她独自做了早饭。</p>\n<h5>3. 和某些动词或介词共同构成固定短语。</h5>\n<p class=\"source-line\">by oneself 亲自</p>\n<p class=\"source-line\">for oneself 为自己</p>\n<p class=\"source-line\">enjoy oneself 玩儿得高兴</p>\n<p class=\"source-line\">help oneself 随意吃</p>\n<p class=\"source-line\">teach oneself 自学</p>\n<p class=\"source-line\">seat oneself 就座</p>\n<p class=\"source-line\">I can do housework by myself. 我能够自己做家务。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">反身代词：第一、二人称由形容词性物主代词加 self／selves 构成，第三人称由人称代词宾格加 self／selves 构成；可作宾语、表语或同位语，不能作主语或定语。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·顺德区】把下列句子变成复数形式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s33-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I teach myself English.（改为复数形式）</p>","options":[],"correct":null,"answer":"We teach ourselves English."},{"id":"s33-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">He usually goes to school by himself.（改为复数形式）</p>","options":[],"correct":null,"answer":"They usually go to school by themselves."},{"id":"s33-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Do it yourself, my boy.（改为复数形式）</p>","options":[],"correct":null,"answer":"Do it yourselves, my boys."},{"id":"s33-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">The little bird got out of the nest by itself.（改为复数形式）</p>","options":[],"correct":null,"answer":"The little birds got out of the nest by themselves."},{"id":"s33-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The girl did all of these herself.（改为复数形式）</p>","options":[],"correct":null,"answer":"The girls did all of these themselves."}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【蚌埠·淮上区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s33-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">The cat can see <span class=\"blank-token\">____</span> in the mirror.</p>","options":["it","its","itself","him"],"correct":2,"answer":"C"},{"id":"s33-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Tom painted the room all by <span class=\"blank-token\">____</span>, because he likes doing it.</p>","options":["yourself","herself","himself","themselves"],"correct":2,"answer":"C\n解析：by oneself 为固定搭配, 主语 Tom [汤姆(男名)] 的反身代词为 himself, 故此题选择 C 选项。"},{"id":"s33-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Boys, don't touch the machine, or you may hurt <span class=\"blank-token\">____</span>.</p>","options":["myself","themselves","yourself","yourselves"],"correct":3,"answer":"D\n解析：主语 boys(男孩们)为复数形式, 根据句意选择 yourselves(你们自己)。"},{"id":"s33-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">I made the cake <span class=\"blank-token\"><strong><em>_</em></strong></span>. Help <span class=\"blank-token\">_</span>, Tom.</p>","options":["ourselves; yourself","myself; yourself","myself; you","me; him"],"correct":1,"answer":"B\n解析：此题意为“我自己做了蛋糕。汤姆,随意吃”。第一句主语I(我)为第一人称,所以反身代词用myself(我自己)。help yourself(随意吃)为固定搭配。故此题选择B选项。"},{"id":"s33-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Did she go to school when she was young?<br/><br>\n—— No. She taught <span class=\"blank-token\">____</span> at home.</br></p>","options":["herself","her","hers","she"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"写出下列代词的反身代词或人称代词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s33-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">me</p>","options":[],"correct":null,"answer":"myself"},{"id":"s33-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">she</p>","options":[],"correct":null,"answer":"herself"},{"id":"s33-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">they</p>","options":[],"correct":null,"answer":"themselves"},{"id":"s33-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">one</p>","options":[],"correct":null,"answer":"oneself"},{"id":"s33-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">you <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"yourself / yourselves"},{"id":"s33-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">yourself</p>","options":[],"correct":null,"answer":"you"},{"id":"s33-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">themselves</p>","options":[],"correct":null,"answer":"they"},{"id":"s33-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">yourselves <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"you"},{"id":"s33-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">himself</p>","options":[],"correct":null,"answer":"he"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s33-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">—— Is that car yours?<br/><br>\n—— Yes, it is <span class=\"blank-token\">____</span> (I).</br></p>","options":[],"correct":null,"answer":"mine"},{"id":"s33-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">—— How is Mr Li?<br/><br>\n—— <span class=\"blank-token\">____</span> (he) is fine, thanks.</br></p>","options":[],"correct":null,"answer":"He"},{"id":"s33-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">I am going to put on the hat by <span class=\"blank-token\">____</span> (me).</p>","options":[],"correct":null,"answer":"myself"},{"id":"s33-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">—— Who is the girl in the photo?<br/><br>\n—— It is <span class=\"blank-token\">____</span> (I).</br></p>","options":[],"correct":null,"answer":"me"},{"id":"s33-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">The old man lives by <span class=\"blank-token\">____</span> (he).</p>","options":[],"correct":null,"answer":"himself"},{"id":"s33-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">You can see <span class=\"blank-token\">____</span> (you) in the mirror.</p>","options":[],"correct":null,"answer":"yourself / yourselves"}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s33-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">We must finish our homework by <span class=\"blank-token\">____</span>.</p>","options":["yourselves","themselves","ourselves"],"correct":2,"answer":"C"},{"id":"s33-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">My sister often looks at <span class=\"blank-token\">____</span> in the mirror.</p>","options":["her","she","herself"],"correct":2,"answer":"C"},{"id":"s33-text-q018","number":18,"type":"mcq","questionHtml":"<p class=\"source-line\">Sandy and Sue, help <span class=\"blank-token\">____</span> to some food, please.</p>","options":["yourselves","yourself","yours"],"correct":0,"answer":"A"},{"id":"s33-text-q019","number":19,"type":"mcq","questionHtml":"<p class=\"source-line\">Tom enjoys <span class=\"blank-token\">____</span> on his birthday.</p>","options":["he","himself","him"],"correct":1,"answer":"B"},{"id":"s33-text-q020","number":20,"type":"mcq","questionHtml":"<p class=\"source-line\">I am new here. Let me introduce (介绍) <span class=\"blank-token\">____</span> to you first.</p>","options":["me","I","myself"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true}]},{"id":"s34","section":34,"unit":6,"unitName":"单元06 · 第31–36节","short":"第34节 · L67–68","title":"含有 be 动词的一般过去时","lessons":"Lesson 67 — Lesson 68","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>含有be动词的一般过去时</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>含有be动词的一般过去时</td>\n<td>含有be动词的一般过去时</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般过去时的概念</div><div class=\"gb\"><p class=\"source-line\">一般过去时表示过去发生的动作、行为或存在的状态。</p>\n<p class=\"source-line\">I was short two years ago. 我两年前很矮。</p>\n<p class=\"source-line\">My grandparents were teachers twenty years ago. 我的(外)祖父母20年前是老师。</p></div></div>\n<div class=\"g\"><div class=\"gt\">含有 be 动词的一般过去时</div><div class=\"gb\"><h5>1. 肯定句: 主语 + was / were + 其他.</h5>\n<p class=\"source-line\">I was tired last night. 我昨天晚上很累。</p>\n<p class=\"source-line\">There were some books there. 那里(曾经)有一些书。</p>\n<h5>2. 否定句: 主语 + was / were not + 其他.</h5>\n<p class=\"source-line\">Mike wasn't at home this morning.<br/>\n迈克今天早上不在家。<br/>\nThey weren't there yesterday.<br/>\n他们昨天不在那里。</p>\n<p class=\"source-line\">was not 可缩写为 wasn't, were not 可缩写为 weren't。</p>\n<h5>3. 一般疑问句: Was / Were + 主语 + 其他?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + was / were.</p>\n<p class=\"source-line\">否定回答: No, 主语 + wasn't / weren't.</p>\n<p class=\"source-line\">—— Was he a driver? 他(以前)是司机吗?<br/>\n—— Yes, he was. 是的，他是。<br/>\n—— No, he wasn't. 不，他不是。<br/>\n—— Were they doctors? 他们(以前)是医生吗?<br/>\n—— Yes, they were. 是的,他们是。<br/>\n—— No, they weren't. 不,他们不是。</p>\n<h5>4. 特殊疑问句:疑问词+was/were+主语(+其他)?</h5>\n<p class=\"source-line\">Where was the dog five days ago? 那只狗 5 天前在哪里？</p>\n<p class=\"source-line\">Where were they two years ago? 他们两年前在哪里？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【惠州·惠城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s34-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> a shy girl before.</p>","options":["were","am","was"],"correct":2,"answer":"C"},{"id":"s34-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">His pen <span class=\"blank-token\">____</span> in the pencil box last night.</p>","options":["is","was","were"],"correct":1,"answer":"B"},{"id":"s34-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> enough milk at home last week.</p>","options":["was","were","is"],"correct":0,"answer":"A"},{"id":"s34-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">It <span class=\"blank-token\">____</span> hot yesterday.</p>","options":["is","are","was"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【玉溪·红塔区】按要求完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s34-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The monkeys were in the tree. (改为否定句)</p>","options":[],"correct":null,"answer":"The monkeys weren't in the tree."},{"id":"s34-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">My pens were in the desk. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Were your pens in the desk?"},{"id":"s34-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My friends weren't happy last Sunday. (改为肯定句)</p>","options":[],"correct":null,"answer":"My friends were happy last Sunday."},{"id":"s34-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Paper was very expensive many years ago. (改为否定句)</p>","options":[],"correct":null,"answer":"Paper wasn't very expensive many years ago."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"用 be 的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s34-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> no one here a moment ago.</p>","options":[],"correct":null,"answer":"was"},{"id":"s34-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> a telephone call for you just now.</p>","options":[],"correct":null,"answer":"was"},{"id":"s34-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> not enough people to pick apples yesterday.</p>","options":[],"correct":null,"answer":"were"},{"id":"s34-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> tired yesterday.</p>","options":[],"correct":null,"answer":"was"},{"id":"s34-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> here just now.</p>","options":[],"correct":null,"answer":"was"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"按要求完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s34-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He was absent from school <u>last week</u>.（分别改为否定句、一般疑问句，并对画线部分提问）</p>","options":[],"correct":null,"answer":"（1）He was not absent from school last week.\n（2）Was he absent from school last week?\n（3）When was he absent from school?"},{"id":"s34-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">There were <u>hundreds of people</u> yesterday.（分别改为否定句、一般疑问句，并对画线部分提问）</p>","options":[],"correct":null,"answer":"（1）There were not hundreds of people yesterday.\n（2）Were there hundreds of people yesterday?\n（3）How many people were there yesterday?"}],"questionCount":2,"hasAnswers":true}]},{"id":"s35","section":35,"unit":6,"unitName":"单元06 · 第31–36节","short":"第35节 · L69–70","title":"表示时间的 at、in 和 on","lessons":"Lesson 69 — Lesson 70","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 at</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 in</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 on</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">at 的用法</div><div class=\"gb\"><h5>1. at 后接具体的时刻, 意为 “在某一时刻”。</h5>\n<p class=\"source-line\">At noon, the sun is high in the sky. 在中午，烈日当空。</p>\n<p class=\"source-line\">We work in the morning, and have lunch at 12 o'clock.</p>\n<p class=\"source-line\">我们在上午工作，在12:00吃午饭。</p>\n<h5>2. at 可放在短暂的时间前或某个节日前。</h5>\n<p class=\"source-line\">He went home at Chinese New Year.</p>\n<p class=\"source-line\">他在春节回家了。</p>\n<p class=\"source-line\">其他含有 at 的短语:</p>\n<p class=\"source-line\">at the weekend 在周末</p>\n<p class=\"source-line\">at night 在晚上</p>\n<p class=\"source-line\">at last 最后</p>\n<p class=\"source-line\">at the end of... 在……的最后</p>\n<p class=\"source-line\">at midnight 在午夜</p></div></div>\n<div class=\"g\"><div class=\"gt\">in 的用法</div><div class=\"gb\"><p class=\"source-line\">in 后接一段时间, 意为 “在……期间”, 也可以放在表示年、季节、月、上午、下午、晚上等时间名词前。</p>\n<p class=\"source-line\">What's the weather like in spring? 春天天气怎么样?</p>\n<p class=\"source-line\">There are 31 days in August. 8月有31天。</p>\n<p class=\"source-line\">其他含有 in 的短语:</p>\n<p class=\"source-line\">in the future 在将来</p>\n<p class=\"source-line\">in one's life 在某人的一生中</p>\n<p class=\"source-line\">in the 1990s 在 20 世纪 90 年代</p>\n<p class=\"source-line\">in one's opinion 在某人看来</p>\n<p class=\"source-line\">in fact 事实上</p></div></div>\n<div class=\"g\"><div class=\"gt\">on 的用法</div><div class=\"gb\"><h5>1. on 用在具体某一天或日期前。</h5>\n<p class=\"source-line\">on 后接具体的某一天或特定的时间。</p>\n<p class=\"source-line\">Mike was born on a cold winter day.</p>\n<p class=\"source-line\">迈克出生在一个寒冷的冬日。</p>\n<h5>2. on 用在表示某一天的上午、下午、晚上的名词前。</h5>\n<p class=\"source-line\">We'll have a party on Sunday evening.</p>\n<p class=\"source-line\">我们将在星期日晚上举行聚会。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">时间介词 in、on、at：in 年、in 月、in 季节；on 日、on 号、on 星期；at 用于具体时刻。泛指早午晚用 in，有具体修饰时用 on。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【合肥·庐阳区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s35-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Mrs Brown came to China <span class=\"blank-token\">____</span> 1996.</p>","options":["on","of","to","in"],"correct":3,"answer":"D"},{"id":"s35-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">He often goes to school <span class=\"blank-token\"><strong><em>_</em></strong></span> six thirty <span class=\"blank-token\">_</span> the morning.</p>","options":["to; in","at; in","for; at","at; to"],"correct":1,"answer":"B\n解析：six thirty(6:30)为具体的时间点, 前用介词 at; in the morning(在早上)为固定搭配。故此题选择 B 选项。"},{"id":"s35-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">A lot of students in our school were born <span class=\"blank-token\">____</span> March, 2014.</p>","options":["in","at","on","since"],"correct":0,"answer":"A"},{"id":"s35-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">He suddenly returned <span class=\"blank-token\">____</span> a rainy night.</p>","options":["on","at","in","during"],"correct":0,"answer":"A\n解析：a rainy night (一个雨夜) 表示具体的某一天的夜晚, 前用介词 on。"},{"id":"s35-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">My grandfather was born <span class=\"blank-token\">____</span> October 10th, 1964.</p>","options":["on","in","at","of"],"correct":0,"answer":"A\n解析：October 10th, 1964 (1964 年 10 月 10 日) 表示具体的一天, 前用介词 on。"},{"id":"s35-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">More and more people go skiing <span class=\"blank-token\">____</span> winter.</p>","options":["in","at","on","of"],"correct":0,"answer":"A"},{"id":"s35-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Jim doesn't go to school <span class=\"blank-token\">____</span> Sundays.</p>","options":["in","at","on","to"],"correct":2,"answer":"C"},{"id":"s35-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">The students put on (上演) a short play <span class=\"blank-token\">____</span> the Spring Festival.</p>","options":["in","with","at","of"],"correct":2,"answer":"C"},{"id":"s35-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— When is your father's birthday?<br/><br>\n—— It's on <span class=\"blank-token\">____</span>.</br></p>","options":["December","ten o'clock","eight","December 8th"],"correct":3,"answer":"D"},{"id":"s35-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Does the autumn start <span class=\"blank-token\"><strong><em>_</em></strong></span> August?<br/><br>\n—— Sometimes it does. But usually it starts <span class=\"blank-token\">_</span> September.</br></p>","options":["in; in","on; on","at; at","in; at"],"correct":0,"answer":"A\n解析：August(8 月)、September(9 月)都表示月份, 前用介词 in。"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s35-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">We go home at half past five <span class=\"blank-token\">____</span> the evening.</p>","options":["on","at","in"],"correct":2,"answer":"C"},{"id":"s35-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you often play computer games <span class=\"blank-token\">____</span> night?</p>","options":["at","in","on"],"correct":0,"answer":"A"},{"id":"s35-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I was born <span class=\"blank-token\">____</span> 1998.</p>","options":["in","on","at"],"correct":0,"answer":"A"},{"id":"s35-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">We have no classes <span class=\"blank-token\">____</span> Sunday morning.</p>","options":["on","at","in"],"correct":0,"answer":"A"},{"id":"s35-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Teachers' Day is <span class=\"blank-token\">____</span> September 10th.</p>","options":["at","in","on"],"correct":2,"answer":"C"},{"id":"s35-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">They have a party <span class=\"blank-token\">____</span> Children's Day.</p>","options":["in","on","at"],"correct":1,"answer":"B"},{"id":"s35-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">There are seven days <span class=\"blank-token\">____</span> a week.</p>","options":["on","at","in"],"correct":2,"answer":"C"},{"id":"s35-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">We often visit relatives (亲戚) and friends <span class=\"blank-token\">____</span> that day.</p>","options":["at","in","on"],"correct":2,"answer":"C"},{"id":"s35-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">We have lunch <span class=\"blank-token\">____</span> 12:00.</p>","options":["in","on","at"],"correct":2,"answer":"C"},{"id":"s35-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">I often watch TV <span class=\"blank-token\">____</span> Mondays.</p>","options":["on","at","in"],"correct":0,"answer":"A"},{"id":"s35-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">China's National Day is <span class=\"blank-token\">____</span> October.</p>","options":["at","in","on"],"correct":1,"answer":"B"},{"id":"s35-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">What do you do <span class=\"blank-token\">____</span> Sundays?</p>","options":["in","on","at"],"correct":1,"answer":"B"},{"id":"s35-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">We have a school trip <span class=\"blank-token\">____</span> autumn.</p>","options":["on","at","in"],"correct":2,"answer":"C"},{"id":"s35-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you often get up <span class=\"blank-token\">____</span> 7:00?</p>","options":["at","in","on"],"correct":0,"answer":"A"},{"id":"s35-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">I have a music class <span class=\"blank-token\">____</span> the afternoon.</p>","options":["in","on","at"],"correct":0,"answer":"A"},{"id":"s35-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">I have fish for dinner <span class=\"blank-token\">____</span> Mondays.</p>","options":["on","at","in"],"correct":0,"answer":"A"},{"id":"s35-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">Please come here <span class=\"blank-token\">____</span> the afternoon of August 15th.</p>","options":["at","in","on"],"correct":2,"answer":"C"},{"id":"s35-text-q018","number":18,"type":"mcq","questionHtml":"<p class=\"source-line\">My parents go to work <span class=\"blank-token\">____</span> the morning.</p>","options":["in","on","at"],"correct":0,"answer":"A"},{"id":"s35-text-q019","number":19,"type":"mcq","questionHtml":"<p class=\"source-line\">They will have a football match <span class=\"blank-token\">____</span> Saturday.</p>","options":["on","at","in"],"correct":0,"answer":"A"},{"id":"s35-text-q020","number":20,"type":"mcq","questionHtml":"<p class=\"source-line\">对句子 “I often go shopping ____ the weekend.” 中空格用法的说明，正确的是：</p>","options":["只能用 in","只能用 on","只能用 at","on 或 at 均可"],"correct":3,"answer":"D"}],"questionCount":20,"hasAnswers":true}]},{"id":"s36","section":36,"unit":6,"unitName":"单元06 · 第31–36节","short":"第36节 · L71–72","title":"含有实义动词的一般过去时的句子","lessons":"Lesson 71 — Lesson 72","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>含有实义动词的一般过去时的句子</td>\n<td>动词过去式的构成规则</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>含有实义动词的一般过去时的句子</td>\n<td>含有实义动词的一般过去时的句子</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">动词过去式的构成规则</div><div class=\"gb\"><h5>1. 一般情况在动词词尾直接加 ed。</h5>\n<p class=\"source-line\">work — worked 工作</p>\n<p class=\"source-line\">jump — jumped 跳</p>\n<p class=\"source-line\">talk — talked 说话</p>\n<p class=\"source-line\">watch — watched 观看</p>\n<h5>2. 以不发音的 e 结尾的动词, 在词尾加 d。</h5>\n<p class=\"source-line\">like — liked 喜欢</p>\n<p class=\"source-line\">arrive — arrived 到达</p>\n<p class=\"source-line\">smile — smiled 微笑</p>\n<p class=\"source-line\">love — loved 爱</p>\n<h5>3. 以辅音字母加 y 结尾的动词, 把 y 变 i, 再加 ed。</h5>\n<p class=\"source-line\">study — studied 学习</p>\n<p class=\"source-line\">carry — carried 拿</p>\n<p class=\"source-line\">try — tried 试图</p>\n<h5>4. 以重读闭音节结尾的动词,末尾只有一个辅音字母时,双写这个辅音字母,再加 ed。</h5>\n<p class=\"source-line\">stop — stopped 停止</p>\n<p class=\"source-line\">plan — planned 计划</p>\n<p class=\"source-line\">chat — chatted 聊天</p>\n<p class=\"source-line\">skip — skipped 跳绳</p></div></div>\n<div class=\"g\"><div class=\"gt\">含有实义动词的一般过去时的句子</div><div class=\"gb\"><h5>1. 肯定句: 主语+动词过去式(+其他).</h5>\n<p class=\"source-line\">I played the piano yesterday afternoon. 我昨天下午弹钢琴了。</p>\n<p class=\"source-line\">She found a new English book. 她找到了一本新英语书。</p>\n<h5>2. 否定句: 主语 + didn't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">I didn't have an English class this morning. 我今天上午没有英语课。</p>\n<p class=\"source-line\">You didn't do your best. 你没有尽力。</p>\n<p class=\"source-line\">含有实义动词的一般过去时的肯定句在变否定句时，在谓语动词前加did not（did not可缩写为didn't），谓语动词变为原形即可。</p>\n<h5>3. 一般疑问句: Did + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">Did he go there yesterday? 他昨天去那里了吗?</p>\n<p class=\"source-line\">Did you play ping-pong last weekend? 你们上周末打乒乓球了吗?</p>\n<h5>4. 特殊疑问句: 疑问词 + did + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">（1）针对做了什么提问。</p>\n<p class=\"source-line\">What did you do yesterday? 你昨天做了什么？<br/>\nWhat did Mike do last night? 迈克昨晚做了什么？</p>\n<p class=\"source-line\">（2）针对时间提问。</p>\n<p class=\"source-line\">What time did you go to school yesterday?</p>\n<p class=\"source-line\">你昨天几点去上学的？</p>\n<p class=\"source-line\">When did your mother go to work last Monday?</p>\n<p class=\"source-line\">你妈妈上星期一什么时候去上班的？</p>\n<p class=\"source-line\">（3）针对地点提问。</p>\n<p class=\"source-line\">Where did your family live five years ago? 你的家人5年前住在哪里？</p>\n<p class=\"source-line\">Where did he play basketball this morning? 他今天早上在哪里打篮球？</p>\n<p class=\"source-line\">（4）针对方式提问。</p>\n<p class=\"source-line\">How did your mother go to work a week ago? 你妈妈一周前是怎么上班的？</p>\n<p class=\"source-line\">How did he get to the zoo the day before yesterday? 他前天是怎么到动物园的？</p>\n<p class=\"source-line\">（5）针对动词的对象提问。</p>\n<p class=\"source-line\">What did she write? 她写了什么？</p>\n<p class=\"source-line\">What did she tell you? 她告诉了你什么？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【成都·锦江区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s36-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (enjoy) ourselves at the party last night.</p>","options":[],"correct":null,"answer":"enjoyed"},{"id":"s36-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> (go) to the Great Wall last year?</p>","options":[],"correct":null,"answer":"Did, go\n解析：根据 last year (去年) 可知此题时态为一般过去时, 助动词用 did, 后面的动词用原形 go。"},{"id":"s36-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">What day <span class=\"blank-token\">____</span> (be) it yesterday?</p>","options":[],"correct":null,"answer":"was\n解析：根据 yesterday (在昨天) 可知此题时态为一般过去时, 主语 it (它) 是第三人称单数, 故 be 动词用 was。"},{"id":"s36-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">The old man <span class=\"blank-token\">____</span> (be) ill and went to see a doctor.</p>","options":[],"correct":null,"answer":"was\n解析：根据 “went to see a doctor (去看医生了)” 可知此题时态为一般过去时, The old man 为第三人称单数, 故 be 动词用 was。"},{"id":"s36-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (visit) the museum and went home.</p>","options":[],"correct":null,"answer":"visited"},{"id":"s36-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (have) a party last night.</p>","options":[],"correct":null,"answer":"had"}],"questionCount":6,"hasAnswers":true},{"source":"practice","title":"【昆明·五华区】句型转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s36-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Mary did her homework at home. (改为否定句)</p>","options":[],"correct":null,"answer":"Mary didn't do her homework at home."},{"id":"s36-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">He found some food in the fridge. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Did he find any food in the fridge?"},{"id":"s36-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">She went to Shanghai <u>last month</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"When did she go to Shanghai?"},{"id":"s36-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">There was some orange juice in the cup. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Was there any orange juice in the cup?"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"写出下列动词的过去式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s36-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">ask</p>","options":[],"correct":null,"answer":"asked"},{"id":"s36-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">carry</p>","options":[],"correct":null,"answer":"carried"},{"id":"s36-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">chat</p>","options":[],"correct":null,"answer":"chatted"},{"id":"s36-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">copy <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"copied"},{"id":"s36-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">play <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"played"},{"id":"s36-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">move <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"moved"},{"id":"s36-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">study</p>","options":[],"correct":null,"answer":"studied"},{"id":"s36-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">look <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"looked"},{"id":"s36-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">try <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"tried"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"填写适当的词完成下列对话。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s36-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">—— How was your weekend?<br/><br>\n—— It <span class=\"blank-token\">____</span> great.</br></p>","options":[],"correct":null,"answer":"was"},{"id":"s36-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> last weekend?<br/><br>\n—— I <span class=\"blank-token\">____</span> some housework.</br></p>","options":[],"correct":null,"answer":"did, do, did"},{"id":"s36-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> she <span class=\"blank-token\">_</span> last weekend?<br/><br>\n—— She <span class=\"blank-token\">____</span> to the beach.</br></p>","options":[],"correct":null,"answer":"did, do, went"},{"id":"s36-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> they do last weekend?<br/><br>\n—— They <span class=\"blank-token\">_</span> swimming.</br></p>","options":[],"correct":null,"answer":"did, went"}],"questionCount":4,"hasAnswers":true}]},{"id":"s37","section":37,"unit":7,"unitName":"单元07 · 第37–42节","short":"第37节 · L73–74","title":"形容词变副词","lessons":"Lesson 73 — Lesson 74","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>形容词变副词</td>\n<td>形容词与副词的关系</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>形容词变副词</td>\n<td>形容词变副词的规则</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">形容词与副词的关系</div><div class=\"gb\"><p class=\"source-line\">形容词和副词一样,都具有修饰功能。形容词修饰名词,说明人或物的特征,在句中可作定语、表语和补语。副词在句中修饰动词、形容词、其他副词或整个句子,说明动作或状态的特征、时间、地点、程度、方式等情况。</p>\n<h5>形容词示例</h5>\n<p class=\"source-line\">His father is a famous scientist. 他父亲是一位著名的科学家。</p>\n<p class=\"source-line\">The boy looks tall.</p>\n<p class=\"source-line\">这个男孩儿看起来很高。</p>\n<h5>副词示例</h5>\n<p class=\"source-line\">The house is very big. 这座房子很大。</p>\n<p class=\"source-line\">Lucy sings well.</p>\n<p class=\"source-line\">露西唱得很好。</p></div></div>\n<div class=\"g\"><div class=\"gt\">形容词变副词的规则</div><div class=\"gb\"><p class=\"source-line\">（1）一般情况下,直接在形容词后加 ly。如:</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>careful</td>\n<td>小心的</td>\n<td>carefully</td>\n<td>小心地</td>\n</tr>\n<tr>\n<td>quick</td>\n<td>快的</td>\n<td>quickly</td>\n<td>很快地</td>\n</tr>\n<tr>\n<td>quiet</td>\n<td>安静的</td>\n<td>quietly</td>\n<td>安静地</td>\n</tr>\n<tr>\n<td>different</td>\n<td>不同的</td>\n<td>differently</td>\n<td>不同地</td>\n</tr>\n<tr>\n<td>successful</td>\n<td>成功的</td>\n<td>successfully</td>\n<td>成功地</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（2）以“辅音字母+y”结尾的形容词,把 y 变 i,再加 ly。如:</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>easy</td>\n<td>容易的</td>\n<td>easily</td>\n<td>容易地</td>\n</tr>\n<tr>\n<td>angry</td>\n<td>愤怒的</td>\n<td>angrily</td>\n<td>愤怒地</td>\n</tr>\n<tr>\n<td>happy</td>\n<td>快乐的</td>\n<td>happily</td>\n<td>快乐地</td>\n</tr>\n<tr>\n<td>noisy</td>\n<td>吵闹的</td>\n<td>noisily</td>\n<td>吵闹地</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（3）以 le 结尾的形容词,把 le 变 ly。如:</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>possible</td>\n<td>可能的</td>\n<td>possibly</td>\n<td>可能地</td>\n</tr>\n<tr>\n<td>terrible</td>\n<td>糟糕的</td>\n<td>terribly</td>\n<td>糟糕地</td>\n</tr>\n<tr>\n<td>comfortable</td>\n<td>舒适的</td>\n<td>comfortably</td>\n<td>舒适地</td>\n</tr>\n<tr>\n<td>whole</td>\n<td>全部的</td>\n<td>wholly</td>\n<td>完全地（例外）</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（4）以 ue 结尾的形容词,去 e 加 ly。如:</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>due</td>\n<td>适当的</td>\n<td>duly</td>\n<td>适当地</td>\n</tr>\n<tr>\n<td>true</td>\n<td>真实的</td>\n<td>truly</td>\n<td>真正地；确实</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（5）以 ic 结尾的形容词通常加 ally；public 是例外，变为 publicly。如：</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>basic</td>\n<td>基本的</td>\n<td>basically</td>\n<td>基本上</td>\n</tr>\n<tr>\n<td>economic</td>\n<td>经济的</td>\n<td>economically</td>\n<td>经济地</td>\n</tr>\n<tr>\n<td>public</td>\n<td>公众的</td>\n<td>publicly</td>\n<td>公开地</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（6）以 ll 结尾的形容词直接加 y。如：</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>full</td>\n<td>完全的</td>\n<td>fully</td>\n<td>完全地</td>\n</tr>\n<tr>\n<td>dull</td>\n<td>沉闷的</td>\n<td>dully</td>\n<td>沉闷地</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（7）常见的形容词、副词同形的单词。如：</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>形容词</th>\n<th>中文释义</th>\n<th>副词</th>\n<th>中文释义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>early</td>\n<td>早的</td>\n<td>early</td>\n<td>早地；提早</td>\n</tr>\n<tr>\n<td>late</td>\n<td>迟的；晚的</td>\n<td>late</td>\n<td>迟；晚</td>\n</tr>\n<tr>\n<td>fast</td>\n<td>快的</td>\n<td>fast</td>\n<td>快</td>\n</tr>\n<tr>\n<td>hard</td>\n<td>困难的；坚硬的</td>\n<td>hard</td>\n<td>努力地；猛烈地</td>\n</tr>\n<tr>\n<td>deep</td>\n<td>深的</td>\n<td>deep</td>\n<td>深深地</td>\n</tr>\n<tr>\n<td>high</td>\n<td>高的</td>\n<td>high</td>\n<td>高</td>\n</tr>\n<tr>\n<td>low</td>\n<td>低的</td>\n<td>low</td>\n<td>低;向下</td>\n</tr>\n<tr>\n<td>far</td>\n<td>较远的</td>\n<td>far</td>\n<td>远</td>\n</tr>\n</tbody>\n</table></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【蚌埠·禹会区】写出下列单词的副词形式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s37-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">bright <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"brightly"},{"id":"s37-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">casual <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"casually"},{"id":"s37-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">correct <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"correctly"},{"id":"s37-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">final <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"finally"},{"id":"s37-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">simple <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"simply"},{"id":"s37-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">easy <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"easily"},{"id":"s37-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">good <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"well"},{"id":"s37-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">possible <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"possibly"},{"id":"s37-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">strong <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"strongly"},{"id":"s37-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">true <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"truly"},{"id":"s37-practice-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">usual <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"usually"},{"id":"s37-practice-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">heavy <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"heavily"}],"questionCount":12,"hasAnswers":true},{"source":"practice","title":"【成都·锦江区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s37-practice-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> go to school at eight am.</p>","options":["very","much","often"],"correct":2,"answer":"C\n解析：go to school (去上学)为动词短语,前面可用副词修饰, often (经常)为频度副词,符合题意。"},{"id":"s37-practice-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">The food tastes <span class=\"blank-token\">____</span>.</p>","options":["terribly","delicious","deliciously"],"correct":1,"answer":"B\n解析：taste (品尝) 为感官连系动词, 后接形容词, 故此题选择 B 选项。"},{"id":"s37-practice-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">She often has supper <span class=\"blank-token\">____</span>.</p>","options":["quick","quickly","slow"],"correct":1,"answer":"B"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【天津·滨海新区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s37-practice-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">Jack runs <span class=\"blank-token\">____</span> (slow).</p>","options":[],"correct":null,"answer":"slowly"},{"id":"s37-practice-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">It is a kind of <span class=\"blank-token\"><strong><em>_</em></strong></span> food. We should eat <span class=\"blank-token\">_</span>. (healthy)</p>","options":[],"correct":null,"answer":"healthy, healthily\n解析：food (食物) 为名词, 可用形容词修饰; eat (吃) 为实义动词, 可用副词修饰, healthy (健康的) 变为 healthily (健康地)。"},{"id":"s37-practice-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">They play together <span class=\"blank-token\">____</span> (happy).</p>","options":[],"correct":null,"answer":"happily"},{"id":"s37-practice-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">I can't hear you when you talk <span class=\"blank-token\">____</span> (quiet).</p>","options":[],"correct":null,"answer":"quietly"},{"id":"s37-practice-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">She gets up <span class=\"blank-token\"><strong><em>_</em></strong></span> to catch the <span class=\"blank-token\">_</span> bus. (early)</p>","options":[],"correct":null,"answer":"early, early\n解析：get up (起床) 为动词短语, 可用副词修饰。bus (公共汽车) 为名词, 可用形容词修饰。early (早的; 早地) 作形容词和副词时同形, 所以每个空都填 early 即可。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s37-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Look at the children on the playground. They are flying kites <span class=\"blank-token\">____</span> (pleasant). Let's join them.</p>","options":[],"correct":null,"answer":"pleasantly"},{"id":"s37-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Why do you think you did so <span class=\"blank-token\">____</span> (terrible) in your test?</p>","options":[],"correct":null,"answer":"terribly"},{"id":"s37-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">We can <span class=\"blank-token\">____</span> (easy) forgive (原谅) a child who is afraid of the dark, but we can't forgive an adult who is afraid of the light.</p>","options":[],"correct":null,"answer":"easily"},{"id":"s37-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Congratulations! You've answered all the questions <span class=\"blank-token\">____</span> (correct).</p>","options":[],"correct":null,"answer":"correctly"},{"id":"s37-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The computer is <span class=\"blank-token\">____</span> (wide) used in our daily life.</p>","options":[],"correct":null,"answer":"widely"},{"id":"s37-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I changed into my sports shoes so that I could walk more <span class=\"blank-token\">____</span> (comfortable).</p>","options":[],"correct":null,"answer":"comfortably"},{"id":"s37-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Mary passed her examination because she studied very <span class=\"blank-token\">____</span> (hard).</p>","options":[],"correct":null,"answer":"hard"},{"id":"s37-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">\"Why didn't you tell me earlier?\" the boss shouted <span class=\"blank-token\">____</span> (angry).</p>","options":[],"correct":null,"answer":"angrily"},{"id":"s37-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span> (true) possible that robot teachers will be popular in schools someday.</p>","options":[],"correct":null,"answer":"truly"},{"id":"s37-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">How <span class=\"blank-token\">____</span> (comfortable) the pandas are living in Sichuan!</p>","options":[],"correct":null,"answer":"comfortably"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s37-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">This kind of skirt looks nice and sells <span class=\"blank-token\">____</span>.</p>","options":["good","well","fine","nice"],"correct":1,"answer":"B"},{"id":"s37-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't go out. It's raining <span class=\"blank-token\">____</span>.</p>","options":["quickly","hardly","heavily","loudly"],"correct":2,"answer":"C"},{"id":"s37-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">When the famous singer started to sing, everyone began to shout very <span class=\"blank-token\">____</span>.</p>","options":["louder","loudly","high","highly"],"correct":1,"answer":"B"},{"id":"s37-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">The old writer lives <span class=\"blank-token\"><strong><em>_</em></strong></span>, but he doesn’t feel <span class=\"blank-token\">_</span>.</p>","options":["alone; alone","lonely; lonely","lonely; alone","alone; lonely"],"correct":3,"answer":"D"},{"id":"s37-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">She isn't feeling very <span class=\"blank-token\">____</span> today.</p>","options":["nice","good","better","well"],"correct":3,"answer":"D"},{"id":"s37-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">John got a nice present yesterday. He looked so <span class=\"blank-token\">____</span>.</p>","options":["sad","happy","tired","happily"],"correct":1,"answer":"B"},{"id":"s37-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">Li Ming did his homework <span class=\"blank-token\">____</span>. So he left school last.</p>","options":["slowly","easily","happily","quickly"],"correct":0,"answer":"A"},{"id":"s37-text-q018","number":18,"type":"mcq","questionHtml":"<p class=\"source-line\">The maths problem (问题) is <span class=\"blank-token\"><strong><em>_</em></strong></span> and I can do it <span class=\"blank-token\">_</span>.</p>","options":["easy; easily","easily; easily","easy; easy","easily; easy"],"correct":0,"answer":"A"}],"questionCount":8,"hasAnswers":true}]},{"id":"s38","section":38,"unit":7,"unitName":"单元07 · 第37–42节","short":"第38节 · L75–76","title":"一般过去时的时间状语","lessons":"Lesson 75 — Lesson 76","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般过去时的时间状语</td>\n<td>一般过去时的时间状语</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般过去时的时间状语</div><div class=\"gb\"><h5>1. yesterday 类</h5>\n<p class=\"source-line\">yesterday morning 昨天早上</p>\n<p class=\"source-line\">yesterday evening 昨天晚上</p>\n<p class=\"source-line\">the day before yesterday 前天</p>\n<p class=\"source-line\">Mike missed the bus yesterday morning.</p>\n<p class=\"source-line\">迈克昨天早上错过了公共汽车。</p>\n<h5>2. last 类</h5>\n<p class=\"source-line\">last night 昨晚</p>\n<p class=\"source-line\">last Sunday 上星期日</p>\n<p class=\"source-line\">last month 上个月</p>\n<p class=\"source-line\">I went to the park with my parents last Sunday.</p>\n<p class=\"source-line\">我上周日和爸爸妈妈去公园了。</p>\n<h5>3. ago 类</h5>\n<p class=\"source-line\">long long ago 很久很久以前</p>\n<p class=\"source-line\">two months ago 2 个月以前</p>\n<p class=\"source-line\">three weeks ago 3 周前</p>\n<p class=\"source-line\">I played in a forest with my friends three days ago.</p>\n<p class=\"source-line\">我和我的朋友们3天前在森林里玩儿。</p>\n<h5>4. in / on 类</h5>\n<p class=\"source-line\">in 1997 在 1997 年</p>\n<p class=\"source-line\">in 2022 在 2022 年</p>\n<p class=\"source-line\">on June 18th 在6月18日(这里指已经过去的某个6月18日)</p>\n<p class=\"source-line\">I went to Xinjiang in 2022. 我在 2022 年去了新疆。</p>\n<h5>5. 其他</h5>\n<p class=\"source-line\">that year 那一年 those days 那些日子</p>\n<p class=\"source-line\">just now 刚才 before two o'clock 2:00 前</p>\n<p class=\"source-line\">We got much love from our grandparents in the past years.</p>\n<p class=\"source-line\">我们在过去的那些年里从(外)祖父母那里得到了很多爱。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【蚌埠·龙子湖区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s38-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How did you go to the park yesterday?<br/><br>\n—— I <span class=\"blank-token\">____</span> a bus.</br></p>","options":["by","take","took"],"correct":2,"answer":"C"},{"id":"s38-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What <span class=\"blank-token\"><strong><em>_</em></strong></span> you do last Sunday?<br/><br>\n—— We <span class=\"blank-token\">_</span> on a picnic with our friends.</br></p>","options":["did; went","do; go","did; go"],"correct":0,"answer":"A\n解析：根据问句中 last Sunday (上周日) 可知本题时态为一般过去时,故助动词用 did,答语中的谓语动词用 went。"},{"id":"s38-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> you at home yesterday?<br/><br>\n—— No, I wasn't.</br></p>","options":["Are","Did","Were"],"correct":2,"answer":"C\n解析：根据问句中 yesterday(在昨天)可知本题时态为一般过去时,主语 you(你)是第二人称,故 be 动词用 Were。"},{"id":"s38-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> her homework, because she was ill.</p>","options":["didn't","does","didn't do"],"correct":2,"answer":"C\n解析：根据句中后半句 “because she was ill（因为她生病了）” 可知本题为一般过去时,故前面助动词用 didn’t,谓语动词用原形 do。"},{"id":"s38-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">It was a busy day <span class=\"blank-token\">____</span>.</p>","options":["yesterday","today","tomorrow"],"correct":0,"answer":"A\n解析：根据句中 was(是)可知本题时态为一般过去时,故时间状语选择 yesterday。"},{"id":"s38-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> TV yesterday.</p>","options":["watching","watched","watches"],"correct":1,"answer":"B"},{"id":"s38-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Did you <span class=\"blank-token\">____</span> your shirt?</p>","options":["wash","washing","washed"],"correct":0,"answer":"A"},{"id":"s38-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span>, I went to the park.</p>","options":["Tomorrow","Next month","Two days ago"],"correct":2,"answer":"C\n解析：根据后半句 “I went to the park（我去了公园）” 可知本题时态为一般过去时，故前面的时间状语用表示过去的 “Two days ago”。"},{"id":"s38-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Did he <span class=\"blank-token\">____</span> his mum yesterday?</p>","options":["called","call","calling"],"correct":1,"answer":"B"},{"id":"s38-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> to the park last Saturday.</p>","options":["went","go","going"],"correct":0,"answer":"A"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s38-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Tom and Mary <span class=\"blank-token\">____</span> (come) to China last month.</p>","options":[],"correct":null,"answer":"came"},{"id":"s38-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Mike <span class=\"blank-token\"><strong><em>_</em></strong></span> (not go) to bed until 12 o'clock last night. So he <span class=\"blank-token\">_</span> (get) up late.</p>","options":[],"correct":null,"answer":"didn't go, got"},{"id":"s38-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Mary <span class=\"blank-token\">____</span> (read) English yesterday morning.</p>","options":[],"correct":null,"answer":"read"},{"id":"s38-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> (be) no one here a moment ago.</p>","options":[],"correct":null,"answer":"was"},{"id":"s38-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (call) Mike this morning.</p>","options":[],"correct":null,"answer":"called"},{"id":"s38-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Amy <span class=\"blank-token\">____</span> (be) a student two years ago.</p>","options":[],"correct":null,"answer":"was"},{"id":"s38-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> (live) in Shanghai last year.</p>","options":[],"correct":null,"answer":"lived"},{"id":"s38-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">My brother <span class=\"blank-token\">____</span> (buy) a gift for me last week.</p>","options":[],"correct":null,"answer":"bought"},{"id":"s38-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">John <span class=\"blank-token\">____</span> (study) for the English test last Sunday.</p>","options":[],"correct":null,"answer":"studied"},{"id":"s38-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (visit) the museum in 2020.</p>","options":[],"correct":null,"answer":"visited"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s38-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">Andy had breakfast <span class=\"blank-token\">____</span>.</p>","options":["tomorrow","yesterday","next Friday"],"correct":1,"answer":"B"},{"id":"s38-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> my room and watched TV last Sunday.</p>","options":["clean","cleaning","cleaned"],"correct":2,"answer":"C"},{"id":"s38-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Lily flew a kite in the park <span class=\"blank-token\">____</span>.</p>","options":["the day before yesterday","in five days","tomorrow"],"correct":0,"answer":"A"},{"id":"s38-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> you busy yesterday?</p>","options":["Was","Were","Are"],"correct":1,"answer":"B"},{"id":"s38-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">The children picked up the trash in the park <span class=\"blank-token\">____</span>. They are good pupils.</p>","options":["next Sunday","yesterday morning","the day after tomorrow"],"correct":1,"answer":"B"}],"questionCount":5,"hasAnswers":true}]},{"id":"s39","section":39,"unit":7,"unitName":"单元07 · 第37–42节","short":"第39节 · L77–78","title":"否定疑问句与一般现在时、一般过去时的对比","lessons":"Lesson 77 — Lesson 78","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>否定疑问句与一般现在时、一般过去时的对比</td>\n<td>否定疑问句</td>\n<td>★★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>否定疑问句与一般现在时、一般过去时的对比</td>\n<td>一般现在时和一般过去时的对比</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">否定疑问句</div><div class=\"gb\"><p class=\"source-line\">表示说话者惊异的情绪、责难的口吻或赞叹，或表示说话者的某种建议、邀请、请求或看法等的疑问句叫否定疑问句。否定疑问句通常译为“……不……吗？”</p>\n<p class=\"source-line\">Isn't he a worker?</p>\n<p class=\"source-line\">他不是一名工人吗？</p>\n<p class=\"source-line\">Didn't you know the truth?</p>\n<p class=\"source-line\">你不知道真相吗？</p>\n<p class=\"source-line\">Can't you see the bus coming?</p>\n<p class=\"source-line\">你没看见公共汽车开过来吗？</p>\n<h5>1. 否定疑问句的结构</h5>\n<p class=\"source-line\">（1）Be 动词 + not + 主语 + 表语?</p>\n<p class=\"source-line\">Aren't you a student?</p>\n<p class=\"source-line\">你不是一名学生吗？</p>\n<p class=\"source-line\">（2）情态动词 + not + 主语 + 谓语（+其他）?</p>\n<p class=\"source-line\">Can't he drive?</p>\n<p class=\"source-line\">他不会开车吗？</p>\n<p class=\"source-line\">（3）助动词 + not + 主语 + 谓语（+其他）?</p>\n<p class=\"source-line\">Don't you want to stay with us?</p>\n<p class=\"source-line\">你不想要和我们待在一起吗？</p>\n<p class=\"source-line\">否定疑问句仍按事实作答：肯定事实用 Yes，否定事实用 No。由于中英文表达习惯不同，翻译时不能机械地把 Yes 译为“是”、把 No 译为“不”。例如，对“Don't you like bananas?”回答“Yes, I do.”表示“不是，我喜欢”；回答“No, I don't.”表示“是的，我不喜欢”。</p>\n<h5>2. 否定疑问句的用法</h5>\n<p class=\"source-line\">（1）寻求赞同。</p>\n<p class=\"source-line\">Isn't it healthier to eat fruit than sweets?</p>\n<p class=\"source-line\">吃水果不比吃糖果更健康吗？</p>\n<p class=\"source-line\">（2）表示惊讶。</p>\n<p class=\"source-line\">Don't you like bananas?</p>\n<p class=\"source-line\">你不喜欢香蕉吗？</p>\n<p class=\"source-line\">（3）表示抱怨或担忧。</p>\n<p class=\"source-line\">Aren't you going to do the dishes?</p>\n<p class=\"source-line\">你不打算洗碗吗？</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时和一般过去时的对比</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>时态</th>\n<th>一般现在时</th>\n<th>一般过去时</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>含义</td>\n<td>经常性、习惯性的动作</td>\n<td>过去发生的动作</td>\n</tr>\n<tr>\n<td>常用的时间状语</td>\n<td>every 系列；always、usually、often、sometimes、never 等频度副词</td>\n<td>yesterday 系列；last 系列；ago 系列；in + 过去的年份；just now</td>\n</tr>\n<tr>\n<td>肯定句结构</td>\n<td>主语（非第三人称单数）+ 动词原形（+其他）；主语（第三人称单数）+ 动词第三人称单数形式（+其他）。</td>\n<td>主语 + 动词过去式（+其他）。</td>\n</tr>\n<tr>\n<td>例句</td>\n<td>They play football every day. 他们每天踢足球。<br/>Jack plays football every day. 杰克每天踢足球。</td>\n<td>Jack played football last night. 杰克昨晚踢足球了。</td>\n</tr>\n</tbody>\n</table></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【滁州·琅琊区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s39-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can't I cancel the appointment?<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["Yes, you can't.","No, you can.","Yes, you can."],"correct":2,"answer":"C\n解析：否定疑问句仍按事实作答。C 项“Yes, you can.”表示“你可以取消”，与答语的肯定事实一致。"},{"id":"s39-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">My parents teach English in a middle school. They <span class=\"blank-token\">____</span> doctors.</p>","options":["are","aren't","isn't"],"correct":1,"answer":"B"},{"id":"s39-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Was there a bus stop here last year?<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["No, there isn't.","No, there weren't.","No, there wasn't."],"correct":2,"answer":"C"},{"id":"s39-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Don’t you think his radio is too noisy?<br/><br>\n—— <span class=\"blank-token\">____</span> Let’s ask him to turn it down.</br></p>","options":["Yes, I do.","No, I do.","No, I don’t."],"correct":0,"answer":"A"},{"id":"s39-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> a good time last holiday.</p>","options":["didn't have","wasn't having","am not having"],"correct":0,"answer":"A\n解析：由 last holiday(上个假期)可知句子时态为一般过去时,have(有)为实义动词,此句变为否定句时,需借助助动词 did 并在后面加 not, did not 可缩写为 didn't。故此题选择 A 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【成都·武侯区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s39-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Three days ago, I <span class=\"blank-token\">____</span> (get) a bike from my parents.</p>","options":[],"correct":null,"answer":"got"},{"id":"s39-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> (be) some flowers before.</p>","options":[],"correct":null,"answer":"were\n解析：before (以前) 是一般过去时的标志, 主语 some flowers (一些花儿) 为第三人称复数, be 应用 were。"},{"id":"s39-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">They can <span class=\"blank-token\">____</span> (tell) many stories.</p>","options":[],"correct":null,"answer":"tell"},{"id":"s39-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Mike often <span class=\"blank-token\">____</span> (go) to school at seven in the morning.</p>","options":[],"correct":null,"answer":"goes\n解析：often(经常)是一般现在时的标志, 表示频率。主语 Mike(迈克)为第三人称单数, go 要变为第三人称单数形式 goes。"},{"id":"s39-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Her father <span class=\"blank-token\">____</span> (read) a newspaper last night.</p>","options":[],"correct":null,"answer":"read\n解析：由 last night (昨晚) 可知句子时态为一般过去时, read (读) 的过去式与原形一致, 即 read。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 翻译下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s39-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">你不能跑快一点吗？</p>","options":[],"correct":null,"answer":"Can't you run faster?"},{"id":"s39-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">你不是一名医生吗？</p>","options":[],"correct":null,"answer":"Aren't you a doctor?"},{"id":"s39-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">你不喜欢吃蔬菜吗？</p>","options":[],"correct":null,"answer":"Don't you like eating vegetables?"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"II. 用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s39-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Did you <span class=\"blank-token\">____</span> (water) the flowers yesterday?</p>","options":[],"correct":null,"answer":"water"},{"id":"s39-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Su Hai <span class=\"blank-token\">____</span> (go) for a walk last Sunday.</p>","options":[],"correct":null,"answer":"went"},{"id":"s39-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Mike <span class=\"blank-token\">____</span> (not finish) his homework yesterday.</p>","options":[],"correct":null,"answer":"didn't finish"},{"id":"s39-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Mike <span class=\"blank-token\">____</span> (do) his homework every day.</p>","options":[],"correct":null,"answer":"does"},{"id":"s39-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> (be) some water in the glass.</p>","options":[],"correct":null,"answer":"is"}],"questionCount":5,"hasAnswers":true}]},{"id":"s40","section":40,"unit":7,"unitName":"单元07 · 第37–42节","short":"第40节 · L79–80","title":"must 和 need 的用法","lessons":"Lesson 79 — Lesson 80","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>must 和 need 的用法</td>\n<td>must 的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>must 和 need 的用法</td>\n<td>need 的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">must 的用法</div><div class=\"gb\"><p class=\"source-line\">（1）must 作情态动词,意为“必须”,没有人称和数的变化,与动词原形搭配使用。</p>\n<p class=\"source-line\">You must come on time. 你必须准时来。</p>\n<p class=\"source-line\">You must be back before nine o'clock. 你必须9:00前回来。</p>\n<p class=\"source-line\">（2）must 的否定缩写形式是 mustn't,意为“一定不要；禁止”。</p>\n<p class=\"source-line\">You mustn't smoke here. 你一定不要在这儿吸烟。</p>\n<p class=\"source-line\">You mustn't be late again. 你别再迟到了。</p>\n<p class=\"source-line\">（3）以 must 开头的一般疑问句的否定回答常用 needn't，needn't 意为“不必”。</p>\n<p class=\"source-line\">—— Must I finish my homework today? 我今天必须完成家庭作业吗？</p>\n<p class=\"source-line\">—— Yes, you must. 是的,你必须完成。</p>\n<p class=\"source-line\">—— No, you needn't. 不,你不必完成。</p></div></div>\n<div class=\"g\"><div class=\"gt\">need 的用法</div><div class=\"gb\"><p class=\"source-line\">（1）need 作情态动词,意为“需要”,与动词原形搭配使用。need 可用于肯定句、否定句和疑问句中,否定缩写形式为 needn't,意为“不需要,不必”。以 need 开头的一般疑问句的肯定回答用 must,否定回答用 needn't。</p>\n<p class=\"source-line\">You need only call her. 你只需给她打电话。</p>\n<p class=\"source-line\">You needn't call her. 你不必给她打电话。</p>\n<p class=\"source-line\">—— Need I call her? 我有必要给她打电话吗？</p>\n<p class=\"source-line\">—— Yes, you must. 是的，你必须。</p>\n<p class=\"source-line\">—— No, you needn't. 不，你不必。</p>\n<p class=\"source-line\">（2）need 作实义动词,意为“需要”,有人称和时态等变化。</p>\n<p class=\"source-line\">（1）need sth. 意为“需要某物”。</p>\n<p class=\"source-line\">All living things need water. 所有生物都需要水。</p>\n<p class=\"source-line\">I need some bread and water. 我需要一些面包和水。</p>\n<p class=\"source-line\">（2）need to do sth. 意为“需要做某事”。</p>\n<p class=\"source-line\">He needs to get some sleep. 他需要睡一会儿。</p>\n<p class=\"source-line\">You need to clean the floor. 你需要擦地板。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s40-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">You <span class=\"blank-token\">____</span> play football on the road, because there are many cars.</p>","options":["mustn't","must"],"correct":0,"answer":"A\n解析：根据安全意识和后一句可知 “你禁止在马路上踢足球”,故选 mustn't。"},{"id":"s40-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">The rabbit can <span class=\"blank-token\">____</span> .</p>","options":["jump","jumping"],"correct":0,"answer":"A"},{"id":"s40-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">This old man <span class=\"blank-token\">____</span> sit down. A kind boy helps him.</p>","options":["can't","can"],"correct":0,"answer":"A\n解析：后一句意为 “一个善良的男孩儿帮助他”。可以推断那位老人不能坐下, 故选 can't。"},{"id":"s40-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> play near the fire.</p>","options":["mustn't","needn't"],"correct":0,"answer":"A"},{"id":"s40-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I can't sing, but I <span class=\"blank-token\">____</span> dance.</p>","options":["can't","can"],"correct":1,"answer":"B\n解析：but 表示转折, 前否后肯, 故选 can。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【沈阳·和平区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s40-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> walk on the grass in the park.</p>","options":["must","can","mustn't"],"correct":2,"answer":"C"},{"id":"s40-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Mum, can I watch TV?<br/><br>\n—— No, you can't. It's too late. You <span class=\"blank-token\">____</span> go to bed.</br></p>","options":["must","can","can't"],"correct":0,"answer":"A\n解析：根据题意“太晚了,你____去睡觉”,must意为“必须”,符合题意,故选must。"},{"id":"s40-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can you play the violin?<br/><br>\n—— No, I <span class=\"blank-token\"><strong><em>_</em></strong></span>, but I <span class=\"blank-token\">_</span> play the piano.</br></p>","options":["can; can","can't; can't","can't; can"],"correct":2,"answer":"C\n解析：“Can you ...?” 的否定回答通常为 “No, I / we can’t.”, 故第一个空选 can’t。but 表示转折, 故第二个空选 can。"},{"id":"s40-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Must I clean the floor now?<br/><br>\n—— No, you <span class=\"blank-token\">____</span>.</br></p>","options":["mustn't","needn't","can't"],"correct":1,"answer":"B\n解析：must 开头的一般疑问句的否定回答为“No, 主语 + needn't.”, 故选 B。"},{"id":"s40-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">You <span class=\"blank-token\">____</span> be late for school again.</p>","options":["mustn't","needn't","don't"],"correct":0,"answer":"A\n解析：根据题意 “你不能再上学迟到了” 可知 mustn’t 符合题意,故选 A。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s40-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What do you <span class=\"blank-token\"><strong><em>_</em></strong></span>?<br/><br>\n—— I <span class=\"blank-token\">_</span> have a rest. I'm tired.</br></p>","options":["must; need","can't; mustn't","need to; need","need; need to / must"],"correct":3,"answer":"D"},{"id":"s40-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> I stay at home on Sunday?<br/><br>\n—— Yes, you <span class=\"blank-token\">_</span>. It's going to rain on Sunday.</br></p>","options":["Can't; need","Mustn't; must","Must; must","Need; can't"],"correct":2,"answer":"C"},{"id":"s40-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> go to the supermarket now. We haven't got enough tomatoes.</p>","options":["mustn't","need to","must","need","can't"],"correct":2,"answer":"C"},{"id":"s40-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can you swim?<br/><br>\n—— No, I <span class=\"blank-token\">____</span>.</br></p>","options":["need to","can't","must","need","mustn't"],"correct":1,"answer":"B"},{"id":"s40-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">In the forest, we <span class=\"blank-token\">____</span> smoke. It's dangerous.</p>","options":["mustn't","must","can't","need","need to"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 按要求完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s40-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Alex needs a lot of oranges. (改为一般疑问句, 并作肯定和否定回答)</p>","options":[],"correct":null,"answer":"Does Alex need a lot of oranges?\nYes, he does.\nNo, he doesn't."},{"id":"s40-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">We must come home at ten o'clock. (改为一般疑问句, 并作肯定和否定回答)</p>","options":[],"correct":null,"answer":"Must we come home at ten o'clock?\nYes, we must.\nNo, we needn't."}],"questionCount":2,"hasAnswers":true}]},{"id":"s41","section":41,"unit":7,"unitName":"单元07 · 第37–42节","short":"第41节 · L81–82","title":"实义动词 have 的用法","lessons":"Lesson 81 — Lesson 82","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>实义动词 have 的用法</td>\n<td>实义动词 have 的用法</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>实义动词 have 的用法</td>\n<td>实义动词 have 与不同人称代词搭配的形式</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">实义动词 have 的用法</div><div class=\"gb\"><p class=\"source-line\">（1）have 作实义动词,意为“有”,表示所属关系。</p>\n<p class=\"source-line\">I have a pen. 我有一支钢笔。</p>\n<p class=\"source-line\">Michael has a new soccer ball.</p>\n<p class=\"source-line\">迈克尔有一个新足球。</p>\n<p class=\"source-line\">（2）have 可表示“组织；举办”。</p>\n<p class=\"source-line\">have a football match</p>\n<p class=\"source-line\">举行足球比赛</p>\n<p class=\"source-line\">have a meeting 开会</p>\n<p class=\"source-line\">have a party 举办聚会</p>\n<p class=\"source-line\">（3）have 可表示“进行（活动）”。</p>\n<p class=\"source-line\">have a walk 散步</p>\n<p class=\"source-line\">have a swim 游泳</p>\n<p class=\"source-line\">have a wash 洗一下</p>\n<p class=\"source-line\">have a shower 冲淋浴</p>\n<p class=\"source-line\">have a rest 休息一会儿</p>\n<p class=\"source-line\">have a bath 洗澡</p>\n<p class=\"source-line\">（4）have 可表示“患病；得病”。</p>\n<p class=\"source-line\">have a cold 感冒</p>\n<p class=\"source-line\">have a toothache 牙疼</p>\n<p class=\"source-line\">have a fever 发烧</p>\n<p class=\"source-line\">have a sore throat 嗓子疼</p>\n<p class=\"source-line\">have a headache 头痛</p>\n<p class=\"source-line\">have a stomachache 胃痛；肚子痛</p>\n<p class=\"source-line\">（5）have 可表示“吃；喝”。</p>\n<p class=\"source-line\">have breakfast / lunch / dinner 吃早饭 / 午饭 / 晚饭</p>\n<p class=\"source-line\">have a cup of coffee 喝一杯咖啡</p>\n<p class=\"source-line\">have a meal 吃一顿饭</p>\n<p class=\"source-line\">（6）have 表示“生；生产”。</p>\n<p class=\"source-line\">She's going to have a baby. 她快生孩子了。</p></div></div>\n<div class=\"g\"><div class=\"gt\">实义动词 have 与不同人称代词搭配的形式</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>主语</th>\n<th>I</th>\n<th>you</th>\n<th>he</th>\n<th>she</th>\n<th>it</th>\n<th>we</th>\n<th>you</th>\n<th>they</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>have 的形式</td>\n<td>have</td>\n<td>have</td>\n<td>has</td>\n<td>has</td>\n<td>has</td>\n<td>have</td>\n<td>have</td>\n<td>have</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">动词 have 表示“有”，通常位于主语之后；第三人称单数用 has，其他人称用 have。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【滁州·南谯区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s41-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How was your weekend?<br/><br>\n—— Great! We <span class=\"blank-token\">____</span> a picnic by the lake.</br></p>","options":["have","are having","had"],"correct":2,"answer":"C\n解析：问句意为 “你的周末过得怎么样?”,由此可知答语的时态是一般过去时, have 的过去式为 had。"},{"id":"s41-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What are you doing, Carol?<br/><br>\n—— I <span class=\"blank-token\">____</span> dinner with my friends.</br></p>","options":["have","had","am having"],"correct":2,"answer":"C\n解析：由问句可知答语的时态为现在进行时,“am / is / are + 动词 -ing 形式”是现在进行时的标志。主语为 I, be 用 am, have 的 -ing 形式为 having。"},{"id":"s41-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What did you have for lunch at the restaurant?<br/><br>\n—— We <span class=\"blank-token\">____</span> roast beef and tomatoes.</br></p>","options":["have had","had","had had"],"correct":1,"answer":"B"},{"id":"s41-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Please <span class=\"blank-token\">____</span> a rest outside the room. It is too windy.</p>","options":["don't have","not have","don't has"],"correct":0,"answer":"A\n解析：此句是一个祈使句, 意为 “请____在房间外面休息, 风太大了”, have a rest (休息) 为固定搭配。根据句意可知此句为否定祈使句, 助动词应用 don't, have 用原形。故此题选择 A 选项。"},{"id":"s41-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Jenny <span class=\"blank-token\">____</span> lunch at home today, because her mother was out.</p>","options":["haven't","not","didn't have"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【合肥·庐阳区】连词成句。(注意字母大小写)。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s41-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">have, can't, dinner, seven, we, at, o'clock( . )</p>","options":[],"correct":null,"answer":"We can't have dinner at seven o'clock."},{"id":"s41-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">will, have, what, we(?)</p>","options":[],"correct":null,"answer":"What will we have?"},{"id":"s41-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">we, going to, potatoes and beef, have, are, today ( . )</p>","options":[],"correct":null,"answer":"We are going to have potatoes and beef today."},{"id":"s41-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">the, long, monkey, has, arms ( . )</p>","options":[],"correct":null,"answer":"The monkey has long arms."},{"id":"s41-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">girl, milk and bread, has, the, for, dinner ( . )</p>","options":[],"correct":null,"answer":"The girl has milk and bread for dinner."}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 用 have 的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s41-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">When can we <span class=\"blank-token\">____</span> dinner?</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Sophie and I <span class=\"blank-token\">____</span> lunch at school every day.</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">My father <span class=\"blank-token\">____</span> an egg and some milk for breakfast yesterday.</p>","options":[],"correct":null,"answer":"had"},{"id":"s41-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">The children <span class=\"blank-token\">____</span> a good time yesterday evening.</p>","options":[],"correct":null,"answer":"had"},{"id":"s41-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Must my little sister <span class=\"blank-token\">____</span> a haircut today?</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">—— It's noisy. What are you doing?<br/><br>\n—— We are <span class=\"blank-token\">____</span> a birthday party.</br></p>","options":[],"correct":null,"answer":"having"},{"id":"s41-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My mother <span class=\"blank-token\">____</span> a beautiful watch.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">The little baby <span class=\"blank-token\">____</span> no teeth.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Does it <span class=\"blank-token\">____</span> a short tail?</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">The robot <span class=\"blank-token\">____</span> two hands.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> some eggs and milk.</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">The monkey <span class=\"blank-token\">____</span> two long arms.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">Jim <span class=\"blank-token\">____</span> some coffee for breakfast.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">Ben and his brother <span class=\"blank-token\">____</span> many stickers.</p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">Their parents <span class=\"blank-token\">____</span> many friends.</p>","options":[],"correct":null,"answer":"have"}],"questionCount":15,"hasAnswers":true},{"source":"textbook","title":"II. 根据汉语意思把句子补充完整。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s41-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">—— 你有什么？——我有一些蛋糕。<br/><br>\n—— What do you <span class=\"blank-token\"><strong><em>_</em></strong></span>?<br/><br>\n—— I <span class=\"blank-token\">_</span> some cake.</br></br></p>","options":[],"correct":null,"answer":"have, have"},{"id":"s41-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">—— 你有一些香蕉吗？——不，我没有。<br/><br>\n—— Do you <span class=\"blank-token\">____</span> any bananas?<br/><br>\n—— No, I don't.</br></br></p>","options":[],"correct":null,"answer":"have"},{"id":"s41-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">杨玲有两个苹果。我有一个橙子。<br/>\nYang Ling <span class=\"blank-token\"><strong><em>_</em></strong></span> two apples. I <span class=\"blank-token\">_</span> an orange.</p>","options":[],"correct":null,"answer":"has, have"},{"id":"s41-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">看！迈克有一顶白色的帽子。<br/>\nLook! Mike <span class=\"blank-token\">____</span> a white cap.</p>","options":[],"correct":null,"answer":"has"},{"id":"s41-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">我的朋友们有一个足球。<br/>\nMy friends <span class=\"blank-token\">____</span> a football.</p>","options":[],"correct":null,"answer":"have"}],"questionCount":5,"hasAnswers":true}]},{"id":"s42","section":42,"unit":7,"unitName":"单元07 · 第37–42节","short":"第42节 · L83–84","title":"现在完成时（一）","lessons":"Lesson 83 — Lesson 84","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在完成时</td>\n<td>现在完成时的概念</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在完成时</td>\n<td>现在完成时的结构</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在完成时</td>\n<td>现在完成时的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">现在完成时的概念</div><div class=\"gb\"><p class=\"source-line\">现在完成时表示一件已发生的事,这件事往往与现在的情况有联系,还可表示持续到现在的状态。</p>\n<p class=\"source-line\">I have been here for an hour.</p>\n<p class=\"source-line\">我已经在这儿待了一个小时。</p>\n<p class=\"source-line\">She has already finished her homework.</p>\n<p class=\"source-line\">她已经完成她的家庭作业了。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在完成时的结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定句: 主语 + have / has + 过去分词（+其他）.</p>\n<p class=\"source-line\">The boy has broken the window. 这个男孩儿把窗户打破了。</p>\n<p class=\"source-line\">He has left the city. 他已经离开这个城市了。</p>\n<p class=\"source-line\">（2）否定句: 主语 + have / has not + 过去分词（+其他）.</p>\n<p class=\"source-line\">I haven't read the book. 我还没有读那本书。</p>\n<p class=\"source-line\">You haven't finished it yet. 你还没有完成它。</p>\n<p class=\"source-line\">（3）一般疑问句: Have / Has + 主语 + 过去分词（+其他）?</p>\n<p class=\"source-line\">肯定回答: Yes, 主语 + have / has.</p>\n<p class=\"source-line\">否定回答: No, 主语 + haven't / hasn't.</p>\n<p class=\"source-line\">—— Have you seen my key? 你看见我的钥匙了吗？</p>\n<p class=\"source-line\">—— Yes, I have. 是的,我看见了。</p>\n<p class=\"source-line\">—— No, I haven't. 不,我没看见。</p>\n<p class=\"source-line\">—— Has he gone home? 他回家了吗？</p>\n<p class=\"source-line\">—— Yes, he has. 是的，他回家了。</p>\n<p class=\"source-line\">—— No, he hasn't. 不，他没回家。</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + have / has + 主语 + 过去分词（+其他）?</p>\n<p class=\"source-line\">What have you got? 你得到了什么？</p>\n<p class=\"source-line\">Where have you been? 你去哪儿了？</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在完成时的用法</div><div class=\"gb\"><p class=\"source-line\">（1）表示过去的动作（现在已结束）对现在所造成的影响,常与 already、yet、just、ever 等词连用。</p>\n<p class=\"source-line\">I haven't received a letter from him yet. 我还没有收到他的信。</p>\n<p class=\"source-line\">Have you ever been to America? 你曾经去过美国吗？</p>\n<p class=\"source-line\">（2）表示过去的动作一直持续到现在,并可能继续持续下去,常与 since、for 等词连用。</p>\n<p class=\"source-line\">It has been 3 years since he went to university. 他已经上 3 年大学了。</p>\n<p class=\"source-line\">Lucy has studied Chinese for 8 years. 露西已经学 8 年汉语了。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·三水区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s42-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> the project by ourselves so far.</p>","options":["finish","will finish","have finished"],"correct":2,"answer":"C"},{"id":"s42-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Where is your father, John?<br/><br>\n—— Oh, he <span class=\"blank-token\">____</span> Beijing on business and he'll come back next week.</br></p>","options":["has been to","has gone to","has returned from"],"correct":1,"answer":"B\n解析：根据题意可知 John 的爸爸去了北京,还没回来,故选 B。"},{"id":"s42-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">My uncle <span class=\"blank-token\">____</span> a new house already.</p>","options":["has bought","have bought","buy"],"correct":0,"answer":"A\n解析：时态为现在完成时,主语 my uncle(我叔叔)是第三人称单数,故选 A。"},{"id":"s42-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you ever <span class=\"blank-token\">_</span> to Shanghai?<br/><br>\n—— Yes, twice.</br></p>","options":["Have ; go","Have ; been","Did ; go"],"correct":1,"answer":"B\n解析：时态为现在完成时,表示某人去过某地已经回来,故选 B。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【天津·东丽区】句型转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s42-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">She has already come home. (改为否定句)</p>","options":[],"correct":null,"answer":"She hasn't come home yet."},{"id":"s42-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">She has been there <u>twice</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"How many times has she been there?"},{"id":"s42-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">I have had lunch <u>at school</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"Where have you had lunch?"},{"id":"s42-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I have been to <u>Australia</u>. (对画线部分提问)</p>","options":[],"correct":null,"answer":"Where have you been?"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s42-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Have you ever <span class=\"blank-token\">____</span> (take) a train?</p>","options":[],"correct":null,"answer":"taken"},{"id":"s42-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Have they <span class=\"blank-token\">____</span> (have) any tea or coffee?</p>","options":[],"correct":null,"answer":"had"},{"id":"s42-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Have you <span class=\"blank-token\">____</span> (make) friends with your new classmates yet?</p>","options":[],"correct":null,"answer":"made"},{"id":"s42-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">I have <span class=\"blank-token\">____</span> (have) my lunch and I'm not hungry now.</p>","options":[],"correct":null,"answer":"had"},{"id":"s42-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (have) just had some peaches.</p>","options":[],"correct":null,"answer":"have"},{"id":"s42-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">We have <span class=\"blank-token\">____</span> (be) good friends since we met at school.</p>","options":[],"correct":null,"answer":"been"},{"id":"s42-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">We can't find him anywhere. Perhaps he has <span class=\"blank-token\">____</span> (go) home.</p>","options":[],"correct":null,"answer":"gone"},{"id":"s42-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> (have) read the book before.</p>","options":[],"correct":null,"answer":"has"},{"id":"s42-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Mr. Green has <span class=\"blank-token\">____</span> (teach) us a lot about social studies since September.</p>","options":[],"correct":null,"answer":"taught"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s42-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> about folk music yet?<br/><br>\n—— Yes, I have.</br></p>","options":["Has ; heard","Have ; heard","Did ; hear","Do ; hear"],"correct":1,"answer":"B"},{"id":"s42-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">Great news! I <span class=\"blank-token\">____</span> the English exam.</p>","options":["passing","am passing","have passed","will pass"],"correct":2,"answer":"C"},{"id":"s42-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">You don't need to talk to Mr. Wang. I <span class=\"blank-token\">____</span> him everything already.</p>","options":["will tell","am telling","have told","told"],"correct":2,"answer":"C"},{"id":"s42-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Lucy, why are you still here? School is over.<br/><br>\n—— I <span class=\"blank-token\">____</span> my classroom yet.</br></p>","options":["don't clean","haven't cleaned","didn't clean","won't clean"],"correct":1,"answer":"B"},{"id":"s42-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\"><strong><em>_</em></strong></span> our English teacher since he <span class=\"blank-token\">_</span> to America.</p>","options":["haven't heard from; returned","didn't hear from; returned","didn't hear from; returns","haven't heard from; returns"],"correct":0,"answer":"A"},{"id":"s42-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">I ate some fruit, which I <span class=\"blank-token\">____</span> since I was a child, and the vegetables from my garden.</p>","options":["have enjoyed","enjoyed","enjoy","had enjoyed"],"correct":0,"answer":"A"},{"id":"s42-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> your homework yet?<br/><br>\n—— Yes, I've just finished it.</br></p>","options":["Did ; finish","Do ; finish","Will ; finish","Have ; finished"],"correct":3,"answer":"D"}],"questionCount":7,"hasAnswers":true}]},{"id":"s43","section":43,"unit":8,"unitName":"单元08 · 第43–48节","short":"第43节 · L85–86","title":"一般过去时与现在完成时的区别","lessons":"Lesson 85 — Lesson 86","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般过去时与现在完成时的区别</td>\n<td>一般过去时</td>\n<td>★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般过去时与现在完成时的区别</td>\n<td>现在完成时</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般过去时与现在完成时的区别</td>\n<td>现在完成时和一般过去时的区别</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般过去时</div><div class=\"gb\"><p class=\"source-line\">（1）含义: 表示过去某个时间发生的动作或存在的状态。</p>\n<p class=\"source-line\">（2）肯定句结构：</p>\n<ul>\n<li>主语 + be 动词（was / were）+ 其他。</li>\n<li>主语 + 实义动词过去式 + 其他。</li>\n</ul>\n<h5>用法</h5>\n<p class=\"source-line\">（1）表示在过去时间里发生的动作或存在的状态,常与表示过去的时间状语 yesterday、last week 等连用。</p>\n<p class=\"source-line\">Mike was very sick yesterday. 迈克昨天病得很严重。</p>\n<p class=\"source-line\">She wrote many letters.</p>\n<p class=\"source-line\">她写了很多信。</p>\n<p class=\"source-line\">（2）表示在过去一段时间里经常性或习惯性的动作或状态。</p>\n<p class=\"source-line\">I played football every morning then.</p>\n<p class=\"source-line\">我那时每天早上踢足球。</p>\n<p class=\"source-line\">He usually got up at six last month.</p>\n<p class=\"source-line\">他上个月通常6:00起床。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在完成时</div><div class=\"gb\"><p class=\"source-line\">（1）含义: 表示一件已发生的事,这件事往往与现在的情况有联系,还可以表示持续到现在的状态。</p>\n<p class=\"source-line\">（2）肯定句结构: 主语 + have / has + 过去分词（+其他）.</p>\n<p class=\"source-line\">（3）用法</p>\n<p class=\"source-line\">（1）表示过去的动作(现在已结束)对现在的影响,常与 already、just、yet、ever 等连用。</p>\n<p class=\"source-line\">I have just read the book. 我刚刚读了这本书。</p>\n<p class=\"source-line\">He has already phoned me about the thief.</p>\n<p class=\"source-line\">他已经给我打电话说过有关那个小偷(的事)了。</p>\n<p class=\"source-line\">（2）表示过去的动作一直持续到现在,并可能继续持续下去,常与 since、for 等连用。</p>\n<p class=\"source-line\">So far he has done very well at school.</p>\n<p class=\"source-line\">到现在为止，他在学校表现得很好。</p>\n<p class=\"source-line\">She has been ill since last Sunday.</p>\n<p class=\"source-line\">她从上个星期日开始一直生病。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在完成时和一般过去时的区别</div><div class=\"gb\"><p class=\"source-line\">现在完成时【have / has done】</p>\n<p class=\"source-line\">强调动作已完成且对现在造成影响。</p>\n<p class=\"source-line\">I have just eaten a hamburger. I'm full. 我刚刚吃过一个汉堡。我饱了。</p>\n<p class=\"source-line\">强调过去吃的，现在饱了，不想再吃了。</p>\n<p class=\"source-line\">一般过去时【did】</p>\n<p class=\"source-line\">强调发生在过去的动作，与现在没有联系。</p>\n<p class=\"source-line\">I ate a hamburger just now. 我刚才吃了一个汉堡。</p>\n<p class=\"source-line\">强调过去吃的，现在还想不想吃暂未可知。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·官渡区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s43-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> (shut) the window 10 minutes ago.</p>","options":[],"correct":null,"answer":"shut\n解析：由 10 minutes ago (10 分钟前) 可知句子时态为一般过去时。shut (关) 的过去式与原形一致,故此空填 shut。"},{"id":"s43-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (live) here since 2000.</p>","options":[],"correct":null,"answer":"have lived\n解析：由 since 2000（自 2000 年以来）可知句子时态为现在完成时,故此空填 have lived。"},{"id":"s43-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> (swim) across the river the day before yesterday.</p>","options":[],"correct":null,"answer":"swam"},{"id":"s43-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">My father <span class=\"blank-token\">____</span> (paint) this room white last week.</p>","options":[],"correct":null,"answer":"painted"},{"id":"s43-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\"><strong><em>_</em></strong></span> (have) already <span class=\"blank-token\">_</span> (have) lunch. She is full.</p>","options":[],"correct":null,"answer":"has, had"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【佛山·禅城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s43-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> many great changes in my hometown since ten years ago.</p>","options":["were","have","are","have been"],"correct":3,"answer":"D\n解析：由 since ten years ago (自 10 年前以来) 可知句子时态为现在完成时。主语 many great changes (许多巨大的变化) 为第三人称复数,故此题选择 D 选项。"},{"id":"s43-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Are you going to see the film with us?<br/><br>\n—— No, thanks. I <span class=\"blank-token\">____</span> it.</br></p>","options":["saw","have seen","see","was seeing"],"correct":1,"answer":"B"},{"id":"s43-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\"><strong><em>_</em></strong></span> trees last Sunday. So far we <span class=\"blank-token\">_</span> over 3,000 trees there.</p>","options":["planted; planted","planted; have planted","have planted; planted","have planted; have planted"],"correct":1,"answer":"B"},{"id":"s43-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Where <span class=\"blank-token\"><strong><em>_</em></strong></span> the recorder? I can't see it anywhere.<br/><br>\n—— I <span class=\"blank-token\">_</span> it right here just now. But now it's gone!</br></p>","options":["did you put; have put","have you put; put","had you put; was putting","did you put; had put"],"correct":1,"answer":"B\n解析：由 “I can't see it anywhere. (我到处都看不见它。)” 可知前一句的时态为现在完成时,故选 have you put。just now (刚才)为表示过去的时间状语,故答语时态用一般过去时,put 的过去式与原形一致。故此题选择 B 选项。"},{"id":"s43-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Jim's father <span class=\"blank-token\"><strong><em>_</em></strong></span> to London last month. He <span class=\"blank-token\">_</span> there three times.</p>","options":["went; has gone","has gone; has been","went; has been","has been; has gone"],"correct":2,"answer":"C\n解析：由 last month (上个月) 可知第一个句子的时态为一般过去时。根据 three times (3 次) 可知他去过 3 次, has been 意为 “去过”, 故此题选择 C 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s43-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (see) Tom last Friday.</p>","options":[],"correct":null,"answer":"saw"},{"id":"s43-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Did you <span class=\"blank-token\">____</span> (go) to the Great Wall last summer?</p>","options":[],"correct":null,"answer":"go"},{"id":"s43-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">When did you <span class=\"blank-token\">____</span> (start) to live in China?</p>","options":[],"correct":null,"answer":"start"},{"id":"s43-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">The train <span class=\"blank-token\">____</span> (leave) already.</p>","options":[],"correct":null,"answer":"has left"},{"id":"s43-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (lose) my pen. I have to write with a pencil.</p>","options":[],"correct":null,"answer":"have lost"},{"id":"s43-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> (visit) the Great Wall last year.</p>","options":[],"correct":null,"answer":"visited"},{"id":"s43-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (have) a good time yesterday.</p>","options":[],"correct":null,"answer":"had"},{"id":"s43-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (live) in the village when I was a child.</p>","options":[],"correct":null,"answer":"lived"},{"id":"s43-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Miss Lin <span class=\"blank-token\">____</span> (do) a lot of work for the poor since 2010.</p>","options":[],"correct":null,"answer":"has done"},{"id":"s43-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Up to now, the computer <span class=\"blank-token\">____</span> (bring) us great changes in our life.</p>","options":[],"correct":null,"answer":"has brought"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s43-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">My father <span class=\"blank-token\"><strong><em>_</em></strong></span> here since he <span class=\"blank-token\">_</span> to this school.</p>","options":["taught; came","has taught; came","taught; has come","has taught; has come"],"correct":1,"answer":"B"},{"id":"s43-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">I am sorry you've missed the train. It <span class=\"blank-token\">____</span> 10 minutes ago.</p>","options":["left","has left","has been left","had left"],"correct":0,"answer":"A"},{"id":"s43-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Hi! Jim! Nice to meet you again! It's one year since I last <span class=\"blank-token\">____</span> you.</p>","options":["saw","see","seeing","have seen"],"correct":0,"answer":"A"},{"id":"s43-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">Her grandfather <span class=\"blank-token\"><strong><em>_</em></strong></span> a car in 2007. He <span class=\"blank-token\">_</span> the car for 10 years.</p>","options":["buys; has bought","bought; has had","buys; has had","bought; has bought"],"correct":1,"answer":"B"},{"id":"s43-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">My brother <span class=\"blank-token\"><strong><em>_</em></strong></span> the league three years ago. He <span class=\"blank-token\">_</span> a league member for three years.</p>","options":["joined; has been","has joined; has been","was joined; is","joined; was"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"III. 按要求完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s43-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">I've already read it twice. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Have you read it twice yet?"},{"id":"s43-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">I ate a packet of biscuits just now. (用 just 改写同义句)</p>","options":[],"correct":null,"answer":"I have just eaten a packet of biscuits."},{"id":"s43-text-q018","number":18,"type":"input","questionHtml":"<p class=\"source-line\">I have already taken my temperature. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Have you taken your temperature yet?"},{"id":"s43-text-q019","number":19,"type":"input","questionHtml":"<p class=\"source-line\">I have already started eating. (改为否定句)</p>","options":[],"correct":null,"answer":"I haven't started eating yet."},{"id":"s43-text-q020","number":20,"type":"input","questionHtml":"<p class=\"source-line\">Lily has already done her homework. (改为一般疑问句, 并作否定回答)</p>","options":[],"correct":null,"answer":"Has Lily done her homework yet?\nNo, she hasn't."}],"questionCount":5,"hasAnswers":true}]},{"id":"s44","section":44,"unit":8,"unitName":"单元08 · 第43–48节","short":"第44节 · L87–88","title":"动词的过去分词","lessons":"Lesson 87 — Lesson 88","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>动词的过去分词</td>\n<td>动词过去分词的规则变化</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>动词的过去分词</td>\n<td>动词过去分词的不规则变化</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">动词过去分词的规则变化</div><div class=\"gb\"><p class=\"source-line\">（1）一般情况下,在词尾加 ed。</p>\n<p class=\"source-line\">look—looked 看</p>\n<p class=\"source-line\">talk—talked 讲话</p>\n<p class=\"source-line\">ask—asked 问</p>\n<p class=\"source-line\">play—played 玩</p>\n<p class=\"source-line\">（2）以不发音的 e 结尾的动词,在词尾加 d。</p>\n<p class=\"source-line\">live—lived 生存</p>\n<p class=\"source-line\">taste—tasted 尝</p>\n<p class=\"source-line\">move—moved 移动</p>\n<p class=\"source-line\">like—liked 喜欢</p>\n<p class=\"source-line\">（3）以“辅音字母+y”结尾的动词,变 y 为 i,再加 ed。</p>\n<p class=\"source-line\">carry—carried 携带</p>\n<p class=\"source-line\">study—studied 学习</p>\n<p class=\"source-line\">copy—copied 抄写</p>\n<p class=\"source-line\">try—tried 试</p>\n<p class=\"source-line\">（4）以重读闭音节结尾,末尾只有一个辅音字母的动词,双写这个辅音字母,再加 ed。</p>\n<p class=\"source-line\">stop—stopped 停止</p>\n<p class=\"source-line\">plan—planned 计划</p>\n<p class=\"source-line\">chat—chatted 聊天</p>\n<p class=\"source-line\">drop—dropped 掉下</p></div></div>\n<div class=\"g\"><div class=\"gt\">动词过去分词的不规则变化</div><div class=\"gb\"><h5>1. AAA型(动词的原形、过去式和过去分词一样)</h5>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>原形</th>\n<th>过去式</th>\n<th>过去分词</th>\n<th>汉语意思</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>cut</td>\n<td>cut</td>\n<td>cut</td>\n<td>切</td>\n</tr>\n<tr>\n<td>let</td>\n<td>let</td>\n<td>let</td>\n<td>让</td>\n</tr>\n<tr>\n<td>hurt</td>\n<td>hurt</td>\n<td>hurt</td>\n<td>受伤</td>\n</tr>\n<tr>\n<td>put</td>\n<td>put</td>\n<td>put</td>\n<td>放</td>\n</tr>\n<tr>\n<td>set</td>\n<td>set</td>\n<td>set</td>\n<td>放</td>\n</tr>\n</tbody>\n</table></div>\n<h5>2. ABB型(动词的过去式和过去分词一样)</h5>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>原形</th>\n<th>过去式</th>\n<th>过去分词</th>\n<th>汉语意思</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>send</td>\n<td>sent</td>\n<td>sent</td>\n<td>邮寄</td>\n</tr>\n<tr>\n<td>bring</td>\n<td>brought</td>\n<td>brought</td>\n<td>带来</td>\n</tr>\n<tr>\n<td>buy</td>\n<td>bought</td>\n<td>bought</td>\n<td>购买</td>\n</tr>\n<tr>\n<td>spend</td>\n<td>spent</td>\n<td>spent</td>\n<td>度过;花费</td>\n</tr>\n<tr>\n<td>think</td>\n<td>thought</td>\n<td>thought</td>\n<td>认为</td>\n</tr>\n</tbody>\n</table></div>\n<h5>3. ABA型(动词的原形和过去分词一样)</h5>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>原形</th>\n<th>过去式</th>\n<th>过去分词</th>\n<th>汉语意思</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>come</td>\n<td>came</td>\n<td>come</td>\n<td>来</td>\n</tr>\n<tr>\n<td>run</td>\n<td>ran</td>\n<td>run</td>\n<td>跑</td>\n</tr>\n<tr>\n<td>become</td>\n<td>became</td>\n<td>become</td>\n<td>变成</td>\n</tr>\n</tbody>\n</table></div>\n<h5>4. ABC型(动词的原形、过去式和过去分词都不一样)</h5>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>原形</th>\n<th>过去式</th>\n<th>过去分词</th>\n<th>汉语意思</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>begin</td>\n<td>began</td>\n<td>begun</td>\n<td>开始</td>\n</tr>\n<tr>\n<td>draw</td>\n<td>drew</td>\n<td>drawn</td>\n<td>画</td>\n</tr>\n<tr>\n<td>break</td>\n<td>broke</td>\n<td>broken</td>\n<td>弄破</td>\n</tr>\n<tr>\n<td>know</td>\n<td>knew</td>\n<td>known</td>\n<td>知道</td>\n</tr>\n<tr>\n<td>wear</td>\n<td>wore</td>\n<td>worn</td>\n<td>穿</td>\n</tr>\n</tbody>\n</table></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·红桥区】写出下列动词的过去分词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s44-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">work</p>","options":[],"correct":null,"answer":"worked"},{"id":"s44-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">live</p>","options":[],"correct":null,"answer":"lived"},{"id":"s44-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">sit</p>","options":[],"correct":null,"answer":"sat"},{"id":"s44-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">dance</p>","options":[],"correct":null,"answer":"danced"},{"id":"s44-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">lie</p>","options":[],"correct":null,"answer":"lied（说谎）/ lain（躺）"},{"id":"s44-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">ask</p>","options":[],"correct":null,"answer":"asked"},{"id":"s44-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">climb</p>","options":[],"correct":null,"answer":"climbed"},{"id":"s44-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">die</p>","options":[],"correct":null,"answer":"died"}],"questionCount":8,"hasAnswers":true},{"source":"practice","title":"【合肥·包河区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s44-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> (write) a letter to your brother yet?</p>","options":[],"correct":null,"answer":"Have, written\n解析：根据题意可知此题为现在完成时的一般疑问句,主语是第二人称 you(你;你们),故填写 Have, written。"},{"id":"s44-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> (not read) the interesting books yet.</p>","options":[],"correct":null,"answer":"haven't read\n解析：根据题意可知此题为现在完成时的否定句,故填写 haven't read。"},{"id":"s44-practice-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> he <span class=\"blank-token\">_</span> (finish) his homework?<br/><br>\n—— Not yet.</br></p>","options":[],"correct":null,"answer":"Has, finished\n解析：根据题意可知此题为现在完成时的一般疑问句, 主语是第三人称单数 he (他), 故填写 Has, finished。"},{"id":"s44-practice-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">Miss White <span class=\"blank-token\">____</span> (teach) us English for four years.</p>","options":[],"correct":null,"answer":"has taught\n解析：根据题意可知此题的时态为现在完成时,主语 Miss White (怀特老师)是第三人称单数,故填写 has taught。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 写出下列动词的过去分词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s44-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">run —</p>","options":[],"correct":null,"answer":"run"},{"id":"s44-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">become —</p>","options":[],"correct":null,"answer":"become"},{"id":"s44-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">begin —</p>","options":[],"correct":null,"answer":"begun"},{"id":"s44-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">sing：<span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"sung"},{"id":"s44-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">swim —</p>","options":[],"correct":null,"answer":"swum"},{"id":"s44-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">buy：<span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"bought"}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"II. 用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s44-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">I haven't <span class=\"blank-token\">____</span> (receive) a letter from Sally.</p>","options":[],"correct":null,"answer":"received"},{"id":"s44-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I'm very hungry. I haven't <span class=\"blank-token\">____</span> (eat) anything since 7:00 this morning.</p>","options":[],"correct":null,"answer":"eaten"},{"id":"s44-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Bob and Jim have <span class=\"blank-token\">____</span> (be) good friends since they joined the same tennis team.</p>","options":[],"correct":null,"answer":"been"},{"id":"s44-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">—— I <span class=\"blank-token\">____</span> (have) a fever since last night.<br/><br>\n—— You'd better go to see a doctor.</br></p>","options":[],"correct":null,"answer":"have had"},{"id":"s44-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">The couple <span class=\"blank-token\">____</span> (not change) their flat since they had a second child.</p>","options":[],"correct":null,"answer":"have not changed"}],"questionCount":5,"hasAnswers":true}]},{"id":"s45","section":45,"unit":8,"unitName":"单元08 · 第43–48节","short":"第45节 · L89–90","title":"现在完成时的时间状语","lessons":"Lesson 89 — Lesson 90","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在完成时的时间状语</td>\n<td>现在完成时的时间状语</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">现在完成时的时间状语</div><div class=\"gb\"><p class=\"source-line\">要表达某个动作或状态从过去某时开始,一直持续到现在时,需要加上一个和现在有关的表示一段时间的时间状语,即现在完成时的时间状语。</p>\n<p class=\"source-line\">（1）“for + 一段时间”表示持续的时间。</p>\n<p class=\"source-line\">（1）结构: for a / an / one + 表示时间名词的单数</p>\n<p class=\"source-line\">for a week (持续)一周了\nfor one month (持续)一个月了</p>\n<p class=\"source-line\">for a year (持续)一年了\nfor an hour (持续)一个小时了</p>\n<p class=\"source-line\">（2）结构: for + 数词 + 时间名词的复数</p>\n<p class=\"source-line\">for five weeks (持续)5个星期了\nfor ten years (持续)10年了</p>\n<p class=\"source-line\">for three months (持续)3个月了</p>\n<p class=\"source-line\">（2）“since + 时间点”表示从过去的某个时间到现在。</p>\n<p class=\"source-line\">（1）结构: since + 过去时间的年份</p>\n<p class=\"source-line\">since 1998 从 1998 年到现在</p>\n<p class=\"source-line\">since 2020 从 2020 年到现在</p>\n<p class=\"source-line\">（2）结构: since + 过去的具体时间点</p>\n<p class=\"source-line\">since last week 从上周到现在</p>\n<p class=\"source-line\">since last month 从上个月到现在</p>\n<p class=\"source-line\">since I was 10 years old 从我 10 岁起到现在</p>\n<p class=\"source-line\">since three days ago 从3天前到现在</p>\n<p class=\"source-line\">since Monday 从星期一到现在</p>\n<h5>3. 其他时间状语</h5>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>时间状语</th>\n<th>用法</th>\n<th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>already(已经)</td>\n<td>一般用于肯定句中,有时也用于疑问句中</td>\n<td>I have already read this book. 我已经读过这本书了。</td>\n</tr>\n<tr>\n<td>yet(已经;还)</td>\n<td>在否定句中,yet意为“还”;在疑问句中,yet意为“已经”</td>\n<td>Lily hasn't found her bag yet. 莉莉还没有找到她的包。</td>\n</tr>\n<tr>\n<td>ever(曾经)</td>\n<td>常用于肯定句或疑问句中,要放在助动词与过去分词之间</td>\n<td>Have you ever been to Beijing? 你曾去过北京吗?</td>\n</tr>\n<tr>\n<td>never（从未）</td>\n<td>本身含否定意义，句中不再与 not 连用</td>\n<td>I have never been to Beijing before. 我以前从未去过北京。</td>\n</tr>\n<tr>\n<td>so far(到目前为止)</td>\n<td>可用来修饰动词,表示到目前为止的动作或状态</td>\n<td>What have you found so far? 到目前为止,你发现了什么?</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">have / has gone to、have / has been to 和 have / has been in 的区别</div><div class=\"gb\"><p class=\"source-line\">（1）“have / has gone to ...”表示“已经去……了”，不能与“for + 一段时间”连用。</p>\n<p class=\"source-line\">She has gone to Shanghai. 她去上海了。</p>\n<p class=\"source-line\">表明她可能已经在去上海的路上或已经到上海了，现在不在这里。</p>\n<p class=\"source-line\">（2）“have / has been to ...”表示“去过……”，不能与“for + 一段时间”连用。</p>\n<p class=\"source-line\">She has been to Shanghai three times. 她已经去过上海 3 次。</p>\n<p class=\"source-line\">表明她曾经去过上海，现在不在那里。</p>\n<p class=\"source-line\">（3）“have / has been in ...”表示“一直待在……”，常与“for + 一段时间”连用。</p>\n<p class=\"source-line\">She has been in Shanghai for three months. 她已经在上海待了3个月。</p>\n<p class=\"source-line\">表明她待在上海一段时间了，以后可能还会在上海。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·西城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s45-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Our country <span class=\"blank-token\"><strong><em>_</em></strong></span> a lot so far.<br/><br>\n—— Yes. I hope it will be <span class=\"blank-token\">_</span>.</br></p>","options":["has changed; well","changed; good","has changed; better","changed; better"],"correct":2,"answer":"C\n解析：由 so far(到目前为止)可知句子的时态为现在完成时, our country(我们的国家)为单数,助动词用 has, change(改变)的过去分词为 changed。better(更好)符合题意,故此题选择 C 选项。"},{"id":"s45-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Zhao Lan <span class=\"blank-token\"><strong><em>_</em></strong></span> already <span class=\"blank-token\">_</span> in this school for two years.</p>","options":["was; studying","will; study","has; studied","are; studying"],"correct":2,"answer":"C"},{"id":"s45-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> your homework yet?<br/><br>\n—— Yes. I <span class=\"blank-token\">____</span> it a moment ago.</br></p>","options":["Did; do; finished","Have; done; finished","Have; done; have finished","Will; do; finish"],"correct":1,"answer":"B\n解析：由 yet 可知问句的时态为现在完成时,主语为 you,助动词用 have, do (做)的过去分词为 done。由 a moment ago (片刻之前)可知答语的时态为一般过去时, finish (完成)的过去式为 finished。故此题选择 B 选项。"},{"id":"s45-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Has your cousin <span class=\"blank-token\"><strong><em>_</em></strong></span> the Great Wall?<br/><br>\n—— Sure. He <span class=\"blank-token\">_</span> there with me last summer.</br></p>","options":["been to; has gone","gone to; went","gone to; has gone","been to; went"],"correct":3,"answer":"D"},{"id":"s45-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Ten years <span class=\"blank-token\"><strong><em>_</em></strong></span> since they <span class=\"blank-token\">_</span> Shanghai.</p>","options":["have passed; arrived in","has passed; got to","passed; reached","has passed; reached to"],"correct":0,"answer":"A\n解析：since 前是主句, 主句的时态用现在完成时, ten years (10 年) 为复数, 助动词用 have。since 后为从句, 从句的时态用一般过去时, arrive in 后接大地点。故此题选择 A 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【天津·东丽区】选择题：选择与问句对应的答语。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s45-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">How long has this factory been open?</p>","options":["Not yet.","Yes, many times.","I've lived here all my life.","Since he left the army.","About 13 years."],"correct":4,"answer":"E"},{"id":"s45-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Have you cleaned up the city parks?</p>","options":["Not yet.","Yes, many times.","I've lived here all my life.","Since he left the army.","About 13 years."],"correct":0,"answer":"A"},{"id":"s45-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Has your father ever been to England?</p>","options":["Not yet.","Yes, many times.","I've lived here all my life.","Since he left the army.","About 13 years."],"correct":1,"answer":"B"},{"id":"s45-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">How long have you lived here?</p>","options":["Not yet.","Yes, many times.","I've lived here all my life.","Since he left the army.","About 13 years."],"correct":2,"answer":"C"},{"id":"s45-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">How long has Tom worked on that farm?</p>","options":["Not yet.","Yes, many times.","I've lived here all my life.","Since he left the army.","About 13 years."],"correct":3,"answer":"D"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s45-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How long have you had the book?<br/><br>\n—— <span class=\"blank-token\">____</span> two hours.</br></p>","options":["since","for"],"correct":1,"answer":"B"},{"id":"s45-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How long have you used your computer?<br/><br>\n—— <span class=\"blank-token\">____</span> 3 weeks.</br></p>","options":["for","since"],"correct":0,"answer":"A"},{"id":"s45-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How long have you been in Shanghai?<br/><br>\n—— <span class=\"blank-token\">____</span> 2016.</br></p>","options":["since","for"],"correct":0,"answer":"A"},{"id":"s45-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">We have been friends <span class=\"blank-token\">____</span> ten years.</p>","options":["for","since"],"correct":0,"answer":"A"},{"id":"s45-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">That woman has swum <span class=\"blank-token\">____</span> two and a half hours.</p>","options":["since","for"],"correct":1,"answer":"B"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 按要求完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s45-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">They have lived here <u>since 2014</u>. (就画线部分提问)</p>","options":[],"correct":null,"answer":"How long have they lived here?"},{"id":"s45-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My grandfather retired <u>5 months ago</u>. (就画线部分提问)</p>","options":[],"correct":null,"answer":"When did your grandfather retire?"},{"id":"s45-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Our English teacher has been to America <u>three times</u>. (就画线部分提问)</p>","options":[],"correct":null,"answer":"How many times has your English teacher been to America?"},{"id":"s45-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">My son has been ill <u>since last Friday</u>. (就画线部分提问)</p>","options":[],"correct":null,"answer":"How long has your son been ill?"},{"id":"s45-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Her grandfather died seven months ago. (用 be、for 改写原句, 意思不变)</p>","options":[],"correct":null,"answer":"Her grandfather has been dead for seven months."}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"III. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s45-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">You are too late. The film <span class=\"blank-token\">____</span> since half an hour ago.</p>","options":["begun","has been on","began","begins"],"correct":1,"answer":"B"},{"id":"s45-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">—— How do you like your workmates?<br/><br>\n—— They are great. We <span class=\"blank-token\">____</span> friends since three years ago.</br></p>","options":["were","have made","have been","have become"],"correct":2,"answer":"C"},{"id":"s45-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Have you met Mr. Li <span class=\"blank-token\">____</span>?</p>","options":["just","ago","before","after"],"correct":2,"answer":"C"},{"id":"s45-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Are Alice and Tim still living in New York?<br/><br>\n—— No, they <span class=\"blank-token\">____</span> to Toronto.</br></p>","options":["are moved","will move","had just moved","have just moved"],"correct":3,"answer":"D"},{"id":"s45-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">She <span class=\"blank-token\">____</span> ill since three days ago.</p>","options":["has caught","has been","had have","has got"],"correct":1,"answer":"B"}],"questionCount":5,"hasAnswers":true}]},{"id":"s46","section":46,"unit":8,"unitName":"单元08 · 第43–48节","short":"第46节 · L91–92","title":"一般将来时（一）","lessons":"Lesson 91 — Lesson 92","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般将来时</td>\n<td>句式结构</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>一般将来时</td>\n<td>标志词</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>一般将来时</td>\n<td>用法</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般将来时</div><div class=\"gb\"><p class=\"source-line\">一般将来时表示将来某一时刻的动作或状态,或将来某一段时间内经常的动作或状态。</p>\n<p class=\"source-line\">We will go to the beach for our holiday.</p>\n<p class=\"source-line\">我们将去沙滩度假。</p>\n<p class=\"source-line\">It will rain this Sunday.</p>\n<p class=\"source-line\">这个星期日将会下雨。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般将来时的句式结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定句: 主语 + will + 动词原形（+其他）.</p>\n<p class=\"source-line\">They will play basketball next weekend. 他们下周末将打篮球。</p>\n<p class=\"source-line\">I will call you this evening. 我今晚将给你打电话。</p>\n<p class=\"source-line\">（2）否定句: 主语 + will not / won't + 动词原形（+其他）.</p>\n<p class=\"source-line\">I won't tell it to him. 我不会把这件事告诉他的。</p>\n<p class=\"source-line\">He won't have time to read English. 他不会有时间读英语的。</p>\n<p class=\"source-line\">will not 的缩写形式为 won't。</p>\n<p class=\"source-line\">（3）一般疑问句: Will + 主语 + 动词原形（+其他）?</p>\n<p class=\"source-line\">Will he go to school tomorrow?</p>\n<p class=\"source-line\">他明天将去上学吗？</p>\n<p class=\"source-line\">Will you often send me emails during summer holiday?</p>\n<p class=\"source-line\">你暑假期间会经常给我发电子邮件吗？</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + will + 主语 + 动词原形（+其他）?</p>\n<p class=\"source-line\">When will Mary arrive here tomorrow? 玛丽明天将什么时候到达这里？</p>\n<p class=\"source-line\">How many books will they give us? 他们将给我们多少本书？</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般将来时的标志词</div><div class=\"gb\"><p class=\"source-line\">（1）in + 一段时间</p>\n<p class=\"source-line\">in a month 1个月后</p>\n<p class=\"source-line\">in two weeks 2 周后</p>\n<p class=\"source-line\">in three years 3 年后</p>\n<p class=\"source-line\">（2）next + 时间</p>\n<p class=\"source-line\">next day 次日</p>\n<p class=\"source-line\">next year 明年</p>\n<p class=\"source-line\">next Friday 下个星期五</p>\n<p class=\"source-line\">next month 下个月</p>\n<p class=\"source-line\">（3）含 tomorrow 的词组</p>\n<p class=\"source-line\">the day after tomorrow 后天</p>\n<p class=\"source-line\">tomorrow night 明晚</p>\n<p class=\"source-line\">（4）其他时间标志词</p>\n<p class=\"source-line\">in the future 在将来</p>\n<p class=\"source-line\">some day 有朝一日</p>\n<p class=\"source-line\">right now 马上</p>\n<p class=\"source-line\">this evening / afternoon / year 今天傍晚 / 今天下午 / 今年</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般将来时的用法</div><div class=\"gb\"><p class=\"source-line\">（1）表示将来某一时刻的动作或状态。</p>\n<p class=\"source-line\">Mr. Green will teach us English this afternoon.</p>\n<p class=\"source-line\">格林先生今天下午将教我们英语。</p>\n<p class=\"source-line\">（2）表示将来某一段时间内经常的动作或状态。</p>\n<p class=\"source-line\">He will call his parents every Sunday.</p>\n<p class=\"source-line\">他将每个星期日给他父母打电话。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·北辰区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s46-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The students will <span class=\"blank-token\">____</span> to the Palace Museum this Friday.</p>","options":["went","go","goes","to go"],"correct":1,"answer":"B\n解析：情态动词 will 后接动词原形, 故此题选择 B 选项。"},{"id":"s46-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Karen <span class=\"blank-token\">____</span> in Shanghai in three years.</p>","options":["live","lives","will live","lived"],"correct":2,"answer":"C"},{"id":"s46-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Will you go for a picnic this weekend?<br/><br>\n—— No, I <span class=\"blank-token\">____</span>.</br></p>","options":["don't","wasn't","won't","am not"],"correct":2,"answer":"C\n解析：问句是 will 开头的一般将来时的一般疑问句,其肯定回答通常为 “Yes, 主语 + will.”, 否定回答通常为 “No, 主语 + won’t.”。故此题选择 C 选项。"},{"id":"s46-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">My sister will <span class=\"blank-token\">____</span> shopping this afternoon.</p>","options":["going","go","goes","went"],"correct":1,"answer":"B"},{"id":"s46-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">She is going <span class=\"blank-token\">____</span> her grandparents.</p>","options":["to visit","visit","visiting","visits"],"correct":0,"answer":"A\n解析：此句为含有 be going to 结构的一般将来时的肯定句, 故此题选择 A 选项。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【滁州·琅琊区】每个句子中有一处错误，圈出错误并在横线上改正。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s46-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">My sister are going to play with her toy.</p>","options":[],"correct":null,"answer":"are 改为 is"},{"id":"s46-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Who will to play basketball?</p>","options":[],"correct":null,"answer":"to 删掉"},{"id":"s46-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Tom and Ann will buying some clothes.</p>","options":[],"correct":null,"answer":"buying 改为 buy"},{"id":"s46-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">What do you do at home next Saturday?</p>","options":[],"correct":null,"answer":"第一个 do 改为 will"},{"id":"s46-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">You is going to fly a kite tomorrow.</p>","options":[],"correct":null,"answer":"is 改为 are"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s46-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Charlie <span class=\"blank-token\">____</span> here next month.</p>","options":["isn't working","doesn't working","isn't going to working","won't work"],"correct":3,"answer":"D"},{"id":"s46-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\"><strong><em>_</em></strong></span> very busy now. He <span class=\"blank-token\">_</span> free tomorrow.</p>","options":["will be; is","is; is","is; will be","will be; will be"],"correct":2,"answer":"C"},{"id":"s46-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> free tomorrow?<br/><br>\n—— No. I <span class=\"blank-token\">____</span> free the day after tomorrow.</br></p>","options":["Do ; be ; will","Will ; be ; will","Are ; be ; will be","Will ; be ; will be"],"correct":3,"answer":"D"},{"id":"s46-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Mother <span class=\"blank-token\">____</span> me a nice present on my next birthday.</p>","options":["will gives","will give","gives","give"],"correct":1,"answer":"B"},{"id":"s46-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">They are going to play football <span class=\"blank-token\">____</span>.</p>","options":["tomorrow","now","yesterday","last Monday"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 句型转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s46-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He will fly to London next month.（分别改为否定句、一般疑问句，并对 fly to London 提问）</p>","options":[],"correct":null,"answer":"（1）He will not / won't fly to London next month.\n（2）Will he fly to London next month?\n（3）What will he do next month?"}],"questionCount":1,"hasAnswers":true}]},{"id":"s47","section":47,"unit":8,"unitName":"单元08 · 第43–48节","short":"第47节 · L93–94","title":"一般将来时（二）","lessons":"Lesson 93 — Lesson 94","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般将来时（二）</td>\n<td>一般将来时的 there be 结构</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">一般将来时的 there be 结构</div><div class=\"gb\"><p class=\"source-line\">一般将来时中的 there be 结构表示某地（或某时）将会有某人（或某物）。</p>\n<p class=\"source-line\">There will be a hospital near my village in the future.</p>\n<p class=\"source-line\">将来我的村子附近会有一所医院。</p></div></div>\n<div class=\"g\"><div class=\"gt\">句式结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定句: There will be + 其他.</p>\n<p class=\"source-line\">There will be a shopping mall in the city next year.</p>\n<p class=\"source-line\">城市里明年将会有一家商场。</p>\n<p class=\"source-line\">（2）否定句: There will not be + 其他.</p>\n<p class=\"source-line\">There will not be a soccer game next term.</p>\n<p class=\"source-line\">下学期将不会有一场足球比赛。</p>\n<p class=\"source-line\">（3）一般疑问句: Will there be + 其他?</p>\n<p class=\"source-line\">Will there be any apples on the tree in summer?</p>\n<p class=\"source-line\">树上夏天将会有苹果吗？</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + will there be + 其他?</p>\n<p class=\"source-line\">When will there be a sports meeting?</p>\n<p class=\"source-line\">什么时候将会有一场运动会？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【佛山·三水区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s47-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> a meeting tomorrow afternoon.</p>","options":["will be going to","will going to be","is going to be","will go to be"],"correct":2,"answer":"C"},{"id":"s47-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">There <span class=\"blank-token\">____</span> a dolphin show in the zoo tomorrow evening.</p>","options":["was","is going to have","will have","is going to be"],"correct":3,"answer":"D"},{"id":"s47-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Are you going to <span class=\"blank-token\">____</span> the cinema at nine?</p>","options":["going","go to","goes to","go"],"correct":1,"answer":"B\n解析：be going to 与动词原形搭配使用, go to the cinema (去看电影) 是固定搭配, 故选 B。"},{"id":"s47-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Linda likes <span class=\"blank-token\"><strong><em>_</em></strong></span> shopping. She <span class=\"blank-token\">_</span> shopping tomorrow.</p>","options":["goes; goes","going; going","going; will go","go; goes"],"correct":2,"answer":"C"},{"id":"s47-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The old man <span class=\"blank-token\">____</span> 80 years old next year.</p>","options":["will be","is going to","was","is"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【北京·丰台区】根据汉语提示补全下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s47-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">她明天不打算参加聚会。<br/>\nShe <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\"><em></em></span> <span class=\"blank-token\"><strong><em>_</em></strong></span> come to the party tomorrow.<br/>\n= She <span class=\"blank-token\"></span> come to the party tomorrow.</p>","options":[],"correct":null,"answer":"isn't going to, won't"},{"id":"s47-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">你今晚打算做什么？<br/>\nWhat <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\"><em></em></span> <span class=\"blank-token\"><strong><em>_</em></strong></span> this evening?<br/>\n= What <span class=\"blank-token\"></span> you <span class=\"blank-token\">____</span> this evening?</p>","options":[],"correct":null,"answer":"are, going to do, will, do"},{"id":"s47-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">他们下周打算野餐吗？<br/>\n<span class=\"blank-token\"><strong><em>_</em></strong></span> they <span class=\"blank-token\"><em></em></span> <span class=\"blank-token\"><strong><em>_</em></strong></span> have a picnic next week?<br/>\n= <span class=\"blank-token\"></span> they have a picnic next week?</p>","options":[],"correct":null,"answer":"Are, going to, Will"},{"id":"s47-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">露西打算明天去旅行。<br/>\nLucy <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\"><em></em></span> <span class=\"blank-token\"><strong><em>_</em></strong></span> travel tomorrow.<br/>\n= Lucy <span class=\"blank-token\"></span> travel tomorrow.</p>","options":[],"correct":null,"answer":"is going to, will"},{"id":"s47-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">今天下午将有一场足球赛。<br/>\nThere <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\"><em></em></span> a football match this afternoon.<br/>\n= There is <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\"></span> <span class=\"blank-token\">____</span> a football match this afternoon.</p>","options":[],"correct":null,"answer":"will be, going to be"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 根据要求改写句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s47-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">There will be <u>a PE class</u>. (就画线部分提问)</p>","options":[],"correct":null,"answer":"What will there be?"},{"id":"s47-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">There will be a big playground next year. (改为否定句)</p>","options":[],"correct":null,"answer":"There will not be a big playground next year."},{"id":"s47-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">There will be a party at 16:30 tomorrow. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Will there be a party at 16:30 tomorrow?"},{"id":"s47-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">There will be a football match tomorrow.(改为一般疑问句,并作肯定回答)</p>","options":[],"correct":null,"answer":"Will there be a football match tomorrow? Yes, there will."},{"id":"s47-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">There will be a film in the cinema this weekend. (改为否定句)</p>","options":[],"correct":null,"answer":"There will not be a film in the cinema this weekend."}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s47-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> a concert next Saturday?</p>","options":["There will be","Will there be","There can be","There are"],"correct":1,"answer":"B"},{"id":"s47-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> a new film in the cinema this evening?</p>","options":["Will there has","Will there be","There will has","There will be"],"correct":1,"answer":"B"},{"id":"s47-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Next year, <span class=\"blank-token\">____</span> a new road.</p>","options":["there is","there are","there will be","there was"],"correct":2,"answer":"C"},{"id":"s47-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— <span class=\"blank-token\">____</span> a soccer match on TV at 7:40 this evening.<br/><br>\n—— Great. Let's watch it then.</br></p>","options":["There is","There are","There be","There will be"],"correct":3,"answer":"D"},{"id":"s47-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">We hope <span class=\"blank-token\">____</span> a computer on every student's desk in the future.</p>","options":["there is","there was","there will be","there has been"],"correct":2,"answer":"C"},{"id":"s47-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What activities <span class=\"blank-token\">____</span> in the English competition?<br/><br>\n—— English songs, shows, speeches and so on.</br></p>","options":["will be there","will there be","are there going to have","be there will"],"correct":1,"answer":"B"},{"id":"s47-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> a singing competition next week.</p>","options":["There will be","There will have","There will is","There will has"],"correct":0,"answer":"A"}],"questionCount":7,"hasAnswers":true}]},{"id":"s48","section":48,"unit":8,"unitName":"单元08 · 第43–48节","short":"第48节 · L95–96","title":"时间表达法","lessons":"Lesson 95 — Lesson 96","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>时间表达法</td>\n<td>时间表达法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">时间表达法</div><div class=\"gb\"><p class=\"source-line\">（1）所有的时间都可以用“小时 + 分钟”直接表达。</p>\n<p class=\"source-line\"><code>txt\nsix ten 6:10 nine thirty 9:30\neleven fifty-eight 11:58\nIt's six ten. It's time to get up.\n6:10 了,到起床的时间了。</code></p>\n<p class=\"source-line\">（2）分钟数小于 30,可以用“分钟 + past + 小时”表达。</p>\n<p class=\"source-line\"><code>txt\ntwelve past seven 7:12  \ntwenty-five past three 3:25  \ntwenty-eight past eleven 11:28  \nIt's twenty-eight past eleven. It's time to have lunch.  \n11:28了，到吃午饭的时间了。</code></p>\n<p class=\"source-line\">（3）分钟数大于 30,可以用“（相差的）分钟 + to +（下一个）小时”表达。</p>\n<p class=\"source-line\"><code>txt\ntwenty to six 5:40  \ntwo to eleven 10:58  \neleven to five 4:49  \nIt's twenty to six. It's time to do your homework.  \n5:40了，到做家庭作业的时间了。</code></p>\n<p class=\"source-line\">（4）分钟数为 30,可以用“half past + 小时”表达。</p>\n<p class=\"source-line\"><code>txt\nhalf past one 1:30  \nhalf past nine 9:30  \nhalf past twelve 12:30  \nIt's half past nine. It's time to go to bed.  \n9:30了，到上床睡觉的时间了。</code></p>\n<p class=\"source-line\">（5）所描述的时间为整点,可以用“小时 + o'clock”表达。</p>\n<p class=\"source-line\"><code>txt\neight o'clock 8:00\nten o'clock 10:00\ntwelve o'clock 12:00\nIt's twelve o'clock. It's time to have a rest.\n12:00 了，到休息的时间了。</code></p>\n<p class=\"source-line\">（6）所描述的分钟和 15 有关,有 3 种表达。15 分钟又叫一刻钟,可以用“a quarter”表达。</p>\n<p class=\"source-line\"><code>txt\n10:15 ① ten fifteen ② fifteen past ten ③ a quarter past ten\n5:45 ① five forty-five ② fifteen to six ③ a quarter to six\nIt's a quarter to seven. It's time to watch TV.\n6:45 了,到看电视的时间了。</code></p>\n<p class=\"source-line\">（7）所描述的是大约时间,可以用“almost / not quite / just after + 时间”等表达。</p>\n<p class=\"source-line\"><code>txt\nIt's almost five. 快 5:00 了。\nIt's not quite ten. 还不到 10:00。\nIt's just after two. 刚过 2:00。</code></p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·丰台区】写出下列时间。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s48-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">five to one</p>","options":[],"correct":null,"answer":"12:55"},{"id":"s48-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">half past three</p>","options":[],"correct":null,"answer":"3:30"},{"id":"s48-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">eight twenty</p>","options":[],"correct":null,"answer":"8:20"},{"id":"s48-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">a quarter to seven</p>","options":[],"correct":null,"answer":"6:45"},{"id":"s48-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">twelve o'clock</p>","options":[],"correct":null,"answer":"12:00"},{"id":"s48-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">eighteen past ten</p>","options":[],"correct":null,"answer":"10:18"},{"id":"s48-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">eleven o'clock</p>","options":[],"correct":null,"answer":"11:00"},{"id":"s48-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">four fourteen</p>","options":[],"correct":null,"answer":"4:14"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"I. 用英文表达出以下时间。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s48-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">9:30</p>","options":[],"correct":null,"answer":"half past nine / nine thirty"},{"id":"s48-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">4:15</p>","options":[],"correct":null,"answer":"a quarter past four / fifteen past four / four fifteen"},{"id":"s48-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">7:36</p>","options":[],"correct":null,"answer":"seven thirty-six / twenty-four to eight"},{"id":"s48-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">8:45</p>","options":[],"correct":null,"answer":"a quarter to nine / fifteen to nine / eight forty-five"},{"id":"s48-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">12:00</p>","options":[],"correct":null,"answer":"twelve o'clock"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 根据括号内的时间用英语补全句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s48-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（7:30）</p>","options":[],"correct":null,"answer":"seven thirty / half past seven"},{"id":"s48-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（4:45）</p>","options":[],"correct":null,"answer":"four forty-five / a quarter to five / fifteen to five"},{"id":"s48-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（11:15）</p>","options":[],"correct":null,"answer":"eleven fifteen / a quarter past eleven / fifteen past eleven"},{"id":"s48-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（4:30）</p>","options":[],"correct":null,"answer":"four thirty / half past four"},{"id":"s48-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（9:05）</p>","options":[],"correct":null,"answer":"nine oh five / five past nine"},{"id":"s48-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">It's <span class=\"blank-token\">____</span>.（5:50）</p>","options":[],"correct":null,"answer":"five fifty / ten to six"}],"questionCount":6,"hasAnswers":true}]},{"id":"s49","section":49,"unit":9,"unitName":"单元09 · 第49–54节","short":"第49节 · L97–98","title":"物主代词","lessons":"Lesson 97 — Lesson 98","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>物主代词</td>\n<td>形容词性物主代词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>物主代词</td>\n<td>名词性物主代词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">物主代词</div><div class=\"gb\"><p class=\"source-line\">物主代词是用来表示所有关系的代词,它包括形容词性物主代词和名词性物主代词两种,并有不同的人称和数之分。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>含义</th>\n<th>我的</th>\n<th>你的</th>\n<th>他的</th>\n<th>她的</th>\n<th>它的</th>\n<th>我们的</th>\n<th>你们的</th>\n<th>他/她/它们的</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>形容词性物主代词</td>\n<td>my</td>\n<td>your</td>\n<td>his</td>\n<td>her</td>\n<td>its</td>\n<td>our</td>\n<td>your</td>\n<td>their</td>\n</tr>\n<tr>\n<td>名词性物主代词</td>\n<td>mine</td>\n<td>yours</td>\n<td>his</td>\n<td>hers</td>\n<td>—</td>\n<td>ours</td>\n<td>yours</td>\n<td>theirs</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">说明：本表保留教材中的 its。现代英语通常不把 its 作为可独立使用的名词性物主代词，实际使用时应避免这种用法。</p>\n<p class=\"source-line\">This is my cat. Its name is Lily.\n这是我的猫。它的名字是莉莉。</p>\n<p class=\"source-line\">This is my bike, not yours.</p>\n<p class=\"source-line\">这是我的自行车,不是你的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">形容词性物主代词与名词性物主代词的用法区别</div><div class=\"gb\"><p class=\"source-line\">（1）形容词性物主代词不能独立使用,只能作定语,用来修饰后面的名词。</p>\n<p class=\"source-line\">My parents are both doctors.</p>\n<p class=\"source-line\">我父母都是医生。</p>\n<p class=\"source-line\">（2）名词性物主代词应独立使用,相当于“形容词性物主代词 + 名词”,在句中可作主语、宾语、表语。</p>\n<p class=\"source-line\">These books are yours. Ours are on the desk.</p>\n<p class=\"source-line\">这些书是你们的。我们的在书桌上。</p>\n<p class=\"source-line\">（作主语）</p>\n<p class=\"source-line\">May I use your ruler? I have lost mine.</p>\n<p class=\"source-line\">我可以用一下你的尺子吗？我的(尺子)丢了。</p>\n<p class=\"source-line\">（作宾语）</p>\n<p class=\"source-line\">The laptop on the desk is yours.</p>\n<p class=\"source-line\">书桌上的那台笔记本电脑是你的。</p>\n<p class=\"source-line\">（作表语）</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">物主代词有两类：形容词性、名词性。形容词性作定语，后面要把名词跟；名词性独立用，主语、宾语、表语都能充当。</p></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【沈阳·和平区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s49-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">This is my book. <span class=\"blank-token\">____</span> book is over there.</p>","options":["Your","You","I","Mine"],"correct":0,"answer":"A\n解析：book(书)为名词, 前面应使用形容词性物主代词, A 选项符合题意。"},{"id":"s49-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Whose pen is it?<br/><br>\n—— It's <span class=\"blank-token\">____</span> pen.</br></p>","options":["her","hers","she","he"],"correct":0,"answer":"A"},{"id":"s49-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> bag is new and <span class=\"blank-token\">_</span> is new, too.</p>","options":["Our; he","Ours; his","My; his","My; her"],"correct":2,"answer":"C"},{"id":"s49-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">This room is ours, and that one is <span class=\"blank-token\">____</span>.</p>","options":["they","them","theirs","their"],"correct":2,"answer":"C"},{"id":"s49-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Is this <span class=\"blank-token\"><strong><em>_</em></strong></span> new watch?<br/><br>\n—— Yes, it's <span class=\"blank-token\">_</span> watch.</br></p>","options":["you; me","yours; mine","your; my","your; mine"],"correct":2,"answer":"C"},{"id":"s49-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">It's a dog. I don't know <span class=\"blank-token\">____</span> name.</p>","options":["its'","its","it","it's"],"correct":1,"answer":"B"},{"id":"s49-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">My mother is a teacher. She loves <span class=\"blank-token\">____</span> students very much.</p>","options":["her","his","my","your"],"correct":0,"answer":"A\n解析：students (学生们)为名词, 前面应使用形容词性物主代词。主语为 she, she 对应的形容词性物主代词为 her, A 选项符合题意。"},{"id":"s49-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Mary and Gina are my cousins. <span class=\"blank-token\">____</span> father works in a company.</p>","options":["Their","They","Them","Theirs"],"correct":0,"answer":"A"},{"id":"s49-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Sally is a young inventor and she talked about <span class=\"blank-token\">____</span> invention on TV last week.</p>","options":["she","her","hers","herself"],"correct":1,"answer":"B"},{"id":"s49-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I want to call my mother. But I can’t find my mobile phone.<br/><br>\n—— Don’t worry. My brother’s mobile phone is here. You can use <span class=\"blank-token\">____</span>.</br></p>","options":["theirs","mine","hers","his"],"correct":3,"answer":"D"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"I. 写出下列单词的相应形式。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s49-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">my(名词性物主代词)</p>","options":[],"correct":null,"answer":"mine"},{"id":"s49-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">her(名词性物主代词)</p>","options":[],"correct":null,"answer":"hers"},{"id":"s49-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">our(名词性物主代词)<span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"ours"},{"id":"s49-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">your(名词性物主代词)</p>","options":[],"correct":null,"answer":"yours"},{"id":"s49-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">they(形容词性物主代词)</p>","options":[],"correct":null,"answer":"their"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 根据括号内所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s49-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">The rabbit hears with <span class=\"blank-token\">____</span> (it) ears.</p>","options":[],"correct":null,"answer":"its"},{"id":"s49-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">I've got a cat. <span class=\"blank-token\">____</span> (it) is very cute.</p>","options":[],"correct":null,"answer":"It"},{"id":"s49-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">This is <span class=\"blank-token\">____</span> (I) book.</p>","options":[],"correct":null,"answer":"my"},{"id":"s49-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> (he) chair is blue.</p>","options":[],"correct":null,"answer":"His"},{"id":"s49-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> (ours) classroom is big.</p>","options":[],"correct":null,"answer":"Our"},{"id":"s49-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">This is <span class=\"blank-token\"><strong><em>_</em></strong></span> (he) bag. It's <span class=\"blank-token\">_</span> (he).</p>","options":[],"correct":null,"answer":"his, his"},{"id":"s49-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">This is <span class=\"blank-token\"><strong><em>_</em></strong></span> (her) bag. It's <span class=\"blank-token\">_</span> (her).</p>","options":[],"correct":null,"answer":"her, hers"},{"id":"s49-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">His bag is green. <span class=\"blank-token\">____</span> (my) is pink.</p>","options":[],"correct":null,"answer":"Mine"},{"id":"s49-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">Her eyes are big, but <span class=\"blank-token\">____</span> (you) are small.</p>","options":[],"correct":null,"answer":"yours"},{"id":"s49-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">—— Are these <span class=\"blank-token\"><strong><em>_</em></strong></span> (you) pencils?<br/><br>\n—— Yes, they are <span class=\"blank-token\">_</span> (our).</br></p>","options":[],"correct":null,"answer":"your, ours"},{"id":"s49-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">—— Whose pencil is this?<br/><br>\n—— It's <span class=\"blank-token\">____</span> (I).</br></p>","options":[],"correct":null,"answer":"mine"},{"id":"s49-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">—— Are these <span class=\"blank-token\"><strong><em>_</em></strong></span> (they) bags?<br/><br>\n—— No, they aren't <span class=\"blank-token\">_</span> (their). They are <span class=\"blank-token\">____</span> (we).</br></p>","options":[],"correct":null,"answer":"their, theirs, ours"}],"questionCount":12,"hasAnswers":true}]},{"id":"s50","section":50,"unit":9,"unitName":"单元09 · 第49–54节","short":"第50节 · L99–100","title":"宾语从句","lessons":"Lesson 99 — Lesson 100","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>宾语从句</td>\n<td>宾语从句的概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>宾语从句</td>\n<td>宾语从句的引导词</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>宾语从句</td>\n<td>宾语从句的时态</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>宾语从句</td>\n<td>宾语从句的语序</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">宾语从句的概念</div><div class=\"gb\"><p class=\"source-line\">在复合句中作宾语的从句叫宾语从句。</p>\n<p class=\"source-line\">I believe that I can do it. 我相信我能做到。</p></div></div>\n<div class=\"g\"><div class=\"gt\">宾语从句的引导词</div><div class=\"gb\"><p class=\"source-line\">（1）由 that 引导。that 无词义,可省略。应用在陈述句中。</p>\n<p class=\"source-line\">I think (that) the girl is a good doctor.</p>\n<p class=\"source-line\">我认为这个女孩儿是一位好医生。</p>\n<p class=\"source-line\">I know (that) you are a teacher.</p>\n<p class=\"source-line\">我知道你是一位老师。</p>\n<p class=\"source-line\">（2）由 if / whether 引导。if / whether 意为“是否”。应用在一般疑问句中。</p>\n<p class=\"source-line\">I want to know if the girl is a doctor. 我想知道这个女孩儿是不是医生。</p>\n<p class=\"source-line\">I'm thinking about whether she will come. 我在想她是否会来。</p>\n<p class=\"source-line\">（3）由疑问词引导,应用在特殊疑问句中。</p>\n<p class=\"source-line\">I wonder who the girl is.</p>\n<p class=\"source-line\">我想知道那个女孩儿是谁。</p></div></div>\n<div class=\"g\"><div class=\"gt\">宾语从句的时态</div><div class=\"gb\"><p class=\"source-line\">（1）主句是过去时态时，从句通常根据语境使用相应的过去时态；如果从句表达客观真理或当前仍成立的事实，则不受这一规则限制。</p>\n<p class=\"source-line\">He said that he was playing basketball at that time.</p>\n<p class=\"source-line\">他说他那时正在打篮球。</p>\n<p class=\"source-line\">She said that she watched TV.</p>\n<p class=\"source-line\">她说她看了电视。</p>\n<p class=\"source-line\">（2）主句是现在的时态,从句的时态可根据实际情况而定。</p>\n<p class=\"source-line\">I remember that he gave me a dictionary yesterday.</p>\n<p class=\"source-line\">我记得他昨天给了我一本字典。</p>\n<p class=\"source-line\">She says that she will go to school tomorrow.</p>\n<p class=\"source-line\">她说她明天将去学校。</p>\n<p class=\"source-line\">（3）从句描述的是客观真理,只能用一般现在时,不受主句影响。</p>\n<p class=\"source-line\">Mary told me that the earth goes around the sun.</p>\n<p class=\"source-line\">玛丽告诉我地球绕着太阳转。</p></div></div>\n<div class=\"g\"><div class=\"gt\">宾语从句的语序</div><div class=\"gb\"><p class=\"source-line\">宾语从句的语序是陈述语序，即“主句+引导词+主语+谓语（+其他）.”。</p>\n<p class=\"source-line\">Do you know what it is? 你知道它是什么吗？</p>\n<p class=\"source-line\">Can you tell me who you are? 你能告诉我你是谁吗？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·五华区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s50-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Does she know <span class=\"blank-token\">____</span>?</p>","options":["what's your name","what name is your","what your is name","what your name is"],"correct":3,"answer":"D"},{"id":"s50-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you know what time <span class=\"blank-token\">____</span>?</p>","options":["does the train leave","leaves the train","the train leave","the train leaves"],"correct":3,"answer":"D"},{"id":"s50-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I want to see Miss Green, but I don't know <span class=\"blank-token\">____</span>.</p>","options":["she lives where","she where lives","where she lives","where does she live"],"correct":2,"answer":"C\n解析：宾语从句用陈述语序,引导词放前面,故选 C。"},{"id":"s50-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The girl asked me <span class=\"blank-token\">____</span>.</p>","options":["where was the cinema","where is the cinema","where the cinema was","where the cinema is"],"correct":2,"answer":"C\n解析：主句的时态是一般过去时, 从句要用过去时态, 且用陈述语序, 故选 C。"},{"id":"s50-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Did you hear <span class=\"blank-token\">____</span>?</p>","options":["what did I say","what I said","I said what","what I say"],"correct":1,"answer":"B"},{"id":"s50-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you tell me where <span class=\"blank-token\">____</span> now?</p>","options":["the tape was","was the tape","the tape is","is the tape"],"correct":2,"answer":"C"},{"id":"s50-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">She told me the sun <span class=\"blank-token\">____</span> in the east.</p>","options":["rise","rose","rises","had risen"],"correct":2,"answer":"C\n解析：从句描述的是客观真理,时态用一般现在时,故选 C。"},{"id":"s50-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you tell us <span class=\"blank-token\">____</span> you are getting on well with your classmates?</p>","options":["that","if","what","where"],"correct":1,"answer":"B"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"I. 用所给动词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s50-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">The radio says it <span class=\"blank-token\">____</span> (be) cloudy tomorrow.</p>","options":[],"correct":null,"answer":"will be"},{"id":"s50-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">The headmaster hopes everything <span class=\"blank-token\">____</span> (go) well.</p>","options":[],"correct":null,"answer":"will go"},{"id":"s50-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Tom says that they <span class=\"blank-token\">____</span> (play) basketball yesterday evening.</p>","options":[],"correct":null,"answer":"played"},{"id":"s50-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">I hear they <span class=\"blank-token\">____</span> (return) it already.</p>","options":[],"correct":null,"answer":"have returned"},{"id":"s50-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The teacher told his class that light <span class=\"blank-token\">____</span> (travel) faster than sound.</p>","options":[],"correct":null,"answer":"travels"},{"id":"s50-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">I didn't know whom the letters <span class=\"blank-token\">____</span> (be) from.</p>","options":[],"correct":null,"answer":"were"},{"id":"s50-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Can you tell me what they <span class=\"blank-token\">____</span> (do) yesterday?</p>","options":[],"correct":null,"answer":"did"},{"id":"s50-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">They said that they <span class=\"blank-token\">____</span> (be) members of the team since 2000.</p>","options":[],"correct":null,"answer":"had been"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s50-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">It's so dark. I can't find out <span class=\"blank-token\"><strong><em>_</em></strong></span> it's a boy <span class=\"blank-token\">_</span> a girl.</p>","options":["if; and","that; and","either; or","whether; or"],"correct":3,"answer":"D"},{"id":"s50-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you tell me if he <span class=\"blank-token\">____</span> to Shanghai?</p>","options":["has gone","had gone","went","go"],"correct":0,"answer":"A"},{"id":"s50-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">He told me <span class=\"blank-token\">____</span> she would catch the early bus.</p>","options":["which","what","who","that"],"correct":3,"answer":"D"}],"questionCount":3,"hasAnswers":true}]},{"id":"s51","section":51,"unit":9,"unitName":"单元09 · 第49–54节","short":"第51节 · L101–102","title":"反意疑问句","lessons":"Lesson 101 — Lesson 102","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>反意疑问句</td>\n<td>概念</td>\n<td>★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>反意疑问句</td>\n<td>结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>反意疑问句</td>\n<td>动词的用法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>反意疑问句</td>\n<td>回答</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">反意疑问句的概念</div><div class=\"gb\"><p class=\"source-line\">反意疑问句是附加在陈述句后的简短问句(又称附加问句),对陈述句所说的事实或看法提出疑问。句子结构遵循“前肯定,后否定;前否定,后肯定”原则。附加问句的人称、时态及动词与陈述部分一致,且主语只能用代词。</p>\n<p class=\"source-line\">It's very delicious, isn't it? 它很好吃,不是吗?</p>\n<p class=\"source-line\">Mike doesn't like hot drinks, does he? 迈克不喜欢热饮，是吗？</p></div></div>\n<div class=\"g\"><div class=\"gt\">反意疑问句的结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定陈述句 + 否定结构的附加问句?</p>\n<p class=\"source-line\">She is a teacher, isn't she? 她是一名教师，不是吗？</p>\n<p class=\"source-line\">前肯后否</p>\n<p class=\"source-line\">（2）否定陈述句 + 肯定结构的附加问句?</p>\n<p class=\"source-line\">They didn't go to the zoo, did they? 他们没去动物园，是吗？</p>\n<p class=\"source-line\">前否后肯</p>\n<p class=\"source-line\">附加疑问句部分所用的 be 动词、助动词、情态动词及其时态必须与陈述部分保持一致。</p></div></div>\n<div class=\"g\"><div class=\"gt\">反意疑问句动词的用法</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>规律</th>\n<th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>前 be 后 be</td>\n<td>She was sick, wasn't she? 她生病了,不是吗?</td>\n</tr>\n<tr>\n<td>前情后情</td>\n<td>He can't swim, can he? 他不会游泳,是吗?</td>\n</tr>\n<tr>\n<td>前实后助</td>\n<td>Amy likes playing the piano, doesn't she?埃米喜欢弹钢琴,不是吗?</td>\n</tr>\n<tr>\n<td>前助后助</td>\n<td>He has known the matter, hasn't he?他已经知道这件事了,不是吗?</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">当陈述句中的 have 为实义动词,附加问句用助动词。</p>\n<p class=\"source-line\">You have dinner at home every day, don't you? 你每天都在家吃晚饭,不是吗?</p>\n<p class=\"source-line\">当陈述句中的 have / has 为助动词,附加问句用 have / has。</p>\n<p class=\"source-line\">You have had dinner at home, haven't you? 你在家吃过晚饭了,不是吗?</p></div></div>\n<div class=\"g\"><div class=\"gt\">反意疑问句的回答</div><div class=\"gb\"><p class=\"source-line\">（1）根据事实确定答语。</p>\n<p class=\"source-line\">（2）遵循“肯肯一致、否否一致”的原则。</p>\n<p class=\"source-line\">Mrs White is an English teacher, isn't she?</p>\n<p class=\"source-line\">怀特夫人是一名英语老师,不是吗?</p>\n<p class=\"source-line\">Mrs White isn't an English teacher, is she?</p>\n<p class=\"source-line\">怀特夫人不是一名英语老师,是吗?</p>\n<p class=\"source-line\">Mrs White 到底是不是英语老师？→根据事实回答：</p>\n<p class=\"source-line\">如果 Mrs White 是一名英语老师: She is an English teacher. → 反意疑问句的回答为:</p>\n<p class=\"source-line\">Yes, she is.</p>\n<p class=\"source-line\">肯肯一致</p>\n<p class=\"source-line\">如果 Mrs White 不是一名英语老师: She isn't an English teacher. 反意疑问句的回答为:</p>\n<p class=\"source-line\">No, she isn't.</p>\n<p class=\"source-line\">否否一致</p></div></div>\n<div class=\"g\"><div class=\"gt\">特殊用法</div><div class=\"gb\"><p class=\"source-line\">（1）陈述部分出现表示否定意义的词,如 never、seldom、hardly、few、little、nobody、no one、nothing 等,附加疑问部分要用肯定式。</p>\n<p class=\"source-line\">He hardly speaks to you, does he? 他几乎不跟你说话,是吗?</p>\n<p class=\"source-line\">（2）陈述部分是 there be 句型,附加疑问部分仍用 there。</p>\n<p class=\"source-line\">There's something wrong with your bike, isn't there?</p>\n<p class=\"source-line\">你的自行车出毛病了,不是吗?</p>\n<p class=\"source-line\">（3）陈述部分用 everything 或 nothing 作主语时,附加疑问部分的主语用 it。</p>\n<p class=\"source-line\">Nothing can stop us, can it? 没有什么能阻挡我们,对吗?</p>\n<p class=\"source-line\">（4）陈述部分用 everybody、everyone、somebody、someone、anybody、anyone、nobody、no one 等表示人的不定代词作主语时，附加疑问部分的主语用 they，但有时用 he。</p>\n<p class=\"source-line\"><code>txt\nEveryone knows the answer, don't they / doesn't he?</code></p>\n<p class=\"source-line\">人人都知道这个答案,不是吗?</p>\n<p class=\"source-line\">（5）陈述部分是“I am...”时，附加疑问部分常用“aren't I”代替“am not I”。</p>\n<p class=\"source-line\">I am late, aren't I? 我迟到了,不是吗?</p>\n<p class=\"source-line\">（6）当反意疑问句以祈使句开头时,附加疑问部分用 will you; 以 let's 开头时,附加疑问部分用 shall we; 以 let us 开头时,附加疑问部分用 will you。</p>\n<p class=\"source-line\">Open the door, will you? 打开门,好吗?</p>\n<p class=\"source-line\">Let's go together, shall we? 让我们一起去,好吗?</p>\n<p class=\"source-line\">Let us do it again, will you? 让我们再做一次,好吗?</p>\n<p class=\"source-line\">（7）当陈述部分有情态动词 must 时：must 表示“必须、应当”时，附加疑问部分常用 mustn't；强调“有必要”时也可用 needn't。must 表示推测时，附加疑问部分通常与 must 后面的实际谓语保持一致。</p>\n<p class=\"source-line\">We must obey the order, mustn't we? 我们必须服从命令,不是吗?</p>\n<p class=\"source-line\">You must go home right now, needn't you? 你需要马上回家,不是吗?</p>\n<p class=\"source-line\">She must be in the bedroom, isn't she? 她一定在卧室里,不是吗?</p>\n<p class=\"source-line\">（8）陈述部分含有 had better,附加疑问部分的动词用 hadn't。</p>\n<p class=\"source-line\">You had better put on your coat, hadn't you? 你最好穿上外套,好吗?</p>\n<p class=\"source-line\">反意疑问句的用法</p>\n<p class=\"source-line\">反意问句并不难,前后两句正相反。后句倒装简略式,两句主语要一致。问句主语用代词,否则就把错误犯。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·盘龙区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s51-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">There is little money for Mr. Lee to buy a ticket, <span class=\"blank-token\">____</span>?</p>","options":["are there","isn't there","aren't there","is there"],"correct":3,"answer":"D"},{"id":"s51-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— It's Father's Day today, <span class=\"blank-token\">____</span>?<br/><br>\n—— Yes, let's buy a gift for Dad.</br></p>","options":["isn't he","doesn't it","isn't it","does it"],"correct":2,"answer":"C"},{"id":"s51-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Kate felt uncomfortable on the plane, <span class=\"blank-token\"><strong><em>_</em></strong></span> she?<br/><br>\n—— <span class=\"blank-token\">_</span>, but she was still excited.</br></p>","options":["did; Yes","did; No","didn’t; Yes","didn’t; No"],"correct":2,"answer":"C\n解析：问句中的前半句为肯定句,所以第一个空填 didn't。在回答时,根据 “but she was still excited” 可知她的确不舒服,故选 C。"},{"id":"s51-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What a fine day! Let's go for a picnic, <span class=\"blank-token\">____</span>?<br/><br>\n—— Sounds a good idea.</br></p>","options":["shall we","don't we","can we","will we"],"correct":0,"answer":"A\n解析：陈述部分是以 let's 开头的祈使句,反意疑问句用 shall we。"},{"id":"s51-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">He has few friends in his new school, <span class=\"blank-token\">____</span>?</p>","options":["hasn't he","does he","is he","doesn't he"],"correct":1,"answer":"B"},{"id":"s51-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Steven had nothing for breakfast this morning, <span class=\"blank-token\">____</span>?<br/><br>\n—— No. Because he had a fever.</br></p>","options":["hadn't he","had he","didn't he","did he"],"correct":3,"answer":"D"},{"id":"s51-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">The kids have never been to such a nice park before, <span class=\"blank-token\">____</span>?</p>","options":["don't they","do they","haven't they","have they"],"correct":3,"answer":"D\n解析：陈述部分中的 have 是助动词,反意疑问句中也应用 have,因陈述部分有 never(从未),表示否定,故疑问部分要用肯定形式。D 选项符合题意。"},{"id":"s51-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Jack needs to change his unhealthy eating habits, <span class=\"blank-token\">____</span> he?</p>","options":["don't","isn't","doesn't","needn't"],"correct":2,"answer":"C"},{"id":"s51-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">He hardly goes to school by car, <span class=\"blank-token\">____</span> he?</p>","options":["does","doesn't","is","isn't"],"correct":0,"answer":"A"},{"id":"s51-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— You can’t understand this grammar, can you?<br/><br>\n—— <span class=\"blank-token\">____</span>. How I wish to get some help from the teacher!</br></p>","options":["Yes, I can","Yes, I can’t","No, I can","No, I can’t"],"correct":3,"answer":"D"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"完成下列反意疑问句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s51-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">He doesn't live in England, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"does he"},{"id":"s51-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Jenny didn't watch TV last night, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"did she"},{"id":"s51-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">She left the case on the train yesterday, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"didn't she"},{"id":"s51-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">We usually drive to work, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"don't we"},{"id":"s51-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Little progress has been made, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"has it"},{"id":"s51-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">The boy is hopeless, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"isn't he"},{"id":"s51-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Please take good care of my pet, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"will you"},{"id":"s51-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Peter has breakfast with his family every weekend, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"doesn't he"},{"id":"s51-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Let's play games, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"shall we"},{"id":"s51-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Many students are planting trees in the countryside, <span class=\"blank-token\">____</span>?</p>","options":[],"correct":null,"answer":"aren't they"}],"questionCount":10,"hasAnswers":true}]},{"id":"s52","section":52,"unit":9,"unitName":"单元09 · 第49–54节","short":"第52节 · L103–104","title":"too、very 与 enough 的用法","lessons":"Lesson 103 — Lesson 104","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>too、very与enough的用法</td>\n<td>too、very、enough的区别</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>too、very与enough的用法</td>\n<td>too、very、enough的相关短语</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">too、very、enough 的区别</div><div class=\"gb\"><p class=\"source-line\">（1）“too + 形容词 / 副词”意为“太 / 过于……”</p>\n<p class=\"source-line\">I think this apple is too small. 我觉得这个苹果太小了。</p>\n<p class=\"source-line\">The weather is too warm for us to go skiing.</p>\n<p class=\"source-line\">天气太暖和了,我们不能去滑雪。</p>\n<p class=\"source-line\">（2）“very + 形容词 / 副词”意为“很 / 非常……”</p>\n<p class=\"source-line\">I love you very much. 我非常爱你。</p>\n<p class=\"source-line\">She can dance very well. 她跳舞跳得很好。</p>\n<p class=\"source-line\">（3）“形容词 / 副词 + enough”意为“足够……”</p>\n<p class=\"source-line\">She isn't fast enough to win the race.</p>\n<p class=\"source-line\">她(跑得)不够快,不能赢得比赛。</p>\n<p class=\"source-line\">She rides fast enough. 她骑得足够快。</p></div></div>\n<div class=\"g\"><div class=\"gt\">too、very、enough 的相关短语</div><div class=\"gb\"><p class=\"source-line\">（1）“so ... that ...”意为“如此……以至……”</p>\n<p class=\"source-line\">He is so young that he can't write.</p>\n<p class=\"source-line\">他如此年幼以至他不会写字。</p>\n<p class=\"source-line\">She runs so fast that nobody can catch up with her.</p>\n<p class=\"source-line\">她跑得非常快，没人能追上她。</p>\n<p class=\"source-line\">（2）“too ... to ...”意为“太……，而不能……”</p>\n<p class=\"source-line\">He is too young to write. 他太年幼了,而不能写字。</p>\n<p class=\"source-line\">My younger sister is too young to go to school. 我妹妹太小了,而不能上学。</p>\n<p class=\"source-line\">“too ... to ...”转换成“not ... enough”时，形容词要转变成反义词。</p>\n<p class=\"source-line\">（3）“... enough to do sth.”意为“做某事足够……”</p>\n<p class=\"source-line\">He is not old enough to write. 他不够大,还不会写字。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【广州·天河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s52-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm <span class=\"blank-token\"><strong><em>_</em></strong></span> tired <span class=\"blank-token\">_</span> finish the homework.</p>","options":["very; too","too; to","not enough; to","too; for"],"correct":1,"answer":"B"},{"id":"s52-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Andy isn't <span class=\"blank-token\">____</span> to go to school.</p>","options":["too big","enough big","old enough","too old"],"correct":2,"answer":"C\n解析：此句意为 “安迪还不够上学的年龄”, “形容词 + enough” 表示 “足够……”, old enough 符合题意及语法, 故选 C。"},{"id":"s52-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't eat <span class=\"blank-token\">____</span> sugar! It's not good for your teeth.</p>","options":["too many","too much","much too","many too"],"correct":1,"answer":"B\n解析：sugar 是不可数名词, 故用 too much 来修饰。"},{"id":"s52-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I have <span class=\"blank-token\"><strong><em>_</em></strong></span> homework to do and <span class=\"blank-token\">_</span> books to read.</p>","options":["too many; too much","too much; too many","very much; many","too small; too big"],"correct":1,"answer":"B"},{"id":"s52-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">We haven't got <span class=\"blank-token\">____</span> money to buy a car.</p>","options":["too","enough","many","very"],"correct":1,"answer":"B\n解析：enough(足够的)符合题意, 故选 B。"},{"id":"s52-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">There isn't <span class=\"blank-token\">____</span> for her. She is very thirsty.</p>","options":["enough water","much","too many","enough"],"correct":0,"answer":"A"}],"questionCount":6,"hasAnswers":true},{"source":"practice","title":"【佛山·高明区】同义句转换。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s52-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">She is too young to go to school.</p>","options":[],"correct":null,"answer":"She isn't old enough to go to school."},{"id":"s52-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">The cake isn't big enough for three people.</p>","options":[],"correct":null,"answer":"The cake is too small for three people."},{"id":"s52-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">I have got too little money to buy a car.</p>","options":[],"correct":null,"answer":"I haven't got enough money to buy a car."}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s52-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I couldn't speak to the boss. He was <span class=\"blank-token\">____</span> busy.</p>","options":["very","enough","too"],"correct":2,"answer":"C"},{"id":"s52-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I couldn't go out. It was <span class=\"blank-token\">____</span> cold for me to go out.</p>","options":["enough","too","very"],"correct":1,"answer":"B"},{"id":"s52-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I could answer all the questions. They were <span class=\"blank-token\">____</span> easy.</p>","options":["too","very","enough"],"correct":1,"answer":"B"},{"id":"s52-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Is that suitcase light <span class=\"blank-token\">____</span> for you to carry?</p>","options":["very","enough","too"],"correct":1,"answer":"B"},{"id":"s52-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Is your brother old <span class=\"blank-token\">____</span> to be a member of our association (社团)?</p>","options":["enough","too","very"],"correct":0,"answer":"A"},{"id":"s52-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">They couldn't see that film. They were <span class=\"blank-token\">____</span> young.</p>","options":["too","very","enough"],"correct":0,"answer":"A"}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"II. 改写同义句，每空一词。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s52-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">The book is interesting enough for everybody to read.（改写为含 so ... that ... 的同义句）</p>","options":[],"correct":null,"answer":"The book is so interesting that everybody likes to read it."},{"id":"s52-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">The boy is so short that he can't reach the buttons of the lift.（改写为含 too ... to ... 的同义句）</p>","options":[],"correct":null,"answer":"The boy is too short to reach the buttons of the lift."}],"questionCount":2,"hasAnswers":true}]},{"id":"s53","section":53,"unit":9,"unitName":"单元09 · 第49–54节","short":"第53节 · L105–106","title":"动词不定式 to do","lessons":"Lesson 105 — Lesson 106","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>动词不定式 to do</td>\n<td>构成</td>\n<td>★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>动词不定式 to do</td>\n<td>用法</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>动词不定式 to do</td>\n<td>常见动词不定式 to do 短语</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">动词不定式</div><div class=\"gb\"><p class=\"source-line\">动词不定式是动词的一种非谓语动词形式,不受主语人称和谓语动词时态的变化干扰。在句子中不能作谓语,但仍然保留动词的特点,可以有自己的宾语和状语,动词不定式同它的宾语或状语构成动词不定式短语,即 to do 形式。</p>\n<p class=\"source-line\">We prefer to travel in spring.</p>\n<p class=\"source-line\">我们更喜欢在春天旅行。</p>\n<p class=\"source-line\">I want to eat beef. 我想吃牛肉。</p></div></div>\n<div class=\"g\"><div class=\"gt\">动词不定式的构成</div><div class=\"gb\"><p class=\"source-line\">（1）肯定形式: to + 动词原形</p>\n<p class=\"source-line\">I want to go to school. 我想去上学。</p>\n<p class=\"source-line\">I plan to go to Shanghai. 我计划去上海。</p>\n<p class=\"source-line\">（2）否定形式: not to + 动词原形</p>\n<p class=\"source-line\">His father told him not to play by the river. 他爸爸告诉他不要在河边玩儿。</p>\n<p class=\"source-line\">I decided not to take the job. 我决定不接受这份工作。</p></div></div>\n<div class=\"g\"><div class=\"gt\">动词不定式的用法</div><div class=\"gb\"><p class=\"source-line\">（1）动词不定式作主语</p>\n<p class=\"source-line\">（1）动词不定式作主语时,一般表示某次具体的或一次性的动作,且谓语动词用第三人称单数形式。</p>\n<p class=\"source-line\">To learn English well is very important to us. 学好英语对我们很重要。</p>\n<p class=\"source-line\">（2）当主语较长时,通常用“it”作形式主语,而将真正的主语和动词不定式后置。</p>\n<p class=\"source-line\">It is very important for us to learn English well. 学好英语对我们很重要。</p>\n<p class=\"source-line\">（2）动词不定式作表语</p>\n<p class=\"source-line\">主语常常是表示意向、打算、计划等的词，如 idea、wish、plan、job、duty、aim、hope。此时，不定式常在 be 动词或 seem 之后，说明主语的内容、性质等。</p>\n<p class=\"source-line\">My job is to do housework well. 我的工作就是做好家务。</p>\n<p class=\"source-line\">She seems to be very angry. 她似乎很生气。</p>\n<p class=\"source-line\">（3）动词不定式作宾语</p>\n<p class=\"source-line\">常与不定式连用的动词有 want、ask、like、offer、plan 等。当不定式作宾语且后面另有宾语补足语时，通常用 it 作形式宾语，把真正的不定式放在宾语补足语之后。</p>\n<p class=\"source-line\">I want to try this coat. 我想试试这件大衣。</p>\n<p class=\"source-line\">I found it very difficult to learn English well.</p>\n<p class=\"source-line\">我发现学好英语很难。</p>\n<p class=\"source-line\">（4）动词不定式作宾语补足语</p>\n<p class=\"source-line\">（1）后接动词不定式作宾语补足语的动词有 tell、ask、help、allow、teach 等。</p>\n<p class=\"source-line\">动词 help 后接动词不定式作宾语补足语时,可以省略 to。</p>\n<p class=\"source-line\">My sister asked me to do my homework. 我姐姐让我做作业。</p>\n<p class=\"source-line\">（2）后接动词不定式作宾语补足语,需省略 to 的动词有 let、make、see、watch、hear、feel 等。</p>\n<p class=\"source-line\">I made my little sister cry.</p>\n<p class=\"source-line\">我把我妹妹弄哭了。</p>\n<p class=\"source-line\">（5）动词不定式作定语</p>\n<p class=\"source-line\">This is the box to hold these books. 这是装这些书的箱子。</p>\n<p class=\"source-line\">Would you like something to drink? 你想要喝点儿什么吗?</p>\n<p class=\"source-line\">（6）动词不定式作状语</p>\n<p class=\"source-line\">用来修饰动词、形容词、副词或整个句子，通常表示目的、结果、原因、条件、程度。</p>\n<p class=\"source-line\">I opened the window to see more clearly. 我打开窗户,为了能看得更清楚。目的状语</p>\n<p class=\"source-line\">The boy is old enough to join the army. 这个男孩儿足够大,可以去参军了。结果状语</p></div></div>\n<div class=\"g\"><div class=\"gt\">常见动词不定式 to do 短语</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>refuse to do sth. 拒绝做某事</th>\n<th>help to do sth. 帮助做某事</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>pretend to do sth. 假装做某事</td>\n<td>manage to do sth. 设法做某事</td>\n</tr>\n<tr>\n<td>learn to do sth. 学习做某事</td>\n<td>offer to do sth. 主动提出做某事</td>\n</tr>\n<tr>\n<td>need to do sth. 需要做某事</td>\n<td>choose to do sth. 选择做某事</td>\n</tr>\n<tr>\n<td>try to do sth. 尽力做某事</td>\n<td>decide to do sth. 决定做某事</td>\n</tr>\n<tr>\n<td>agree to do sth. 同意做某事</td>\n<td>expect to do sth. 期望做某事</td>\n</tr>\n<tr>\n<td>seem to do sth. 似乎做某事</td>\n<td>prepare to do sth. 准备做某事</td>\n</tr>\n<tr>\n<td>plan to do sth. 计划做某事</td>\n<td>promise to do sth. 承诺做某事</td>\n</tr>\n<tr>\n<td>wish to do sth. 希望做某事</td>\n<td>would like to do sth. 想要做某事</td>\n</tr>\n<tr>\n<td>hope to do sth. 希望做某事</td>\n<td>fail to do sth. 未能做某事</td>\n</tr>\n</tbody>\n</table></div></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·五华区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s53-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">My mother wants me <span class=\"blank-token\">____</span> too many computer games.</p>","options":["not to play","not playing","not play","to not play"],"correct":0,"answer":"A\n解析：want sb. not to do sth. (想要某人不要做某事) 是固定搭配, 故选 A。"},{"id":"s53-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">It isn't easy for us <span class=\"blank-token\">____</span> English well.</p>","options":["learn","learns","to learn","learning"],"correct":2,"answer":"C"},{"id":"s53-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Let's do something at the party. What about <span class=\"blank-token\"><strong><em>_</em></strong></span>?<br/><br>\n—— No, I'd like <span class=\"blank-token\">_</span>.</br></p>","options":["to sing; to dance","to sing; dancing","singing; dancing","singing; to dance"],"correct":3,"answer":"D"},{"id":"s53-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">It's very difficult for the students in the village <span class=\"blank-token\">____</span> to school.</p>","options":["gets","to get","getting","get"],"correct":1,"answer":"B"},{"id":"s53-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">He loves music and wants <span class=\"blank-token\">____</span> the music club.</p>","options":["join","joins","to join","joining"],"correct":2,"answer":"C"},{"id":"s53-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Could you please tell me how <span class=\"blank-token\">____</span> the post office?</p>","options":["to get to","get to","got to","to get"],"correct":0,"answer":"A"},{"id":"s53-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">They let the little boy <span class=\"blank-token\">____</span> the room every day.</p>","options":["cleans","clean","cleaned","cleaning"],"correct":1,"answer":"B"},{"id":"s53-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">It's going to rain. Remember <span class=\"blank-token\">____</span> an umbrella.</p>","options":["taking","takes","take","to take"],"correct":3,"answer":"D"},{"id":"s53-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> English well, you should read it <span class=\"blank-token\">_</span> twenty minutes a day.</p>","options":["Studying; at least","Study; at most","To study; at least","To study; at most"],"correct":2,"answer":"C\n解析：表达目的可以用动词不定式作目的状语, 即 “To study”。at least 意为 “至少”, at most 意为 “至多”, 根据题意可知此处所表达的意思是 “一天至少读 20 分钟”。C 选项符合题意。"},{"id":"s53-practice-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">I expected Mark <span class=\"blank-token\">____</span> his talents in the talent show, but he didn't appear.</p>","options":["show","showed","showing","to show"],"correct":3,"answer":"D"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"I. 用所给动词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s53-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">He plans <span class=\"blank-token\">____</span> (go) to Beijing for the holiday.</p>","options":[],"correct":null,"answer":"to go"},{"id":"s53-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">The boy hopes <span class=\"blank-token\">____</span> (pass) the English exam.</p>","options":[],"correct":null,"answer":"to pass"},{"id":"s53-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">My parents decide <span class=\"blank-token\">____</span> (give) me more money.</p>","options":[],"correct":null,"answer":"to give"},{"id":"s53-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">I'll try my best <span class=\"blank-token\">____</span> (help) you.</p>","options":[],"correct":null,"answer":"to help"},{"id":"s53-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">I found it hard <span class=\"blank-token\"><strong><em>_</em></strong></span> (give) up <span class=\"blank-token\">_</span> (smoke).</p>","options":[],"correct":null,"answer":"to give, smoking"},{"id":"s53-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Don't forget <span class=\"blank-token\">____</span> (turn off) the light.</p>","options":[],"correct":null,"answer":"to turn off"},{"id":"s53-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Please tell her <span class=\"blank-token\">____</span> (come) here on time.</p>","options":[],"correct":null,"answer":"to come"},{"id":"s53-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I don't want you <span class=\"blank-token\">____</span> (help) me.</p>","options":[],"correct":null,"answer":"to help"},{"id":"s53-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">I hope <span class=\"blank-token\">____</span> (have) a good time.</p>","options":[],"correct":null,"answer":"to have"},{"id":"s53-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Would you like <span class=\"blank-token\">____</span> (listen) to music?</p>","options":[],"correct":null,"answer":"to listen"},{"id":"s53-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">Jack asked the boy <span class=\"blank-token\">____</span> (not play) this kind of game.</p>","options":[],"correct":null,"answer":"not to play"},{"id":"s53-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">I'd love <span class=\"blank-token\">____</span> (see) that film. Will it be on again?</p>","options":[],"correct":null,"answer":"to see"}],"questionCount":12,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s53-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Would you like <span class=\"blank-token\">____</span> eat?</p>","options":["nice anything to","something nice","something nice to","nice something"],"correct":2,"answer":"C"},{"id":"s53-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">Science is my favourite subject, so I have prepared <span class=\"blank-token\">____</span> the STEAM club.</p>","options":["join","joining","to join","to joining"],"correct":2,"answer":"C"},{"id":"s53-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">David learnt <span class=\"blank-token\">____</span> when he was five.</p>","options":["swim","swims","swam","to swim"],"correct":3,"answer":"D"},{"id":"s53-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Mike, we are told not <span class=\"blank-token\">____</span> the phone while crossing the street.<br/><br>\n—— I am sorry. I won't do it again.</br></p>","options":["answering","to answer","answer","answered"],"correct":1,"answer":"B"},{"id":"s53-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What are you going to do this summer vacation?<br/><br>\n—— I plan <span class=\"blank-token\">____</span> a lovely panda in Chengdu.</br></p>","options":["see","saw","seeing","to see"],"correct":3,"answer":"D"},{"id":"s53-text-q018","number":18,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Betty, I'm not good at English. Could you help me, please?<br/><br>\n—— Sure. I'll do what I can <span class=\"blank-token\">____</span> you improve your English.</br></p>","options":["to help","help","helping","helps"],"correct":0,"answer":"A"}],"questionCount":6,"hasAnswers":true}]},{"id":"s54","section":54,"unit":9,"unitName":"单元09 · 第49–54节","short":"第54节 · L107–108","title":"形容词的比较级","lessons":"Lesson 107 — Lesson 108","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>形容词的比较级</td>\n<td>形容词及形容词比较级的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>形容词的比较级</td>\n<td>形容词比较级的构成</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>形容词的比较级</td>\n<td>形容词比较级的用法</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">形容词及形容词比较级的概念</div><div class=\"gb\"><p class=\"source-line\">（1）形容词用来修饰名词,说明人或事物的性质或特征。</p>\n<p class=\"source-line\">Mary is a nice girl. 玛丽是一个漂亮的女孩儿。</p>\n<p class=\"source-line\">（2）形容词的比较级表示“较……”或“更……”，用于两个人或事物作比较。</p>\n<p class=\"source-line\">This apple is much bigger than that one.</p>\n<p class=\"source-line\">这个苹果比那个苹果大得多。</p></div></div>\n<div class=\"g\"><div class=\"gt\">形容词比较级的构成</div><div class=\"gb\"><p class=\"source-line\">（1）规则变化</p>\n<p class=\"source-line\">（1）一般情况下,在词尾加 er。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>高的</td>\n<td>tall</td>\n<td>taller</td>\n</tr>\n<tr>\n<td>长的</td>\n<td>long</td>\n<td>longer</td>\n</tr>\n<tr>\n<td>短的;矮的</td>\n<td>short</td>\n<td>shorter</td>\n</tr>\n<tr>\n<td>冷的</td>\n<td>cold</td>\n<td>colder</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（2）以不发音的字母 e 结尾的单音节词, 在词尾加 r。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>美好的</td>\n<td>nice</td>\n<td>nicer</td>\n</tr>\n<tr>\n<td>晚的</td>\n<td>late</td>\n<td>later</td>\n</tr>\n<tr>\n<td>广泛的</td>\n<td>wide</td>\n<td>wider</td>\n</tr>\n<tr>\n<td>大的;广泛的</td>\n<td>large</td>\n<td>larger</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（3）只有一个辅音字母结尾的重读闭音节单词,先双写该辅音字母,再加 er。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>大的;重大的</td>\n<td>big</td>\n<td>bigger</td>\n</tr>\n<tr>\n<td>热的</td>\n<td>hot</td>\n<td>hotter</td>\n</tr>\n<tr>\n<td>瘦的;薄的</td>\n<td>thin</td>\n<td>thinner</td>\n</tr>\n<tr>\n<td>肥胖的</td>\n<td>fat</td>\n<td>fatter</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（4）以辅音字母加 y 结尾的双音节词, 先把 y 变 i, 再加 er。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>重的;沉的</td>\n<td>heavy</td>\n<td>heavier</td>\n</tr>\n<tr>\n<td>繁忙的</td>\n<td>busy</td>\n<td>busier</td>\n</tr>\n<tr>\n<td>容易的</td>\n<td>easy</td>\n<td>easier</td>\n</tr>\n<tr>\n<td>快乐的</td>\n<td>happy</td>\n<td>happier</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（5）多音节词和部分双音节词的比较级在原级前加 more。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>美丽的</td>\n<td>beautiful</td>\n<td>more beautiful</td>\n</tr>\n<tr>\n<td>外向的</td>\n<td>outgoing</td>\n<td>more outgoing</td>\n</tr>\n<tr>\n<td>重要的</td>\n<td>important</td>\n<td>more important</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（2）不规则变化</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>比较级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>好的;健康的</td>\n<td>good / well</td>\n<td>better</td>\n</tr>\n<tr>\n<td>坏的;有病的</td>\n<td>bad / ill</td>\n<td>worse</td>\n</tr>\n<tr>\n<td>许多</td>\n<td>many / much</td>\n<td>more</td>\n</tr>\n<tr>\n<td>少量的</td>\n<td>little</td>\n<td>less</td>\n</tr>\n<tr>\n<td>远的</td>\n<td>far</td>\n<td>farther / further</td>\n</tr>\n<tr>\n<td>老的;年纪大的</td>\n<td>old</td>\n<td>older / elder</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">形容词比较级的用法</div><div class=\"gb\"><p class=\"source-line\">表示两者的比较,我们要用形容词的比较级。我们常用以下4种结构:</p>\n<p class=\"source-line\">（1）比较级 + than</p>\n<p class=\"source-line\">(含义:一方超过或低于另一方)</p>\n<p class=\"source-line\">He is taller than me. 他比我高。</p>\n<p class=\"source-line\">He is more hardworking than before. 他比以前更努力了。</p>\n<p class=\"source-line\">（2）比较级 + and + 比较级</p>\n<p class=\"source-line\">(含义:越来越……)</p>\n<p class=\"source-line\">The weather is becoming colder and colder. 天气变得越来越冷了。</p>\n<p class=\"source-line\">She is becoming more and more beautiful. 她变得越来越美了。</p>\n<p class=\"source-line\">（3）Which / Who + be 动词 + 比较级, A or B?</p>\n<p class=\"source-line\">(含义:两者之中哪一个/谁更……)</p>\n<p class=\"source-line\">Who is taller, Andy or John? 谁更高,安迪还是约翰?</p>\n<p class=\"source-line\">Which bag is cheaper, the red one or the yellow one?</p>\n<p class=\"source-line\">哪个包更便宜,红色的还是黄色的?</p>\n<p class=\"source-line\">（4）the + 比较级, the + 比较级</p>\n<p class=\"source-line\">(含义:越……,越……)</p>\n<p class=\"source-line\">The more you eat, the fatter you will become. 你吃得越多,你就会越胖。</p>\n<p class=\"source-line\">The later I get up, the more tired I feel. 我起得越晚，我就越觉得累。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·顺义区】用所给词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s54-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I am very <span class=\"blank-token\"><strong><em>_</em></strong></span> (tall) now. I am <span class=\"blank-token\">_</span> (tall) than before.</p>","options":[],"correct":null,"answer":"tall, taller"},{"id":"s54-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">My schoolbag is very <span class=\"blank-token\"><strong><em>_</em></strong></span> (heavy). His schoolbag is <span class=\"blank-token\">_</span> (heavy) than mine.</p>","options":[],"correct":null,"answer":"heavy, heavier\n解析：前一句说 “我的书包很重”, 故用原形 heavy; 由后一句中的 than 可知第二个空填 heavier。"},{"id":"s54-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Andy is much <span class=\"blank-token\">____</span> (healthy) than his brother.</p>","options":[],"correct":null,"answer":"healthier\n解析：句中有 than, than 前面的形容词用比较级 healthier。"},{"id":"s54-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">My pencils are <span class=\"blank-token\"><strong><em>_</em></strong></span> (long) than <span class=\"blank-token\">_</span> (your).</p>","options":[],"correct":null,"answer":"longer, yours"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【北京·密云区】连词成句。(注意字母大小写)。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s54-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">you, me, younger, are, than ( . )</p>","options":[],"correct":null,"answer":"You are younger than me."},{"id":"s54-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">my bag, smaller, yours, is, than ( . )</p>","options":[],"correct":null,"answer":"My bag is smaller than yours."},{"id":"s54-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">and, getting, warmer, warmer, is, the, day ( . )</p>","options":[],"correct":null,"answer":"The day is getting warmer and warmer."},{"id":"s54-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">your, is, clean, room( . )</p>","options":[],"correct":null,"answer":"Your room is clean."}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 写出下列形容词的比较级。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s54-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">old</p>","options":[],"correct":null,"answer":"older（一般比较）/ elder（主要用于表示家庭成员中年长者）"},{"id":"s54-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">young <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"younger"},{"id":"s54-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">tall</p>","options":[],"correct":null,"answer":"taller"},{"id":"s54-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">long <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"longer"},{"id":"s54-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">short</p>","options":[],"correct":null,"answer":"shorter"},{"id":"s54-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">strong <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"stronger"},{"id":"s54-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">fat</p>","options":[],"correct":null,"answer":"fatter"},{"id":"s54-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">thin</p>","options":[],"correct":null,"answer":"thinner"},{"id":"s54-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">heavy <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"heavier"},{"id":"s54-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">nice <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"nicer"},{"id":"s54-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">good <span class=\"blank-token\">____</span></p>","options":[],"correct":null,"answer":"better"},{"id":"s54-text-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">slow</p>","options":[],"correct":null,"answer":"slower"},{"id":"s54-text-q013","number":13,"type":"input","questionHtml":"<p class=\"source-line\">fast</p>","options":[],"correct":null,"answer":"faster"},{"id":"s54-text-q014","number":14,"type":"input","questionHtml":"<p class=\"source-line\">beautiful</p>","options":[],"correct":null,"answer":"more beautiful"}],"questionCount":14,"hasAnswers":true},{"source":"textbook","title":"II. 翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s54-text-q015","number":15,"type":"input","questionHtml":"<p class=\"source-line\">—— 谁比吉姆年纪大？——是你。<br/><br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong></span> is <span class=\"blank-token\">_</span> than Jim?<br/><br>\n—— <span class=\"blank-token\">____</span> are.</br></br></p>","options":[],"correct":null,"answer":"Who, older, You"},{"id":"s54-text-q016","number":16,"type":"input","questionHtml":"<p class=\"source-line\">—— 谁比戴维强壮？——是高山。<br/><br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong></span> is <span class=\"blank-token\">_</span> than David?<br/><br>\n—— Gao Shan <span class=\"blank-token\">____</span>.</br></br></p>","options":[],"correct":null,"answer":"Who, stronger, is"},{"id":"s54-text-q017","number":17,"type":"input","questionHtml":"<p class=\"source-line\">—— 谁的铅笔长,他的还是她的? ——我想是她的。<br/><br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong></span> pencil is <span class=\"blank-token\"><em></em></span>, <span class=\"blank-token\"><strong><em>_</em></strong></span> or <span class=\"blank-token\"></span>?<br/><br>\n—— <span class=\"blank-token\">____</span> is, I think.</br></br></p>","options":[],"correct":null,"answer":"Whose, longer, his, hers, Hers"}],"questionCount":3,"hasAnswers":true}]},{"id":"s55","section":55,"unit":10,"unitName":"单元10 · 第55–60节","short":"第55节 · L109–110","title":"形容词的最高级、提建议的句型","lessons":"Lesson 109 — Lesson 110","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>形容词的最高级,提建议的句型</td>\n<td>形容词最高级的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>形容词的最高级,提建议的句型</td>\n<td>形容词最高级的构成</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>形容词的最高级,提建议的句型</td>\n<td>形容词最高级的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>形容词的最高级,提建议的句型</td>\n<td>提建议的句型</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">形容词最高级的概念</div><div class=\"gb\"><p class=\"source-line\">形容词的最高级主要用来表示三者或三者以上人或事物的比较,它的结构一般是“the +形容词最高级(+所修饰词)+ of / in ...”,表示“……中最……”。</p>\n<p class=\"source-line\">Spring is the best season of the year. 春天是一年中最好的季节。</p>\n<p class=\"source-line\">Lucy is the youngest of all. 露西是所有人中最年轻的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">形容词最高级的构成</div><div class=\"gb\"><p class=\"source-line\">（1）规则变化</p>\n<p class=\"source-line\">（1）一般情况下,在词尾加 est。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>长的</td>\n<td>long</td>\n<td>longest</td>\n</tr>\n<tr>\n<td>短的;矮的</td>\n<td>short</td>\n<td>shortest</td>\n</tr>\n<tr>\n<td>便宜的</td>\n<td>cheap</td>\n<td>cheapest</td>\n</tr>\n<tr>\n<td>小的</td>\n<td>small</td>\n<td>smallest</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（2）以不发音的字母 e 结尾的单音节词, 在词尾加 st。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>简单的</td>\n<td>simple</td>\n<td>simplest</td>\n</tr>\n<tr>\n<td>可爱的</td>\n<td>cute</td>\n<td>cutest</td>\n</tr>\n<tr>\n<td>晚的;迟的</td>\n<td>late</td>\n<td>latest</td>\n</tr>\n<tr>\n<td>大的;广泛的</td>\n<td>large</td>\n<td>largest</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（3）只有一个辅音字母结尾的重读闭音节单词,先双写该辅音字母,再加 est。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>热的</td>\n<td>hot</td>\n<td>hottest</td>\n</tr>\n<tr>\n<td>肥的</td>\n<td>fat</td>\n<td>fattest</td>\n</tr>\n<tr>\n<td>瘦的;薄的</td>\n<td>thin</td>\n<td>thinnest</td>\n</tr>\n<tr>\n<td>大的;重大的</td>\n<td>big</td>\n<td>biggest</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（4）以辅音字母加 y 结尾的双音节词, 先把 y 变 i, 再加 est。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>容易的</td>\n<td>easy</td>\n<td>easiest</td>\n</tr>\n<tr>\n<td>快乐的</td>\n<td>happy</td>\n<td>happiest</td>\n</tr>\n<tr>\n<td>生气的</td>\n<td>angry</td>\n<td>angriest</td>\n</tr>\n<tr>\n<td>繁忙的</td>\n<td>busy</td>\n<td>busiest</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（5）多音节词和部分双音节词的最高级在原级前加 most。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>有用的</td>\n<td>useful</td>\n<td>most useful</td>\n</tr>\n<tr>\n<td>昂贵的</td>\n<td>expensive</td>\n<td>most expensive</td>\n</tr>\n<tr>\n<td>美丽的</td>\n<td>beautiful</td>\n<td>most beautiful</td>\n</tr>\n<tr>\n<td>有趣的</td>\n<td>interesting</td>\n<td>most interesting</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（2）不规则变化</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>汉语意思</th>\n<th>原级</th>\n<th>最高级</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>许多</td>\n<td>many / much</td>\n<td>most</td>\n</tr>\n<tr>\n<td>好的;健康的</td>\n<td>good / well</td>\n<td>best</td>\n</tr>\n<tr>\n<td>老的;年纪大的</td>\n<td>old</td>\n<td>oldest / eldest</td>\n</tr>\n<tr>\n<td>远的</td>\n<td>far</td>\n<td>farthest / furthest</td>\n</tr>\n<tr>\n<td>少量的</td>\n<td>little</td>\n<td>least</td>\n</tr>\n<tr>\n<td>坏的;有病的</td>\n<td>bad / ill</td>\n<td>worst</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">形容词最高级的用法</div><div class=\"gb\"><p class=\"source-line\">（1）形容词最高级前通常需要加定冠词 the,句末常接 in / of 短语表示范围。</p>\n<p class=\"source-line\">Lily is the tallest girl in our class.</p>\n<p class=\"source-line\">莉莉是我们班最高的女孩儿。</p>\n<p class=\"source-line\">Mike is my youngest brother.</p>\n<p class=\"source-line\">迈克是我最小的弟弟。</p>\n<p class=\"source-line\">（2）表示“最……之一”时，用“one of the + 最高级”。</p>\n<p class=\"source-line\">The Great Wall is one of the most famous places in the world.</p>\n<p class=\"source-line\">长城是世界上最著名的地方之一。</p>\n<p class=\"source-line\">Alice is one of the cleverest students in our class.</p>\n<p class=\"source-line\">艾丽斯是我们班最聪明的学生之一。</p>\n<p class=\"source-line\">（3）表示“第几……”时,用“the + 序数词 + 形容词最高级”。</p>\n<p class=\"source-line\">The Yellow River is the second longest river in China.</p>\n<p class=\"source-line\">黄河是中国第二长河。</p></div></div>\n<div class=\"g\"><div class=\"gt\">提建议的句型</div><div class=\"gb\"><p class=\"source-line\">（1）“Why not + 动词原形（+其他）?” = “Why don’t you + 动词原形（+其他）?”，意为“为什么不……呢？”，用来提出建议。</p>\n<p class=\"source-line\">Why not write to him? = Why don't you write to him?</p>\n<p class=\"source-line\">为什么不给他写信呢？</p>\n<p class=\"source-line\">（2）“What / How about ... ?”意为“……怎么样?”,用来向对方提出建议或征求对方的意见。</p>\n<p class=\"source-line\">—— What / How about having a picnic today? 今天野餐怎么样？</p>\n<p class=\"source-line\">—— Good idea. 好主意。</p>\n<p class=\"source-line\">（3）“Let's (not) do sth.”意为“让我们（不）做某事”，用于向某人提出建议。</p>\n<p class=\"source-line\">Let's go to the park together. 让我们一起去公园吧。</p>\n<p class=\"source-line\">（4）“Shall I / we + 动词原形（+其他）?”意为“我 / 我们……好吗?”。</p>\n<p class=\"source-line\">Shall we have dinner outside? 我们到外面吃晚饭好吗？</p>\n<p class=\"source-line\">（5）“Would you like to + 动词原形（+其他）?”意为“你愿意……吗?”，用来提出请求或建议。</p>\n<p class=\"source-line\">—— Would you like to see the movie with us? 你愿意和我们一起看电影吗？</p>\n<p class=\"source-line\">—— Yes, I'd like / love to. 是的,我愿意。</p>\n<p class=\"source-line\">（6）“You’d better (not) do sth.”意为“你最好（不）做某事”。</p>\n<p class=\"source-line\">You'd better do it now. 你最好现在就做。</p>\n<p class=\"source-line\">（7）“You should / shouldn't do sth.”意为“你应该 / 不应该做某事”，用于表示义务或者责任。</p>\n<p class=\"source-line\">You should get up early. 你应该早点儿起床。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【合肥·包河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s55-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The whale is the <span class=\"blank-token\">____</span> animal.</p>","options":["heavy","heavier","heaviest","lightest"],"correct":2,"answer":"C\n解析：此题所表达的意思是 “鲸是最重的动物”。D 选项不符合实际。故选最高级 heaviest。"},{"id":"s55-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> hair is the longest?</p>","options":["Who","Whose","Whom","What"],"correct":1,"answer":"B\n解析：hair(头发)是名词, whose 意为 “谁的”, 符合题意, 故选 whose。"},{"id":"s55-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">The giraffe is the <span class=\"blank-token\">____</span> animal.</p>","options":["tallest","smaller","tall","smallest"],"correct":0,"answer":"A\n解析：此题所表达的意思是 “长颈鹿是最高的动物”。D 选项不符合实际。故选最高级 tallest。"},{"id":"s55-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Ruby is the <span class=\"blank-token\">____</span> dancer.</p>","options":["best","good","better","bestest"],"correct":0,"answer":"A"},{"id":"s55-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Josh sings the <span class=\"blank-token\">____</span> in his class.</p>","options":["bad","good","worst","better"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【沈阳·沈河区】根据汉语意思完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s55-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">为什么不让她做她自己喜欢的呢？</p>","options":[],"correct":null,"answer":"Why not let her do what she likes?"},{"id":"s55-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">乘坐高铁怎么样？</p>","options":[],"correct":null,"answer":"How / What about taking the high-speed train?"}],"questionCount":2,"hasAnswers":true},{"source":"textbook","title":"I. 写出下列形容词的最高级。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s55-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">tall —</p>","options":[],"correct":null,"answer":"tallest"},{"id":"s55-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">dark —</p>","options":[],"correct":null,"answer":"darkest"},{"id":"s55-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">beautiful —</p>","options":[],"correct":null,"answer":"most beautiful"},{"id":"s55-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">young —</p>","options":[],"correct":null,"answer":"youngest"},{"id":"s55-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">big —</p>","options":[],"correct":null,"answer":"biggest"},{"id":"s55-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">expensive —</p>","options":[],"correct":null,"answer":"most expensive"},{"id":"s55-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">important —</p>","options":[],"correct":null,"answer":"most important"},{"id":"s55-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">strong —</p>","options":[],"correct":null,"answer":"strongest"},{"id":"s55-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">thin —</p>","options":[],"correct":null,"answer":"thinnest"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s55-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Oh, I had a terrible toothache.<br/><br>\n—— You'd better <span class=\"blank-token\">____</span> a dentist and have your bad teeth pulled out.</br></p>","options":["to go to","going to","goes to","go to"],"correct":3,"answer":"D"},{"id":"s55-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">Since you have finished your homework, how about <span class=\"blank-token\">____</span>?</p>","options":["go to run","go running","to run","going running"],"correct":3,"answer":"D"}],"questionCount":2,"hasAnswers":true}]},{"id":"s56","section":56,"unit":10,"unitName":"单元10 · 第55–60节","short":"第56节 · L111–112","title":"形容词、副词的同级比较","lessons":"Lesson 111 — Lesson 112","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>形容词、副词的同级比较</td>\n<td>形容词、副词的同级比较</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">形容词、副词的同级比较</div><div class=\"gb\"><p class=\"source-line\">（1）“A + 动词（be 动词 / 实义动词）+ as + 形容词原级 / 副词原级 + as B.”表示“A 和 B 程度相同”。</p>\n<p class=\"source-line\">Mary is as young as Alice. 玛丽和艾丽斯一样年轻。</p>\n<p class=\"source-line\">Mike studies as hard as John. 迈克学习和约翰一样努力。</p>\n<p class=\"source-line\">（2）“A + 动词（否定式）+ as / so + 形容词原级 / 副词原级 + as B.”表示“A 与 B 程度不相同”。</p>\n<p class=\"source-line\">This desk is not as heavy as that one. = This desk is not so heavy as that one.\n这张书桌不如那张书桌重。</p>\n<p class=\"source-line\">（3）“A + 动词 + 倍数 + as + 形容词原级 / 副词原级 + as B.”表示“A 是 B 的几倍”。</p>\n<p class=\"source-line\">The room is twice as large as that one.</p>\n<p class=\"source-line\">这个房间是那个房间的2倍大。</p>\n<p class=\"source-line\">He is three times as heavy as I am. 他是我的3倍重。</p>\n<p class=\"source-line\">（4）当“as ... as”结构涉及数量或程度时,可用“as much + 不可数名词 + as”或“as many + 可数名词复数 + as”表示“……和……一样多”。</p>\n<p class=\"source-line\">He made as much money as I did. 他赚的钱和我一样多。<br/>\nYou made as many mistakes as I did in the exam.<br/>\n你在考试中犯的错误和我一样多。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·昌平区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s56-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Who is <span class=\"blank-token\">____</span>, Li Ping or Wei Fang?</p>","options":["tall","the tallest","taller"],"correct":2,"answer":"C"},{"id":"s56-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Li Lei's bag is <span class=\"blank-token\">____</span> of the three.</p>","options":["so heavy","the heaviest","heavier"],"correct":1,"answer":"B\n解析：由 of the three 可知是三人之间进行比较,故用最高级 the heaviest。"},{"id":"s56-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't work <span class=\"blank-token\">____</span> my sister.</p>","options":["as harder as","so harder as","as hard as"],"correct":2,"answer":"C"},{"id":"s56-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Of all these subjects, I like Chinese <span class=\"blank-token\">____</span>.</p>","options":["best","more","well"],"correct":0,"answer":"A"},{"id":"s56-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Some young people are <span class=\"blank-token\">____</span> to buy private cars now.</p>","options":["enough rich","rather rich","rich enough"],"correct":2,"answer":"C\n解析：enough 作副词时, 用于形容词之后, 故选 rich enough。"},{"id":"s56-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">My cousin is one year <span class=\"blank-token\">____</span> than my brother.</p>","options":["taller","shorter","older"],"correct":2,"answer":"C"},{"id":"s56-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">That's <span class=\"blank-token\">____</span> dinosaur in this hall.</p>","options":["taller","tallest","the tallest"],"correct":2,"answer":"C\n解析：由 in this hall (在这个大厅里) 可知是大厅里的所有恐龙之间进行比较,故用最高级 the tallest。"}],"questionCount":7,"hasAnswers":true},{"source":"textbook","title":"I. 用形容词或副词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s56-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">The street is as <span class=\"blank-token\">____</span> (long) as that one.</p>","options":[],"correct":null,"answer":"long"},{"id":"s56-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Mr Zhang is the <span class=\"blank-token\">____</span> (busy) worker in our workshop.</p>","options":[],"correct":null,"answer":"busiest"},{"id":"s56-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">It is one of the <span class=\"blank-token\">____</span> (big) libraries in China.</p>","options":[],"correct":null,"answer":"biggest"},{"id":"s56-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Lesson One is <span class=\"blank-token\">____</span> (easy) than Lesson Three.</p>","options":[],"correct":null,"answer":"easier"},{"id":"s56-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">My mother often gets up <span class=\"blank-token\">____</span> (early) in the family.</p>","options":[],"correct":null,"answer":"earliest"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s56-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">This box is <span class=\"blank-token\">____</span> that one.</p>","options":["heavy than","so heavy than","heavier as","as heavy as"],"correct":3,"answer":"D"},{"id":"s56-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Dad, could you buy me a computer like this?<br/><br>\n—— Of course, we can buy <span class=\"blank-token\"><strong><em>_</em></strong></span> one than this, but <span class=\"blank-token\">_</span> it.</br></p>","options":["a better; better than","a popular; as good as","a more popular; not as good as","a cheaper; as good as"],"correct":3,"answer":"D"},{"id":"s56-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">This box is <span class=\"blank-token\">____</span> as big as that one.</p>","options":["three","three time","three times","time three"],"correct":2,"answer":"C"},{"id":"s56-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Mary <span class=\"blank-token\">____</span> as careful as Linda.</p>","options":["does","is","has","am"],"correct":1,"answer":"B"},{"id":"s56-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Linda studies as <span class=\"blank-token\">____</span> as Chris.</p>","options":["well","better","best","good"],"correct":0,"answer":"A"},{"id":"s56-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">Tom is not as <span class=\"blank-token\">____</span> as Mike.</p>","options":["taller","tallest","tall","the tallest"],"correct":2,"answer":"C"},{"id":"s56-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">Li Lei <span class=\"blank-token\">____</span> as quickly as Li Ming.</p>","options":["is","run","runs","running"],"correct":2,"answer":"C"},{"id":"s56-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">This house is <span class=\"blank-token\">____</span> as large as that one.</p>","options":["two","twice","second","one"],"correct":1,"answer":"B"},{"id":"s56-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">He is not as tall as <span class=\"blank-token\">____</span>.</p>","options":["me","my","mine","his"],"correct":0,"answer":"A"},{"id":"s56-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\">I am not so <span class=\"blank-token\">____</span> as she is.</p>","options":["heavier","heavy","heaviest","the heaviest"],"correct":1,"answer":"B"}],"questionCount":10,"hasAnswers":true}]},{"id":"s57","section":57,"unit":10,"unitName":"单元10 · 第55–60节","short":"第57节 · L113–114","title":"so、neither 引导的倒装句","lessons":"Lesson 113 — Lesson 114","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>so、neither 引导的倒装句</td>\n<td>so 引导的倒装句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>so、neither 引导的倒装句</td>\n<td>neither 引导的倒装句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">倒装句</div><div class=\"gb\"><p class=\"source-line\">为了强调、突出等目的会颠倒原有语序,这种句式叫倒装句。倒装句分为全部倒装和部分倒装,so 和 neither 引导的倒装句属于部分倒装。so 和 neither 位于分句或句子的开头,这种结构通常表示前面所说的情况也适合另一个人或事物。</p>\n<p class=\"source-line\">He can ride a bike, and so can I.</p>\n<p class=\"source-line\">他会骑自行车,我也会。</p>\n<p class=\"source-line\">They haven't been to the Great Wall.</p>\n<p class=\"source-line\">Neither have I.</p>\n<p class=\"source-line\">他们没去过长城。我也没去过。</p></div></div>\n<div class=\"g\"><div class=\"gt\">so 引导的倒装句</div><div class=\"gb\"><p class=\"source-line\">（1）用法: so 引导的倒装句通常用在肯定句后,意为“……也……”。</p>\n<p class=\"source-line\">（2）结构: So + be 动词 / 助动词 / 情态动词 + 主语.</p>\n<p class=\"source-line\">Tom watched TV last night. So did Ann. 汤姆昨晚看电视了。安也看了。</p>\n<p class=\"source-line\">Lucy is a good student, so is Lily. 露西是一个好学生，莉莉也是。</p>\n<p class=\"source-line\">I can sing. So can Tom. 我会唱歌。汤姆也会。</p>\n<p class=\"source-line\">We will be in the classroom. So will they.</p>\n<p class=\"source-line\">我们将会在这个教室。他们也会在。</p></div></div>\n<div class=\"g\"><div class=\"gt\">neither 引导的倒装句</div><div class=\"gb\"><p class=\"source-line\">（1）用法: neither 引导的倒装句通常用在否定句后,意为“……也不……”。</p>\n<p class=\"source-line\">（2）结构: Neither + be 动词 / 助动词 / 情态动词 + 主语.</p>\n<p class=\"source-line\">I don't eat meat, neither does Helen. 我不吃肉，海伦也不吃。</p>\n<p class=\"source-line\">Tom can't dance, neither can Mary. 汤姆不会跳舞,玛丽也不会。</p>\n<p class=\"source-line\">You haven't been there, neither has Mike. 你没去过那里，迈克也没去过。</p>\n<p class=\"source-line\">Her mother won't go there by bus, neither will she.</p>\n<p class=\"source-line\">她妈妈不会坐公共汽车去那儿，她也不会。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【昆明·西山区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s57-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I can speak English.<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["So I can.","So can you.","So can I.","So do I."],"correct":2,"answer":"C"},{"id":"s57-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">They have all got up, and <span class=\"blank-token\">____</span>.</p>","options":["Jack has too","so has Jack","Jack hasn't","also has Jack"],"correct":1,"answer":"B"},{"id":"s57-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">He didn't know the answer, and <span class=\"blank-token\">____</span>.</p>","options":["neither did I","I did neither","so did I","I did so"],"correct":0,"answer":"A"},{"id":"s57-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— My mum doesn't allow me <span class=\"blank-token\"><strong><em>_</em></strong></span> other's homework.<br/><br>\n—— <span class=\"blank-token\">_</span> does my mum.</br></p>","options":["copy; Nor","to copy; Neither","copying; So","copy; Also"],"correct":1,"answer":"B\n解析：第一个空考查动词不定式, allow sb. to do sth. 意为 “允许某人做某事”; 由于第一个句子为否定句, 所以第二个空要用 neither。故选 B。"},{"id":"s57-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I don’t like watching TV ads.<br/><br>\n—— <span class=\"blank-token\">____</span>. I think watching TV ads is just a waste of time.</br></p>","options":["So I do","Neither do I","Neither did I","So did I"],"correct":1,"answer":"B"},{"id":"s57-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Most students like chatting on the Internet. <span class=\"blank-token\">____</span> Alice.</p>","options":["So does","So do","Neither does","Neither do"],"correct":0,"answer":"A"},{"id":"s57-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I’ve never been to Beijing, Judy.<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["So have I.","Neither am I.","Neither have I.","So I have."],"correct":2,"answer":"C\n解析：由 “I’ve never been to Beijing, Judy. (我从来没去过北京,朱迪。)” 可知答语应表达 “我也没去过”。第一个句子中有 never (从不) 表否定,时态为现在完成时,故用 neither 引导的倒装句回答。故选 C。"},{"id":"s57-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— He swam in the river this summer.<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["So do he.","So she did.","So did she.","So does she."],"correct":2,"answer":"C"},{"id":"s57-practice-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Mary has made great progress this term.<br/><br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong></span> and <span class=\"blank-token\">_</span>.</br></p>","options":["So she has; so have you","So she has; so you have","So has she; so you have","So has she; so have you"],"correct":0,"answer":"A"}],"questionCount":9,"hasAnswers":true},{"source":"textbook","title":"I. 根据 so、neither 引导的倒装句句式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s57-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">He can ride a bike. <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> I.</p>","options":[],"correct":null,"answer":"So can"},{"id":"s57-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">The boy came, and a week later, <span class=\"blank-token\">____</span> his friend.</p>","options":[],"correct":null,"answer":"so did"},{"id":"s57-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Tom doesn't like bananas. <span class=\"blank-token\">____</span> his wife.</p>","options":[],"correct":null,"answer":"Neither does"},{"id":"s57-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">If you don't go, <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> I.</p>","options":[],"correct":null,"answer":"neither do"},{"id":"s57-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">He is a teacher. <span class=\"blank-token\">____</span> his wife.</p>","options":[],"correct":null,"answer":"So is"},{"id":"s57-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">She hasn't seen that film. <span class=\"blank-token\">____</span> I.</p>","options":[],"correct":null,"answer":"Neither have"},{"id":"s57-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">He doesn't like football. <span class=\"blank-token\">____</span> I.</p>","options":[],"correct":null,"answer":"Neither do"},{"id":"s57-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">They couldn't afford to stay there. <span class=\"blank-token\">____</span> I.</p>","options":[],"correct":null,"answer":"Neither could"},{"id":"s57-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">He has been to Beijing. <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> I.</p>","options":[],"correct":null,"answer":"So have"},{"id":"s57-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">Li Wei can't answer the question. <span class=\"blank-token\">____</span> I.</p>","options":[],"correct":null,"answer":"Neither can"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s57-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">If Joe's wife doesn't go to the party, <span class=\"blank-token\">____</span>.</p>","options":["he will either","neither will he","he neither will","either he will"],"correct":1,"answer":"B"},{"id":"s57-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">You forgot your purse. <span class=\"blank-token\">____</span> Mary.</p>","options":["So did","So was","Did so","Neither did"],"correct":0,"answer":"A"},{"id":"s57-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I don't know that Jim quarrelled with his brother.<br/><br>\n—— <span class=\"blank-token\">____</span></br></p>","options":["Nor don't I.","Neither do I.","I don't neither.","Neither I do."],"correct":1,"answer":"B"}],"questionCount":3,"hasAnswers":true}]},{"id":"s58","section":58,"unit":10,"unitName":"单元10 · 第55–60节","short":"第58节 · L115–116","title":"不定代词","lessons":"Lesson 115 — Lesson 116","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>不定代词</td>\n<td>不定代词的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>不定代词</td>\n<td>不定代词的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">不定代词的概念</div><div class=\"gb\"><p class=\"source-line\">不定代词用来指代不确定的人或事物。下表中，由 -one、-body、-thing 构成的是复合不定代词；由 -where 构成的是不定副词。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>every-</th>\n<th>no-</th>\n<th>any-</th>\n<th>some-</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>everyone 每个人</td>\n<td>no one 没有人</td>\n<td>anyone 任何人</td>\n<td>someone 某人</td>\n</tr>\n<tr>\n<td>everybody 每个人</td>\n<td>nobody 没有人</td>\n<td>anybody 任何人</td>\n<td>somebody 某人</td>\n</tr>\n<tr>\n<td>everything 一切事物</td>\n<td>nothing 没有任何事物</td>\n<td>anything 任何事物</td>\n<td>something 某事物</td>\n</tr>\n<tr>\n<td>everywhere 到处</td>\n<td>nowhere 无处</td>\n<td>anywhere 任何地方</td>\n<td>somewhere 某处</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">不定代词的用法</div><div class=\"gb\"><p class=\"source-line\">（1）不定代词作主语,谓语动词用单数。</p>\n<p class=\"source-line\">Is everyone here today? 今天大家都到了吗？</p>\n<p class=\"source-line\">There is nothing wrong with the radio. 收音机没有毛病。</p>\n<p class=\"source-line\">（2）不定代词的定语要后置。</p>\n<p class=\"source-line\">（1）不定代词+形容词</p>\n<p class=\"source-line\">Can you find anyone else? 你能找到其他人吗？</p>\n<p class=\"source-line\">I have something important to tell you. 我有重要的事要告诉你。</p>\n<p class=\"source-line\">（2）不定代词+动词不定式(to do)</p>\n<p class=\"source-line\">Would you like something to eat?</p>\n<p class=\"source-line\">你想吃什么？</p>\n<p class=\"source-line\">（3）不定代词 some- 常用于肯定句中（表达请求、提建议或希望得到肯定回答的疑问句中也可以用 some-）。</p>\n<p class=\"source-line\">He found something strange but interesting. 他发现了一些奇怪但有趣的事情。</p>\n<p class=\"source-line\">Will you please bring something to the party? 请你带一些东西来参加聚会好吗？</p>\n<p class=\"source-line\">（4）不定代词 any- 常用于否定句或疑问句中。</p>\n<p class=\"source-line\">I can't meet anybody on the island. 在岛上,我没遇见任何人。</p>\n<p class=\"source-line\">Is there anything wrong with the car? 小汽车有什么毛病吗?</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【合肥·包河区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s58-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Children mean <span class=\"blank-token\">____</span> to some parents in China.</p>","options":["something","everything","anything","nothing"],"correct":1,"answer":"B\n解析：此题意为“对于中国的一些父母，孩子意味着全部”。everything符合题意，故选B。"},{"id":"s58-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Is there <span class=\"blank-token\">____</span> in today's morning news on CCTV?</p>","options":["anything special","special anything","something special","special something"],"correct":0,"answer":"A"},{"id":"s58-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">We will have a sports meeting in October, but <span class=\"blank-token\">____</span> knows the date for sure.</p>","options":["everybody","nobody","anybody","somebody"],"correct":1,"answer":"B\n解析：but 意为 “但是”, 表示转折, nobody (没有人) 符合题意, 故选 B。"},{"id":"s58-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Would you like <span class=\"blank-token\">____</span> to buy?<br/><br>\n—— Yes, a bottle of water.</br></p>","options":["something else","nothing else","else something","anything else"],"correct":0,"answer":"A\n解析：表示建议或请求的疑问句中复合不定代词用 something, else 用于复合不定代词之后。"},{"id":"s58-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Our teacher was very happy because <span class=\"blank-token\">____</span> failed the exam.</p>","options":["somebody","nobody","anybody","everybody"],"correct":1,"answer":"B"},{"id":"s58-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">The light went out suddenly. It was very dark and <span class=\"blank-token\">____</span> could be seen clearly.</p>","options":["anything","something","nothing","everything"],"correct":2,"answer":"C"},{"id":"s58-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What else do you need?<br/><br>\n—— <span class=\"blank-token\">____</span> else. I’ve got enough. Thanks.</br></p>","options":["Nothing","Anything","Something","Everything"],"correct":0,"answer":"A"},{"id":"s58-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> in the world is perfect, that is, <span class=\"blank-token\">_</span> has shortcomings.</p>","options":["Nobody; somebody","No one; everyone","Someone; anyone","Not everybody; each one"],"correct":1,"answer":"B"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"I. 根据所给词填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s58-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I'm hungry. I want <span class=\"blank-token\">____</span> (anything) to eat.</p>","options":[],"correct":null,"answer":"something"},{"id":"s58-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Do you have <span class=\"blank-token\">____</span> (something) to say?</p>","options":[],"correct":null,"answer":"anything"},{"id":"s58-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">Why not ask <span class=\"blank-token\">____</span> (someone) to help you?</p>","options":[],"correct":null,"answer":"someone"},{"id":"s58-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Is there <span class=\"blank-token\">____</span> (something) important in today's newspaper?</p>","options":[],"correct":null,"answer":"anything"},{"id":"s58-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">Did you do <span class=\"blank-token\">____</span> (something) interesting last summer vacation?</p>","options":[],"correct":null,"answer":"anything"},{"id":"s58-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">Hello, Jenny. I can't find my math book <span class=\"blank-token\">____</span> (somewhere). Did you see it?</p>","options":[],"correct":null,"answer":"anywhere"},{"id":"s58-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">There isn't <span class=\"blank-token\">____</span> (some) tea in the cup.</p>","options":[],"correct":null,"answer":"any"},{"id":"s58-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">Can I have <span class=\"blank-token\">____</span> (some) hot dogs?</p>","options":[],"correct":null,"answer":"some"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s58-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Would you like <span class=\"blank-token\">____</span> to eat?</p>","options":["nobody","everyone","something","anywhere"],"correct":2,"answer":"C"},{"id":"s58-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">The room was empty, but Betty felt that <span class=\"blank-token\">____</span> was watching her.</p>","options":["everybody","somebody","nobody","anybody"],"correct":1,"answer":"B"},{"id":"s58-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">There isn't <span class=\"blank-token\">____</span> water in the glass.</p>","options":["some","any","a","many"],"correct":1,"answer":"B"},{"id":"s58-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm not busy. I haven't <span class=\"blank-token\">____</span> to do.</p>","options":["something","everything","nothing","anything"],"correct":3,"answer":"D"}],"questionCount":4,"hasAnswers":true}]},{"id":"s59","section":59,"unit":10,"unitName":"单元10 · 第55–60节","short":"第59节 · L117–118","title":"过去进行时","lessons":"Lesson 117 — Lesson 118","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>过去进行时</td>\n<td>句式结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>过去进行时</td>\n<td>用法</td>\n<td>★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>过去进行时</td>\n<td>when和while引导的时间状语从句的区别</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">过去进行时</div><div class=\"gb\"><p class=\"source-line\">过去进行时表示在过去某一时刻或某一段时间内正在进行或发生的动作。过去进行时常和表示过去的时间状语连用。</p>\n<p class=\"source-line\">He was having breakfast at seven o'clock yesterday morning.</p>\n<p class=\"source-line\">他昨天早上7:00正在吃早饭。</p>\n<p class=\"source-line\">I was writing stories the whole morning.</p>\n<p class=\"source-line\">我整个早上都在写故事。</p></div></div>\n<div class=\"g\"><div class=\"gt\">过去进行时的句式结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定句: 主语 + was / were + 动词 -ing 形式（+其他）.</p>\n<p class=\"source-line\">I was watching TV at eight last night.</p>\n<p class=\"source-line\">我昨晚 8:00 正在看电视。</p>\n<p class=\"source-line\">（2）否定句: 主语 + was / were not + 动词 -ing 形式（+其他）.</p>\n<p class=\"source-line\">I was not watching TV at eight last night.</p>\n<p class=\"source-line\">我昨晚 8:00 没在看电视。</p>\n<p class=\"source-line\">（3）一般疑问句: Was / Were + 主语 + 动词 -ing 形式（+其他）?</p>\n<p class=\"source-line\">—— Were you watching TV at eight last night? 你昨晚8:00正在看电视吗?<br/>\n—— Yes, I was. 是的,我正在看电视。<br/>\n—— No, I wasn't. 不,我没在看电视。</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + was / were + 主语 + 动词 -ing 形式（+其他）?</p>\n<p class=\"source-line\">Who was watching TV at eight last night? 昨晚 8:00 谁正在看电视?\nWhat were you doing at eight last night? 你昨晚 8:00 正在做什么?\nWhen were you watching TV? 你什么时候正在看电视?</p></div></div>\n<div class=\"g\"><div class=\"gt\">过去进行时的用法</div><div class=\"gb\"><p class=\"source-line\">（1）表示在过去某一时刻正在进行的动作。</p>\n<p class=\"source-line\">My mother and I were dancing at eight yesterday evening.</p>\n<p class=\"source-line\">昨晚 8:00, 我和妈妈正在跳舞。</p>\n<p class=\"source-line\">（2）表示在过去某一段时间内一直在进行的动作。</p>\n<p class=\"source-line\">I was playing games the whole night. 我整个晚上都在玩儿游戏。</p>\n<p class=\"source-line\">（3）表示过去反复性或习惯性的动作,也可以表示满意、称赞、惊讶、厌恶等,通常与 always、forever 等副词连用。</p>\n<p class=\"source-line\">Li Ming was always thinking of others. 李明总是想着别人。（赞扬）</p>\n<p class=\"source-line\">He was always talking in class. 他总是在课堂上说话。（厌烦）</p>\n<p class=\"source-line\"><code>txt\n表示过去进行时的时间状语\nthe whole morning 整个上午\nfrom 8 to 9 last night 昨晚从 8:00 到 9:00\nat 9 o'clock last night 在昨晚 9:00</code></p>\n<p class=\"source-line\">all day yesterday 昨天一天\nat that moment / time 在那一刻 / 在那时</p>\n<p class=\"source-line\">（4）表示一个动作发生时,另外一个动作正在进行。此时常与 when、while、as 引导的时间状语从句连用。</p>\n<p class=\"source-line\">When his mother came in, he was doing his homework.</p>\n<p class=\"source-line\">当他妈妈进来的时候,他正在做家庭作业。</p></div></div>\n<div class=\"g\"><div class=\"gt\">when 和 while 引导的时间状语从句的区别</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>引导词</th>\n<th>所指时间</th>\n<th>从句谓语</th>\n<th>动作关系</th>\n<th>常见时态</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>when</td>\n<td>时间点或时间段</td>\n<td>可用延续性动词，也可用非延续性动词</td>\n<td>主句和从句动作可同时发生，也可先后发生</td>\n<td>从句常用一般过去时</td>\n</tr>\n<tr>\n<td>while</td>\n<td>时间段</td>\n<td>通常用延续性动词或表示状态的动词</td>\n<td>主句和从句动作通常同时发生</td>\n<td>从句常用过去进行时</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">When I came home, my mother was cooking.</p>\n<p class=\"source-line\">当我回家的时候,我妈妈正在做饭。</p>\n<p class=\"source-line\">由 when 引导的一般过去时的从句, come 为非延续性动词。</p>\n<p class=\"source-line\">While he was reading, his friend came to see him.</p>\n<p class=\"source-line\">当他正在看书的时候,他的朋友来看他了。</p>\n<p class=\"source-line\">由 while 引导的过去进行时的从句, read 为延续性动词。</p>\n<p class=\"source-line\">She was sleeping while her sister was reading.</p>\n<p class=\"source-line\">她正在睡觉，而她姐姐正在看（书）。</p>\n<p class=\"source-line\">强调两个动作同时发生,主句和从句都用过去进行时,用while引导。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【惠州·惠城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s59-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Eric <span class=\"blank-token\">____</span> books when it began to rain heavily.</p>","options":["reads","are reading","were reading","was reading"],"correct":3,"answer":"D\n解析：句子是由 when 引导的时间状语从句。由 began 可知从句的时态是一般过去时, 主句的时态应为过去进行时。主语 Eric 是第三人称单数, be 应用 was, 故选 D。"},{"id":"s59-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you know where Tom is?<br/><br>\n—— Yes, he's in Room 203. When I saw him, he <span class=\"blank-token\">____</span> a drum.</br></p>","options":["beat","is beating","was beating","were beating"],"correct":2,"answer":"C"},{"id":"s59-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> on the computer when Frank called me.</p>","options":["was working","will work","worked","am working"],"correct":0,"answer":"A"},{"id":"s59-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Why didn't you open the door if you were at home?<br/><br>\n—— I <span class=\"blank-token\">____</span> a shower.</br></p>","options":["am taking","take","took","was taking"],"correct":3,"answer":"D"},{"id":"s59-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">Paul <span class=\"blank-token\">____</span> the report at 9 yesterday morning.</p>","options":["writes","was writing","write","has written"],"correct":1,"answer":"B"},{"id":"s59-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I met a good friend of mine while I <span class=\"blank-token\">____</span> on the street.</p>","options":["walk","walked","am walking","was walking"],"correct":3,"answer":"D\n解析：句子是由 while 引导的时间状语从句。由 met 可知主句的时态为一般过去时, 从句的时态应使用过去进行时。主语是 I, be 应用 was, 故选 D。"},{"id":"s59-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">He fell asleep while he <span class=\"blank-token\">____</span> books.</p>","options":["is reading","reads","was reading","read"],"correct":2,"answer":"C"}],"questionCount":7,"hasAnswers":true},{"source":"practice","title":"【昆明·官渡区】按要求完成下列各题。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s59-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">I was <u>talking to my uncle on the phone</u> when my father came in. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What were you doing when your father came in?\n解析：对做某事进行提问疑问词用 what, 主语为 you, be 用 were。"},{"id":"s59-practice-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">He was <u>watching TV</u> at 6:00 p.m. yesterday. (对画线部分提问)</p>","options":[],"correct":null,"answer":"What was he doing at 6:00 p.m. yesterday?"},{"id":"s59-practice-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">While we were waiting for the bus, it began to rain. (改为同义句)</p>","options":[],"correct":null,"answer":"We were waiting for the bus when it began to rain."},{"id":"s59-practice-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">I was having dinner at my friend's last night. (改为一般疑问句)</p>","options":[],"correct":null,"answer":"Were you having dinner at your friend's last night?"},{"id":"s59-practice-q012","number":12,"type":"input","questionHtml":"<p class=\"source-line\">Jeff was watching CCTV news at 7:10 yesterday evening. (改为否定句)</p>","options":[],"correct":null,"answer":"Jeff wasn't watching CCTV news at 7:10 yesterday evening.\n解析：过去进行时的肯定句变否定句时, 在 be 后加 not 即可。"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s59-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> (have) supper when the phone rang.</p>","options":[],"correct":null,"answer":"were having"},{"id":"s59-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> (climb) the hill at 2:30 yesterday afternoon.</p>","options":[],"correct":null,"answer":"was climbing"},{"id":"s59-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (watch) TV when you called me.</p>","options":[],"correct":null,"answer":"was watching"},{"id":"s59-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">While we <span class=\"blank-token\"><strong><em>_</em></strong></span> (read) the story, the bell <span class=\"blank-token\">_</span> (ring) last night.</p>","options":[],"correct":null,"answer":"were reading, rang"},{"id":"s59-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">When you <span class=\"blank-token\"><strong><em>_</em></strong></span> (see) me last night, I <span class=\"blank-token\">_</span> (do) some washing.</p>","options":[],"correct":null,"answer":"saw, was doing"},{"id":"s59-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">She said she <span class=\"blank-token\">____</span> (watch) TV at this time yesterday.</p>","options":[],"correct":null,"answer":"was watching"},{"id":"s59-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> he <span class=\"blank-token\">_</span> (lie) on the ground at nine yesterday evening?</p>","options":[],"correct":null,"answer":"Was, lying"},{"id":"s59-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\"><strong><em>_</em></strong></span> Jim <span class=\"blank-token\">_</span> (write) when the teacher came in?</p>","options":[],"correct":null,"answer":"was, writing"},{"id":"s59-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">Were you <span class=\"blank-token\">____</span> (sleep) when the earthquake happened?</p>","options":[],"correct":null,"answer":"sleeping"},{"id":"s59-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">They <span class=\"blank-token\">____</span> (plan) a trip to Shanghai at this time yesterday.</p>","options":[],"correct":null,"answer":"were planning"}],"questionCount":10,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s59-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I saw your light still on at 11:30 last night.<br/><br>\n—— Oh, I <span class=\"blank-token\">____</span> an exciting book at that time. I lost myself in the story.</br></p>","options":["read","am reading","was reading","were reading"],"correct":2,"answer":"C"},{"id":"s59-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">At four o'clock yesterday afternoon, my father <span class=\"blank-token\">____</span> for me at the school gate.</p>","options":["waits","waited","was waiting","is waiting"],"correct":2,"answer":"C"},{"id":"s59-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">Tom <span class=\"blank-token\">____</span> up at six o'clock every day that week.</p>","options":["getting","was getting","get","to get"],"correct":1,"answer":"B"},{"id":"s59-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">It <span class=\"blank-token\">____</span> hard when I left my office.</p>","options":["rain","is raining","rains","was raining"],"correct":3,"answer":"D"},{"id":"s59-text-q015","number":15,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> basketball at four yesterday afternoon?</p>","options":["Were; playing","Was; playing","Are; playing","Is; play"],"correct":0,"answer":"A"},{"id":"s59-text-q016","number":16,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\">____</span> supper when the phone rang.</p>","options":["were having","was having","are having","is having"],"correct":0,"answer":"A"},{"id":"s59-text-q017","number":17,"type":"mcq","questionHtml":"<p class=\"source-line\">This time yesterday Jack <span class=\"blank-token\">____</span> TV.</p>","options":["was watching","were watching","is watching","are watching"],"correct":0,"answer":"A"},{"id":"s59-text-q018","number":18,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> if you could give me a lift.</p>","options":["is wondered","are wondered","was wondering","were wondering"],"correct":2,"answer":"C"}],"questionCount":8,"hasAnswers":true}]},{"id":"s60","section":60,"unit":10,"unitName":"单元10 · 第55–60节","short":"第60节 · L119–120","title":"过去完成时","lessons":"Lesson 119 — Lesson 120","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>过去完成时</td>\n<td>概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>过去完成时</td>\n<td>过去完成时的标志词</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>过去完成时</td>\n<td>过去完成时的句式结构</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是过去完成时</div><div class=\"gb\"><p class=\"source-line\">表示在过去的某一时间或动作之前已经发生或完成的动作 / 状态, 即发生在 “过去的过去”。</p>\n<p class=\"source-line\">When we got to the cinema, the film had begun.</p>\n<p class=\"source-line\">当我们到达电影院时,电影已经开始了。</p>\n<p class=\"source-line\">We had reached the top of the hill before midnight.</p>\n<p class=\"source-line\">在半夜之前,我们已登上了山顶。</p></div></div>\n<div class=\"g\"><div class=\"gt\">过去完成时的标志词</div><div class=\"gb\"><p class=\"source-line\">过去完成时中会有表示过去的时间点,才会存在“过去的过去”这个概念。常用于过去完成时中的标志词如下:</p>\n<p class=\"source-line\">（1）by + 过去时间点（到……为止）</p>\n<p class=\"source-line\">I had finished reading the novel by nine o'clock last night.</p>\n<p class=\"source-line\">到昨晚 9:00 为止,我已看完这本小说了。</p>\n<p class=\"source-line\">（2）by the end of + 过去时间点（到……末）</p>\n<p class=\"source-line\">We had learned over three hundred English words by the end of last term.</p>\n<p class=\"source-line\">到上学期末,我们已经学了300多个英语单词。</p>\n<p class=\"source-line\">（3）before + 过去时间点（在……之前）</p>\n<p class=\"source-line\">He had written three novels before last year.</p>\n<p class=\"source-line\">在去年之前，他已经写了3本小说了。</p></div></div>\n<div class=\"g\"><div class=\"gt\">过去完成时的句式结构</div><div class=\"gb\"><p class=\"source-line\">（1）肯定句: 主语 + had + 动词过去分词 + 其他.</p>\n<p class=\"source-line\">I had finished my homework by last night.</p>\n<p class=\"source-line\">到昨晚为止,我已经完成了作业。</p>\n<p class=\"source-line\">（2）否定句: 主语 + had not + 动词过去分词 + 其他.</p>\n<p class=\"source-line\">I had not finished my homework by last night.</p>\n<p class=\"source-line\">到昨晚为止,我还没有完成作业。</p>\n<p class=\"source-line\">（3）一般疑问句: Had + 主语 + 动词过去分词 + 其他?</p>\n<p class=\"source-line\">Had you finished your homework by last night?</p>\n<p class=\"source-line\">到昨晚为止,你完成作业了吗?</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + had + 主语 + 动词过去分词 + 其他?</p>\n<p class=\"source-line\">What had you finished by last night?</p>\n<p class=\"source-line\">到昨晚为止,你完成了什么?</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【惠州·惠城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s60-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">By the time I got into the classroom, the teacher <span class=\"blank-token\">____</span> the test papers.</p>","options":["had handed out","handed out","has handed out"],"correct":0,"answer":"A"},{"id":"s60-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— You look unhappy. What happened?<br/><br>\n—— Bad luck. I planned to go to Beijing, but the plane <span class=\"blank-token\"><strong><em>_</em></strong></span> when I <span class=\"blank-token\">_</span> at the airport.</br></p>","options":["has left; arrived","had left; arrived","left; arrives"],"correct":1,"answer":"B"},{"id":"s60-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— You look sad. What's wrong with you?<br/><br>\n—— I had a bad morning. By the time I got to school, I found I <span class=\"blank-token\">____</span> my homework at home.</br></p>","options":["have forgotten","had forgotten","had left"],"correct":2,"answer":"C\n解析：根据 “By the time I got to school” 可知横线处所在句子时态应为过去完成时。had left my homework at home 意为 “把我的作业落在家里了”,故选 C。"},{"id":"s60-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\"><strong><em>_</em></strong></span> already <span class=\"blank-token\">_</span> 5,000 words by the end of last year.</p>","options":["have ; learned","had ; learned","are ; learning"],"correct":1,"answer":"B"},{"id":"s60-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> all Harry Potter books by the time I was ten.</p>","options":["read","have read","had read"],"correct":2,"answer":"C\n解析：根据 “by the time I was ten” 可知主句时态应为过去完成时, 故选 C。"},{"id":"s60-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">When the doctor arrived, the patient <span class=\"blank-token\">____</span> for just one minute.</p>","options":["has died","had died","had been dead"],"correct":2,"answer":"C\n解析：根据 “when the doctor arrived” 可知主句时态应为过去完成时。“for + 时间” 表示持续一段时间, had died 不能与其连用。故选 C。"},{"id":"s60-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Miss Wang <span class=\"blank-token\">____</span> the office for a few minutes when I arrived. I didn't meet her.</p>","options":["had been away from","has left","has been away from"],"correct":0,"answer":"A\n解析：根据 “when I arrived” 可知主句时态应为过去完成时, 故选 A。"},{"id":"s60-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What happened to you on April Fool's Day?<br/><br>\n—— I was the only one at school on Saturday. I realized that I <span class=\"blank-token\">____</span> by my classmates.</br></p>","options":["am fooled","had been fooled","had fooled"],"correct":1,"answer":"B"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"I. 用所给词的正确形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s60-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">I didn't meet him. He <span class=\"blank-token\">____</span> (leave) when I got there.</p>","options":[],"correct":null,"answer":"had left"},{"id":"s60-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">When we reached the town, it <span class=\"blank-token\">____</span> (get) dark.</p>","options":[],"correct":null,"answer":"had got"},{"id":"s60-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">The robbers <span class=\"blank-token\">____</span> (run away) before the policemen arrived.</p>","options":[],"correct":null,"answer":"had run away"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s60-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Mary asked me <span class=\"blank-token\">____</span> during the Spring Festival.</p>","options":["where I had finished","where I had gone","where had I finished","where had I gone"],"correct":1,"answer":"B"},{"id":"s60-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\"><strong><em>_</em></strong></span> Peter <span class=\"blank-token\">_</span> by the time he left Beijing?</p>","options":["did; do","has; done","did; did","had; done"],"correct":3,"answer":"D"},{"id":"s60-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> 1,000 English words by the end of last term.</p>","options":["learned","was learning","had learned","was learned"],"correct":2,"answer":"C"}],"questionCount":3,"hasAnswers":true}]},{"id":"s61","section":61,"unit":11,"unitName":"单元11 · 第61–66节","short":"第61节 · L121–122","title":"定语从句","lessons":"Lesson 121 — Lesson 122","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>定语从句</td>\n<td>定语从句概述</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>定语从句</td>\n<td>关系代词引导的定语从句</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">定语从句概述</div><div class=\"gb\"><h5>1. 定义和例句</h5>\n<p class=\"source-line\">用作定语的从句称为定语从句。定语从句通常位于被修饰词(即先行词)之后,由关系代词或关系副词引导。</p>\n<p class=\"source-line\">The vase that I broke yesterday was very expensive.</p>\n<p class=\"source-line\">我昨天打坏的花瓶是很昂贵的。</p>\n<p class=\"source-line\">The boy who helped you yesterday is my neighbour.</p>\n<p class=\"source-line\">昨天帮助了你的男孩儿是我的邻居。</p>\n<p class=\"source-line\">This is the teaching building which was built last year. 这就是去年建成的教学楼。</p>\n<h5>2. 先行词和关系词</h5>\n<p class=\"source-line\">被定语从句所修饰的词是先行词。指代先行词,放在先行词和定语从句之间起连接作用,同时又充当定语从句的某一成分(主语、宾语、表语、状语、定语等)的词叫关系词。其中关系代词有 who、whom、that、whose、which 等,关系副词有 when、where、why 等。</p>\n<p class=\"source-line\">关系词代替先行词在定语从句中充当句子成分,因此定语从句中不能再重复出现相当于先行词的词。</p>\n<p class=\"source-line\"><code>txt\n例如: This is the pen that you are looking for. (√)\nThis is the pen that you are looking for the pen. (×)\n这就是你一直在找的那只钢笔。</code></p></div></div>\n<div class=\"g\"><div class=\"gt\">关系代词引导的定语从句</div><div class=\"gb\"><p class=\"source-line\">引导定语从句的关系代词有 who、whom、whose、that、which 等,关系代词在从句中作主语、宾语、表语或定语,其主要用法如下:</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>关系代词</th>\n<th>先行词</th>\n<th>在从句中的作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>who</td>\n<td>人</td>\n<td>主语、宾语、表语</td>\n</tr>\n<tr>\n<td>whom</td>\n<td>人</td>\n<td>宾语</td>\n</tr>\n<tr>\n<td>whose</td>\n<td>人或物</td>\n<td>定语</td>\n</tr>\n<tr>\n<td>that</td>\n<td>人或物</td>\n<td>主语、宾语、表语</td>\n</tr>\n<tr>\n<td>which</td>\n<td>物</td>\n<td>主语、宾语、表语</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">口诀</div><p class=\"source-line\">关系代词引定从,它们用法须分清。\nthat 可作主与宾,指人指物都能行。\nwhich 用来指代物,主语宾语都可充。\nwho 和 whom 只指人,作主作宾不相同。\nwhose 一词作用大,表人表物都能用。</p></div>\n<h5>1. who 和 whom 引导的定语从句</h5>\n<p class=\"source-line\">二者都用于指人。who 在定语从句中作主语、宾语或表语，whom 在定语从句中作宾语。</p>\n<p class=\"source-line\">The man who is playing basketball is Xiao Han.</p>\n<p class=\"source-line\">正在打篮球的那个男人是肖涵。</p>\n<p class=\"source-line\">whom 在定语从句中作介词的宾语,介词提到 whom 前面时, whom 不能用 who 代替。\n例如: The man to whom you just talked is Mike. (√)\nThe man to who you just talked is Mike. (×)\n刚刚跟你说话的那个男人是迈克。</p>\n<h5>2. which 引导的定语从句</h5>\n<p class=\"source-line\">which 指物,在定语从句中作主语、宾语或表语。作宾语的关系代词 which 可以省略(放在介词后除外)。</p>\n<p class=\"source-line\">This is the book (which) I want to buy.</p>\n<p class=\"source-line\">这是我要买的那本书。(作宾语,可省略)</p>\n<p class=\"source-line\">The building in which Xiao Mei studied was very old.</p>\n<p class=\"source-line\">肖梅在里面学习的那栋楼很旧。(介词提前,不能省略)</p>\n<h5>3. that 引导的定语从句</h5>\n<p class=\"source-line\">that 既可以指人,也可以指物,在定语从句中作主语、宾语或表语。作宾语时可以省略。在从句中作介词宾语时,介词不可以提到 that 之前,若介词提前,指物用 which,指人用 whom。</p>\n<p class=\"source-line\">She doesn't like the songs that are too long.</p>\n<p class=\"source-line\">她不喜欢那些太长的歌。(作主语,指物)</p>\n<p class=\"source-line\">The lessons (that) he taught were not easily forgotten.</p>\n<p class=\"source-line\">他教的课不容易被忘记。(作宾语,指物,可省略)</p>\n<h5>4. whose 引导的定语从句</h5>\n<p class=\"source-line\">whose 可以指人也可以指物,在定语从句中作定语。</p>\n<p class=\"source-line\">This is the student whose bike was broken last week.</p>\n<p class=\"source-line\">这就是上周自行车坏了的那个学生。(指人,相当于 the student's)\nWe want a room whose window looks out over the sea.</p>\n<p class=\"source-line\">我们想要一个窗户朝向大海的房间。(指物,相当于 the room's)</p>\n<p class=\"source-line\">关系副词在定语从句中充当状语。常用的关系副词有 when、where、why 等，在从句中分别充当时间状语、地点状语和原因状语。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·昌平区】在下列题目中选出错误的选项并改正。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s61-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Mr. Brown is talking to the students <u>which</u> come from Canada.（改正画线部分）</p>","options":[],"correct":null,"answer":"C which 改成 who\n解析：先行词 the students 表示人,关系代词应使用 who,在定语从句中作主语。"},{"id":"s61-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">The factory in <u>that</u> we are going to work is far from here.（改正画线部分）</p>","options":[],"correct":null,"answer":"A that 改成 which\n解析：定语从句中的介词不可以提到 that 之前, 若介词提前, 指物用 which, 故应把 that 改成 which。"},{"id":"s61-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">This is the child <u>who</u> father died last year.（改正画线部分）</p>","options":[],"correct":null,"answer":"C who 改成 whose\n解析：先行词 the child 表示人,关系代词应使用 whose,在定语从句中作定语。"},{"id":"s61-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">I went to the library, but I didn't find the book that I needed <u>it</u>.（改正画线部分）</p>","options":[],"correct":null,"answer":"D 删掉 it"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【黑龙江·绥化】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s61-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I like smart clothes <span class=\"blank-token\">____</span> are made of silk.</p>","options":["who","which","what"],"correct":1,"answer":"B\n解析：先行词 clothes 表示物,关系代词应用 that 或 which,故选 B。"},{"id":"s61-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I like music <span class=\"blank-token\">____</span> I can dance to.</p>","options":["that","what","who"],"correct":0,"answer":"A"},{"id":"s61-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">They are the ones <span class=\"blank-token\">____</span> help you out when you are in need.</p>","options":["whom","who","whose"],"correct":1,"answer":"B\n解析：先行词 the ones 表示帮助你的人,关系代词作主语,故选 B。"},{"id":"s61-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you know the woman <span class=\"blank-token\">____</span> wears a blue sweater?</p>","options":["who","whom","/"],"correct":0,"answer":"A\n解析：先行词 the woman 表示人,关系代词作主语且不能省略,故选 A。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s61-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The place <span class=\"blank-token\">____</span> interested me most was the Children's Palace.</p>","options":["that","where","what","who"],"correct":0,"answer":"A"},{"id":"s61-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">She is wearing the hat <span class=\"blank-token\">____</span> I wore yesterday.</p>","options":["what","which","as","in which"],"correct":1,"answer":"B"},{"id":"s61-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">The factory <span class=\"blank-token\">____</span> we'll visit next week is not far from here.</p>","options":["where","to which","which","in which"],"correct":2,"answer":"C"},{"id":"s61-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you know the man <span class=\"blank-token\">____</span> is talking with your father?</p>","options":["whose","who","which","what"],"correct":1,"answer":"B"},{"id":"s61-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The boys <span class=\"blank-token\">____</span> the teacher talked to are from Class One.</p>","options":["when","which","who","while"],"correct":2,"answer":"C"},{"id":"s61-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Those <span class=\"blank-token\">____</span> want to go to the museum must be at the school gate at 7 tomorrow morning.</p>","options":["who","which","whom","that"],"correct":0,"answer":"A"},{"id":"s61-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">She is a teacher <span class=\"blank-token\">____</span> has much teaching experience.</p>","options":["whose","who","whom","what"],"correct":1,"answer":"B"},{"id":"s61-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What are you looking for?<br/><br>\n—— I'm looking for the dictionary <span class=\"blank-token\">____</span> you lent me last week.</br></p>","options":["who","what","that","whose"],"correct":2,"answer":"C"}],"questionCount":8,"hasAnswers":true}]},{"id":"s62","section":62,"unit":11,"unitName":"单元11 · 第61–66节","short":"第62节 · L123–124","title":"感叹句","lessons":"Lesson 123 — Lesson 124","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>感叹句</td>\n<td>概念</td>\n<td>★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>感叹句</td>\n<td>how和what引导的感叹句</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是感叹句</div><div class=\"gb\"><p class=\"source-line\">用来表示说话人强烈的喜、怒、哀、乐等感情的句子叫感叹句,一般用 what 或 how 引导。朗读时用降调,句末用感叹号。</p>\n<p class=\"source-line\">What a nice day! 多么美好的一天啊！<br/>\nHow lovely she is! 她多么可爱啊！</p>\n<p class=\"source-line\">感叹句的用法:感叹句并不难,what 或 how 放句前;强调名词用 what,其余情况 how 来担;为了简洁而明了,主谓省去也常见。</p></div></div>\n<div class=\"g\"><div class=\"gt\">how 和 what 引导的感叹句</div><div class=\"gb\"><h5>1. how 引导的感叹句</h5>\n<p class=\"source-line\">how 作状语,修饰形容词、副词或整个句子。</p>\n<p class=\"source-line\">结构 1: How + 形容词 / 副词（+主语+谓语）!</p>\n<p class=\"source-line\">How cute the dogs are!</p>\n<p class=\"source-line\">多么可爱的狗啊！</p>\n<p class=\"source-line\">How hard he works!</p>\n<p class=\"source-line\">他工作多么努力啊！</p>\n<p class=\"source-line\">How new the building is!</p>\n<p class=\"source-line\">多么新的楼房啊！</p>\n<p class=\"source-line\">How clever the boy is!</p>\n<p class=\"source-line\">多么聪明的男孩儿啊！</p>\n<p class=\"source-line\">结构 2: How + 主语 + 谓语!</p>\n<p class=\"source-line\">How time flies! 光阴似箭!</p>\n<h5>2. what 引导的感叹句</h5>\n<p class=\"source-line\">what 作定语,修饰名词。名词前可有形容词或冠词。</p>\n<p class=\"source-line\">结构 1: What + a / an + 形容词 + 可数名词单数 (+ 主语 + 谓语)!</p>\n<p class=\"source-line\">What an interesting story it is!</p>\n<p class=\"source-line\">多么有趣的一个故事啊！</p>\n<p class=\"source-line\">What an exciting sport it is to climb mountains!</p>\n<p class=\"source-line\">爬山是多么令人兴奋的一项运动啊！</p>\n<p class=\"source-line\">结构 2: What + 形容词 + 可数名词复数 / 不可数名词（+主语+谓语）!</p>\n<p class=\"source-line\">What interesting stories they are! 多么有趣的故事啊!</p>\n<p class=\"source-line\">What fresh air it is! 多么新鲜的空气啊!</p>\n<h5>3. 两种感叹句的互换</h5>\n<p class=\"source-line\">由 what 引导的感叹句和由 how 引导的感叹句有时可以互换。</p>\n<p class=\"source-line\">What a delicious cake it is! = How delicious the cake is!</p>\n<p class=\"source-line\">多么美味的蛋糕啊！</p>\n<p class=\"source-line\">What a lovely day it is! = How lovely the day is!</p>\n<p class=\"source-line\">多么好的天气啊！</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">判断 what 与 how 的三步法</div><p class=\"source-line\">一划主谓(先划感叹句后部的主语、谓语);二往前(往前看);三判断(往前看若是名词就用what,若是形容词或副词就用how)。</p></div>\n<p class=\"source-line\">例如: What nice weather it is! 多么好的天气啊!\nHow well he plays basketball! 他篮球打得多么好啊!</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【吉林·长春】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s62-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> nice day it is!</p>","options":["What a","How","How a"],"correct":0,"answer":"A\n解析：根据 what 引导的感叹句结构 “What a / an + 形容词 + 可数名词单数 (+ 主语 + 谓语)!” 可知此题选 A。"},{"id":"s62-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> sunny and clear weather it is!</p>","options":["What","What a","How"],"correct":0,"answer":"A"},{"id":"s62-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> delicious the dumplings taste!</p>","options":["What","What a","How"],"correct":2,"answer":"C"},{"id":"s62-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> important it is for teenagers to be creative!</p>","options":["How","What","What a"],"correct":0,"answer":"A\n解析：根据 how 引导的感叹句结构“How + 形容词(+主语+谓语)!”可知此题选 A。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【山东·青岛】连词成句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s62-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">science, a, what, museum, great (!)</p>","options":[],"correct":null,"answer":"What a great science museum!"},{"id":"s62-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">useful, advice, gave, you, us, what (!)</p>","options":[],"correct":null,"answer":"What useful advice you gave us!"},{"id":"s62-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">driverless, is, car, how, the, smart (!)</p>","options":[],"correct":null,"answer":"How smart the driverless car is!"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s62-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> sweet music!</p>","options":["What","How","What a","How an"],"correct":0,"answer":"A"},{"id":"s62-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> special shirt he has!</p>","options":["What a","What","How a","What an"],"correct":0,"answer":"A"},{"id":"s62-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> an interesting film!</p>","options":["What","How","What an","How an"],"correct":0,"answer":"A"},{"id":"s62-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> useful work!</p>","options":["What","How","How a","What an"],"correct":0,"answer":"A"},{"id":"s62-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> nice picture!</p>","options":["What","How","What a","What an"],"correct":2,"answer":"C"},{"id":"s62-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> exciting news!</p>","options":["What an","What","How an","How"],"correct":1,"answer":"B"},{"id":"s62-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> Mr. Smith is!</p>","options":["How polite man","What a polite man","What polite man","How a polite man"],"correct":1,"answer":"B"},{"id":"s62-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> important meeting!</p>","options":["What a","What","What an","How"],"correct":2,"answer":"C"},{"id":"s62-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> is running!</p>","options":["How fast the boys","How fast boy","What fast the boy","How fast the boy"],"correct":3,"answer":"D"},{"id":"s62-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\"><span class=\"blank-token\">____</span> beautiful the flowers are!</p>","options":["What a","What","What an","How"],"correct":3,"answer":"D"}],"questionCount":10,"hasAnswers":true}]},{"id":"s63","section":63,"unit":11,"unitName":"单元11 · 第61–66节","short":"第63节 · L125–126","title":"must 和 have to 的用法","lessons":"Lesson 125 — Lesson 126","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>must 和 have to 的用法</td>\n<td>must 的用法</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>must 和 have to 的用法</td>\n<td>辨析 must 与 have to</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">must 的用法</div><div class=\"gb\"><h5>1. must 表示必须</h5>\n<p class=\"source-line\">must 意为 “必须”, 多指现在或将来的情况, 强调说话者的主观语气, 即说话者认为有必要或有义务做某事, 后加动词原形。</p>\n<p class=\"source-line\">I must water the garden first. 我必须先给花园浇水。</p>\n<p class=\"source-line\">—— Must I obey the traffic rules? 我必须遵守交通规则吗?<br/>\n—— Yes, you must. 是的,你必须(遵守交通规则)。</p>\n<h5>2. must 表示推测</h5>\n<p class=\"source-line\">must 表示推测时, 意为 “一定, 准是”, 指有把握的、有根据的推测, 通常只用于肯定句中, 可以对现在、过去或将来的情况进行推测, 后面加动词原形。</p>\n<p class=\"source-line\">—— Look! There are so many people in the restaurant. 看！这个饭店里有好多人。</p>\n<p class=\"source-line\">—— Yes. The food there must be delicious. 是的。那里的食物一定很美味。</p>\n<p class=\"source-line\">You must be tired after the sports meeting.</p>\n<p class=\"source-line\">你运动会后一定很累。</p>\n<p class=\"source-line\">表示有把握的肯定推测用 must, 表示有把握的否定推测用 can't。mustn't 不能用来表示推测。</p>\n<p class=\"source-line\">例如: The bike must be Peter's. 这辆自行车一定是彼得的。\nThe bike can't be Peter's. 这辆自行车不可能是彼得的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">辨析 must 与 have to</div><div class=\"gb\"><p class=\"source-line\">（1）must 表示主观看法,意为“必须”；have to 表示客观需求,意为“不得不”。</p>\n<p class=\"source-line\">I must go now.</p>\n<p class=\"source-line\">现在,我必须走了。(强调主观意愿)</p>\n<p class=\"source-line\">He has to stop the car and wait for the policeman.</p>\n<p class=\"source-line\">他不得不停车等那个警察。(表示客观情况,此时 has to 不能换成 must)</p>\n<p class=\"source-line\">（2）must 只有一种形式,而 have to 有多种时态形式。</p>\n<p class=\"source-line\">I'll have to look after my brother next week.</p>\n<p class=\"source-line\">It rained hard. I had to stay at home.</p>\n<p class=\"source-line\">我下周将不得不照顾我弟弟。</p>\n<p class=\"source-line\">雨下得很大。我不得不待在家里。</p>\n<p class=\"source-line\">（3）must 的否定式为 mustn't,意为“不准；不允许”；而 have to 的否定式为 don't / doesn't have to,意为“不必”,相当于 needn't。</p>\n<p class=\"source-line\">Don't you know passengers mustn't smoke on high-speed trains?</p>\n<p class=\"source-line\">难道你不知道旅客在高速列车上禁止吸烟吗？</p>\n<p class=\"source-line\">巧记 must 和 have to: 主观职责说 “必须”, must 赶紧用上去; 若是环境 “不得不”, 赶快换用 have to。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【湖北·黄石】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s63-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— May I smoke here?<br/><br>\n—— No, you <span class=\"blank-token\">____</span>. This is a no-smoking room.</br></p>","options":["must","mustn't","need","wouldn't"],"correct":1,"answer":"B\n解析：根据答语中的 “a no-smoking room（禁烟房）” 可知横线处应表示 “禁止”,故选 B。"},{"id":"s63-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Someone is knocking at the door. It <span class=\"blank-token\">____</span> be my mother. It's time for her to be back.</p>","options":["needn't","may not","must","have to"],"correct":2,"answer":"C"},{"id":"s63-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Sorry, Miss Liu. I left my workbook at home. Must I hand it in today?<br/><br>\n—— No, you <span class=\"blank-token\"><strong><em>_</em></strong></span>. You <span class=\"blank-token\">_</span> bring it here tomorrow.</br></p>","options":["mustn't; should","can't; must","mustn't; may","needn't; can"],"correct":3,"answer":"D\n解析：“Must I ... ?”的否定回答通常为“No, you needn’t.”，故选 D。"},{"id":"s63-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Excuse me, sir. Visiting hours (探视时间) are over. You <span class=\"blank-token\">____</span> leave.<br/><br>\n—— Pardon me (对不起), nurse. I didn't hear the bell (铃声).</br></p>","options":["may","can","must","need"],"correct":2,"answer":"C\n解析：“Visiting hours are over.” 意为“探视时间结束了”，must（必须）符合题意，故选 C。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s63-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Does he <span class=\"blank-token\">____</span> wear the uniform at school?<br/><br>\n—— Yes, he does.</br></p>","options":["have to","has to","had to","must"],"correct":0,"answer":"A\n解析：does 是助动词, 句中缺少谓语动词, 故填 have to。"},{"id":"s63-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Mum, may I go swimming now?<br/><br>\n—— Yes, dear, but remember that you <span class=\"blank-token\">____</span> go with your dad.</br></p>","options":["has to","had to","must","has to"],"correct":2,"answer":"C"},{"id":"s63-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> look after his sister yesterday.</p>","options":["had to","must","have to","has to"],"correct":0,"answer":"A\n解析：根据 yesterday 可知此句时态为一般过去时, 故填 had to。"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s63-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Must I finish my homework right now?<br/><br>\n—— No, you <span class=\"blank-token\">____</span>.</br></p>","options":["needn't","may not","mustn't"],"correct":0,"answer":"A"},{"id":"s63-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do we have to tell her the truth?<br/><br>\n—— Yes, you <span class=\"blank-token\">____</span>.</br></p>","options":["do","can","need"],"correct":0,"answer":"A"},{"id":"s63-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Must I be home before 8:00?<br/><br>\n—— Yes, you <span class=\"blank-token\">____</span>.</br></p>","options":["may","do","must"],"correct":2,"answer":"C"},{"id":"s63-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> water the garden every day.</p>","options":["had to","have to","has to"],"correct":1,"answer":"B"},{"id":"s63-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I will <span class=\"blank-token\">____</span> get up at six o'clock tomorrow morning.</p>","options":["must","have to","need"],"correct":1,"answer":"B"},{"id":"s63-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Tom and Mary <span class=\"blank-token\">____</span> travel by ship last spring.</p>","options":["have to","has to","had to"],"correct":2,"answer":"C"},{"id":"s63-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">It's seven o'clock. Jack <span class=\"blank-token\">____</span> be here now.</p>","options":["have to","must","must to"],"correct":1,"answer":"B"},{"id":"s63-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Can you go shopping with us this afternoon?<br/><br>\n—— Sorry, I can't. I <span class=\"blank-token\">____</span> look after my little sister.</br></p>","options":["can","may","have to"],"correct":2,"answer":"C"}],"questionCount":8,"hasAnswers":true}]},{"id":"s64","section":64,"unit":11,"unitName":"单元11 · 第61–66节","short":"第64节 · L127–128","title":"表示猜测和推断的情态动词 must（一）","lessons":"Lesson 127 — Lesson 128","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>表示猜测和推断的情态动词 must(一)</td>\n<td>表示对现在的情况的猜测和推断</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>表示猜测和推断的情态动词 must(一)</td>\n<td>表示对正在进行的情况的猜测和推断</td>\n<td>★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示猜测和推断的情态动词 must(一)</td>\n<td>表示对过去的情况的猜测和推断</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">表示对现在的情况的猜测和推断</div><div class=\"gb\"><p class=\"source-line\">must 表示有客观事实作为依据的猜测和推断，意为“一定”。must 表示推测时一般用于肯定句；表示有把握的否定推测通常用 can't，疑问句中的推测常用 can。表示对现在情况的肯定或否定推测，可以分别使用“must be”和“can't be”。</p>\n<p class=\"source-line\">He must be a doctor.</p>\n<p class=\"source-line\">他一定是一名医生。</p>\n<p class=\"source-line\">He can't be a doctor.</p>\n<p class=\"source-line\">他不可能是一名医生。</p></div></div>\n<div class=\"g\"><div class=\"gt\">表示对正在进行的情况的猜测和推断</div><div class=\"gb\"><p class=\"source-line\">表示对正在进行的情况的猜测和推断,我们可以用 “must / can't be doing”。</p>\n<p class=\"source-line\">She must be doing exercises in the classroom.</p>\n<p class=\"source-line\">她一定在教室里做习题。</p>\n<p class=\"source-line\">She can't be watching TV now.</p>\n<p class=\"source-line\">她现在不可能在看电视。</p></div></div>\n<div class=\"g\"><div class=\"gt\">表示对过去的情况的猜测和推断</div><div class=\"gb\"><p class=\"source-line\">表示对过去情况的猜测和推断，可以用“must have done”表示肯定推断，用“can't have done”表示否定推断。</p>\n<p class=\"source-line\">He must have finished the work.</p>\n<p class=\"source-line\">他一定已经完成了工作。</p>\n<p class=\"source-line\">He can't have gone to Shanghai, for I saw him a minute ago.</p>\n<p class=\"source-line\">他不可能去了上海,因为我刚才看见他了。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【辽宁·沈阳】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s64-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">This actress <span class=\"blank-token\">____</span> at least 45 years old. Look at the wrinkles on her face!</p>","options":["must is","must be","can be"],"correct":1,"answer":"B\n解析：根据 “Look at the wrinkles on her face!” 可知这名女演员的年龄肯定至少 45 岁, must 与动词原形搭配使用, 故选 B。"},{"id":"s64-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">It <span class=\"blank-token\">____</span> my book. Mine is red.</p>","options":["can't be","can be","will be"],"correct":0,"answer":"A"},{"id":"s64-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— I saw Kevin in the supermarket this morning.<br/><br>\n—— No, it <span class=\"blank-token\">____</span> him. He moved to Canada last week.</br></p>","options":["can be","can't be","mustn't be"],"correct":1,"answer":"B\n解析：根据“He moved to Canada last week.”可知，在超市见到的那个人不可能是 Kevin。mustn't 表示“禁止”，不能表示这种否定推测，故选 B。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【山东·潍坊】用所给单词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s64-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">It's dangerous outside. You must <span class=\"blank-token\">____</span> (stay) at home.</p>","options":[],"correct":null,"answer":"stay\n解析：must 后面接动词原形。"},{"id":"s64-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">At this moment, our teacher must be <span class=\"blank-token\">____</span> (correct) our exam papers.</p>","options":[],"correct":null,"answer":"correcting\n解析：根据 “At this moment” 可知此题表示对现在进行的动作的猜测, 应用 “must be doing” 的形式, 故填 correcting。"},{"id":"s64-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">The girl looks very much like Alice. She must <span class=\"blank-token\">____</span> (be) her daughter.</p>","options":[],"correct":null,"answer":"be"},{"id":"s64-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Mike can't <span class=\"blank-token\">____</span> (find) his car, for he came to work by bus this morning.</p>","options":[],"correct":null,"answer":"have found\n解析：根据后半句可知前半句是对过去情况的否定推测,应用 “can’t have done” 的形式,故填 have found。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s64-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">他不可能是一名老师,他一定是一名牙医。</p>","options":[],"correct":null,"answer":"He can't be a teacher. He must be a dentist."},{"id":"s64-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">他不可能在读书,他一定是在玩儿游戏。</p>","options":[],"correct":null,"answer":"He can't be reading a book. He must be playing games."},{"id":"s64-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">他一定已经到了。</p>","options":[],"correct":null,"answer":"He must have arrived already."},{"id":"s64-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">杰克的房间开着灯,他一定在家。</p>","options":[],"correct":null,"answer":"Jack's light is on in his room. He must be at home."},{"id":"s64-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">地面是湿的,昨晚一定下雨了。</p>","options":[],"correct":null,"answer":"The ground is wet. It must have rained last night."}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s64-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Look! The light is off in her room. She <span class=\"blank-token\">____</span> to bed already.</p>","options":["must go","had to go","must have gone","hasn't gone"],"correct":2,"answer":"C"},{"id":"s64-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">He <span class=\"blank-token\">____</span> have completed his work. Otherwise, he can't be enjoying himself by the seaside.</p>","options":["can","must","wouldn't","can't"],"correct":1,"answer":"B"},{"id":"s64-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">This cake is too sweet. You <span class=\"blank-token\">____</span> a lot of sugar in it.</p>","options":["should put","could have put","can put","must have put"],"correct":3,"answer":"D"},{"id":"s64-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Even the top students can't work out this problem. So it <span class=\"blank-token\">____</span> be very difficult.</p>","options":["can","may","need","must"],"correct":3,"answer":"D"},{"id":"s64-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">Miss Zhang <span class=\"blank-token\">____</span> be in Shanghai now, because she went to Beijing this morning.</p>","options":["mustn't","may not","can't","needn't"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true}]},{"id":"s65","section":65,"unit":11,"unitName":"单元11 · 第61–66节","short":"第65节 · L129–130","title":"表示猜测和推断的情态动词 must（二）","lessons":"Lesson 129 — Lesson 130","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>表示猜测和推断的情态动词 must（二）</td>\n<td>must 表示对过去某段时间一直在发生的事情的猜测和推断</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">表示对过去某段时间一直在发生的事情的猜测和推断</div><div class=\"gb\"><p class=\"source-line\">当 must 表示对过去某段时间一直在发生的事情的猜测和推断时, 可以分为肯定的推断和否定的推断。其中, 表示肯定的推断结构为 “must have been doing”, 表示否定的推断结构为 “can’t have been doing”。</p>\n<p class=\"source-line\">You must have been driving at seventy kilometres an hour.</p>\n<p class=\"source-line\">你一定是一直以每小时70千米的速度开车。</p>\n<p class=\"source-line\">I must have been dreaming.</p>\n<p class=\"source-line\">我刚才一定是在做梦。</p>\n<p class=\"source-line\">They can't have been listening to music.</p>\n<p class=\"source-line\">他们不可能一直在听音乐。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【北京·东城区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s65-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Why didn't you answer my phone call?<br/><br>\n—— Well, I <span class=\"blank-token\">____</span> sleeping, so I didn't hear it.</br></p>","options":["must","must have been","should have"],"correct":1,"answer":"B\n解析：根据 “I didn't hear it” 可知答语是对过去情况的肯定推测, 故选 B。"},{"id":"s65-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Harry is feeling uncomfortable. He <span class=\"blank-token\">____</span> too much at the party last night.</p>","options":["could drink","should drink","must have drunk"],"correct":2,"answer":"C\n解析：根据 “Harry is feeling uncomfortable.” 可推断 “他在昨晚的聚会上一定喝多了”, 故选 C。"},{"id":"s65-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Didn't you see the speed limit?<br/><br>\n—— I'm afraid I didn't. I must <span class=\"blank-token\">____</span> dreaming.</br></p>","options":["be","have been","have"],"correct":1,"answer":"B"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【山东·菏泽】用所给单词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s65-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">Do you think you are on a race track? You must <span class=\"blank-token\">____</span> (be) driving at eighty miles an hour.</p>","options":[],"correct":null,"answer":"have been\n解析：根据“Do you think you are on a race track?”可推测“开车的人刚才的速度达到了每小时 80 英里”，故填 have been。"},{"id":"s65-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">He must have been <span class=\"blank-token\">____</span> (read) in the library the whole afternoon yesterday.</p>","options":[],"correct":null,"answer":"reading"},{"id":"s65-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">He must have <span class=\"blank-token\">____</span> (finish) the work yesterday.</p>","options":[],"correct":null,"answer":"finished\n解析：根据题意 “他昨天一定已经完成了工作” 可知应填 finished。"},{"id":"s65-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">She can't <span class=\"blank-token\">____</span> (be) working in the garden then.</p>","options":[],"correct":null,"answer":"have been\n解析：根据题意 “她那时不可能在花园干活” 可知应填 have been。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 用 be 的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s65-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">You must <span class=\"blank-token\">____</span> at the library an hour ago, because I saw you there.</p>","options":[],"correct":null,"answer":"have been"},{"id":"s65-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">She can't <span class=\"blank-token\"><strong><em>_</em></strong></span> 29 at that time. She must <span class=\"blank-token\">_</span> 36.</p>","options":[],"correct":null,"answer":"have been, have been"},{"id":"s65-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">I must <span class=\"blank-token\">____</span> sleeping, so I didn't hear it.</p>","options":[],"correct":null,"answer":"have been"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"II. 翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s65-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">他当时一定有 40 岁了。</p>","options":[],"correct":null,"answer":"He must have been forty years old."},{"id":"s65-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">他们一定一直在读英语书。</p>","options":[],"correct":null,"answer":"They must have been reading English books."},{"id":"s65-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">他们不可能一直在看电视。</p>","options":[],"correct":null,"answer":"They can't have been watching TV."}],"questionCount":3,"hasAnswers":true}]},{"id":"s66","section":66,"unit":11,"unitName":"单元11 · 第61–66节","short":"第66节 · L131–132","title":"表示推测的情态动词 may","lessons":"Lesson 131 — Lesson 132","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>表示推测的情态动词 may</td>\n<td>表示对现在或将来情况的推测</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示推测的情态动词 may</td>\n<td>表示对过去情况的推测</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示推测的情态动词 may</td>\n<td>表示对过去某段时间发生的事情的推测</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">表示对现在或将来情况的推测</div><div class=\"gb\"><p class=\"source-line\">may 意为 “可能；也许”，表示对现在或将来情况的推测时，我们可以用 “may do”。表示否定通常在 may 后加 not。</p>\n<p class=\"source-line\">He may be twenty-one. 他可能21岁。</p>\n<p class=\"source-line\">She may go abroad. 她可能出国。</p>\n<p class=\"source-line\">Ann may not come to the party tonight. She isn't well.</p>\n<p class=\"source-line\">安今晚可能不会来参加派对了。她身体不舒服。</p></div></div>\n<div class=\"g\"><div class=\"gt\">表示对过去情况的推测</div><div class=\"gb\"><p class=\"source-line\">may 表示对过去情况的推测时,我们可以用 “may have done”。</p>\n<p class=\"source-line\">He may have forgotten about the meeting.</p>\n<p class=\"source-line\">他可能忘记了会议。</p>\n<p class=\"source-line\">The ground is wet. It may have rained last night.</p>\n<p class=\"source-line\">地面是湿的。昨晚可能下雨了。</p></div></div>\n<div class=\"g\"><div class=\"gt\">表示对过去某段时间发生的事情的推测</div><div class=\"gb\"><p class=\"source-line\">may 表示对过去某段时间发生的事情的推测时,我们常用 “may have been doing”。</p>\n<p class=\"source-line\">They may have been watching TV.</p>\n<p class=\"source-line\">他们可能一直在看电视。</p>\n<p class=\"source-line\">She may have been looking for a new job.</p>\n<p class=\"source-line\">她可能一直在找一份新工作。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【天津·和平区】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s66-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— What are you going to do tomorrow?<br/><br>\n—— I'm not sure. I <span class=\"blank-token\">____</span> make a trip to Hangzhou with my friend.</br></p>","options":["may","maybe","will"],"correct":0,"answer":"A\n解析：根据 “I’m not sure.” 可知此题表示对将来情况的不确定, 故选 A。"},{"id":"s66-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> be late, so don't wait for me to start the meeting.</p>","options":["mustn't","needn't","may"],"correct":2,"answer":"C\n解析：根据后半句可推断前半句意为“我可能会晚”,故选C。"},{"id":"s66-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— The lake is said to be dry. Is that true?<br/><br>\n—— It <span class=\"blank-token\">____</span>. Look, some kids are swimming in it.</br></p>","options":["may be true","can't be true","may not be true"],"correct":1,"answer":"B"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s66-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Peter may <span class=\"blank-token\">____</span> with us this afternoon, but he isn't very sure yet.</p>","options":["come","comes"],"correct":0,"answer":"A\n解析：may 后面接动词原形。"},{"id":"s66-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— He <span class=\"blank-token\"><strong><em>_</em></strong></span> be in the classroom, I think.<br/><br>\n—— No, he <span class=\"blank-token\">_</span> be in the classroom. I saw him go home a minute ago.</br></p>","options":["may, can't","need, may not","need, can't","may, may not"],"correct":0,"answer":"A\n解析：may 意为 “可能”, need 意为 “需要”, may 符合第一句话的意思, 故第一个空填 may。“I saw him go home a minute ago.” 意为 “我看见他一分钟前回家了”, 因此他不可能在教室。故第二个空填 can't。"},{"id":"s66-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't get close to the fire. It <span class=\"blank-token\">____</span> hurt you.</p>","options":["may","must"],"correct":0,"answer":"A"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"I. 翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s66-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">他当时可能在家。</p>","options":[],"correct":null,"answer":"He may have been at home."},{"id":"s66-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">她可能是一名医生,但我不确定。</p>","options":[],"correct":null,"answer":"She may be a doctor, but I'm not sure."},{"id":"s66-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">他们可能一直在田地里干活。</p>","options":[],"correct":null,"answer":"They may have been working in the field."},{"id":"s66-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">它可能不是汤姆的手机。</p>","options":[],"correct":null,"answer":"It may not be Tom's mobile phone."},{"id":"s66-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">他在这次事故中可能受伤了。</p>","options":[],"correct":null,"answer":"He may have been hurt in the accident."}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s66-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I hear you've got a new phone. <span class=\"blank-token\">____</span> I have a look?</p>","options":["May","Must","Shall"],"correct":0,"answer":"A"},{"id":"s66-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Have you decided which bag to choose?<br/><br>\n—— Not yet. I <span class=\"blank-token\">____</span> choose the green one.</br></p>","options":["must","may","need"],"correct":1,"answer":"B"},{"id":"s66-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Would you like to go to the concert with me?<br/><br>\n—— I'm not sure. I <span class=\"blank-token\">____</span> have a meeting that night.</br></p>","options":["must","should","may"],"correct":2,"answer":"C"},{"id":"s66-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Look out! The knife is very sharp. You <span class=\"blank-token\">____</span> cut your finger.</p>","options":["need","must","may"],"correct":2,"answer":"C"},{"id":"s66-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">I searched for my keys and they weren't there. I thought I <span class=\"blank-token\">____</span> them at home.</p>","options":["left","should have left","might have left"],"correct":2,"answer":"C"}],"questionCount":5,"hasAnswers":true}]},{"id":"s67","section":67,"unit":12,"unitName":"单元12 · 第67–72节","short":"第67节 · L133–134","title":"直接引语变间接引语","lessons":"Lesson 133 — Lesson 134","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>直接引语变间接引语</td>\n<td>直接引语和间接引语的特点</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>直接引语变间接引语</td>\n<td>各种句式变间接引语时要发生的变化</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">直接引语和间接引语的特点</div><div class=\"gb\"><p class=\"source-line\">直接引用别人的原话,叫作直接引语;转述别人的话,叫作间接引语。将直接引语变成间接引语时,间接引语多以宾语从句的形式表现出来。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>引语</th>\n<th>特点</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>直接引语</td>\n<td>被引用的话放在引号里；引述词在前时，通常在引述词后加逗号。被引用的话是原话，不作任何改动，包括标点符号。</td>\n</tr>\n<tr>\n<td>间接引语</td>\n<td>转述的话不加引号，引述词后不加标点符号，必要时在转述的话前加引导词。句中的时态、人称、时间状语和地点状语等通常有相应变化，标点符号也要根据主句的语气调整。</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">Tom said, \"I am 11 now.\"（直接引语）<br/>\n汤姆说：“我现在 11 岁。”</p>\n<p class=\"source-line\">Tom said (that) he was 11 then.（间接引语）<br/>\n汤姆说他那时 11 岁。</p>\n<p class=\"source-line\">Jerry said, \"The car is mine.\"（直接引语）<br/>\n杰里说：“那辆小汽车是我的。”</p>\n<p class=\"source-line\">Jerry said that the car was his.（间接引语）<br/>\n杰里说那辆小汽车是他的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">各种句式变间接引语时要发生的变化</div><div class=\"gb\"><p class=\"source-line\">（1）陈述句</p>\n<p class=\"source-line\">直接引语是陈述句,变为间接引语时,要用连词 that 引导(that 可省略)。</p>\n<p class=\"source-line\">Tony said to me, \"I will leave this book in your desk.\" 托尼对我说：“我会把这本书留在你的书桌里。”</p>\n<p class=\"source-line\">Tony told me (that) he would leave that book in my desk. 托尼告诉我他会把那本书留在我的书桌里。</p>\n<p class=\"source-line\">（2）一般疑问句、选择疑问句或反意疑问句</p>\n<p class=\"source-line\">直接引语是一般疑问句、选择疑问句或反意疑问句，变间接引语时，要用连词whether或if引导，同时把原来的疑问句语序变为陈述句语序。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">陈述句变间接引语口诀</div><p class=\"source-line\">去掉引号添 that，人称变化要灵活；时态通常向后退一步，状语变化按规定。</p></div>\n<p class=\"source-line\">The woman asked me, \"Can you show me the way to the nearest bookstore?\"</p>\n<p class=\"source-line\">那个女人问我：“你能告诉我最近的书店怎么走吗？”</p>\n<p class=\"source-line\">The woman asked me whether / if I could show her the way to the nearest bookstore.</p>\n<p class=\"source-line\">那个女人问我能否告诉她去最近的书店的路。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">一般疑问句变间接引语口诀</div><p class=\"source-line\">去掉引号加 whether 或 if，陈述语序要记住；时态、人称和状语，小心变化别马虎。</p></div>\n<p class=\"source-line\">（3）特殊疑问句</p>\n<p class=\"source-line\">直接引语是特殊疑问句,变间接引语时,间接引语要变为由原来特殊疑问句的疑问词引导的宾语从句。</p>\n<p class=\"source-line\">She asked, \"Where do you come from, Tom?\"<br/>\n她问：“你来自哪里，汤姆？”<br/>\nShe asked Tom where he came from.<br/>\n她问汤姆来自哪里。</p>\n<p class=\"source-line\">（4）表示请求、提议、建议或劝告等意义的疑问句</p>\n<p class=\"source-line\">直接引语是表示请求、提议、建议或劝告等意义的疑问句，变为间接引语时，可以变为动词不定式、动词-ing形式或含有虚拟语气的宾语从句。</p>\n<p class=\"source-line\">\"Could you please tell me something about the trip?\" David said to his sister. \"你能告诉我一些关于这次旅行的事情吗?\" 戴维对他姐姐说。<br/>\nDavid asked his sister to tell him something about the trip. 戴维让他姐姐告诉他一些关于这次旅行的事情。</p>\n<p class=\"source-line\">（5）祈使句</p>\n<p class=\"source-line\">直接引语是祈使句,变间接引语时,要将祈使句的动词原形变为动词不定式,并在不定式的前面根据句子的意思加上 tell、ask、order 等动词。如果祈使句为否定形式,则在不定式的前面加 not。</p>\n<p class=\"source-line\">Mrs. Li said to her, \"Please come here again tomorrow.\"<br/>\n李太太对她说：“请明天再来这儿吧。”</p>\n<p class=\"source-line\">Mrs. Li asked her to go there again the next / following day.<br/>\n李太太让她第二天再去那儿。</p>\n<div class=\"custom-block tip\"><div class=\"custom-block-title\">祈使句变间接引语口诀</div><p class=\"source-line\">去掉引号，选用 tell、ask、order 等引述动词，再接不定式；直接引语若是否定式，not 放在 to 前。</p></div>\n<p class=\"source-line\">（6）感叹句</p>\n<p class=\"source-line\">直接引语是感叹句，变为间接引语时，可以保留 what 或 how 引导的感叹结构，也可以改为 that 引导的宾语从句。引述动词常用 exclaim。</p>\n<p class=\"source-line\">\"What a sunny day it is!\" she said. “多么晴朗的一天啊!”她说。</p>\n<p class=\"source-line\">She exclaimed what a sunny day it was. 她感叹那是多么晴朗的一天。</p>\n<p class=\"source-line\">She said that it was a sunny day. 她说那是一个晴朗的日子。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【四川·乐山】将直接引语改为间接引语。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s67-practice-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">Tony said, \"I am singing now.\"</p>","options":[],"correct":null,"answer":"Tony said that he was singing then.\n解析：引述动词的主语是 Tony，因此 I 要变成 he；现在进行时变为过去进行时，时间状语 now 变为 then。"},{"id":"s67-practice-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">Daming said, \"I'm going to take up English this term.\"</p>","options":[],"correct":null,"answer":"Daming said that he was going to take up English that term."},{"id":"s67-practice-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">\"Don't smoke in the room,\" he said to me.</p>","options":[],"correct":null,"answer":"He told me not to smoke in the room."},{"id":"s67-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">\"How beautiful the pictures are!\" he said.</p>","options":[],"correct":null,"answer":"He exclaimed how beautiful the pictures were.\n解析：直接引语是感叹句，变为间接引语时可以保留 how 引导的感叹结构，并把 are 变为 were。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"【湖北·武汉】选择正确的选项,将直接引语变为间接引语。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s67-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">“Have you seen the film?” he asked me.<br/><br>\nHe asked me <span class=\"blank-token\">____</span>.</br></p>","options":["had I seen the film","have I seen the film","if I have seen the film","whether I had seen the film"],"correct":3,"answer":"D\n解析：直接引语是一般疑问句时, 间接引语变为由 whether/if 引导的宾语从句。直接引语的时态为现在完成时, 变间接引语时, 时态为过去完成时, 故选 D。"},{"id":"s67-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">“Please close the window,” he said to me.<br/><br>\nHe <span class=\"blank-token\"><strong><em>_</em></strong></span> me <span class=\"blank-token\">_</span> the window.</br></p>","options":["said to; to close","told to; closing","asked; to close","said to; please close"],"correct":2,"answer":"C"}],"questionCount":2,"hasAnswers":true},{"source":"textbook","title":"将下列直接引语变为间接引语。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s67-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">He said, \"I've left my bag in my room.\"</p>","options":[],"correct":null,"answer":"He said that he had left his bag in his room."},{"id":"s67-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">She said, \"He will be hungry.\"</p>","options":[],"correct":null,"answer":"She said that he would be hungry."},{"id":"s67-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">She said to us, \"I can't finish the work on time.\"</p>","options":[],"correct":null,"answer":"She told us that she couldn't finish the work on time."},{"id":"s67-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">She said, \"He will be busy.\"</p>","options":[],"correct":null,"answer":"She said that he would be busy."},{"id":"s67-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">The teacher said to the students, \"Don't waste your time.\"</p>","options":[],"correct":null,"answer":"The teacher told the students not to waste their time."},{"id":"s67-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">The mother said, \"Tom, get up early, please.\"</p>","options":[],"correct":null,"answer":"The mother asked Tom to get up early."},{"id":"s67-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">My father said, \"Practice makes perfect.\"</p>","options":[],"correct":null,"answer":"My father said practice makes perfect."}],"questionCount":7,"hasAnswers":true}]},{"id":"s68","section":68,"unit":12,"unitName":"单元12 · 第67–72节","short":"第68节 · L135–136","title":"使役动词 let 的用法","lessons":"Lesson 135 — Lesson 136","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>使役动词</td>\n<td>什么是使役动词</td>\n<td>★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>使役动词</td>\n<td>使役动词 let 的用法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是使役动词</div><div class=\"gb\"><p class=\"source-line\">使役动词表示“使、令、让、叫”等意义，英语中常见的使役动词有 leave（使……处于某种状态）、get（使……做／使……被做）、make（使）、let（让）、have（让）等。</p>\n<p class=\"source-line\">He made me laugh.</p>\n<p class=\"source-line\">他使我发笑。</p>\n<p class=\"source-line\">I have my hair cut every month. 我每个月都理发。</p></div></div>\n<div class=\"g\"><div class=\"gt\">使役动词 let 的用法</div><div class=\"gb\"><p class=\"source-line\">使役动词后接宾语,再接省略 to 的动词不定式作宾语补足语。使役动词后接宾语时,人称代词用宾格。常见形式为 “let + 宾语 + 动词原形”。</p>\n<p class=\"source-line\">Let them stay in the classroom and do their exercises themselves.</p>\n<p class=\"source-line\">让他们自己待在教室里做习题吧。</p>\n<p class=\"source-line\">I let him go. 我让他走。</p>\n<p class=\"source-line\">还有一些使役动词和感官动词也用省略 to 的动词不定式作宾补, 这些动词有: “一感”(feel), “二听”(hear、listen to), “三让”(let、make、have), “四看”(look at、see、watch、notice)。</p>\n<p class=\"source-line\">Mike often hears someone cry next door.</p>\n<p class=\"source-line\">迈克经常听到隔壁有人在哭。</p>\n<p class=\"source-line\">Please let him come here.</p>\n<p class=\"source-line\">请让他到这里来。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【贵州·安顺】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s68-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">He is a man with strong will and nothing will make him <span class=\"blank-token\">____</span> his mind.</p>","options":["to change","change","changing","changed"],"correct":1,"answer":"B\n解析：make sb. do sth. 表示 “让某人做某事”, 是固定用法, 故选 B。"},{"id":"s68-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Though he often made his little sister <span class=\"blank-token\"><strong><em>_</em></strong></span>, today he was made <span class=\"blank-token\">_</span> by his little sister.</p>","options":["cry; to cry","crying; crying","cry; cry","to cry; cry"],"correct":0,"answer":"A"},{"id":"s68-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">There was so much noise outside that the teacher couldn't make herself <span class=\"blank-token\">____</span>.</p>","options":["hear","heard","to hear","hearing"],"correct":1,"answer":"B\n解析：此句意为 “外面的噪音太大以至于老师无法使她自己的声音被同学们听到”。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s68-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Mr. Wang let them <span class=\"blank-token\">____</span> there yesterday.</p>","options":["sit","to sit"],"correct":0,"answer":"A\n解析：let 与动词原形搭配使用, 故填 sit。"},{"id":"s68-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">His father doesn't let him <span class=\"blank-token\">____</span> .</p>","options":["smoking","smoke"],"correct":1,"answer":"B"},{"id":"s68-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Have <span class=\"blank-token\">____</span> do it.</p>","options":["he","him"],"correct":1,"answer":"B\n解析：have 后接人称代词时, 人称代词用宾格, 故填 him。"},{"id":"s68-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">She got her computer <span class=\"blank-token\">____</span> .</p>","options":["fixed","fix"],"correct":0,"answer":"A"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"I. 翻译句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s68-text-q001","number":1,"type":"input","questionHtml":"<p class=\"source-line\">让我看一看。</p>","options":[],"correct":null,"answer":"Let me have a look."},{"id":"s68-text-q002","number":2,"type":"input","questionHtml":"<p class=\"source-line\">我经常听见她在隔壁房间唱歌。</p>","options":[],"correct":null,"answer":"I often hear her sing in the next room."},{"id":"s68-text-q003","number":3,"type":"input","questionHtml":"<p class=\"source-line\">我妈妈让我每天按时完成作业。</p>","options":[],"correct":null,"answer":"My mother lets me finish my homework on time every day."},{"id":"s68-text-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">男孩儿把女孩儿惹哭了。</p>","options":[],"correct":null,"answer":"The boy made the girl cry."},{"id":"s68-text-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">让他自己去做这件事吧。</p>","options":[],"correct":null,"answer":"Let him do it himself."},{"id":"s68-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">请准备好你们的票。</p>","options":[],"correct":null,"answer":"Please get your tickets ready."}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s68-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">The teacher made us <span class=\"blank-token\">____</span> the words three times.</p>","options":["to say","saying","say","said"],"correct":2,"answer":"C"},{"id":"s68-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">He is only a child. Don't make him <span class=\"blank-token\">____</span> for a long time.</p>","options":["to work","works","working","work"],"correct":3,"answer":"D"},{"id":"s68-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">Working in the field for a whole day let the children <span class=\"blank-token\">____</span> the farmer's hard life.</p>","options":["understand","to understand","understood","understanding"],"correct":0,"answer":"A"},{"id":"s68-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">It's very hot. Let me <span class=\"blank-token\">____</span> the air conditioner.</p>","options":["turn off","to turn off","to turn on","turn on"],"correct":3,"answer":"D"}],"questionCount":4,"hasAnswers":true}]},{"id":"s69","section":69,"unit":12,"unitName":"单元12 · 第67–72节","short":"第69节 · L137–138","title":"条件状语从句","lessons":"Lesson 137 — Lesson 138","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>条件状语从句</td>\n<td>什么是条件状语从句</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>条件状语从句</td>\n<td>引导条件状语从句的从属连词</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">什么是条件状语从句</div><div class=\"gb\"><p class=\"source-line\">在句子中作条件状语的从句叫作条件状语从句。条件状语从句可置于句首，也可置于句末，有时还可以置于主语和谓语之间。</p>\n<p class=\"source-line\">If I go out, I will be wet. 如果我出去,我会被淋湿的。</p>\n<p class=\"source-line\">I will be bored if I stay at home. 如果我待在家里我会很无聊。</p>\n<p class=\"source-line\">If it is sunny tomorrow, we will go for a ride. 如果明天天气晴朗，我们将去兜风。</p></div></div>\n<div class=\"g\"><div class=\"gt\">引导条件状语从句的从属连词</div><div class=\"gb\"><p class=\"source-line\">（1）引导条件状语从句的从属连词主要有：</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>从属连词</th>\n<th>含义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>if</td>\n<td>如果</td>\n</tr>\n<tr>\n<td>unless</td>\n<td>除非;如果不</td>\n</tr>\n<tr>\n<td>as / so long as</td>\n<td>只要</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">I won't take part in Julie's birthday party unless I am invited.</p>\n<p class=\"source-line\">我不会参加朱莉的生日聚会，除非我被邀请。</p>\n<p class=\"source-line\">We can get over the difficulty as long as we have confidence.</p>\n<p class=\"source-line\">只要我们有信心,我们就能克服困难。</p>\n<p class=\"source-line\">as long as 还表示“和……一样长”。</p>\n<p class=\"source-line\">例如: Her hair is as long as mine. 她的头发和我的一样长。</p>\n<p class=\"source-line\">（2）在含有 if、unless、as / so long as 等引导的条件状语从句的复合句中,如果主句的时态是一般将来时,从句常用一般现在时表示将来。</p>\n<p class=\"source-line\">We'll go fishing if it doesn't rain this weekend.</p>\n<p class=\"source-line\">如果这个周末不下雨,我们将去钓鱼。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【湖北·咸宁】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s69-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Let's go climbing if it <span class=\"blank-token\"><strong><em>_</em></strong></span> this Saturday.<br/><br>\n—— Good idea. But nobody knows if it <span class=\"blank-token\">_</span>.</br></p>","options":["is fine; rains","is fine; will rain","will be fine; rains","will be fine; will rain"],"correct":1,"answer":"B\n解析：第一个句子是 if 引导的条件状语从句,主句为祈使句,从句的时态为一般现在时。第二个句子是 if 引导的宾语从句,句子想表达的是“没有人知道这星期六会不会下雨”,从句时态用一般将来时,故此题选 B。"},{"id":"s69-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">If you <span class=\"blank-token\">____</span> along this road, you will find a park.</p>","options":["go","went","goes","going"],"correct":0,"answer":"A"},{"id":"s69-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">If you <span class=\"blank-token\"><strong><em>_</em></strong></span> your toys on the table, I <span class=\"blank-token\">_</span> them away.</p>","options":["leave; will throw","left; throw","leave; throw","will leave; will throw"],"correct":0,"answer":"A\n解析：此题为 if 引导的条件状语从句, 从句时态用一般现在时, 主句时态用一般将来时, 故选 A。"}],"questionCount":3,"hasAnswers":true},{"source":"practice","title":"【江苏·徐州】根据句意完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s69-practice-q004","number":4,"type":"input","questionHtml":"<p class=\"source-line\">只要你努力,你就能学好英语。<br/>\nYou can learn English well as <span class=\"blank-token\"><strong><em>_</em></strong></span> <span class=\"blank-token\">_</span> you study hard.</p>","options":[],"correct":null,"answer":"long as\n解析：as long as 表示 “只要”, 在此句中引导条件状语从句。"},{"id":"s69-practice-q005","number":5,"type":"input","questionHtml":"<p class=\"source-line\">除非你开窗，否则这个房间会很热的。<br/>\nThe room will get very hot <span class=\"blank-token\"><strong><em>_</em></strong></span> you <span class=\"blank-token\">_</span> the window.</p>","options":[],"correct":null,"answer":"unless; open\n解析：unless 表示 “除非”, open 表示 “打开”。"},{"id":"s69-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">如果你给一个例子,孩子们就能更好地理解它了。<br/>\n<span class=\"blank-token\"><strong><em>_</em></strong></span> you give an example, the kids <span class=\"blank-token\">_</span> understand it better.</p>","options":[],"correct":null,"answer":"If; will\n解析：此句为条件状语从句, if 意为 “如果”, 第一个空填 if。根据 “主将从现” 原则可知第二个空填 will。"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"I. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s69-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">What <span class=\"blank-token\"><strong><em>_</em></strong></span> you do if you <span class=\"blank-token\">_</span> the exam?</p>","options":["could; pass","will; pass","do; passed","can; passed"],"correct":1,"answer":"B"},{"id":"s69-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">If you are tired, you <span class=\"blank-token\">____</span> have a rest.</p>","options":["could","would","might","can"],"correct":3,"answer":"D"},{"id":"s69-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">If the flowers are dry, <span class=\"blank-token\">____</span> water them at once.</p>","options":["you","will","please","can"],"correct":2,"answer":"C"},{"id":"s69-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Martin's dad will buy him a new computer, if he <span class=\"blank-token\">____</span> the football game.</p>","options":["wins","will win","win","would win"],"correct":0,"answer":"A"},{"id":"s69-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">We <span class=\"blank-token\"><strong><em>_</em></strong></span> go swimming if it <span class=\"blank-token\">_</span> fine tomorrow.</p>","options":["will; is","can; will be","will; will be","would; is"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 用所给单词的适当形式填空。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s69-text-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">They will need a lot of money if they <span class=\"blank-token\">____</span> (get) married next week.</p>","options":[],"correct":null,"answer":"get"},{"id":"s69-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">If you don't leave, I will <span class=\"blank-token\">____</span> (call) the police.</p>","options":[],"correct":null,"answer":"call"},{"id":"s69-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">We can take a taxi if there <span class=\"blank-token\">____</span> (be) a problem with the car.</p>","options":[],"correct":null,"answer":"is"},{"id":"s69-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">If you <span class=\"blank-token\">____</span> (not work) hard, you will be poor.</p>","options":[],"correct":null,"answer":"don't"},{"id":"s69-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">I <span class=\"blank-token\">____</span> (study) abroad if I have lots of money.</p>","options":[],"correct":null,"answer":"will study"}],"questionCount":5,"hasAnswers":true}]},{"id":"s70","section":70,"unit":12,"unitName":"单元12 · 第67–72节","short":"第70节 · L139–140","title":"that 引导的限制性定语从句","lessons":"Lesson 139 — Lesson 140","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>that引导的限制性定语从句</td>\n<td>限制性定语从句的概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>that引导的限制性定语从句</td>\n<td>限制性定语从句中只用that的情况</td>\n<td>★★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>that引导的限制性定语从句</td>\n<td>that在宾语从句和定语从句中的区别</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">限制性定语从句的概念</div><div class=\"gb\"><p class=\"source-line\">限制性定语从句是英语语法中从句的一种, 是定语从句的分支之一。限制性定语从句是先行词在意义上不可缺少的定语, 若省略, 所修饰主句的内容就不完整或失去意义, 和主句的关系十分密切。书写时不可用逗号分开。</p>\n<p class=\"source-line\">She is the girl that talked to you yesterday.</p>\n<p class=\"source-line\">她就是昨天和你说话的那个女孩儿。</p>\n<p class=\"source-line\">He is the man who lives next door.</p>\n<p class=\"source-line\">他就是住在隔壁的那个男人。</p>\n<p class=\"source-line\">The book which I borrowed from the library is very interesting.</p>\n<p class=\"source-line\">我从图书馆借的那本书非常有趣。</p></div></div>\n<div class=\"g\"><div class=\"gt\">限制性定语从句中只用 that 的情况</div><div class=\"gb\"><p class=\"source-line\">that 和 which 都可指物,且在句中都可作主语和宾语,多数情况下可以互换。但在以下情况中,关系代词只能用 that 不能用 which。</p>\n<p class=\"source-line\">（1）先行词被形容词最高级修饰时</p>\n<p class=\"source-line\">Polly is the most direct young woman that I have ever come across.</p>\n<p class=\"source-line\">波莉是我所遇到的最直率的年轻女子。</p>\n<p class=\"source-line\">（2）先行词被序数词修饰时</p>\n<p class=\"source-line\">This is the third time that they have met.</p>\n<p class=\"source-line\">这是他们第三次见面。</p>\n<p class=\"source-line\">（3）主句是以 which 或 who 开头的特殊疑问句时</p>\n<p class=\"source-line\">Which is the T-shirt that fits me most?</p>\n<p class=\"source-line\">哪件T恤衫最适合我？</p>\n<p class=\"source-line\">Who is the man that is sitting by the lake?</p>\n<p class=\"source-line\">坐在湖边的那个男人是谁？</p>\n<p class=\"source-line\">（4）先行词既有人又有物时</p>\n<p class=\"source-line\">She took photographs of the things and people that she was interested in.</p>\n<p class=\"source-line\">她把她感兴趣的人和物全拍摄了下来。</p>\n<p class=\"source-line\">（5）先行词是 all、much、few、little、something、everything、anything、nothing、none 等不定代词时</p>\n<p class=\"source-line\">It's easy to do the repair. All that you need is a hammer and some nails.</p>\n<p class=\"source-line\">修理很容易。你所需要的是一把锤子和一些钉子。</p>\n<p class=\"source-line\">We haven't got much that we can offer you.</p>\n<p class=\"source-line\">我们没有太多能向你们提供的(东西)。</p>\n<p class=\"source-line\">I'd like to tell you something that will make you surprised.</p>\n<p class=\"source-line\">我想要告诉你一件会让你大吃一惊的事。</p>\n<p class=\"source-line\">（6）先行词被 the very、the only、the same、the last 等词修饰时</p>\n<p class=\"source-line\">The only thing that we can do is to give you some money.</p>\n<p class=\"source-line\">我们唯一能做的就是给你一些钱。</p>\n<p class=\"source-line\">（7）有两个定语从句,其中一个定语从句的关系代词已经用 which,另一个用 that</p>\n<p class=\"source-line\">Edison built a factory which produced things that had never been seen before.</p>\n<p class=\"source-line\">爱迪生建了一家工厂，生产以前从未见过的东西。</p></div></div>\n<div class=\"g\"><div class=\"gt\">that 在宾语从句和定语从句中的区别</div><div class=\"gb\"><p class=\"source-line\">在宾语从句中，that 作引导词，不充当宾语从句中的任何成分，通常可以被省略。</p>\n<p class=\"source-line\">I think (that) you're right. 我觉得你是对的。</p>\n<p class=\"source-line\">在定语从句中，that 作关系代词，既可以指人，也可以指物；既可以充当主语，也可以充当宾语。只有充当宾语时，可以被省略。</p>\n<p class=\"source-line\">The book (that) I bought yesterday is very interesting. 我昨天买的那本书非常有趣。</p>\n<p class=\"source-line\">This is all the information (that) I know. 这是我所知道的全部信息。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【湖北·鄂州】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s70-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Do you like the weekly talk show The Reader on CCTV?<br/><br>\n—— Sure. It's a great TV program <span class=\"blank-token\">____</span> can develop the habit of reading.</br></p>","options":["who","that","what","whose"],"correct":1,"answer":"B"},{"id":"s70-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">China is getting better at making hi-tech products <span class=\"blank-token\">____</span> can be bought in all parts of the world.</p>","options":["who","which","what","whose"],"correct":1,"answer":"B\n解析：此句意为 “中国正变得更擅长制造能在世界各地买到的高科技产品”。先行词为 hi-tech products, 关系代词应用 that / which, 在从句中作主语。故此题选 B。"},{"id":"s70-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Tomorrow is Father's Day. What's your surprise for your father?<br/><br>\n—— The first thing <span class=\"blank-token\">____</span> I will do is making a card for him.</br></p>","options":["who","where","which","that"],"correct":3,"answer":"D"},{"id":"s70-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Have you ever heard about the new law against food waste?<br/><br>\n—— I'm wondering <span class=\"blank-token\">____</span>.<br/><br>\n—— Don't worry. Of course it will.</br></br></p>","options":["will it be helpful","how will it be helpful","it will be helpful","whether it will be helpful"],"correct":3,"answer":"D\n解析：由题干可知空格处应为宾语从句。宾语从句的语序为陈述语序,可排除 A、B 两项。由 “Of course it will.” 可知此处应表示 “我想知道它是否会有帮助”, whether 意为 “是否”, 故选 D。"}],"questionCount":4,"hasAnswers":true},{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s70-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Have you seen the film?<br/><br>\n—— Yes. It's the best one <span class=\"blank-token\">____</span> I have ever seen.</br></p>","options":["which","that"],"correct":1,"answer":"B\n解析：先行词 one 被 best 修饰时,关系代词只能填 that。"},{"id":"s70-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you know the man <span class=\"blank-token\">____</span> spoke at the meeting just now?</p>","options":["who","which"],"correct":0,"answer":"A"},{"id":"s70-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Frank, look! Who are the children under the tree <span class=\"blank-token\">____</span> waiting in line?<br/><br>\n—— They are the students from No.1 Primary School.</br></p>","options":["who is","that are"],"correct":1,"answer":"B"},{"id":"s70-practice-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">In the past, people didn't know <span class=\"blank-token\">____</span> the earth moves around the sun.</p>","options":["that","which"],"correct":0,"answer":"A\n解析：根据句意 “在过去,人们不知道地球绕着太阳转” 可知 know 的后面为表达客观事实或规律的宾语从句,故填 that。"}],"questionCount":4,"hasAnswers":true},{"source":"textbook","title":"判断下列句子是否含有定语从句。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s70-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">I like music that I can dance to.</p>","options":["含有","不含有"],"correct":0,"answer":"A"},{"id":"s70-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">I wonder who is knocking on the door.</p>","options":["含有","不含有"],"correct":1,"answer":"B"},{"id":"s70-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't like riding on the drop tower (跳楼机) because it is too high for me.</p>","options":["含有","不含有"],"correct":1,"answer":"B"},{"id":"s70-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you know the girl whose sweater is backwards (毛衣穿反了)?</p>","options":["含有","不含有"],"correct":0,"answer":"A"},{"id":"s70-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The boy who puts shoes on the wrong feet (鞋子穿反了) is my brother.</p>","options":["含有","不含有"],"correct":0,"answer":"A"}],"questionCount":5,"hasAnswers":true},{"source":"textbook","title":"II. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s70-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">The factory <span class=\"blank-token\">____</span> we'll visit next week is not far from here.</p>","options":["where","to which","which","in which"],"correct":2,"answer":"C"},{"id":"s70-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">Everything <span class=\"blank-token\">____</span> happens here can and may be recorded by a security camera.</p>","options":["where","which","when","that"],"correct":3,"answer":"D"},{"id":"s70-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">He says <span class=\"blank-token\">____</span> he is listening to the weather report.</p>","options":["who","where","what","that"],"correct":3,"answer":"D"},{"id":"s70-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">I'm afraid <span class=\"blank-token\">____</span> he can't come.</p>","options":["whose","where","that","why"],"correct":2,"answer":"C"}],"questionCount":4,"hasAnswers":true}]},{"id":"s71","section":71,"unit":12,"unitName":"单元12 · 第67–72节","short":"第71节 · L141–142","title":"被动语态","lessons":"Lesson 141 — Lesson 142","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>被动语态</td>\n<td>被动语态的含义和用法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>被动语态</td>\n<td>被动语态的构成</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<div class=\"g\"><div class=\"gt\">被动语态的含义和用法</div><div class=\"gb\"><h5>1. 主动语态和被动语态</h5>\n<p class=\"source-line\">英语中有两种语态：主动语态和被动语态。主动语态表示主语是谓语动作的执行者，而被动语态则表示主语是谓语动作的承受者。</p>\n<p class=\"source-line\">We clean the room every day.</p>\n<p class=\"source-line\">我们每天打扫房间。(主动语态)</p>\n<p class=\"source-line\">The room is cleaned (by us) every day.</p>\n<p class=\"source-line\">房间每天都(被我们)打扫。(被动语态)</p>\n<h5>2. 需要使用被动语态的几种情况</h5>\n<p class=\"source-line\">（1）不知道或者不必提及动作的执行者。</p>\n<p class=\"source-line\">This bridge was built in 1700.</p>\n<p class=\"source-line\">这座桥建于 1700 年。</p>\n<p class=\"source-line\">（2）强调动作的承受者。</p>\n<p class=\"source-line\">Frank was hit by a car.</p>\n<p class=\"source-line\">弗兰克被车撞了。</p>\n<p class=\"source-line\">（3）说话者希望所说的内容更加客观,避免就自己不太肯定的事表态。</p>\n<p class=\"source-line\">It is said that this city's industrial progress was very remarkable.</p>\n<p class=\"source-line\">据说这个城市的工业进步非常显著。</p></div></div>\n<div class=\"g\"><div class=\"gt\">被动语态的构成</div><div class=\"gb\"><h5>1. 各时态的基本结构</h5>\n<p class=\"source-line\">被动语态的基本结构为“be + 及物动词的过去分词”。助动词 be 有时态、人称和数的变化。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>时态</th>\n<th>结构</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般现在时</td>\n<td>主语+ am / is / are done.</td>\n</tr>\n<tr>\n<td>一般过去时</td>\n<td>主语+ was / were done.</td>\n</tr>\n<tr>\n<td>现在进行时</td>\n<td>主语+ am / is / are being done.</td>\n</tr>\n<tr>\n<td>现在完成时</td>\n<td>主语+ have / has been done.</td>\n</tr>\n<tr>\n<td>一般将来时</td>\n<td>主语+ will be done.</td>\n</tr>\n<tr>\n<td>过去进行时</td>\n<td>主语+ was / were being done.</td>\n</tr>\n<tr>\n<td>过去完成时</td>\n<td>主语+ had been done.</td>\n</tr>\n<tr>\n<td>含有情态动词的被动语态</td>\n<td>主语+情态动词+ be done.</td>\n</tr>\n</tbody>\n</table></div>\n<h5>2. 被动语态的句式结构</h5>\n<p class=\"source-line\">（1）肯定句: 主语 + be + 过去分词（+ by ...）.</p>\n<p class=\"source-line\">Sally was invited to a party last week.</p>\n<p class=\"source-line\">萨莉上周被邀请参加一个聚会。</p>\n<p class=\"source-line\">（2）否定句: 主语 + be not + 过去分词（+ by ...）.</p>\n<p class=\"source-line\">Sally was not invited to a party last week.</p>\n<p class=\"source-line\">萨莉上周没有被邀请参加一个聚会。</p>\n<p class=\"source-line\">（3）一般疑问句: Be + 主语 + 过去分词（+ by ...）?</p>\n<p class=\"source-line\">Was Sally invited to a party last week?</p>\n<p class=\"source-line\">萨莉上周被邀请参加一个聚会了吗？</p>\n<p class=\"source-line\">（4）特殊疑问句: 疑问词 + be + 主语 + 过去分词（+ by ...）?</p>\n<p class=\"source-line\">When was Sally invited to a party?</p>\n<p class=\"source-line\">萨莉什么时候被邀请参加了一个聚会？</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"【江苏·盐城】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s71-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">In Chinese culture, children born in the year of the monkey <span class=\"blank-token\">____</span> to be smart.</p>","options":["say","said","is said","are said"],"correct":3,"answer":"D\n解析：此题意为 “在中国文化中, 猴年出生的孩子据说很聪明”。be said 意为 “据说”, 主语为 children, 故选 D。"},{"id":"s71-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Look at the flowers on both sides of the streets. They <span class=\"blank-token\">____</span> last month.</p>","options":["were planted","are planted","are planting","were planting"],"correct":0,"answer":"A\n解析：由 last month 可知第二句的时态为一般过去时。they 指代 flowers,与 plant 之间存在被动关系,因此使用一般过去时的被动语态。故选 A。"},{"id":"s71-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">I learnt to swim when I was six. I <span class=\"blank-token\">____</span> by my mother.</p>","options":["am taught","was taught","will be taught","have taught"],"correct":1,"answer":"B"},{"id":"s71-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Would you like to go shopping with me after lunch?<br/><br>\n—— I’d love to, but I <span class=\"blank-token\">____</span> to go out this afternoon.</br></p>","options":["don’t allow","will allow","won’t be allowed","will not allow"],"correct":2,"answer":"C"},{"id":"s71-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The villagers expect that the construction of the bridge <span class=\"blank-token\">____</span> before the rainy season comes.</p>","options":["is completed","was completed","will be completed","has been completed"],"correct":2,"answer":"C\n解析：由 expect(期待) 可知这座桥的建造还没有完成, 应用一般将来时的被动语态。故选 C。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【黑龙江·哈尔滨】根据句意完成句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s71-practice-q006","number":6,"type":"input","questionHtml":"<p class=\"source-line\">这张桌子是我父亲昨晚做的。<br/>\nThis table <span class=\"blank-token\">____</span> by my father last night.</p>","options":[],"correct":null,"answer":"was made\n解析：根据 last night 可知此句时态为一般过去时。桌子应是被 “我” 父亲做的, 所以应用被动语态。故答案为 was made。"},{"id":"s71-practice-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">我明年夏天将被教游泳。<br/>\nI will <span class=\"blank-token\">____</span> to swim next summer.</p>","options":[],"correct":null,"answer":"be taught\n解析：根据句意可知此句为一般将来时的被动语态。故答案为 be taught。"},{"id":"s71-practice-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">这是最近我们城市建造的最高的建筑物之一。<br/>\nThis is one of the highest buildings that <span class=\"blank-token\">____</span> in our city recently.</p>","options":[],"correct":null,"answer":"have been built"}],"questionCount":3,"hasAnswers":true},{"source":"textbook","title":"I. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s71-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The school hall <span class=\"blank-token\">____</span> next week to celebrate this year's Science &amp; Technology Festival.</p>","options":["is decorated","will decorate","is decorating","will be decorated"],"correct":3,"answer":"D"},{"id":"s71-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Mum, can I eat a hamburger?<br/><br>\n—— Sure, if the dishes <span class=\"blank-token\">____</span>.</br></p>","options":["washed","are washed","will wash","was washed"],"correct":1,"answer":"B"},{"id":"s71-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't discuss the problem with your partner unless you <span class=\"blank-token\">____</span> to.</p>","options":["ask","are asked","will ask","will be asked"],"correct":1,"answer":"B"},{"id":"s71-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Aunt Li, who is the pretty girl in red in the picture?<br/><br>\n—— It's my daughter. The picture <span class=\"blank-token\">____</span> 10 years ago.</br></p>","options":["took","is taken","has taken","was taken"],"correct":3,"answer":"D"},{"id":"s71-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The villagers expect that the bridge <span class=\"blank-token\">____</span> before the rainy season comes.</p>","options":["completed","was completed","will be completed","are completed"],"correct":2,"answer":"C"},{"id":"s71-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">—— Daddy, when will we go out to fly a kite?<br/><br>\n—— As soon as your homework <span class=\"blank-token\">____</span>.</br></p>","options":["will finish","will be finished","is finished","finishes"],"correct":2,"answer":"C"}],"questionCount":6,"hasAnswers":true},{"source":"textbook","title":"II. 完成下列句子。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s71-text-q007","number":7,"type":"input","questionHtml":"<p class=\"source-line\">Football <span class=\"blank-token\">____</span> (play) all over the world.</p>","options":[],"correct":null,"answer":"is played"},{"id":"s71-text-q008","number":8,"type":"input","questionHtml":"<p class=\"source-line\">The house <span class=\"blank-token\">____</span> (build) in 1978.</p>","options":[],"correct":null,"answer":"was built"},{"id":"s71-text-q009","number":9,"type":"input","questionHtml":"<p class=\"source-line\">No stars can <span class=\"blank-token\">____</span> (see) in the daytime.</p>","options":[],"correct":null,"answer":"be seen"},{"id":"s71-text-q010","number":10,"type":"input","questionHtml":"<p class=\"source-line\">The letter <span class=\"blank-token\">____</span> (write) by Lin Tao now.</p>","options":[],"correct":null,"answer":"is being written"},{"id":"s71-text-q011","number":11,"type":"input","questionHtml":"<p class=\"source-line\">The bridge <span class=\"blank-token\">____</span> (finish) next month.</p>","options":[],"correct":null,"answer":"will be finished"}],"questionCount":5,"hasAnswers":true}]},{"id":"s72","section":72,"unit":12,"unitName":"单元12 · 第67–72节","short":"第72节 · L143–144","title":"when、where、why 引导的定语从句","lessons":"Lesson 143 — Lesson 144","knowledgeHtml":"<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>when、where、why引导的定语从句</td>\n<td>when 引导的定语从句</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>when、where、why引导的定语从句</td>\n<td>where 引导的定语从句</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>when、where、why引导的定语从句</td>\n<td>why 引导的定语从句</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>","grammarHtml":"<p class=\"source-line\">关系副词在定语从句中充当状语,一般不可省略。常用的关系副词有 when、where、why 等,其主要用法如下:</p>\n<div class=\"g\"><div class=\"gt\">when 引导的定语从句</div><div class=\"gb\"><p class=\"source-line\">由 when 引导的定语从句, 其先行词通常为 time、day、week 等表示时间的名词。此时常可用 on which、in which、during which 等替换。when 在从句中作时间状语。</p>\n<p class=\"source-line\">I'll never forget the time when we first met in London. = I'll never forget the time during which we first met in London.</p>\n<p class=\"source-line\">我永远不会忘记我们第一次在伦敦见面的时光。</p></div></div>\n<div class=\"g\"><div class=\"gt\">where 引导的定语从句</div><div class=\"gb\"><p class=\"source-line\">由 where 引导的定语从句, 其先行词通常为 place、house、country 等表示地点的名词。where 在从句中作地点状语。</p>\n<p class=\"source-line\">The factory where his father works is in the west of the city.</p>\n<p class=\"source-line\">他父亲工作的工厂在城市西部。</p>\n<p class=\"source-line\">Keep the magazines in a place where you can find them easily.</p>\n<p class=\"source-line\">把杂志放在你容易找到的地方。</p></div></div>\n<div class=\"g\"><div class=\"gt\">why 引导的定语从句</div><div class=\"gb\"><p class=\"source-line\">由 why 引导的定语从句, 常用在先行词 reason 后面。why 在定语从句中作原因状语。</p>\n<p class=\"source-line\">I don't know the reason why she left home.</p>\n<p class=\"source-line\">我不知道她离开家的原因。</p>\n<p class=\"source-line\">The reason why I got a job was that I worked hard.</p>\n<p class=\"source-line\">我找到工作的原因是我工作努力。</p></div></div>","notesHtml":"","exerciseGroups":[{"source":"practice","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s72-practice-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">Is this the park <span class=\"blank-token\">____</span> the exhibition was held?</p>","options":["when","why","where"],"correct":2,"answer":"C\n解析：was held 后缺少地点状语, 故空格处填 where。"},{"id":"s72-practice-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">This is the company <span class=\"blank-token\">____</span> he used to work.</p>","options":["why","where","when"],"correct":1,"answer":"B"},{"id":"s72-practice-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">We'd like to know the reason <span class=\"blank-token\">____</span> he didn't accept the job.</p>","options":["where","when","why"],"correct":2,"answer":"C\n解析：先行词是 the reason,需用关系副词 why 作原因状语。"},{"id":"s72-practice-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The reason <span class=\"blank-token\">____</span> he was so sad was that he lost the game.</p>","options":["when","why","where"],"correct":1,"answer":"B"},{"id":"s72-practice-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">I shall never forget the days <span class=\"blank-token\">____</span> we worked in the factory.</p>","options":["why","where","when"],"correct":2,"answer":"C\n解析：先行词是 the days,需用关系副词 when 作时间状语。"}],"questionCount":5,"hasAnswers":true},{"source":"practice","title":"【山东·青岛】单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s72-practice-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">I visited the town <span class=\"blank-token\">____</span> my grandpa used to live last weekend.</p>","options":["what","which","that","where"],"correct":3,"answer":"D\n解析：根据句意 “我上个周末参观了我爷爷曾经住过的那个小镇” 可知从句中缺少地点状语,故答案为 D。"},{"id":"s72-practice-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">These old pictures bring to their mind the college days <span class=\"blank-token\"><strong><em>_</em></strong></span> they spent together, <span class=\"blank-token\">_</span> life was hard but happy.</p>","options":["when; whose","which; whose","which; when","when; which"],"correct":2,"answer":"C"}],"questionCount":2,"hasAnswers":true},{"source":"textbook","title":"I. 单项选择。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s72-text-q001","number":1,"type":"mcq","questionHtml":"<p class=\"source-line\">The reason <span class=\"blank-token\">____</span> I am writing to you is to tell you about a party on Saturday.</p>","options":["because","why","how","which"],"correct":1,"answer":"B"},{"id":"s72-text-q002","number":2,"type":"mcq","questionHtml":"<p class=\"source-line\">Great changes have taken place in the factory <span class=\"blank-token\">____</span> we are working.</p>","options":["where","that","which","there"],"correct":0,"answer":"A"},{"id":"s72-text-q003","number":3,"type":"mcq","questionHtml":"<p class=\"source-line\">Do you still remember the day <span class=\"blank-token\">____</span> we first met?</p>","options":["that","when","what","which"],"correct":1,"answer":"B"},{"id":"s72-text-q004","number":4,"type":"mcq","questionHtml":"<p class=\"source-line\">The engineer <span class=\"blank-token\">____</span> my father works is about 50 years old.</p>","options":["to whom","on whom","with which","with whom"],"correct":3,"answer":"D"},{"id":"s72-text-q005","number":5,"type":"mcq","questionHtml":"<p class=\"source-line\">The reason <span class=\"blank-token\"><strong><em>_</em></strong></span> he didn't come was <span class=\"blank-token\">_</span> he was ill.</p>","options":["why ; that","that ; why","for that ; that","for which ; what"],"correct":0,"answer":"A"},{"id":"s72-text-q006","number":6,"type":"mcq","questionHtml":"<p class=\"source-line\">This is the reason <span class=\"blank-token\">____</span> he didn't come to the meeting.</p>","options":["in which","with which","at which","for which"],"correct":3,"answer":"D"},{"id":"s72-text-q007","number":7,"type":"mcq","questionHtml":"<p class=\"source-line\">After living in London for thirty years, Mr Smith returned to the small town <span class=\"blank-token\">____</span> he grew up as a child.</p>","options":["which","where","that","when"],"correct":1,"answer":"B"},{"id":"s72-text-q008","number":8,"type":"mcq","questionHtml":"<p class=\"source-line\">Don't forget the day <span class=\"blank-token\">____</span> you were admitted to Peking University.</p>","options":["when","that","which","where"],"correct":0,"answer":"A"}],"questionCount":8,"hasAnswers":true},{"source":"textbook","title":"选择题：选择正确答案。","questionsHtml":"","answersHtml":"","preambleHtml":"","items":[{"id":"s72-text-q009","number":9,"type":"mcq","questionHtml":"<p class=\"source-line\">This is the museum <span class=\"blank-token\">____</span> my mother worked 10 years ago.</p>","options":["where","when","why"],"correct":0,"answer":"A"},{"id":"s72-text-q010","number":10,"type":"mcq","questionHtml":"<p class=\"source-line\">July 1, 1921 was the day <span class=\"blank-token\">____</span> the Communist Party of China was founded (成立).</p>","options":["when","why","where"],"correct":0,"answer":"A"},{"id":"s72-text-q011","number":11,"type":"mcq","questionHtml":"<p class=\"source-line\">I remember the days <span class=\"blank-token\">____</span> I lived in my hometown.</p>","options":["why","where","when"],"correct":2,"answer":"C"},{"id":"s72-text-q012","number":12,"type":"mcq","questionHtml":"<p class=\"source-line\">The reason <span class=\"blank-token\">____</span> he did it is not clear.</p>","options":["where","when","why"],"correct":2,"answer":"C"},{"id":"s72-text-q013","number":13,"type":"mcq","questionHtml":"<p class=\"source-line\">The hotel <span class=\"blank-token\">____</span> we stayed wasn't very clean.</p>","options":["when","why","where"],"correct":2,"answer":"C"},{"id":"s72-text-q014","number":14,"type":"mcq","questionHtml":"<p class=\"source-line\">I don't know the reason <span class=\"blank-token\">____</span> he looks unhappy today.</p>","options":["why","where","when"],"correct":0,"answer":"A"}],"questionCount":6,"hasAnswers":true}]}];
(function clientRuntime() {
  const $ = (id) => document.getElementById(id);
  const escapeHtml = (value) =>
    String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  const storageKeyPrefix = "new-concept-grammar-72-v2";
  let curUnit = 1;
  let curSec = DATA[0].id;
  let cloudSync = null;
  let activeStorageKey = "";
  let state = { solved: {}, work: {}, stars: {}, vocab: {}, updatedAt: 0 };

  function emptyState() {
    return { solved: {}, work: {}, stars: {}, vocab: {}, updatedAt: 0 };
  }

  function activateStudentStorage(identity) {
    const keyPart = String(identity.userId || identity.username || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_.:-]/g, "-");
    activeStorageKey = keyPart ? `${storageKeyPrefix}:${keyPart}` : "";
    state = emptyState();
    if (activeStorageKey) {
      try {
        state = normalizeState(JSON.parse(localStorage.getItem(activeStorageKey) || "{}"));
      } catch (error) {
        state = emptyState();
      }
    }
    render();
  }

  function deactivateStudentStorage() {
    activeStorageKey = "";
    state = emptyState();
    render();
  }

  function saveState({ skipCloud = false, preserveTimestamp = false } = {}) {
    if (!preserveTimestamp) state.updatedAt = Date.now();
    try {
      if (activeStorageKey) localStorage.setItem(activeStorageKey, JSON.stringify(state));
    } catch (error) {
      // Local files or privacy settings may block storage; the page still works in-memory.
    }
    if (!skipCloud && cloudSync) cloudSync.queueSync();
  }

  function normalizeState(nextState = {}) {
    return {
      solved: nextState.solved || {},
      work: nextState.work || {},
      stars: nextState.stars || {},
      vocab: nextState.vocab || {},
      updatedAt: Number(nextState.updatedAt) || Date.now(),
    };
  }

  function applyCloudState(nextState) {
    state = normalizeState(nextState);
    saveState({ skipCloud: true, preserveTimestamp: true });
    render();
  }

  function progressSummary() {
    const totalItems = DATA.reduce((sum, section) => sum + totalOf(section), 0);
    const completedItems = Object.values(state.solved).reduce(
      (sum, values) => sum + new Set(values || []).size,
      0
    );
    const completedSections = DATA.filter((section) => {
      const total = totalOf(section);
      return total > 0 && solvedSet(section.id).size >= total;
    }).length;
    const starredItems = Object.values(state.stars).reduce(
      (sum, values) => sum + new Set(values || []).size,
      0
    );

    return {
      completedItems,
      totalItems,
      completedSections,
      totalSections: DATA.length,
      progressPercent: totalItems ? Math.round((completedItems / totalItems) * 100) : 0,
      starredItems,
      vocabItems: Object.keys(state.vocab).length,
      lastSection: curSec,
    };
  }

  async function initializeCloudSync() {
    if (window.NCE_LEGACY_BROWSER && !window.NCE_SINGLE_FILE_SYNC) {
      const applyLegacyIdentity = (identity) => {
        if (identity) activateStudentStorage(identity);
      };
      window.addEventListener("nce-legacy-authenticated", (event) => {
        applyLegacyIdentity(event.detail);
      });
      window.addEventListener("nce-legacy-signed-out", deactivateStudentStorage);
      applyLegacyIdentity(window.NCE_LEGACY_IDENTITY);
      return;
    }
    try {
      const createCloudSync = window.NCECloudSync && window.NCECloudSync.createCloudSync;
      if (typeof createCloudSync !== "function") {
        throw new Error("QQ 兼容登录模块未加载");
      }
      cloudSync = await createCloudSync({
        getState: () => normalizeState(state),
        applyState: applyCloudState,
        getSummary: progressSummary,
        onAuthenticated: activateStudentStorage,
        onSignedOut: deactivateStudentStorage,
      });
    } catch (error) {
      const status = $("cloudSyncStatus");
      const dot = $("cloudSyncDot");
      if (status) status.textContent = "本机保存 · 云同步暂不可用";
      if (dot) dot.classList.add("error");
      console.error("CloudBase 初始化失败", error);
    }
  }

  function matchesKey(event, key, keyCode) {
    return event.key === key || event.keyCode === keyCode || event.which === keyCode;
  }

  function focusAdjacentAnswerInput(currentInput, direction) {
    const inputs = $("main").querySelectorAll("[data-input]");
    if (inputs.length < 2) return;

    let currentIndex = -1;
    for (let index = 0; index < inputs.length; index += 1) {
      if (inputs[index] === currentInput) {
        currentIndex = index;
        break;
      }
    }
    if (currentIndex < 0) return;

    const nextIndex = (currentIndex + direction + inputs.length) % inputs.length;
    const nextInput = inputs[nextIndex];
    nextInput.focus();
    if (typeof nextInput.select === "function") nextInput.select();
  }

  function solvedSet(id) {
    return new Set(state.solved[id] || []);
  }

  function setSolved(id, values) {
    state.solved[id] = [...values].sort();
    saveState();
  }

  function totalOf(section) {
    return section.exerciseGroups.reduce(
      (sum, group) => sum + (group.items.length || 1),
      0
    );
  }

  function itemKey(groupIndex, itemIndex) {
    return `${groupIndex}-${itemIndex}`;
  }

  function groupsOf(section, source) {
    return section.exerciseGroups.filter((group) => group.source === source);
  }

  function groupLabel(group) {
    const source = group.source === "practice" ? "真题锦囊" : "典型例题";
    return `${source} · ${group.title}`;
  }

  function answerOnly(value) {
    return String(value || "").split(/\n解析：/, 1)[0].trim();
  }

  function answerHtml(value) {
    return escapeHtml(value).replace(/\n/g, "<br>");
  }

  function speak(text) {}

  function buildNav() {
    const units = [...new Set(DATA.map((section) => section.unit))];
    $("units").innerHTML = units
      .map((unit) => {
        const name = DATA.find((section) => section.unit === unit).unitName;
        return `<button class="unit-tab${unit === curUnit ? " on" : ""}" data-u="${unit}">${name}</button>`;
      })
      .join("");

    if ($("top-actions")) {
      $("top-actions").innerHTML = `<button class="unit-tab${curUnit === 'stars' ? " on" : ""}" style="color:#B96A00;background:${curUnit==='stars'?'#FFF3E2':'transparent'};border:1px solid #FFF3E2" data-u="stars">⭐ 错题本</button>` + `<button class="unit-tab${curUnit === 'vocab' ? " on" : ""}" style="color:#0EA5E9;background:${curUnit==='vocab'?'#E0F2FE':'transparent'};border:1px solid #E0F2FE" data-u="vocab">📖 生词本</button>`;
      
      $("top-actions").querySelectorAll(".unit-tab").forEach(button => {
        button.onclick = () => {
          const u = button.dataset.u;
          if (u === "stars") {
            curUnit = "stars";
            if (typeof renderStars === 'function') renderStars();
          } else if (u === "vocab") {
            curUnit = "vocab";
            if (typeof renderVocabBook === 'function') renderVocabBook();
          }
        };
      });
    }

    $("units")
      .querySelectorAll(".unit-tab")
      .forEach((button) => {
        button.onclick = () => {
          const u = button.dataset.u;
          curUnit = Number(u);
          curSec = DATA.find((section) => section.unit === curUnit).id;
          render();
        };
      });

    const list = DATA.filter((section) => section.unit === curUnit);
    $("chips").innerHTML = list
      .map((section) => {
        const count = solvedSet(section.id).size;
        const done = count >= totalOf(section) && totalOf(section) > 0;
        return `<button class="chip${section.id === curSec ? " on" : ""}" data-s="${section.id}">
          ${section.short}${done ? ' <span class="dot">✓</span>' : ""}
        </button>`;
      })
      .join("");

    $("chips")
      .querySelectorAll(".chip")
      .forEach((button) => {
        button.onclick = () => {
          curSec = button.dataset.s;
          render();
          window.scrollTo({ top: 0, behavior: "smooth" });
        };
      });
  }

  function feedbackHtml(secId, groupIndex, itemIndex) {
    return `<div class="fb" id="feedback-${secId}-${groupIndex}-${itemIndex}"></div>`;
  }

  function practiceItemHtml(section, item, groupIndex, itemIndex) {
    const isStarred = (state.stars[section.id] || []).includes(itemKey(groupIndex, itemIndex));
    const starBtn = `<button class="star-btn${isStarred ? " on" : ""}" type="button" data-star="${section.id}|${itemKey(groupIndex, itemIndex)}" title="收藏本题">⭐</button>`;
    const key = itemKey(groupIndex, itemIndex);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    if (item.type === "mcq") {
      const options = item.options
        .map(
          (option, optionIndex) =>
            `<button class="opt" type="button" data-mcq="${section.id}|${groupIndex}-${itemIndex}" data-option="${optionIndex}">
              ${String.fromCharCode(65 + optionIndex)}. ${option}
            </button>`
        )
        .join("");
      return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
        <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
        <div class="opts">${options}</div>
        <div class="group-actions" style="display:flex; justify-content: space-between; align-items: center; width: 100%;">
          ${item.correct === null ? `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">${done ? "✓ 已完成本题" : "标记本题完成"}</button>` : "<div></div>"}
          ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
        </div>
        ${feedbackHtml(section.id, groupIndex, itemIndex)}
      </div>`;
    }

    const answerButtons = item.answer
      ? `<button class="btn p" type="button" data-check="${section.id}|${key}">检查</button>
         <button class="btn s" type="button" data-show="${section.id}|${key}">看答案</button>`
      : `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
           ${done ? "✓ 已完成本题" : "标记本题完成"}
         </button>
         <button class="btn s" type="button" disabled>原文未列答案</button>`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
      <div class="row" style="display:flex; flex-wrap:wrap; gap:8px;">
        <input type="text" class="item-input" id="input-${section.id}-${key}" data-input="${section.id}|${key}"
          value="${escapeHtml(state.work[workKey] || "")}" placeholder="在这里填写答案…" autocomplete="off" spellcheck="false" style="flex:1;">
        ${answerButtons}
        ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
      </div>
      ${feedbackHtml(section.id, groupIndex, itemIndex)}
    </div>`;
  }

  function fallbackGroupHtml(section, group, groupIndex) {
    const key = itemKey(groupIndex, 0);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="source-content">${group.questionsHtml}</div>
      <label class="work-label" for="work-${key}">我的作答（自动保存在本浏览器）</label>
      <textarea class="workpad" id="work-${key}" data-fallback="${key}" placeholder="在这里写下答案、改写后的句子或翻译……">${escapeHtml(
        state.work[workKey] || ""
      )}</textarea>
      <div class="group-actions">
        <button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
          ${done ? "✓ 已完成本组" : "标记本组完成"}
        </button>
      </div>
      ${group.hasAnswers ? `<div class="answer-panel source-content"><div class="answer-label">参考答案</div>${group.answersHtml}</div>` : ""}
    </div>`;
  }

  function groupHtml(section, group, groupIndex) {
    const items = group.items.length
      ? group.items
          .map((item, itemIndex) => practiceItemHtml(section, item, groupIndex, itemIndex))
          .join("")
      : fallbackGroupHtml(section, group, groupIndex);
    return `<section class="exercise-section">
      <div class="group-top">
        <div class="group-title">${group.title}</div>
        <span class="count-badge">约 ${group.questionCount} 题</span>
      </div>
      ${group.preambleHtml ? `<div class="source-content">${group.preambleHtml}</div>` : ""}
      ${items}
      ${
        group.hasAnswers
          ? ""
          : ""
      }
    </section>`;
  }

  function exerciseCollectionHtml(section, source, title, icon, { reset = false, completion = false } = {}) {
    const groups = groupsOf(section, source);
    if (!groups.length) return "";
    const questionCount = groups.reduce(
      (sum, group) => sum + (group.questionCount || 0),
      0
    );
    return `<div class="card exercise-collection ${source}">
      <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:12px;">
        <h2><span class="em">${icon}</span>${title}</h2>
        ${reset ? '<button class="btn" id="btnResetSection" type="button" style="color:#d32f2f; background:#ffebee;">🔄 重置本节练习</button>' : ""}
      </div>
      <p class="lead">共 ${groups.length} 组、${questionCount} 题。先在作答区完成，再查看参考答案。</p>
      ${groups
        .map((group) => groupHtml(section, group, section.exerciseGroups.indexOf(group)))
        .join("")}
      ${completion ? '<div id="allDone"></div>' : ""}
    </div>`;
  }

  
  function toggleStar(secId, key) {
    state.stars[secId] = state.stars[secId] || [];
    const stars = new Set(state.stars[secId]);
    if (stars.has(key)) stars.delete(key);
    else stars.add(key);
    state.stars[secId] = [...stars];
    saveState();
    document.querySelectorAll(`[data-star="${secId}|${key}"]`).forEach(btn => {
      btn.classList.toggle("on", stars.has(key));
    });
    if (curUnit === "stars" && !stars.has(key)) {
      renderStars();
    }
  }

  window.removeVocab = (word) => {
    delete state.vocab[word];
    saveState();
    if (curUnit === 'vocab') renderVocabBook();
  };
  
  window.clearVocab = () => {
    state.vocab = {};
    saveState();
    if (curUnit === 'vocab') renderVocabBook();
  };

  function renderVocabBook() {
    buildNav();
    $("chips").innerHTML = "";
    
    const list = Object.keys(state.vocab).map(word => {
      const v = state.vocab[word];
      return `<div class="exercise-item" style="padding: 16px; border: 1px solid var(--line); border-radius: 12px; margin-bottom: 12px; background: #fff;">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div style="font-weight:700; font-size:18px; color:var(--ink);">${escapeHtml(word)}</div>
          <div style="font-size:12px; color:#9AA3B5;">${new Date(v.ts).toLocaleString()}</div>
        </div>
        <div style="margin-top:6px; color:var(--ink2); font-size:15px;">${escapeHtml(v.translation)}</div>
        <div class="group-actions" style="margin-top:12px;">
          <button class="btn" onclick="removeVocab('${escapeHtml(word)}')">🗑️ 移除生词</button>
        </div>
      </div>`;
    }).join("");

    $("main").innerHTML = `
      <div class="card">
        <div class="group-top" style="align-items:center;">
          <h2><span class="em">📖</span>我的生词本 <span class="count-badge">${Object.keys(state.vocab).length} 词</span></h2>
          <div>
             <button class="btn" style="background:#FFEEEE; color:#E02424;" onclick="if(confirm('确定清空所有生词吗？')) { window.clearVocab(); }">清空生词本</button>
          </div>
        </div>
        <div style="margin-top: 20px;">
          ${list || '<p style="color:#9AA3B5; font-size:14px; text-align:center; padding: 40px 0;">双击课文或题目中的英文单词，即可查看中文意思并自动加入生词本哦~</p>'}
        </div>
      </div>
    `;
  }

  function renderStars() {
    buildNav();
    $("chips").innerHTML = "";
    let html = `<div class="card">
        <h2><span class="em">⭐</span>错题本</h2>
        <p class="lead">您收藏的所有错题和难点。</p>
        <div class="exp-row" style="margin:12px 0 10px;"><b>导出</b>
          <label><input type="checkbox" id="optStarsEx" checked> 错题</label>
          <label><input type="checkbox" id="optStarsAns" checked> 答案</label>
        </div>
        <div style="display:flex; gap:10px;">
          <button class="btn p" id="btnExportStars" type="button">⬇️ 导出错题为 Word</button>
          <button class="btn" id="btnResetStars" type="button" style="color:#f57c00; background:#fff3e0;">🔄 重置所有答案</button>
          <button class="btn" id="btnClearStars" type="button" style="color:#d32f2f; background:#ffebee;">🗑️ 清空所有错题</button>
        </div>
      </div>`;
    
    let hasStars = false;
    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      
      let sectionHtml = `<div class="card"><h3>${section.short} ${section.title}</h3>`;
      let sectionHasItems = false;
      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            sectionHasItems = true;
            sectionHtml += `<div class="group-title" style="margin-top:14px;margin-bottom:8px">${groupLabel(group)}</div>`;
            starredItems.forEach(item => {
               const iIdx = group.items.indexOf(item);
               sectionHtml += practiceItemHtml(section, item, gIdx, iIdx);
            });
         }
      });
      sectionHtml += `</div>`;
      if (sectionHasItems) {
         html += sectionHtml;
         hasStars = true;
      }
    });

    if (!hasStars) {
      html += `<div class="card"><p style="text-align:center;color:#999;padding:40px 0">还没有收藏任何题目哦~</p></div>`;
    }

    $("main").innerHTML = html;
    bindMainEvents();
  }

    function bindMainEvents() {
    const btnResetSection = $("btnResetSection");
    if (btnResetSection) {
       btnResetSection.onclick = () => {
          if (confirm("确定要清空本节所有练习的输入内容和完成状态吗？（错题本收藏不会被清空）")) {
             state.solved[curSec] = [];
             Object.keys(state.work).forEach(key => {
                if (key.startsWith(curSec + "-")) {
                   delete state.work[key];
                }
             });
             saveState();
             render();
          }
       };
    }
    const btnExportStars = $("btnExportStars");
    if (btnExportStars) btnExportStars.onclick = exportStarsDoc;
    
    const btnResetStars = $("btnResetStars");
    if (btnResetStars) btnResetStars.onclick = () => {
       if (confirm("确定要清空错题本中所有题目的输入内容和完成状态吗？（题目仍会保留在错题本中）")) {
          Object.keys(state.stars).forEach(secId => {
             const starKeys = state.stars[secId] || [];
             starKeys.forEach(key => {
                delete state.work[`${secId}-${key}`];
                if (state.solved[secId]) {
                   state.solved[secId] = state.solved[secId].filter(k => k !== key);
                }
             });
          });
          saveState();
          renderStars();
       }
    };

    const btnClearStars = $("btnClearStars");
    if (btnClearStars) btnClearStars.onclick = () => {
       if (confirm("确定要清空所有错题吗？操作不可恢复。")) {
          state.stars = {};
          saveState();
          renderStars();
       }
    };
    $("main")
      .querySelectorAll(".spk")
      .forEach((button) => (button.onclick = () => {} /* TTS removed */));
    $("main")
      .querySelectorAll("[data-mcq]")
      .forEach((button) => (button.onclick = () => pickMcq(button)));
    $("main")
      .querySelectorAll("[data-check]")
      .forEach((button) => (button.onclick = () => checkInput(button.dataset.check)));
    $("main")
      .querySelectorAll("[data-show]")
      .forEach((button) => (button.onclick = () => showInputAnswer(button.dataset.show)));
    $("main")
      .querySelectorAll("[data-manual]")
      .forEach((button) => (button.onclick = () => toggleManual(button.dataset.manual)));
    $("main")
      .querySelectorAll("[data-star]")
      .forEach((button) => (button.onclick = () => {
         const [secId, key] = button.dataset.star.split("|");
         toggleStar(secId, key);
      }));
    $("main")
      .querySelectorAll("[data-input]")
      .forEach((input) => {
        input.addEventListener("input", () => {
          const [secId, key] = input.dataset.input.split("|");
          state.work[`${secId}-${key}`] = input.value;
          saveState();
        });
        input.addEventListener("keydown", (event) => {
          if (matchesKey(event, "Enter", 13)) {
            event.preventDefault();
            checkInput(input.dataset.input);
            return;
          }
          if (matchesKey(event, "Tab", 9)) {
            event.preventDefault();
            focusAdjacentAnswerInput(input, event.shiftKey ? -1 : 1);
          }
        });
      });
  }

  function render() {
    buildNav();
    const section = DATA.find((item) => item.id === curSec) || DATA[0];
    curSec = section.id;

    $("main").innerHTML = `
      <div class="card">
        <div class="section-kicker">第${String(section.section).padStart(2, "0")}节 · ${section.lessons}</div>
        <h2><span class="em">📖</span>${section.title}</h2>
        <div class="course-meta">
          <span class="meta-pill">全课共 72 节</span>
          <span class="meta-pill">${section.unitName}</span>
          <span class="meta-pill">语法精讲 + 典型例题 + 真题锦囊</span>
        </div>
        <div class="overview source-content">
          ${section.knowledgeHtml || "<p>本节知识图谱请结合语法讲解学习。</p>"}
        </div>
      </div>

      <div class="card">
        <h2><span class="em">🧩</span>语法要点</h2>
        <div class="source-content">${section.grammarHtml}</div>
      </div>

      ${exerciseCollectionHtml(section, "textbook", "典型例题", "✏️", { reset: true })}
      ${exerciseCollectionHtml(section, "practice", "真题锦囊", "🎯", { completion: true })}

      <div class="card">
        <h2><span class="em">📄</span>一键导出 Word</h2>
        <p class="lead">生成 .doc 文件，可用 Word 或 WPS 打开并打印。</p>
        <div class="exp-row"><b>范围</b>
          <label><input type="radio" name="scope" value="sec" checked> 本节</label>
          <label><input type="radio" name="scope" value="unit"> 本单元</label>
          <label><input type="radio" name="scope" value="all"> 全部 72 节</label>
        </div>
        <div class="exp-row"><b>内容</b>
          <label><input type="checkbox" id="optMap" checked> 知识图谱</label>
          <label><input type="checkbox" id="optGram" checked> 语法要点</label>
          <label><input type="checkbox" id="optEx" checked> 练习题</label>
          <label><input type="checkbox" id="optAns" checked> 参考答案</label>

        </div>
        <button class="btn p" id="btnExport" type="button">⬇️ 导出 Word 文档</button>
        <div class="tip">制作纯练习卷时，可只保留“练习题”和“参考答案”。</div>
      </div>`;

    bindMainEvents();
    $("btnExport").onclick = exportDoc;
    updateScore(curSec);
  }

  function getItem(secId, key) {
    const [groupIndex, itemIndex] = key.split("-").map(Number);
    const section = DATA.find((item) => item.id === secId);
    return {
      section,
      groupIndex,
      itemIndex,
      item: section.exerciseGroups[groupIndex].items[itemIndex],
    };
  }

  function markSolved(secId, key) {
    const values = solvedSet(secId);
    values.add(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    if (item) item.classList.add("is-done");
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function updateCurrentChip(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const values = solvedSet(secId);
    const chip = $("chips").querySelector(`.chip[data-s="${section.id}"]`);
    if (chip) {
      const complete = values.size >= totalOf(section) && totalOf(section) > 0;
      chip.innerHTML = `${section.short}${complete ? ' <span class="dot">✓</span>' : ""}`;
    }
  }

  function toggleManual(dataset_manual) {
    const [secId, key] = dataset_manual.split("|");
    const values = solvedSet(secId);
    const done = !values.has(key);
    if (done) values.add(key);
    else values.delete(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    const button = document.querySelector(`[data-manual="${secId}|${key}"]`);
    if (item) item.classList.toggle("is-done", done);
    if (button) {
      button.classList.toggle("on", done);
      button.textContent = done ? "✓ 已完成本题" : "标记本题完成";
    }
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function feedback(secId, key, correct, html) {
    const panel = $(`feedback-${secId}-${key}`);
    if (!panel) return;
    panel.className = `fb show ${correct ? "good" : "bad"}`;
    panel.innerHTML = html;
  }

  function pickMcq(button) {
    const [secId, key] = button.dataset.mcq.split("|");
    const { item } = getItem(secId, key);
    const picked = Number(button.dataset.option);
    const box = $(`item-${secId}-${key}`);
    const options = box.querySelectorAll(".opt");

    if (item.correct === null) {
      options.forEach((option) => option.classList.remove("on"));
      button.classList.add("on");
      feedback(secId, key, false, "本题源文件未单列答案，请完成后使用“标记本题完成”。");
      return;
    }

    options.forEach((option, index) => {
      option.disabled = true;
      if (index === item.correct) option.classList.add("ok");
      else if (index === picked) option.classList.add("no");
    });
    const correct = picked === item.correct;
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `再看看～ 正确答案是 <span class="ans">${String.fromCharCode(
            65 + item.correct
          )}. ${item.options[item.correct]}</span>`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function normalizeAnswer(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/[.,!?;:"()，。！？；：]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function checkInput(dataset_check) {
    const [secId, key] = dataset_check.split("|");
    const { item } = getItem(secId, key);
    const input = $(`input-${secId}-${key}`);
    const value = input ? input.value : "";
    if (!value.trim()) {
      feedback(secId, key, false, "先填写答案再检查哦～");
      return;
    }
    const expected = answerOnly(item.answer);
    const correct = normalizeAnswer(value) === normalizeAnswer(expected);
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `还差一点，参考答案：<span class="ans">${answerHtml(item.answer)}</span>`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function showInputAnswer(dataset_show) {
    const [secId, key] = dataset_show.split("|");
    const { item } = getItem(secId, key);
    feedback(secId, key, false, `参考答案：<span class="ans">${answerHtml(item.answer)}</span>`);
  }

  function updateScore(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const count = solvedSet(section.id).size;
    const total = totalOf(section);
    const scoreTxt = $("scoreTxt");
    if (!scoreTxt) return;
    scoreTxt.textContent = `本节练习进度 ${count} / ${total} 组`;
    const scoreBar = $("scoreBar");
    if (scoreBar) scoreBar.style.width = `${total ? Math.round((count / total) * 100) : 0}%`;
    const done = $("allDone");
    if (done) {
      done.innerHTML =
        total && count >= total
          ? '<div class="done">🏆 本节练习全部完成！可以进入下一节。</div>'
          : "";
    }
  }

  const WORD_CSS = `@page{size:A4;margin:2cm 1.8cm}
body{font-family:"Microsoft YaHei","PingFang SC",SimSun,sans-serif;font-size:10.5pt;line-height:1.75;color:#111}
h1{font-size:19pt;text-align:center;margin:0 0 4pt}
.head-sub{text-align:center;color:#666;font-size:9.5pt;margin:0 0 18pt}
h2{font-size:15pt;border-bottom:1.5pt solid #4F7DF3;padding-bottom:3pt;margin:20pt 0 4pt;color:#1F3A93}
h3{font-size:12pt;margin:13pt 0 5pt;color:#B45309}
p{margin:3pt 0}.source-heading{font-size:11.5pt;color:#1F3A93}.english-line{font-family:"Times New Roman",serif}
table{border-collapse:collapse;width:100%;margin:5pt 0;font-size:9.5pt}td,th{border:.5pt solid #999;padding:3pt 5pt}
th{background:#EEF2FB}.lesson-figure img{max-width:100%;height:auto}.spk{display:none}
.answer-block{background:#F1FBF4;padding:7pt;margin:5pt 0}.exercise-block{margin:8pt 0 14pt}.blank-token{border-bottom:.75pt solid #444;color:transparent}`;

  function exportClean(html) {
    return html
      .replace(/<button[\s\S]*?<\/button>/g, "")
      .replace(/\sloading="lazy"/g, "")
      .replace(/<figure class="lesson-figure">/g, "<div class=\"lesson-figure\">")
      .replace(/<\/figure>/g, "</div>");
  }

  
  function exportStarsDoc() {
    const includeEx = $("optStarsEx") ? $("optStarsEx").checked : true;
    const includeAns = $("optStarsAns") ? $("optStarsAns").checked : true;
    
    if (!includeEx && !includeAns) {
       alert("请至少选择一项导出内容！");
       return;
    }

    let body = `<h1>错题本聚合练习卷</h1><p class="head-sub">姓名：__________　日期：__________</p>`;
    
    let hasStars = false;
    let questionsHtmlAll = "";
    let answersHtmlAll = "";

    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      hasStars = true;
      
      let secQHtml = "";
      let secAHtml = "";

      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            secQHtml += `<div class="exercise-block"><b>${groupLabel(group)}</b>`;
            secAHtml += `<div class="answer-block"><b>${groupLabel(group)}</b><div style="margin-top: 5px;">`;
            
            starredItems.forEach(item => {
               let qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
               secQHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
               if (item.type === 'mcq') {
                 secQHtml += `<div style="margin-left: 18pt;">${item.options.map((opt, i) => String.fromCharCode(65+i) + '. ' + opt).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
               }
               secQHtml += `</div>`;
               
               secAHtml += `<div style="margin: 4px 0;"><b>${item.number}.</b> ${answerHtml(item.answer)}</div>`;
            });
            secQHtml += `</div>`;
            secAHtml += `</div></div>`;
         }
      });
      if (secQHtml) {
         if (includeEx) {
             questionsHtmlAll += `<h2>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h2>${secQHtml}`;
         }
         if (includeAns) {
             answersHtmlAll += `<h3>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h3>${secAHtml}`;
         }
      }
    });

    if (!hasStars) {
       alert("错题本为空，无法导出！");
       return;
    }

    if (includeEx) {
       body += questionsHtmlAll;
    }
    if (includeAns) {
       if (includeEx) body += '<h2 style="page-break-before:always">参考答案</h2>';
       else body += '<h2>参考答案</h2>';
       body += answersHtmlAll;
    }
    
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob(['\ufeff' + html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `错题本_新概念语法课.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  function str_padStart(str, len, pad) {
     return String(str).padStart(len, pad);
  }

  function exportDoc() {
    const scope = (document.querySelector('input[name="scope"]:checked') || { value: "sec" })
      .value;
    const include = {
      map: $("optMap").checked,
      grammar: $("optGram").checked,
      exercise: $("optEx").checked,
      answers: $("optAns").checked,
    };
    const current = DATA.find((section) => section.id === curSec);
    let sections;
    let name;
    if (scope === "unit") {
      sections = DATA.filter((section) => section.unit === current.unit);
      name = `72节新概念语法课_${current.unitName.replace(" · ", "_")}`;
    } else if (scope === "all") {
      sections = DATA.slice();
      name = "72节新概念语法课_全册";
    } else {
      sections = [current];
      name = `72节新概念语法课_第${String(current.section).padStart(2, "0")}节_${current.title}`;
    }

    let body = `<h1>${name}</h1><p class="head-sub">新概念英语第一册 · 语法知识、典型例题与真题锦囊　　姓名：__________　日期：__________</p>`;
    sections.forEach((section) => {
      body += `<h2>第${String(section.section).padStart(2, "0")}节　${section.title}</h2>`;
      body += `<p>${section.lessons}</p>`;
      if (include.map) body += `<h3>知识图谱</h3>${exportClean(section.knowledgeHtml)}`;
      if (include.grammar) body += `<h3>语法要点</h3>${exportClean(section.grammarHtml)}`;
      if (include.exercise) {
        [["textbook", "典型例题"], ["practice", "真题锦囊"]].forEach(([source, heading]) => {
          const groups = groupsOf(section, source);
          if (!groups.length) return;
          body += `<h3>${heading}</h3>`;
          groups.forEach((group) => {
            let questionsHtml = group.preambleHtml || "";
            group.items.forEach((item) => {
              const qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
              questionsHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
              if (item.type === "mcq") {
                questionsHtml += `<div style="margin-left: 18pt;">${item.options
                  .map((option, optionIndex) => `${String.fromCharCode(65 + optionIndex)}. ${option}`)
                  .join("&nbsp;&nbsp;&nbsp;&nbsp;")}</div>`;
              }
              questionsHtml += "</div>";
            });
            body += `<div class="exercise-block"><b>${group.title}</b>${exportClean(questionsHtml)}</div>`;
          });
        });
      }

    });

    if (include.answers && include.exercise) {
      body += '<h2 style="page-break-before:always">参考答案</h2>';
      sections.forEach((section) => {
        body += `<h3>第${String(section.section).padStart(2, "0")}节　${section.title}</h3>`;
        [["textbook", "典型例题"], ["practice", "真题锦囊"]].forEach(([source, heading]) => {
          const groups = groupsOf(section, source);
          if (!groups.length) return;
          body += `<p class="source-heading"><b>${heading}</b></p>`;
          groups.forEach((group) => {
            const answersHtml = group.items
              .map((item) => `<div style="margin: 4px 0;"><b>${item.number}.</b> ${answerHtml(item.answer)}</div>`)
              .join("");
            body += `<div class="answer-block"><b>${group.title}</b><div style="margin-top: 5px;">${
              answersHtml || "<p>源文件未单列本组答案。</p>"
            }</div></div>`;
          });
        });
      });
    }

    const html =
      "﻿<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
      "xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>" +
      `<head><meta charset="utf-8"><title>${name}</title><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob([html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `${name.replace(/[\\/:*?"<>|]/g, "")}.doc`;
    document.body.appendChild(anchor);
    anchor.click();
    setTimeout(() => {
      URL.revokeObjectURL(url);
      anchor.remove();
    }, 1500);
    const button = $("btnExport");
    const original = button.textContent;
    button.textContent = "✅ 已导出，去下载文件夹查看";
    setTimeout(() => (button.textContent = original), 2600);
  }


  // Translation Popup Logic
  let translationToast = null;
  
  function showTranslationToast(x, y, word, text) {
    if (translationToast) {
      translationToast.remove();
    }
    translationToast = document.createElement("div");
    translationToast.style.position = "absolute";
    translationToast.style.left = x + "px";
    translationToast.style.top = y + "px";
    translationToast.style.background = "#fff";
    translationToast.style.padding = "12px 16px";
    translationToast.style.borderRadius = "12px";
    translationToast.style.boxShadow = "0 8px 24px rgba(0,0,0,0.12)";
    translationToast.style.border = "1px solid #E2E8F0";
    translationToast.style.zIndex = "10000";
    translationToast.style.transform = "translate(-50%, -100%)";
    translationToast.style.marginTop = "-10px";
    translationToast.style.pointerEvents = "auto";
    
    const isAdded = !!state.vocab[word];
    
    translationToast.innerHTML = `
      <div style="font-weight:700; color:var(--blue); font-size:16px;">${escapeHtml(word)}</div>
      <div style="color:var(--ink2); font-size:14px; margin-top:4px; max-width:250px; line-height: 1.4;">${escapeHtml(text)}</div>
      <div style="margin-top:10px;">
        <button id="btn-add-vocab" style="border:none; background:${isAdded ? '#F1FBF4' : '#E0F2FE'}; color:${isAdded ? '#10B981' : 'var(--blue)'}; padding: 6px 12px; border-radius: 6px; font-size:13px; cursor:pointer; font-weight: 500; transition: all 0.2s;">
          ${isAdded ? '✅ 已收录生词本' : '➕ 收录到生词本'}
        </button>
      </div>
    `;
    
    document.body.appendChild(translationToast);
    
    document.getElementById("btn-add-vocab").onclick = (e) => {
       e.stopPropagation();
       if (!state.vocab[word]) {
          state.vocab[word] = { translation: text, ts: Date.now() };
          saveState();
          e.target.innerText = '✅ 已收录生词本';
          e.target.style.background = '#F1FBF4';
          e.target.style.color = '#10B981';
          if (typeof curUnit !== "undefined" && curUnit === "vocab" && typeof renderVocabBook === "function") {
            renderVocabBook();
          }
       }
    };
    
    setTimeout(() => {
      document.addEventListener("click", function closeToast(e) {
        if (translationToast && !translationToast.contains(e.target)) {
          translationToast.remove();
          translationToast = null;
          document.removeEventListener("click", closeToast);
        }
      });
    }, 100);
  }

  document.body.addEventListener("dblclick", async (e) => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0) return;
    const text = selection.toString().trim();
    if (!text) return;
    
    // Only accept alphabetic words, allow apostrophe
    if (!/^[a-zA-Z']+$/.test(text)) return;
    
    // Don't translate very short common words
    if (text.length <= 2) return;
    
    const word = text.toLowerCase();
    
    // Calculate position
    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    const x = rect.left + rect.width / 2 + window.scrollX;
    const y = rect.top + window.scrollY;
    
    const callbackName = "jsonp_youdao_" + Date.now() + "_" + Math.floor(Math.random() * 10000);
    window[callbackName] = function(data) {
      delete window[callbackName];
      const scriptElem = document.getElementById(callbackName);
      if (scriptElem) scriptElem.remove();
      
      if (data && data.data && data.data.entries && data.data.entries.length > 0) {
        let trans = data.data.entries[0].explain;
        if (!trans) trans = data.data.entries[0].entry;
        
        showTranslationToast(x, y, word, trans);
      } else {
        showTranslationToast(x, y, word, "未找到释义");
      }
    };
    
    const script = document.createElement("script");
    script.id = callbackName;
    script.src = `https://dict.youdao.com/suggest?num=1&doctype=json&q=${encodeURIComponent(word)}&callback=${callbackName}`;
    document.body.appendChild(script);
  });

  render();
  initializeCloudSync();
})();
